INSERT INTO `AM_LLM_PROVIDER` VALUES ('10a5019b-e1fc-4ab4-b5f2-84b024b36df4','Gemini','1.0.0','carbon.super','true','Gemini service',_binary '{\"connectorType\":\"gemini_1.0.0\",\"metadata\":[{\"attributeName\":\"requestModel\",\"inputSource\":\"pathParams\",\"attributeIdentifier\":\"(?<=models/)[a-zA-Z0-9.\\\\-]+\",\"required\":false},{\"attributeName\":\"responseModel\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.modelVersion\",\"required\":true},{\"attributeName\":\"promptTokenCount\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.usageMetadata.promptTokenCount\",\"required\":true},{\"attributeName\":\"completionTokenCount\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.usageMetadata.candidatesTokenCount\",\"required\":true},{\"attributeName\":\"totalTokenCount\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.usageMetadata.totalTokenCount\",\"required\":false}],\"authenticationConfiguration\":{\"enabled\":true,\"type\":\"apikey\",\"parameters\":{\"headerEnabled\":true,\"headerName\":\"X-goog-api-key\",\"queryParameterEnabled\":false}}}',_binary 'openapi: 3.0.3\ninfo:\n  title: Gemini API\n  description: >-\n    The Gemini API allows developers to build generative AI applications using\n    Gemini models. Gemini is our most capable model, built from the ground up to\n    be multimodal. It can generalize and seamlessly understand, operate across,\n    and combine different types of information including language, images,\n    audio, video, and code. You can use the Gemini API for use cases like\n    reasoning across text and images, content generation, dialogue agents,\n    summarization and classification systems, and more.\n  version: v1beta\n  x-google-revision: \'20250902\'\nexternalDocs:\n  description: Find more info here.\n  url: \'https://developers.generativeai.google/api\'\nservers:\n  - url: \'https://generativelanguage.googleapis.com\'\n    description: Global Endpoint\nsecurity:\n  - default: []\npaths:\n  \'/v1b