s/workspaces/{workspace_id}/members:\n    get:\n      tags:\n        - Admin - Workspace Member Management\n      summary: List Workspace Members\n      description: Retrieves a list of all members in a workspace\n      security:\n        - ApiKeyAuth: []\n      parameters:\n        - $ref: \'#/components/parameters/AnthropicVersionHeader\'\n        - $ref: \'#/components/parameters/WorkspaceId\'\n        - $ref: \'#/components/parameters/BeforeId\'\n        - $ref: \'#/components/parameters/AfterId\'\n        - $ref: \'#/components/parameters/Limit\'\n        - $ref: \'#/components/parameters/AnthropicDangerousDirectBrowserAccessHeader\'\n      responses:\n        \'200\':\n          description: Workspace members retrieved successfully\n          headers:\n            request-id:\n              $ref: \'#/components/headers/RequestId\'\n            anthropic-organization-id:\n              $ref: \'#/components/headers/AnthropicOrganizationId\'\n            retry-after:\n              $ref: \'#/components/headers/RetryAfter\'\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - data\n                  - first_id\n                  - has_more\n                  - last_id\n                properties:\n                  data:\n                    type: array\n                    items:\n                      $ref: \'#/components/schemas/AdminWorkspaceMemberData\'\n                  first_id:\n                    $ref: \'#/components/schemas/FirstId\'\n                  has_more:\n                    $ref: \'#/components/schemas/HasMore\'\n                  last_id:\n                    $ref: \'#/components/schemas/LastId\'\n        \'400\':\n          $ref: \'#/components/responses/Error400\'\n        \'401\':\n          $ref: \'#/components/responses/Error401\'\n        \'403\':\n          $ref: \'#/components/responses/Error403\'\n        \'404\':\n          $ref: \'#/components/responses/Error404\'\n        \'413\':\n          $ref: \'#/components/responses/Error413\'\n        \'429\':\n          $ref: \'#/components/responses/Error429\'\n        \'500\':\n          $ref: \'#/components/responses/Error500\'\n        \'529\':\n          $ref: \'#/components/responses/Error529\'\n    post:\n      tags:\n        - Admin - Workspace Member Management\n      summary: Create Workspace Member\n      description: Creates a new workspace member\n      security:\n        - ApiKeyAuth: []\n      parameters:\n        - $ref: \'#/components/parameters/AnthropicVersionHeader\'\n        - $ref: \'#/components/parameters/WorkspaceId\'\n        - $ref: \'#/components/parameters/AnthropicDangerousDirectBrowserAccessHeader\'\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              type: object\n              required:\n                - user_id\n                - workspace_role\n              properties:\n                user_id:\n                  type: string\n                  description: ID of the User.\n                workspace_role:\n                  type: string\n                  enum: [workspace_user, workspace_developer, workspace_admin]\n                  description: Role of the new Workspace Member. Cannot be \"workspace_billing\".\n      responses:\n        \'200\':\n          description: Workspace member created successfully\n          headers:\n            request-id:\n              $ref: \'#/components/headers/RequestId\'\n            anthropic-organization-id:\n              $ref: \'#/components/headers/AnthropicOrganizationId\'\n            retry-after:\n              $ref: \'#/components/headers/RetryAfter\'\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/AdminWorkspaceMemberData\'\n        \'400\':\n          $ref: \'#/components/responses/Error400\'\n        \'401\':\n          $ref: \'#/components/responses/Error401\'\n        \'403\':\n          $ref: \'#/components/responses/Error403\'\n        \'404\':\n          $ref: \'#/components/responses/Error404\'\n        \'413\':\n          $ref: \'#/components/responses/Error413\'\n        \'429\':\n          $ref: \'#/components/responses/Error429\'\n        \'500\':\n          $ref: \'#/components/responses/Error500\'\n        \'529\':\n          $ref: \'#/components/responses/Error529\'\n  /v1/organizations/workspaces/{workspace_id}/members/{user_id}:\n    get:\n      tags:\n        - Admin - Workspace Member Management\n      summary: Get Workspace Member\n      description: Retrieves details for a specific workspace member\n      security:\n        - ApiKeyAuth: []\n      parameters:\n        - $ref: \'#/components/parameters/AnthropicVersionHeader\'\n        - $ref: \'#/components/parameters/WorkspaceId\'\n        - $ref: \'#/components/parameters/UserId\'\n        - $ref: \'#/components/parameters/AnthropicDangerousDirectBrowserAccessHeader\'\n      responses:\n        \'200\':\n          description: Workspace member details retrieved successfully\n          headers:\n            request-id:\n              $ref: \'#/components/headers/RequestId\'\n            anthropic-organization-id:\n              $ref: \'#/components/headers/AnthropicOrganizationId\'\n            retry-after:\n              $ref: \'#/components/headers/RetryAfter\'\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/AdminWorkspaceMemberData\'\n        \'400\':\n          $ref: \'#/components/responses/Error400\'\n        \'401\':\n          $ref: \'#/components/responses/Error401\'\n        \'403\':\n          $ref: \'#/components/responses/Error403\'\n        \'404\':\n          $ref: \'#/components/responses/Error404\'\n        \'413\':\n          $ref: \'#/components/responses/Error413\'\n        \'429\':\n          $ref: \'#/components/responses/Error429\'\n        \'500\':\n          $ref: \'#/components/responses/Error500\'\n        \'529\':\n          $ref: \'#/components/responses/Error529\'\n    post:\n      tags:\n        - Admin - Workspace Member Management\n      summary: Update Workspace Member\n      description: Updates details for a specific workspace member\n      security:\n        - ApiKeyAuth: []\n      parameters:\n        - $ref: \'#/components/parameters/AnthropicVersionHeader\'\n        - $ref: \'#/components/parameters/WorkspaceId\'\n        - $ref: \'#/components/parameters/UserId\'\n        - $ref: \'#/components/parameters/AnthropicDangerousDirectBrowserAccessHeader\'\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              type: object\n              required:\n                - workspace_role\n              properties:\n                workspace_role:\n                  type: string\n                  enum: [workspace_user, workspace_developer, workspace_admin, workspace_billing]\n                  description: New workspace role for the User.\n      responses:\n        \'200\':\n          description: Workspace member updated successfully\n          headers:\n            request-id:\n              $ref: \'#/components/headers/RequestId\'\n            anthropic-organization-id:\n              $ref: \'#/components/headers/AnthropicOrganizationId\'\n            retry-after:\n              $ref: \'#/components/headers/RetryAfter\'\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/AdminWorkspaceMemberData\'\n        \'400\':\n          $ref: \'#/components/responses/Error400\'\n        \'401\':\n          $ref: \'#/components/responses/Error401\'\n        \'403\':\n          $ref: \'#/components/responses/Error403\'\n        \'404\':\n          $ref: \'#/components/responses/Error404\'\n        \'413\':\n          $ref: \'#/components/responses/Error413\'\n        \'429\':\n          $ref: \'#/components/responses/Error429\'\n        \'500\':\n          $ref: \'#/components/responses/Error500\'\n        \'529\':\n          $ref: \'#/components/responses/Error529\'\n    delete:\n      tags:\n        - Admin - Workspace Member Management\n      summary: Delete Workspace Member\n      description: Removes a member from the workspace\n      security:\n        - ApiKeyAuth: []\n      parameters:\n        - $ref: \'#/components/parameters/AnthropicVersionHeader\'\n        - $ref: \'#/components/parameters/WorkspaceId\'\n        - $ref: \'#/components/parameters/UserId\'\n        - $ref: \'#/components/parameters/AnthropicDangerousDirectBrowserAccessHeader\'\n      responses:\n        \'200\':\n          description: Workspace member successfully removed\n          headers:\n            request-id:\n              $ref: \'#/components/headers/RequestId\'\n            anthropic-organization-id:\n              $ref: \'#/components/headers/AnthropicOrganizationId\'\n            retry-after:\n              $ref: \'#/components/headers/RetryAfter\'\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - type\n                  - user_id\n                  - workspace_id\n                properties:\n                  type:\n                    type: string\n                    enum: [workspace_member_deleted]\n                    default: workspace_member_deleted\n                    description: Deleted object type. For Workspace Members, this is always \"workspace_member_deleted\".\n                  user_id:\n                    type: string\n                    description: ID of the User.\n                  workspace_id:\n                    type: string\n                    description: ID of the Workspace.\n        \'400\':\n          $ref: \'#/components/responses/Error400\'\n        \'401\':\n          $ref: \'#/components/responses/Error401\'\n        \'403\':\n          $ref: \'#/components/responses/Error403\'\n        \'404\':\n          $ref: \'#/components/responses/Error404\'\n        \'413\':\n          $ref: \'#/components/responses/Error413\'\n        \'429\':\n          $ref: \'#/components/responses/Error429\'\n        \'500\':\n          $ref: \'#/components/responses/Error500\'\n        \'529\':\n          $ref: \'#/components/responses/Error529\'\n  /v1/organizations/api_keys:\n    get:\n      tags:\n        - Admin - API Keys\n      summary: List Api Keys\n      description: Retrieves a list of all API keys\n      security:\n        - ApiKeyAuth: []\n      parameters:\n        - $ref: \'#/components/parameters/AnthropicVersionHeader\'\n        - $ref: \'#/components/parameters/BeforeId\'\n        - $ref: \'#/components/parameters/AfterId\'\n        - $ref: \'#/components/parameters/Limit\'\n        - $ref: \'#/components/parameters/AnthropicDangerousDirectBrowserAccessHeader\'\n        - name: status\n          in: query\n          schema:\n            type: string\n            nullable: true\n            enum: [active, inactive, archived]\n          description: Filter by API key status.\n        - name: workspace_id\n          in: query\n          schema:\n            type: string\n            nullable: true\n          description: Filter by Workspace ID.\n        - name: created_by_user_id\n          in: query\n          schema:\n            type: string\n            nullable: true\n          description: Filter by the ID of the User who created the object.\n      responses:\n        \'200\':\n          description: API keys retrieved successfully\n          headers:\n            request-id:\n              $ref: \'#/components/headers/RequestId\'\n            anthropic-organization-id:\n              $ref: \'#/components/headers/AnthropicOrganizationId\'\n            retry-after:\n              $ref: \'#/components/headers/RetryAfter\'\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - data\n                  - first_id\n                  - has_more\n                  - last_id\n                properties:\n                  data:\n                    type: array\n                    items:\n                      $ref: \'#/components/schemas/AdminAPIKeyData\'\n                  first_id:\n                    $ref: \'#/components/schemas/FirstId\'\n                  has_more:\n                    $ref: \'#/components/schemas/HasMore\'\n                  last_id:\n                    $ref: \'#/components/schemas/LastId\'\n        \'400\':\n          $ref: \'#/components/responses/Error400\'\n        \'401\':\n          $ref: \'#/components/responses/Error401\'\n        \'403\':\n          $ref: \'#/components/responses/Error403\'\n        \'404\':\n          $ref: \'#/components/responses/Error404\'\n        \'413\':\n          $ref: \'#/components/responses/Error413\'\n        \'429\':\n          $ref: \'#/components/responses/Error429\'\n        \'500\':\n          $ref: \'#/components/responses/Error500\'\n        \'529\':\n          $ref: \'#/components/responses/Error529\'\n  /v1/organizations/api_keys/{api_key_id}:\n    get:\n      tags:\n        - Admin - API Keys\n      summary: Get Api Key\n      description: Retrieves details for a specific API key\n      security:\n        - ApiKeyAuth: []\n      parameters:\n        - $ref: \'#/components/parameters/AnthropicVersionHeader\'\n        - $ref: \'#/components/parameters/ApiKeyId\'\n        - $ref: \'#/components/parameters/AnthropicDangerousDirectBrowserAccessHeader\'\n      responses:\n        \'200\':\n          description: API key details retrieved successfully\n          headers:\n            request-id:\n              $ref: \'#/components/headers/RequestId\'\n            anthropic-organization-id:\n              $ref: \'#/components/headers/AnthropicOrganizationId\'\n            retry-after:\n              $ref: \'#/components/headers/RetryAfter\'\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/AdminAPIKeyData\'\n        \'400\':\n          $ref: \'#/components/responses/Error400\'\n        \'401\':\n          $ref: \'#/components/responses/Error401\'\n        \'403\':\n          $ref: \'#/components/responses/Error403\'\n        \'404\':\n          $ref: \'#/components/responses/Error404\'\n        \'413\':\n          $ref: \'#/components/responses/Error413\'\n        \'429\':\n          $ref: \'#/components/responses/Error429\'\n        \'500\':\n          $ref: \'#/components/responses/Error500\'\n        \'529\':\n          $ref: \'#/components/responses/Error529\'\n    post:\n      tags:\n        - Admin - API Keys\n      summary: Update Api Key\n      description: Updates details for a specific API key\n      security:\n        - ApiKeyAuth: []\n      parameters:\n        - $ref: \'#/components/parameters/AnthropicVersionHeader\'\n        - $ref: \'#/components/parameters/ApiKeyId\'\n        - $ref: \'#/components/parameters/AnthropicDangerousDirectBrowserAccessHeader\'\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              type: object\n              properties:\n                name:\n                  type: string\n                  minLength: 1\n                  maxLength: 500\n                  description: Name of the API key.\n                status:\n                  type: string\n                  nullable: true\n                  enum: [active, inactive, archived]\n                  description: Status of the API key.\n      responses:\n        \'200\':\n          description: API key updated successfully\n          headers:\n            request-id:\n              $ref: \'#/components/headers/RequestId\'\n            anthropic-organization-id:\n              $ref: \'#/components/headers/AnthropicOrganizationId\'\n            retry-after:\n              $ref: \'#/components/headers/RetryAfter\'\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/AdminAPIKeyData\'\n        \'400\':\n          $ref: \'#/components/responses/Error400\'\n        \'401\':\n          $ref: \'#/components/responses/Error401\'\n        \'403\':\n          $ref: \'#/components/responses/Error403\'\n        \'404\':\n          $ref: \'#/components/responses/Error404\'\n        \'413\':\n          $ref: \'#/components/responses/Error413\'\n        \'429\':\n          $ref: \'#/components/responses/Error429\'\n        \'500\':\n          $ref: \'#/components/responses/Error500\'\n        \'529\':\n          $ref: \'#/components/responses/Error529\'\n  /v1/experimental/generate_prompt:\n    post:\n      tags:\n        - Experimental - Prompt Tools\n      summary: Generate Prompt\n      description: Generates a prompt for a given input\n      security:\n        - ApiKeyAuth: []\n      parameters:\n        - $ref: \'#/components/parameters/AnthropicBetaHeader\'\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              type: object\n              required:\n                - task\n              properties:\n                task:\n                  type: string\n                  description: Description of the prompt\'s purpose.\n                target_model:\n                  type: string\n                  nullable: true\n                  description: The model this prompt will be used for.\n                  minLength: 1\n                  maxLength: 256\n      responses:\n        \'200\':\n          description: Successful response\n          headers:\n            request-id:\n              $ref: \'#/components/headers/RequestId\'\n            anthropic-organization-id:\n              $ref: \'#/components/headers/AnthropicOrganizationId\'\n            retry-after:\n              $ref: \'#/components/headers/RetryAfter\'\n            anthropic-ratelimit-requests-limit:\n              $ref: \'#/components/headers/AnthropicRateLimitRequestsLimit\'\n            anthropic-ratelimit-requests-remaining:\n              $ref: \'#/components/headers/AnthropicRateLimitRequestsRemaining\'\n            anthropic-ratelimit-requests-reset:\n              $ref: \'#/components/headers/AnthropicRateLimitRequestsReset\'\n            anthropic-ratelimit-tokens-limit:\n              $ref: \'#/components/headers/AnthropicRateLimitTokensLimit\'\n            anthropic-ratelimit-tokens-remaining:\n              $ref: \'#/components/headers/AnthropicRateLimitTokensRemaining\'\n            anthropic-ratelimit-tokens-reset:\n              $ref: \'#/components/headers/AnthropicRateLimitTokensReset\'\n            anthropic-ratelimit-input-tokens-limit:\n              $ref: \'#/components/headers/AnthropicRateLimitInputTokensLimit\'\n            anthropic-ratelimit-input-tokens-remaining:\n              $ref: \'#/components/headers/AnthropicRateLimitInputTokensRemaining\'\n            anthropic-ratelimit-input-tokens-reset:\n              $ref: \'#/components/headers/AnthropicRateLimitInputTokensReset\'\n            anthropic-ratelimit-output-tokens-limit:\n              $ref: \'#/components/headers/AnthropicRateLimitOutputTokensLimit\'\n            anthropic-ratelimit-output-tokens-remaining:\n              $ref: \'#/components/headers/AnthropicRateLimitOutputTokensRemaining\'\n            anthropic-ratelimit-output-tokens-reset:\n              $ref: \'#/components/headers/AnthropicRateLimitOutputTokensReset\'\n            anthropic-priority-input-tokens-limit:\n              $ref: \'#/components/headers/AnthropicPriorityInputTokensLimit\'\n            anthropic-priority-input-tokens-remaining:\n              $ref: \'#/components/headers/AnthropicPriorityInputTokensRemaining\'\n            anthropic-priority-input-tokens-reset:\n              $ref: \'#/components/headers/AnthropicPriorityInputTokensReset\'\n            anthropic-priority-output-tokens-limit:\n              $ref: \'#/components/headers/AnthropicPriorityOutputTokensLimit\'\n            anthropic-priority-output-tokens-remaining:\n              $ref: \'#/components/headers/AnthropicPriorityOutputTokensRemaining\'\n            anthropic-priority-output-tokens-reset:\n              $ref: \'#/components/headers/AnthropicPriorityOutputTokensReset\'\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - message\n                  - system\n                  - usage\n                properties:\n                  messages:\n                    type: array\n                    description: The response contains a list of message objects in the same format used by the Messages API. Typically includes a user message with the complete generated prompt text, and may include an assistant message with a prefill to guide the model\'s initial response. These messages can be used directly in a Messages API request to start a conversation with the generated prompt.\n                    items:\n                      $ref: \'#/components/schemas/Message\'\n                  system:\n                    type: string\n                    default: \"\"\n                    description: Currently, the system field is always returned as an empty string (\"\"). In future iterations, this field may contain generated system prompts. Directions similar to what would normally be included in a system prompt are included in messages when generating a prompt.\n                  usage:\n                    $ref: \'#/components/schemas/Usage\'\n        \'400\':\n          $ref: \'#/components/responses/Error400\'\n        \'401\':\n          $ref: \'#/components/responses/Error401\'\n        \'403\':\n          $ref: \'#/components/responses/Error403\'\n        \'404\':\n          $ref: \'#/components/responses/Error404\'\n        \'413\':\n          $ref: \'#/components/responses/Error413\'\n        \'429\':\n          $ref: \'#/components/responses/Error429\'\n        \'500\':\n          $ref: \'#/components/responses/Error500\'\n        \'529\':\n          $ref: \'#/components/responses/Error529\'\n  /v1/experimental/improve_prompt:\n    post:\n      tags:\n        - Experimental - Prompt Tools\n      summary: Improve Prompt\n      description: Improves a prompt for a given input\n      security:\n        - ApiKeyAuth: []\n      parameters:\n        - $ref: \'#/components/parameters/AnthropicBetaHeader\'\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              type: object\n              required:\n                - message\n              properties:\n                messages:\n                  type: array\n                  description: The response contains a list of message objects in the same format used by the Messages API. Typically includes a user message with the complete generated prompt text, and may include an assistant message with a prefill to guide the model\'s initial response. These messages can be used directly in a Messages API request to start a conversation with the generated prompt.\n                  items:\n                    $ref: \'#/components/schemas/Message\'\n                feedback:\n                  type: string\n                  nullable: true\n                system:\n                  type: string\n                  nullable: true\n                target_model:\n                  type: string\n                  nullable: true\n                  description: The model this prompt will be used for.\n                  minLength: 1\n                  maxLength: 256\n      responses:\n        \'200\':\n          description: Successful response\n          headers:\n            request-id:\n              $ref: \'#/components/headers/RequestId\'\n            anthropic-organization-id:\n              $ref: \'#/components/headers/AnthropicOrganizationId\'\n            retry-after:\n              $ref: \'#/components/headers/RetryAfter\'\n            anthropic-ratelimit-requests-limit:\n              $ref: \'#/components/headers/AnthropicRateLimitRequestsLimit\'\n            anthropic-ratelimit-requests-remaining:\n              $ref: \'#/components/headers/AnthropicRateLimitRequestsRemaining\'\n            anthropic-ratelimit-requests-reset:\n              $ref: \'#/components/headers/AnthropicRateLimitRequestsReset\'\n            anthropic-ratelimit-tokens-limit:\n              $ref: \'#/components/headers/AnthropicRateLimitTokensLimit\'\n            anthropic-ratelimit-tokens-remaining:\n              $ref: \'#/components/headers/AnthropicRateLimitTokensRemaining\'\n            anthropic-ratelimit-tokens-reset:\n              $ref: \'#/components/headers/AnthropicRateLimitTokensReset\'\n            anthropic-ratelimit-input-tokens-limit:\n              $ref: \'#/components/headers/AnthropicRateLimitInputTokensLimit\'\n            anthropic-ratelimit-input-tokens-remaining:\n              $ref: \'#/components/headers/AnthropicRateLimitInputTokensRemaining\'\n            anthropic-ratelimit-input-tokens-reset:\n              $ref: \'#/components/headers/AnthropicRateLimitInputTokensReset\'\n            anthropic-ratelimit-output-tokens-limit:\n              $ref: \'#/components/headers/AnthropicRateLimitOutputTokensLimit\'\n            anthropic-ratelimit-output-tokens-remaining:\n              $ref: \'#/components/headers/AnthropicRateLimitOutputTokensRemaining\'\n            anthropic-ratelimit-output-tokens-reset:\n              $ref: \'#/components/headers/AnthropicRateLimitOutputTokensReset\'\n            anthropic-priority-input-tokens-limit:\n              $ref: \'#/components/headers/AnthropicPriorityInputTokensLimit\'\n            anthropic-priority-input-tokens-remaining:\n              $ref: \'#/components/headers/AnthropicPriorityInputTokensRemaining\'\n            anthropic-priority-input-tokens-reset:\n              $ref: \'#/components/headers/AnthropicPriorityInputTokensReset\'\n            anthropic-priority-output-tokens-limit:\n              $ref: \'#/components/headers/AnthropicPriorityOutputTokensLimit\'\n            anthropic-priority-output-tokens-remaining:\n              $ref: \'#/components/headers/AnthropicPriorityOutputTokensRemaining\'\n            anthropic-priority-output-tokens-reset:\n              $ref: \'#/components/headers/AnthropicPriorityOutputTokensReset\'\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - message\n                  - system\n                  - usage\n                properties:\n                  messages:\n                    type: array\n                    description: The response contains a list of message objects in the same format used by the Messages API. Typically includes a user message with the complete generated prompt text, and may include an assistant message with a prefill to guide the model\'s initial response. These messages can be used directly in a Messages API request to start a conversation with the generated prompt.\n                    items:\n                      $ref: \'#/components/schemas/Message\'\n                  system:\n                    type: string\n                    default: \"\"\n                    description: Currently, the system field is always returned as an empty string (\"\"). In future iterations, this field may contain generated system prompts. Directions similar to what would normally be included in a system prompt are included in messages when generating a prompt.\n                  usage:\n                    $ref: \'#/components/schemas/Usage\'\n        \'400\':\n          $ref: \'#/components/responses/Error400\'\n        \'401\':\n          $ref: \'#/components/responses/Error401\'\n        \'403\':\n          $ref: \'#/components/responses/Error403\'\n        \'404\':\n          $ref: \'#/components/responses/Error404\'\n        \'413\':\n          $ref: \'#/components/responses/Error413\'\n        \'429\':\n          $ref: \'#/components/responses/Error429\'\n        \'500\':\n          $ref: \'#/components/responses/Error500\'\n        \'529\':\n          $ref: \'#/components/responses/Error529\'\n  /v1/experimental/templatize_prompt:\n    post:\n      tags:\n        - Experimental - Prompt Tools\n      summary: Templatize Prompt\n      description: Templatizes a prompt for a given input\n      security:\n        - ApiKeyAuth: []\n      parameters:\n        - $ref: \'#/components/parameters/AnthropicBetaHeader\'\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              type: object\n              required:\n                - message\n              properties:\n                messages:\n                  type: array\n                  description: The response contains a list of message objects in the same format used by the Messages API. Typically includes a user message with the complete generated prompt text, and may include an assistant message with a prefill to guide the model\'s initial response. These messages can be used directly in a Messages API request to start a conversation with the generated prompt.\n                  items:\n                    $ref: \'#/components/schemas/Message\'\n                system:\n                  type: string\n                  nullable: true\n      responses:\n        \'200\':\n          description: Successful response\n          headers:\n            request-id:\n              $ref: \'#/components/headers/RequestId\'\n            anthropic-organization-id:\n              $ref: \'#/components/headers/AnthropicOrganizationId\'\n            retry-after:\n              $ref: \'#/components/headers/RetryAfter\'\n            anthropic-ratelimit-requests-limit:\n              $ref: \'#/components/headers/AnthropicRateLimitRequestsLimit\'\n            anthropic-ratelimit-requests-remaining:\n              $ref: \'#/components/headers/AnthropicRateLimitRequestsRemaining\'\n            anthropic-ratelimit-requests-reset:\n              $ref: \'#/components/headers/AnthropicRateLimitRequestsReset\'\n            anthropic-ratelimit-tokens-limit:\n              $ref: \'#/components/headers/AnthropicRateLimitTokensLimit\'\n            anthropic-ratelimit-tokens-remaining:\n              $ref: \'#/components/headers/AnthropicRateLimitTokensRemaining\'\n            anthropic-ratelimit-tokens-reset:\n              $ref: \'#/components/headers/AnthropicRateLimitTokensReset\'\n            anthropic-ratelimit-input-tokens-limit:\n              $ref: \'#/components/headers/AnthropicRateLimitInputTokensLimit\'\n            anthropic-ratelimit-input-tokens-remaining:\n              $ref: \'#/components/headers/AnthropicRateLimitInputTokensRemaining\'\n            anthropic-ratelimit-input-tokens-reset:\n              $ref: \'#/components/headers/AnthropicRateLimitInputTokensReset\'\n            anthropic-ratelimit-output-tokens-limit:\n              $ref: \'#/components/headers/AnthropicRateLimitOutputTokensLimit\'\n            anthropic-ratelimit-output-tokens-remaining:\n              $ref: \'#/components/headers/AnthropicRateLimitOutputTokensRemaining\'\n            anthropic-ratelimit-output-tokens-reset:\n              $ref: \'#/components/headers/AnthropicRateLimitOutputTokensReset\'\n            anthropic-priority-input-tokens-limit:\n              $ref: \'#/components/headers/AnthropicPriorityInputTokensLimit\'\n            anthropic-priority-input-tokens-remaining:\n              $ref: \'#/components/headers/AnthropicPriorityInputTokensRemaining\'\n            anthropic-priority-input-tokens-reset:\n              $ref: \'#/components/headers/AnthropicPriorityInputTokensReset\'\n            anthropic-priority-output-tokens-limit:\n              $ref: \'#/components/headers/AnthropicPriorityOutputTokensLimit\'\n            anthropic-priority-output-tokens-remaining:\n              $ref: \'#/components/headers/AnthropicPriorityOutputTokensRemaining\'\n            anthropic-priority-output-tokens-reset:\n              $ref: \'#/components/headers/AnthropicPriorityOutputTokensReset\'\n          content:\n            application/json:\n              schema:\n                type: object\n                required:\n                  - message\n                  - system\n                  - usage\n                  - variable_values\n                properties:\n                  messages:\n                    type: array\n                    description: The response contains a list of message objects in the same format used by the Messages API. Typically includes a user message with the complete generated prompt text, and may include an assistant message with a prefill to guide the model\'s initial response. These messages can be used directly in a Messages API request to start a conversation with the generated prompt.\n                    items:\n                      $ref: \'#/components/schemas/Message\'\n                  system:\n                    type: string\n                    default: \"\"\n                    description: Currently, the system field is always returned as an empty string (\"\"). In future iterations, this field may contain generated system prompts. Directions similar to what would normally be included in a system prompt are included in messages when generating a prompt.\n                  usage:\n                    $ref: \'#/components/schemas/Usage\'\n                  variable_values:\n                    type: object\n                    description: A mapping of template variable names to their original values, as extracted from the input prompt during templatization. Each key represents a variable name identified in the templatized prompt, and each value contains the corresponding content from the original prompt that was replaced by that variable.\n                    additionalProperties:\n                      type: string\n        \'400\':\n          $ref: \'#/components/responses/Error400\'\n        \'401\':\n          $ref: \'#/components/responses/Error401\'\n        \'403\':\n          $ref: \'#/components/responses/Error403\'\n        \'404\':\n          $ref: \'#/components/responses/Error404\'\n        \'413\':\n          $ref: \'#/components/responses/Error413\'\n        \'429\':\n          $ref: \'#/components/responses/Error429\'\n        \'500\':\n          $ref: \'#/components/responses/Error500\'\n        \'529\':\n          $ref: \'#/components/responses/Error529\'\nx-wso2-cors:\n  corsConfigurationEnabled: true\n  accessControlAllowOrigins:\n    - \'*\'\n  accessControlAllowCredentials: false\n  accessControlAllowHeaders:\n    - authorization\n    - Access-Control-Allow-Origin\n    - Content-Type\n    - SOAPAction\n    - apikey\n    - Internal-Key\n    - anthropic-version\n    - anthropic-beta\n    - anthropic-dangerous-direct-browser-access\n  accessControlAllowMethods:\n    - GET\n    - PUT\n    - POST\n    - DELETE\n    - PATCH\n    - OPTIONS\n','false'),('2784c31f-bb0d-4d7c-bba4-53c66b5b56ab','MistralAI','1.0.0','adpsample.com','true','Mistral AI service',_binary '{\"connectorType\":\"mistralAi_1.0.0\",\"metadata\":[{\"attributeName\":\"requestModel\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.model\",\"required\":false},{\"attributeName\":\"responseModel\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.model\",\"required\":true},{\"attributeName\":\"promptTokenCount\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.usage.prompt_tokens\",\"required\":true},{\"attributeName\":\"completionTokenCount\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.usage.completion_tokens\",\"required\":true},{\"attributeName\":\"totalTokenCount\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.usage.total_tokens\",\"required\":true},{\"attributeName\":\"remainingTokenCount\",\"inputSource\":\"header\",\"attributeIdentifier\":\"x-ratelimit-remaining-tokens\",\"required\":false}],\"authHeader\":\"Authorization\"}',_binary 'openapi: 3.1.0\ninfo:\n  title: Mistral AI API\n  description: >-\n    Our Chat Completion and Embeddings APIs specification. Create your account\n    on [La Plateforme](https://console.mistral.ai) to get access and read the\n    [docs](https://docs.mistral.ai) to learn how to use it.\n  version: 0.0.2\npaths:\n  /v1/models:\n    get:\n      summary: List Models\n      description: List all models available to the user.\n      operationId: list_models_v1_models_get\n      responses:\n        \'200\':\n          description: Successful Response\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/ModelList\'\n        \'422\':\n          description: Validation Error\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/HTTPValidationError\'\n      tags:\n        - models\n  /v1/models/{model_id}:\n    get:\n      summary: Retrieve Model\n      description: Retrieve a model information.\n      operationId: retrieve_model_v1_models__model_id__get\n      parameters:\n        - name: model_id\n          in: path\n          required: true\n          schema:\n            type: string\n            title: Model Id\n          example: ft:open-mistral-7b:587a6b29:20240514:7e773925\n          description: The ID of the model to retrieve.\n      responses:\n        \'200\':\n          description: Successful Response\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/ModelCard\'\n        \'422\':\n          description: Validation Error\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/HTTPValidationError\'\n      tags:\n        - models\n    delete:\n      summary: Delete Model\n      description: Delete a fine-tuned model.\n      operationId: delete_model_v1_models__model_id__delete\n      parameters:\n        - name: model_id\n          in: path\n          required: true\n          schema:\n            type: string\n            title: Model Id\n          example: ft:open-mistral-7b:587a6b29:20240514:7e773925\n          description: The ID of the model to delete.\n      responses:\n        \'200\':\n          description: Successful Response\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/DeleteModelOut\'\n        \'422\':\n          description: Validation Error\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/HTTPValidationError\'\n      tags:\n        - models\n  /v1/files:\n    post:\n      operationId: files_api_routes_upload_file\n      summary: Upload File\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/UploadFileOut\'\n      description: >-\n        Upload a file that can be used across various endpoints.\n\n\n        The size of individual files can be a maximum of 512 MB. The Fine-tuning\n        API only supports .jsonl files.\n\n\n        Please contact us if you need to increase these storage limits.\n      requestBody:\n        content:\n          multipart/form-data:\n            schema:\n              title: MultiPartBodyParams\n              type: object\n              properties:\n                purpose:\n                  const: fine-tune\n                  default: fine-tune\n                  enum:\n                    - fine-tune\n                  title: Purpose\n                  type: string\n                file:\n                  format: binary\n                  title: File\n                  type: string\n                  description: |-\n                    The File object (not file name) to be uploaded.\n                     To upload a file and specify a custom file name you should format your request as such:\n                     ```bash\n                     file=@path/to/your/file.jsonl;filename=custom_name.jsonl\n                     ```\n                     Otherwise, you can just keep the original file name:\n                     ```bash\n                     file=@path/to/your/file.jsonl\n                     ```\n              required:\n                - file\n        required: true\n      tags:\n        - files\n    get:\n      operationId: files_api_routes_list_files\n      summary: List Files\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/ListFilesOut\'\n      description: Returns a list of files that belong to the user\'s organization.\n      tags:\n        - files\n  /v1/files/{file_id}:\n    get:\n      operationId: files_api_routes_retrieve_file\n      summary: Retrieve File\n      parameters:\n        - in: path\n          name: file_id\n          schema:\n            title: File Id\n            type: string\n          required: true\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/RetrieveFileOut\'\n      description: Returns information about a specific file.\n      tags:\n        - files\n    delete:\n      operationId: files_api_routes_delete_file\n      summary: Delete File\n      parameters:\n        - in: path\n          name: file_id\n          schema:\n            title: File Id\n            type: string\n          required: true\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/DeleteFileOut\'\n      description: Delete a file.\n      tags:\n        - files\n  /v1/fine_tuning/jobs:\n    get:\n      operationId: jobs_api_routes_fine_tuning_get_fine_tuning_jobs\n      summary: Get Fine Tuning Jobs\n      parameters:\n        - in: query\n          name: page\n          schema:\n            default: 0\n            title: Page\n            type: integer\n          required: false\n          description: The page number of the results to be returned.\n        - in: query\n          name: page_size\n          schema:\n            default: 100\n            title: Page Size\n            type: integer\n          required: false\n          description: The number of items to return per page.\n        - in: query\n          name: model\n          schema:\n            anyOf:\n              - type: string\n              - type: \'null\'\n            title: Model\n          required: false\n          description: >-\n            The model name used for fine-tuning to filter on. When set, the\n            other results are not displayed.\n        - in: query\n          name: created_after\n          schema:\n            anyOf:\n              - format: date-time\n                type: string\n              - type: \'null\'\n            title: Created After\n          required: false\n          description: >-\n            The date/time to filter on. When set, the results for previous\n            creation times are not displayed.\n        - in: query\n          name: created_by_me\n          schema:\n            default: false\n            title: Created By Me\n            type: boolean\n          required: false\n          description: >-\n            When set, only return results for jobs created by the API caller.\n            Other results are not displayed.\n        - in: query\n          name: status\n          schema:\n            anyOf:\n              - enum:\n                  - QUEUED\n                  - STARTED\n                  - VALIDATING\n                  - VALIDATED\n                  - RUNNING\n                  - FAILED_VALIDATION\n                  - FAILED\n                  - SUCCESS\n                  - CANCELLED\n                  - CANCELLATION_REQUESTED\n                type: string\n              - type: \'null\'\n            title: Status\n          required: false\n          description: >-\n            The current job state to filter on. When set, the other results are\n            not displayed.\n        - in: query\n          name: wandb_project\n          schema:\n            anyOf:\n              - type: string\n              - type: \'null\'\n            title: Wandb Project\n          required: false\n          description: >-\n            The Weights and Biases project to filter on. When set, the other\n            results are not displayed.\n        - in: query\n          name: wandb_name\n          schema:\n            anyOf:\n              - type: string\n              - type: \'null\'\n            title: Wandb Name\n          required: false\n          description: >-\n            The Weight and Biases run name to filter on. When set, the other\n            results are not displayed.\n        - in: query\n          name: suffix\n          schema:\n            anyOf:\n              - type: string\n              - type: \'null\'\n            title: Suffix\n          required: false\n          description: >-\n            The model suffix to filter on. When set, the other results are not\n            displayed.\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/JobsOut\'\n      description: Get a list of fine-tuning jobs for your organization and user.\n      tags:\n        - fine-tuning\n    post:\n      operationId: jobs_api_routes_fine_tuning_create_fine_tuning_job\n      summary: Create Fine Tuning Job\n      parameters:\n        - in: query\n          name: dry_run\n          schema:\n            anyOf:\n              - type: boolean\n              - type: \'null\'\n            title: Dry Run\n          required: false\n          description: >\n            * If `true` the job is not spawned, instead the query returns a\n            handful of useful metadata\n              for the user to perform sanity checks (see `LegacyJobMetadataOut` response).\n            * Otherwise, the job is started and the query returns the job ID\n            along with some of the\n              input parameters (see `JobOut` response).\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                anyOf:\n                  - $ref: \'#/components/schemas/JobOut\'\n                  - $ref: \'#/components/schemas/LegacyJobMetadataOut\'\n                title: Response\n      description: Create a new fine-tuning job, it will be queued for processing.\n      requestBody:\n        content:\n          application/json:\n            schema:\n              $ref: \'#/components/schemas/JobIn\'\n        required: true\n      tags:\n        - fine-tuning\n  /v1/fine_tuning/jobs/{job_id}:\n    get:\n      operationId: jobs_api_routes_fine_tuning_get_fine_tuning_job\n      summary: Get Fine Tuning Job\n      parameters:\n        - in: path\n          name: job_id\n          schema:\n            format: uuid\n            title: Job Id\n            type: string\n          required: true\n          description: The ID of the job to analyse.\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/DetailedJobOut\'\n      description: Get a fine-tuned job details by its UUID.\n      tags:\n        - fine-tuning\n  /v1/fine_tuning/jobs/{job_id}/cancel:\n    post:\n      operationId: jobs_api_routes_fine_tuning_cancel_fine_tuning_job\n      summary: Cancel Fine Tuning Job\n      parameters:\n        - in: path\n          name: job_id\n          schema:\n            format: uuid\n            title: Job Id\n            type: string\n          required: true\n          description: The ID of the job to cancel.\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/DetailedJobOut\'\n      description: Request the cancellation of a fine tuning job.\n      tags:\n        - fine-tuning\n  /v1/fine_tuning/jobs/{job_id}/start:\n    post:\n      operationId: jobs_api_routes_fine_tuning_start_fine_tuning_job\n      summary: Start Fine Tuning Job\n      parameters:\n        - in: path\n          name: job_id\n          schema:\n            format: uuid\n            title: Job Id\n            type: string\n          required: true\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/DetailedJobOut\'\n      description: Request the start of a validated fine tuning job.\n      tags:\n        - fine-tuning\n  /v1/fine_tuning/models/{model_id}:\n    patch:\n      operationId: jobs_api_routes_fine_tuning_update_fine_tuned_model\n      summary: Update Fine Tuned Model\n      parameters:\n        - in: path\n          name: model_id\n          schema:\n            title: Model Id\n            type: string\n          required: true\n          example: ft:open-mistral-7b:587a6b29:20240514:7e773925\n          description: The ID of the model to update.\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/FTModelOut\'\n      description: Update a model name or description.\n      requestBody:\n        content:\n          application/json:\n            schema:\n              $ref: \'#/components/schemas/UpdateFTModelIn\'\n        required: true\n      tags:\n        - models\n  /v1/fine_tuning/models/{model_id}/archive:\n    post:\n      operationId: jobs_api_routes_fine_tuning_archive_fine_tuned_model\n      summary: Archive Fine Tuned Model\n      parameters:\n        - in: path\n          name: model_id\n          schema:\n            title: Model Id\n            type: string\n          required: true\n          example: ft:open-mistral-7b:587a6b29:20240514:7e773925\n          description: The ID of the model to archive.\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/ArchiveFTModelOut\'\n      description: Archive a fine-tuned model.\n      tags:\n        - models\n    delete:\n      operationId: jobs_api_routes_fine_tuning_unarchive_fine_tuned_model\n      summary: Unarchive Fine Tuned Model\n      parameters:\n        - in: path\n          name: model_id\n          schema:\n            title: Model Id\n            type: string\n          required: true\n          example: ft:open-mistral-7b:587a6b29:20240514:7e773925\n          description: The ID of the model to unarchive.\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/UnarchiveFTModelOut\'\n      description: Un-archive a fine-tuned model.\n      tags:\n        - models\n  /v1/chat/completions:\n    post:\n      summary: Chat Completion\n      operationId: chat_completion_v1_chat_completions_post\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \'#/components/schemas/ChatCompletionRequest\'\n      responses:\n        \'200\':\n          description: Successful Response\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/ChatCompletionResponse\'\n            text/event-stream:\n              schema:\n                $ref: \'#/components/schemas/CompletionEvent\'\n        \'422\':\n          description: Validation Error\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/HTTPValidationError\'\n      tags:\n        - chat\n  /v1/fim/completions:\n    post:\n      summary: Fim Completion\n      description: FIM completion.\n      operationId: fim_completion_v1_fim_completions_post\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \'#/components/schemas/FIMCompletionRequest\'\n      responses:\n        \'200\':\n          description: Successful Response\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/FIMCompletionResponse\'\n            text/event-stream:\n              schema:\n                $ref: \'#/components/schemas/CompletionEvent\'\n        \'422\':\n          description: Validation Error\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/HTTPValidationError\'\n      tags:\n        - fim\n  /v1/agents/completions:\n    post:\n      summary: Agents Completion\n      operationId: agents_completion_v1_agents_completions_post\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \'#/components/schemas/AgentsCompletionRequest\'\n      responses:\n        \'200\':\n          description: Successful Response\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/ChatCompletionResponse\'\n        \'422\':\n          description: Validation Error\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/HTTPValidationError\'\n      tags:\n        - agents\n  /v1/embeddings:\n    post:\n      summary: Embeddings\n      description: Embeddings\n      operationId: embeddings_v1_embeddings_post\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \'#/components/schemas/EmbeddingRequest\'\n      responses:\n        \'200\':\n          description: Successful Response\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/EmbeddingResponse\'\n        \'422\':\n          description: Validation Error\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/HTTPValidationError\'\n      tags:\n        - embeddings\ncomponents:\n  schemas:\n    DeleteModelOut:\n      properties:\n        id:\n          type: string\n          title: Id\n          description: The ID of the deleted model.\n          examples:\n            - ft:open-mistral-7b:587a6b29:20240514:7e773925\n        object:\n          type: string\n          title: Object\n          default: model\n          description: The object type that was deleted\n        deleted:\n          type: boolean\n          title: Deleted\n          default: true\n          description: The deletion status\n          examples:\n            - true\n      type: object\n      required:\n        - id\n      title: DeleteModelOut\n    HTTPValidationError:\n      properties:\n        detail:\n          items:\n            $ref: \'#/components/schemas/ValidationError\'\n          type: array\n          title: Detail\n      type: object\n      title: HTTPValidationError\n    ModelCapabilities:\n      properties:\n        completion_chat:\n          type: boolean\n          title: Completion Chat\n          default: true\n        completion_fim:\n          type: boolean\n          title: Completion Fim\n          default: false\n        function_calling:\n          type: boolean\n          title: Function Calling\n          default: true\n        fine_tuning:\n          type: boolean\n          title: Fine Tuning\n          default: false\n      type: object\n      title: ModelCapabilities\n    ModelCard:\n      properties:\n        id:\n          type: string\n          title: Id\n        object:\n          type: string\n          title: Object\n          default: model\n        created:\n          type: integer\n          title: Created\n        owned_by:\n          type: string\n          title: Owned By\n          default: mistralai\n        root:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Root\n        archived:\n          type: boolean\n          title: Archived\n          default: false\n        name:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Name\n        description:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Description\n        capabilities:\n          $ref: \'#/components/schemas/ModelCapabilities\'\n        max_context_length:\n          type: integer\n          title: Max Context Length\n          default: 32768\n        aliases:\n          items:\n            type: string\n          type: array\n          title: Aliases\n          default: []\n        deprecation:\n          anyOf:\n            - type: string\n              format: date-time\n            - type: \'null\'\n          title: Deprecation\n      type: object\n      required:\n        - id\n        - capabilities\n      title: ModelCard\n    ModelList:\n      properties:\n        object:\n          type: string\n          title: Object\n          default: list\n        data:\n          items:\n            $ref: \'#/components/schemas/ModelCard\'\n          type: array\n          title: Data\n      type: object\n      title: ModelList\n    ValidationError:\n      properties:\n        loc:\n          items:\n            anyOf:\n              - type: string\n              - type: integer\n          type: array\n          title: Location\n        msg:\n          type: string\n          title: Message\n        type:\n          type: string\n          title: Error Type\n      type: object\n      required:\n        - loc\n        - msg\n        - type\n      title: ValidationError\n    SampleType:\n      enum:\n        - pretrain\n        - instruct\n      title: SampleType\n      type: string\n    Source:\n      enum:\n        - upload\n        - repository\n      title: Source\n      type: string\n    UploadFileOut:\n      properties:\n        id:\n          format: uuid\n          title: Id\n          type: string\n          description: The unique identifier of the file.\n          examples:\n            - 497f6eca-6276-4993-bfeb-53cbbbba6f09\n        object:\n          title: Object\n          type: string\n          description: The object type, which is always \"file\".\n          examples:\n            - file\n        bytes:\n          title: Bytes\n          type: integer\n          description: The size of the file, in bytes.\n          examples:\n            - 13000\n        created_at:\n          title: Created At\n          type: integer\n          description: The UNIX timestamp (in seconds) of the event.\n          examples:\n            - 1716963433\n        filename:\n          title: Filename\n          type: string\n          description: The name of the uploaded file.\n          examples:\n            - files_upload.jsonl\n        purpose:\n          const: fine-tune\n          enum:\n            - fine-tune\n          title: Purpose\n          type: string\n          description: >-\n            The intended purpose of the uploaded file. Only accepts fine-tuning\n            (`fine-tune`) for now.\n          examples:\n            - fine-tune\n        sample_type:\n          $ref: \'#/components/schemas/SampleType\'\n        num_lines:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Num Lines\n        source:\n          $ref: \'#/components/schemas/Source\'\n      required:\n        - id\n        - object\n        - bytes\n        - created_at\n        - filename\n        - purpose\n        - sample_type\n        - source\n      title: UploadFileOut\n      type: object\n    FileSchema:\n      properties:\n        id:\n          format: uuid\n          title: Id\n          type: string\n          description: The unique identifier of the file.\n          examples:\n            - 497f6eca-6276-4993-bfeb-53cbbbba6f09\n        object:\n          title: Object\n          type: string\n          description: The object type, which is always \"file\".\n          examples:\n            - file\n        bytes:\n          title: Bytes\n          type: integer\n          description: The size of the file, in bytes.\n          examples:\n            - 13000\n        created_at:\n          title: Created At\n          type: integer\n          description: The UNIX timestamp (in seconds) of the event.\n          examples:\n            - 1716963433\n        filename:\n          title: Filename\n          type: string\n          description: The name of the uploaded file.\n          examples:\n            - files_upload.jsonl\n        purpose:\n          const: fine-tune\n          enum:\n            - fine-tune\n          title: Purpose\n          type: string\n          description: >-\n            The intended purpose of the uploaded file. Only accepts fine-tuning\n            (`fine-tune`) for now.\n          examples:\n            - fine-tune\n        sample_type:\n          $ref: \'#/components/schemas/SampleType\'\n        num_lines:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Num Lines\n        source:\n          $ref: \'#/components/schemas/Source\'\n      required:\n        - id\n        - object\n        - bytes\n        - created_at\n        - filename\n        - purpose\n        - sample_type\n        - source\n      title: FileSchema\n      type: object\n    ListFilesOut:\n      properties:\n        data:\n          items:\n            $ref: \'#/components/schemas/FileSchema\'\n          title: Data\n          type: array\n        object:\n          title: Object\n          type: string\n      required:\n        - data\n        - object\n      title: ListFilesOut\n      type: object\n    RetrieveFileOut:\n      properties:\n        id:\n          format: uuid\n          title: Id\n          type: string\n          description: The unique identifier of the file.\n          examples:\n            - 497f6eca-6276-4993-bfeb-53cbbbba6f09\n        object:\n          title: Object\n          type: string\n          description: The object type, which is always \"file\".\n          examples:\n            - file\n        bytes:\n          title: Bytes\n          type: integer\n          description: The size of the file, in bytes.\n          examples:\n            - 13000\n        created_at:\n          title: Created At\n          type: integer\n          description: The UNIX timestamp (in seconds) of the event.\n          examples:\n            - 1716963433\n        filename:\n          title: Filename\n          type: string\n          description: The name of the uploaded file.\n          examples:\n            - files_upload.jsonl\n        purpose:\n          const: fine-tune\n          enum:\n            - fine-tune\n          title: Purpose\n          type: string\n          description: >-\n            The intended purpose of the uploaded file. Only accepts fine-tuning\n            (`fine-tune`) for now.\n          examples:\n            - fine-tune\n        sample_type:\n          $ref: \'#/components/schemas/SampleType\'\n        num_lines:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Num Lines\n        source:\n          $ref: \'#/components/schemas/Source\'\n      required:\n        - id\n        - object\n        - bytes\n        - created_at\n        - filename\n        - purpose\n        - sample_type\n        - source\n      title: RetrieveFileOut\n      type: object\n    DeleteFileOut:\n      properties:\n        id:\n          format: uuid\n          title: Id\n          type: string\n          description: The ID of the deleted file.\n          examples:\n            - 497f6eca-6276-4993-bfeb-53cbbbba6f09\n        object:\n          title: Object\n          type: string\n          description: The object type that was deleted\n          examples:\n            - file\n        deleted:\n          title: Deleted\n          type: boolean\n          description: The deletion status.\n          examples:\n            - false\n      required:\n        - id\n        - object\n        - deleted\n      title: DeleteFileOut\n      type: object\n    FineTuneableModel:\n      enum:\n        - open-mistral-7b\n        - mistral-small-latest\n        - codestral-latest\n        - mistral-large-latest\n        - open-mistral-nemo\n      title: FineTuneableModel\n      type: string\n      description: The name of the model to fine-tune.\n    GithubRepositoryOut:\n      properties:\n        type:\n          const: github\n          default: github\n          enum:\n            - github\n          title: Type\n          type: string\n        name:\n          title: Name\n          type: string\n        owner:\n          title: Owner\n          type: string\n        ref:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Ref\n        weight:\n          default: 1\n          exclusiveMinimum: 0\n          title: Weight\n          type: number\n        commit_id:\n          maxLength: 40\n          minLength: 40\n          title: Commit Id\n          type: string\n      required:\n        - name\n        - owner\n        - commit_id\n      title: GithubRepositoryOut\n      type: object\n    JobMetadataOut:\n      properties:\n        expected_duration_seconds:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Expected Duration Seconds\n        cost:\n          anyOf:\n            - type: number\n            - type: \'null\'\n          title: Cost\n        cost_currency:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Cost Currency\n        train_tokens_per_step:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Train Tokens Per Step\n        train_tokens:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Train Tokens\n        data_tokens:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Data Tokens\n        estimated_start_time:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Estimated Start Time\n      title: JobMetadataOut\n      type: object\n    JobOut:\n      properties:\n        id:\n          format: uuid\n          title: Id\n          type: string\n          description: The ID of the job.\n        auto_start:\n          title: Auto Start\n          type: boolean\n        hyperparameters:\n          $ref: \'#/components/schemas/TrainingParameters\'\n        model:\n          $ref: \'#/components/schemas/FineTuneableModel\'\n        status:\n          enum:\n            - QUEUED\n            - STARTED\n            - VALIDATING\n            - VALIDATED\n            - RUNNING\n            - FAILED_VALIDATION\n            - FAILED\n            - SUCCESS\n            - CANCELLED\n            - CANCELLATION_REQUESTED\n          title: Status\n          type: string\n          description: The current status of the fine-tuning job.\n        job_type:\n          title: Job Type\n          type: string\n          description: The type of job (`FT` for fine-tuning).\n        created_at:\n          title: Created At\n          type: integer\n          description: >-\n            The UNIX timestamp (in seconds) for when the fine-tuning job was\n            created.\n        modified_at:\n          title: Modified At\n          type: integer\n          description: >-\n            The UNIX timestamp (in seconds) for when the fine-tuning job was\n            last modified.\n        training_files:\n          items:\n            format: uuid\n            type: string\n          title: Training Files\n          type: array\n          description: >-\n            A list containing the IDs of uploaded files that contain training\n            data.\n        validation_files:\n          anyOf:\n            - items:\n                format: uuid\n                type: string\n              type: array\n            - type: \'null\'\n          default: []\n          title: Validation Files\n          description: >-\n            A list containing the IDs of uploaded files that contain validation\n            data.\n        object:\n          const: job\n          default: job\n          enum:\n            - job\n          title: Object\n          type: string\n          description: The object type of the fine-tuning job.\n        fine_tuned_model:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Fine Tuned Model\n          description: >-\n            The name of the fine-tuned model that is being created. The value\n            will be `null` if the fine-tuning job is still running.\n        suffix:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Suffix\n          description: >-\n            Optional text/code that adds more context for the model. When given\n            a `prompt` and a `suffix` the model will fill what is between them.\n            When `suffix` is not provided, the model will simply execute\n            completion starting with `prompt`.\n        integrations:\n          anyOf:\n            - items:\n                discriminator:\n                  mapping:\n                    wandb: \'#/components/schemas/WandbIntegrationOut\'\n                  propertyName: type\n                oneOf:\n                  - $ref: \'#/components/schemas/WandbIntegrationOut\'\n              type: array\n            - type: \'null\'\n          title: Integrations\n          description: A list of integrations enabled for your fine-tuning job.\n        trained_tokens:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Trained Tokens\n          description: Total number of tokens trained.\n        repositories:\n          default: []\n          items:\n            discriminator:\n              mapping:\n                github: \'#/components/schemas/GithubRepositoryOut\'\n              propertyName: type\n            oneOf:\n              - $ref: \'#/components/schemas/GithubRepositoryOut\'\n          maxItems: 20\n          title: Repositories\n          type: array\n        metadata:\n          anyOf:\n            - $ref: \'#/components/schemas/JobMetadataOut\'\n            - type: \'null\'\n      required:\n        - id\n        - auto_start\n        - hyperparameters\n        - model\n        - status\n        - job_type\n        - created_at\n        - modified_at\n        - training_files\n      title: JobOut\n      type: object\n    JobsOut:\n      properties:\n        data:\n          default: []\n          items:\n            $ref: \'#/components/schemas/JobOut\'\n          title: Data\n          type: array\n        object:\n          const: list\n          default: list\n          enum:\n            - list\n          title: Object\n          type: string\n        total:\n          title: Total\n          type: integer\n      required:\n        - total\n      title: JobsOut\n      type: object\n    TrainingParameters:\n      properties:\n        training_steps:\n          anyOf:\n            - minimum: 1\n              type: integer\n            - type: \'null\'\n          title: Training Steps\n        learning_rate:\n          default: 0.0001\n          maximum: 1\n          minimum: 1.e-8\n          title: Learning Rate\n          type: number\n        weight_decay:\n          anyOf:\n            - maximum: 1\n              minimum: 0\n              type: number\n            - type: \'null\'\n          default: 0.1\n          title: Weight Decay\n        warmup_fraction:\n          anyOf:\n            - maximum: 1\n              minimum: 0\n              type: number\n            - type: \'null\'\n          default: 0.05\n          title: Warmup Fraction\n        epochs:\n          anyOf:\n            - minimum: 0.01\n              type: number\n            - type: \'null\'\n          title: Epochs\n        fim_ratio:\n          anyOf:\n            - maximum: 1\n              minimum: 0\n              type: number\n            - type: \'null\'\n          default: 0.9\n          title: Fim Ratio\n      title: TrainingParameters\n      type: object\n    WandbIntegrationOut:\n      properties:\n        type:\n          const: wandb\n          default: wandb\n          enum:\n            - wandb\n          title: Type\n          type: string\n        project:\n          title: Project\n          type: string\n          description: The name of the project that the new run will be created under.\n        name:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Name\n          description: >-\n            A display name to set for the run. If not set, will use the job ID\n            as the name.\n        run_name:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Run Name\n      required:\n        - project\n      title: WandbIntegrationOut\n      type: object\n    LegacyJobMetadataOut:\n      properties:\n        expected_duration_seconds:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Expected Duration Seconds\n          description: >-\n            The approximated time (in seconds) for the fine-tuning process to\n            complete.\n          examples:\n            - 220\n        cost:\n          anyOf:\n            - type: number\n            - type: \'null\'\n          title: Cost\n          description: The cost of the fine-tuning job.\n          examples:\n            - 10\n        cost_currency:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Cost Currency\n          description: The currency used for the fine-tuning job cost.\n          examples:\n            - EUR\n        train_tokens_per_step:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Train Tokens Per Step\n          description: The number of tokens consumed by one training step.\n          examples:\n            - 131072\n        train_tokens:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Train Tokens\n          description: The total number of tokens used during the fine-tuning process.\n          examples:\n            - 1310720\n        data_tokens:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Data Tokens\n          description: The total number of tokens in the training dataset.\n          examples:\n            - 305375\n        estimated_start_time:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Estimated Start Time\n        deprecated:\n          default: true\n          title: Deprecated\n          type: boolean\n        details:\n          title: Details\n          type: string\n        epochs:\n          anyOf:\n            - type: number\n            - type: \'null\'\n          title: Epochs\n          description: The number of complete passes through the entire training dataset.\n          examples:\n            - 4.2922\n        training_steps:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Training Steps\n          description: >-\n            The number of training steps to perform. A training step refers to a\n            single update of the model weights during the fine-tuning process.\n            This update is typically calculated using a batch of samples from\n            the training dataset.\n          examples:\n            - 10\n        object:\n          const: job.metadata\n          default: job.metadata\n          enum:\n            - job.metadata\n          title: Object\n          type: string\n      required:\n        - details\n      title: LegacyJobMetadataOut\n      type: object\n    GithubRepositoryIn:\n      properties:\n        type:\n          const: github\n          default: github\n          enum:\n            - github\n          title: Type\n          type: string\n        name:\n          title: Name\n          type: string\n        owner:\n          title: Owner\n          type: string\n        ref:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Ref\n        weight:\n          default: 1\n          exclusiveMinimum: 0\n          title: Weight\n          type: number\n        token:\n          title: Token\n          type: string\n      required:\n        - name\n        - owner\n        - token\n      title: GithubRepositoryIn\n      type: object\n    JobIn:\n      properties:\n        model:\n          $ref: \'#/components/schemas/FineTuneableModel\'\n        training_files:\n          default: []\n          items:\n            $ref: \'#/components/schemas/TrainingFile\'\n          title: Training Files\n          type: array\n        validation_files:\n          anyOf:\n            - items:\n                format: uuid\n                type: string\n              type: array\n            - type: \'null\'\n          title: Validation Files\n          description: >-\n            A list containing the IDs of uploaded files that contain validation\n            data. If you provide these files, the data is used to generate\n            validation metrics periodically during fine-tuning. These metrics\n            can be viewed in `checkpoints` when getting the status of a running\n            fine-tuning job. The same data should not be present in both train\n            and validation files.\n        hyperparameters:\n          $ref: \'#/components/schemas/TrainingParametersIn\'\n        suffix:\n          anyOf:\n            - maxLength: 18\n              type: string\n            - type: \'null\'\n          title: Suffix\n          description: >-\n            A string that will be added to your fine-tuning model name. For\n            example, a suffix of \"my-great-model\" would produce a model name\n            like `ft:open-mistral-7b:my-great-model:xxx...`\n        integrations:\n          anyOf:\n            - items:\n                discriminator:\n                  mapping:\n                    wandb: \'#/components/schemas/WandbIntegration\'\n                  propertyName: type\n                oneOf:\n                  - $ref: \'#/components/schemas/WandbIntegration\'\n              type: array\n            - type: \'null\'\n          title: Integrations\n          description: A list of integrations to enable for your fine-tuning job.\n        repositories:\n          default: []\n          items:\n            discriminator:\n              mapping:\n                github: \'#/components/schemas/GithubRepositoryIn\'\n              propertyName: type\n            oneOf:\n              - $ref: \'#/components/schemas/GithubRepositoryIn\'\n          title: Repositories\n          type: array\n        auto_start:\n          description: This field will be required in a future release.\n          title: Auto Start\n          type: boolean\n      required:\n        - model\n        - hyperparameters\n      title: JobIn\n      type: object\n    TrainingFile:\n      properties:\n        file_id:\n          format: uuid\n          title: File Id\n          type: string\n        weight:\n          default: 1\n          exclusiveMinimum: 0\n          title: Weight\n          type: number\n      required:\n        - file_id\n      title: TrainingFile\n      type: object\n    TrainingParametersIn:\n      properties:\n        training_steps:\n          anyOf:\n            - minimum: 1\n              type: integer\n            - type: \'null\'\n          title: Training Steps\n          description: >-\n            The number of training steps to perform. A training step refers to a\n            single update of the model weights during the fine-tuning process.\n            This update is typically calculated using a batch of samples from\n            the training dataset.\n        learning_rate:\n          default: 0.0001\n          maximum: 1\n          minimum: 1.e-8\n          title: Learning Rate\n          type: number\n          description: >-\n            A parameter describing how much to adjust the pre-trained model\'s\n            weights in response to the estimated error each time the weights are\n            updated during the fine-tuning process.\n        weight_decay:\n          anyOf:\n            - maximum: 1\n              minimum: 0\n              type: number\n            - type: \'null\'\n          default: 0.1\n          title: Weight Decay\n          description: >-\n            (Advanced Usage) Weight decay adds a term to the loss function that\n            is proportional to the sum of the squared weights. This term reduces\n            the magnitude of the weights and prevents them from growing too\n            large.\n        warmup_fraction:\n          anyOf:\n            - maximum: 1\n              minimum: 0\n              type: number\n            - type: \'null\'\n          default: 0.05\n          title: Warmup Fraction\n          description: >-\n            (Advanced Usage) A parameter that specifies the percentage of the\n            total training steps at which the learning rate warm-up phase ends.\n            During this phase, the learning rate gradually increases from a\n            small value to the initial learning rate, helping to stabilize the\n            training process and improve convergence. Similar to `pct_start` in\n            [mistral-finetune](https://github.com/mistralai/mistral-finetune)\n        epochs:\n          anyOf:\n            - minimum: 0.01\n              type: number\n            - type: \'null\'\n          title: Epochs\n        fim_ratio:\n          anyOf:\n            - maximum: 1\n              minimum: 0\n              type: number\n            - type: \'null\'\n          default: 0.9\n          title: Fim Ratio\n      title: TrainingParametersIn\n      type: object\n      description: The fine-tuning hyperparameter settings used in a fine-tune job.\n    WandbIntegration:\n      properties:\n        type:\n          const: wandb\n          default: wandb\n          enum:\n            - wandb\n          title: Type\n          type: string\n        project:\n          title: Project\n          type: string\n          description: The name of the project that the new run will be created under.\n        name:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Name\n          description: >-\n            A display name to set for the run. If not set, will use the job ID\n            as the name.\n        api_key:\n          maxLength: 40\n          minLength: 40\n          title: Api Key\n          type: string\n          description: The WandB API key to use for authentication.\n        run_name:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Run Name\n      required:\n        - project\n        - api_key\n      title: WandbIntegration\n      type: object\n    CheckpointOut:\n      properties:\n        metrics:\n          $ref: \'#/components/schemas/MetricOut\'\n        step_number:\n          title: Step Number\n          type: integer\n          description: The step number that the checkpoint was created at.\n        created_at:\n          title: Created At\n          type: integer\n          description: The UNIX timestamp (in seconds) for when the checkpoint was created.\n          examples:\n            - 1716963433\n      required:\n        - metrics\n        - step_number\n        - created_at\n      title: CheckpointOut\n      type: object\n    DetailedJobOut:\n      properties:\n        id:\n          format: uuid\n          title: Id\n          type: string\n        auto_start:\n          title: Auto Start\n          type: boolean\n        hyperparameters:\n          $ref: \'#/components/schemas/TrainingParameters\'\n        model:\n          $ref: \'#/components/schemas/FineTuneableModel\'\n        status:\n          enum:\n            - QUEUED\n            - STARTED\n            - VALIDATING\n            - VALIDATED\n            - RUNNING\n            - FAILED_VALIDATION\n            - FAILED\n            - SUCCESS\n            - CANCELLED\n            - CANCELLATION_REQUESTED\n          title: Status\n          type: string\n        job_type:\n          title: Job Type\n          type: string\n        created_at:\n          title: Created At\n          type: integer\n        modified_at:\n          title: Modified At\n          type: integer\n        training_files:\n          items:\n            format: uuid\n            type: string\n          title: Training Files\n          type: array\n        validation_files:\n          anyOf:\n            - items:\n                format: uuid\n                type: string\n              type: array\n            - type: \'null\'\n          default: []\n          title: Validation Files\n        object:\n          const: job\n          default: job\n          enum:\n            - job\n          title: Object\n          type: string\n        fine_tuned_model:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Fine Tuned Model\n        suffix:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Suffix\n        integrations:\n          anyOf:\n            - items:\n                discriminator:\n                  mapping:\n                    wandb: \'#/components/schemas/WandbIntegrationOut\'\n                  propertyName: type\n                oneOf:\n                  - $ref: \'#/components/schemas/WandbIntegrationOut\'\n              type: array\n            - type: \'null\'\n          title: Integrations\n        trained_tokens:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Trained Tokens\n        repositories:\n          default: []\n          items:\n            discriminator:\n              mapping:\n                github: \'#/components/schemas/GithubRepositoryOut\'\n              propertyName: type\n            oneOf:\n              - $ref: \'#/components/schemas/GithubRepositoryOut\'\n          maxItems: 20\n          title: Repositories\n          type: array\n        metadata:\n          anyOf:\n            - $ref: \'#/components/schemas/JobMetadataOut\'\n            - type: \'null\'\n        events:\n          default: []\n          items:\n            $ref: \'#/components/schemas/EventOut\'\n          title: Events\n          type: array\n          description: >-\n            Event items are created every time the status of a fine-tuning job\n            changes. The timestamped list of all events is accessible here.\n        checkpoints:\n          default: []\n          items:\n            $ref: \'#/components/schemas/CheckpointOut\'\n          title: Checkpoints\n          type: array\n      required:\n        - id\n        - auto_start\n        - hyperparameters\n        - model\n        - status\n        - job_type\n        - created_at\n        - modified_at\n        - training_files\n      title: DetailedJobOut\n      type: object\n    EventOut:\n      properties:\n        name:\n          title: Name\n          type: string\n          description: The name of the event.\n        data:\n          anyOf:\n            - type: object\n              additionalProperties: true\n            - type: \'null\'\n          title: Data\n        created_at:\n          title: Created At\n          type: integer\n          description: The UNIX timestamp (in seconds) of the event.\n      required:\n        - name\n        - created_at\n      title: EventOut\n      type: object\n    MetricOut:\n      properties:\n        train_loss:\n          anyOf:\n            - type: number\n            - type: \'null\'\n          title: Train Loss\n        valid_loss:\n          anyOf:\n            - type: number\n            - type: \'null\'\n          title: Valid Loss\n        valid_mean_token_accuracy:\n          anyOf:\n            - type: number\n            - type: \'null\'\n          title: Valid Mean Token Accuracy\n      title: MetricOut\n      type: object\n      description: >-\n        Metrics at the step number during the fine-tuning job. Use these metrics\n        to assess if the training is going smoothly (loss should decrease, token\n        accuracy should increase).\n    FTModelCapabilitiesOut:\n      properties:\n        completion_chat:\n          default: true\n          title: Completion Chat\n          type: boolean\n        completion_fim:\n          default: false\n          title: Completion Fim\n          type: boolean\n        function_calling:\n          default: false\n          title: Function Calling\n          type: boolean\n        fine_tuning:\n          default: false\n          title: Fine Tuning\n          type: boolean\n      title: FTModelCapabilitiesOut\n      type: object\n    FTModelOut:\n      properties:\n        id:\n          title: Id\n          type: string\n        object:\n          const: model\n          default: model\n          enum:\n            - model\n          title: Object\n          type: string\n        created:\n          title: Created\n          type: integer\n        owned_by:\n          title: Owned By\n          type: string\n        root:\n          title: Root\n          type: string\n        archived:\n          title: Archived\n          type: boolean\n        name:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Name\n        description:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Description\n        capabilities:\n          $ref: \'#/components/schemas/FTModelCapabilitiesOut\'\n        max_context_length:\n          default: 32768\n          title: Max Context Length\n          type: integer\n        aliases:\n          default: []\n          items:\n            type: string\n          title: Aliases\n          type: array\n        job:\n          format: uuid\n          title: Job\n          type: string\n      required:\n        - id\n        - created\n        - owned_by\n        - root\n        - archived\n        - capabilities\n        - job\n      title: FTModelOut\n      type: object\n    UpdateFTModelIn:\n      properties:\n        name:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Name\n        description:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Description\n      title: UpdateFTModelIn\n      type: object\n    ArchiveFTModelOut:\n      properties:\n        id:\n          title: Id\n          type: string\n        object:\n          const: model\n          default: model\n          enum:\n            - model\n          title: Object\n          type: string\n        archived:\n          default: true\n          title: Archived\n          type: boolean\n      required:\n        - id\n      title: ArchiveFTModelOut\n      type: object\n    UnarchiveFTModelOut:\n      properties:\n        id:\n          title: Id\n          type: string\n        object:\n          const: model\n          default: model\n          enum:\n            - model\n          title: Object\n          type: string\n        archived:\n          default: false\n          title: Archived\n          type: boolean\n      required:\n        - id\n      title: UnarchiveFTModelOut\n      type: object\n    AssistantMessage:\n      properties:\n        content:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Content\n        tool_calls:\n          anyOf:\n            - items:\n                $ref: \'#/components/schemas/ToolCall\'\n              type: array\n            - type: \'null\'\n          title: Tool Calls\n        prefix:\n          type: boolean\n          title: Prefix\n          default: false\n          description: >-\n            Set this to `true` when adding an assistant message as prefix to\n            condition the model response. The role of the prefix message is to\n            force the model to start its answer by the content of the message.\n        role:\n          type: string\n          default: assistant\n          title: Role\n          enum:\n            - assistant\n      additionalProperties: false\n      type: object\n      title: AssistantMessage\n    ChatCompletionRequest:\n      properties:\n        model:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Model\n          description: >-\n            ID of the model to use. You can use the [List Available\n            Models](/api/#tag/models/operation/list_models_v1_models_get) API to\n            see all of your available models, or see our [Model\n            overview](/models) for model descriptions.\n          examples:\n            - mistral-small-latest\n        temperature:\n          type: number\n          maximum: 1.5\n          minimum: 0\n          title: Temperature\n          default: 0.7\n          description: >-\n            What sampling temperature to use, between 0.0 and 1.0. Higher values\n            like 0.8 will make the output more random, while lower values like\n            0.2 will make it more focused and deterministic. We generally\n            recommend altering this or `top_p` but not both.\n        top_p:\n          type: number\n          maximum: 1\n          minimum: 0\n          title: Top P\n          default: 1\n          description: >-\n            Nucleus sampling, where the model considers the results of the\n            tokens with `top_p` probability mass. So 0.1 means only the tokens\n            comprising the top 10% probability mass are considered. We generally\n            recommend altering this or `temperature` but not both.\n        max_tokens:\n          anyOf:\n            - type: integer\n              minimum: 300\n            - type: \'null\'\n          title: Max Tokens\n          default: 300\n          description: >-\n            The maximum number of tokens to generate in the completion. The\n            token count of your prompt plus `max_tokens` cannot exceed the\n            model\'s context length.\n        min_tokens:\n          anyOf:\n            - type: integer\n              minimum: 0\n            - type: \'null\'\n          title: Min Tokens\n          description: The minimum number of tokens to generate in the completion.\n        stream:\n          type: boolean\n          title: Stream\n          default: false\n          description: >-\n            Whether to stream back partial progress. If set, tokens will be sent\n            as data-only server-side events as they become available, with the\n            stream terminated by a data: [DONE] message. Otherwise, the server\n            will hold the request open until the timeout or until completion,\n            with the response containing the full result as JSON.\n        stop:\n          anyOf:\n            - type: string\n            - items:\n                type: string\n              type: array\n          title: Stop\n          description: >-\n            Stop generation if this token is detected. Or if one of these tokens\n            is detected when providing an array\n        random_seed:\n          anyOf:\n            - type: integer\n              minimum: 0\n            - type: \'null\'\n          title: Random Seed\n          description: >-\n            The seed to use for random sampling. If set, different calls will\n            generate deterministic results.\n        messages:\n          items:\n            oneOf:\n              - $ref: \'#/components/schemas/SystemMessage\'\n              - $ref: \'#/components/schemas/UserMessage\'\n              - $ref: \'#/components/schemas/AssistantMessage\'\n              - $ref: \'#/components/schemas/ToolMessage\'\n            discriminator:\n              propertyName: role\n              mapping:\n                assistant: \'#/components/schemas/AssistantMessage\'\n                system: \'#/components/schemas/SystemMessage\'\n                tool: \'#/components/schemas/ToolMessage\'\n                user: \'#/components/schemas/UserMessage\'\n          type: array\n          title: Messages\n          description: >-\n            The prompt(s) to generate completions for, encoded as a list of dict\n            with role and content.\n          examples:\n            - - role: user\n                content: Who is the best French painter? Answer in one short sentence.\n        response_format:\n          $ref: \'#/components/schemas/ResponseFormat\'\n        tools:\n          anyOf:\n            - items:\n                $ref: \'#/components/schemas/Tool\'\n              type: array\n            - type: \'null\'\n          title: Tools\n        tool_choice:\n          allOf:\n            - $ref: \'#/components/schemas/ToolChoice\'\n          default: auto\n        safe_prompt:\n          type: boolean\n          description: Whether to inject a safety prompt before all conversations.\n          default: false\n      additionalProperties: false\n      type: object\n      required:\n        - messages\n        - model\n      title: ChatCompletionRequest\n    ChunkTypes:\n      type: string\n      const: text\n      title: ChunkTypes\n    ContentChunk:\n      properties:\n        type:\n          allOf:\n            - $ref: \'#/components/schemas/ChunkTypes\'\n          default: text\n        text:\n          type: string\n          title: Text\n      additionalProperties: false\n      type: object\n      required:\n        - text\n      title: ContentChunk\n    FIMCompletionRequest:\n      properties:\n        model:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Model\n          default: codestral-2405\n          description: |-\n            ID of the model to use. Only compatible for now with:\n              - `codestral-2405`\n              - `codestral-latest`\n          examples:\n            - codestral-2405\n        temperature:\n          type: number\n          maximum: 1.5\n          minimum: 0\n          title: Temperature\n          default: 0.7\n          description: >-\n            What sampling temperature to use, between 0.0 and 1.0. Higher values\n            like 0.8 will make the output more random, while lower values like\n            0.2 will make it more focused and deterministic. We generally\n            recommend altering this or `top_p` but not both.\n        top_p:\n          type: number\n          maximum: 1\n          minimum: 0\n          title: Top P\n          default: 1\n          description: >-\n            Nucleus sampling, where the model considers the results of the\n            tokens with `top_p` probability mass. So 0.1 means only the tokens\n            comprising the top 10% probability mass are considered. We generally\n            recommend altering this or `temperature` but not both.\n        max_tokens:\n          anyOf:\n            - type: integer\n              minimum: 300\n            - type: \'null\'\n          title: Max Tokens\n          default: 300\n          description: >-\n            The maximum number of tokens to generate in the completion. The\n            token count of your prompt plus `max_tokens` cannot exceed the\n            model\'s context length.\n        min_tokens:\n          anyOf:\n            - type: integer\n              minimum: 0\n            - type: \'null\'\n          title: Min Tokens\n          description: The minimum number of tokens to generate in the completion.\n        stream:\n          type: boolean\n          title: Stream\n          default: false\n          description: >-\n            Whether to stream back partial progress. If set, tokens will be sent\n            as data-only server-side events as they become available, with the\n            stream terminated by a data: [DONE] message. Otherwise, the server\n            will hold the request open until the timeout or until completion,\n            with the response containing the full result as JSON.\n        stop:\n          anyOf:\n            - type: string\n            - items:\n                type: string\n              type: array\n          title: Stop\n          description: >-\n            Stop generation if this token is detected. Or if one of these tokens\n            is detected when providing an array\n        random_seed:\n          anyOf:\n            - type: integer\n              minimum: 0\n            - type: \'null\'\n          title: Random Seed\n          description: >-\n            The seed to use for random sampling. If set, different calls will\n            generate deterministic results.\n        prompt:\n          type: string\n          title: Prompt\n          description: The text/code to complete.\n          examples:\n            - def\n        suffix:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Suffix\n          default: \'\'\n          description: >-\n            Optional text/code that adds more context for the model. When given\n            a `prompt` and a `suffix` the model will fill what is between them.\n            When `suffix` is not provided, the model will simply execute\n            completion starting with `prompt`.\n          examples:\n            - return a+b\n      additionalProperties: false\n      type: object\n      required:\n        - prompt\n        - model\n      title: FIMCompletionRequest\n    Function:\n      properties:\n        name:\n          type: string\n          title: Name\n        description:\n          type: string\n          title: Description\n          default: \'\'\n        parameters:\n          type: object\n          title: Parameters\n          additionalProperties: true\n      additionalProperties: false\n      type: object\n      required:\n        - name\n        - parameters\n      title: Function\n    FunctionCall:\n      properties:\n        name:\n          type: string\n          title: Name\n        arguments:\n          title: Arguments\n          anyOf:\n            - type: object\n              additionalProperties: true\n            - type: string\n      additionalProperties: false\n      type: object\n      required:\n        - name\n        - arguments\n      title: FunctionCall\n    ResponseFormat:\n      properties:\n        type:\n          allOf:\n            - $ref: \'#/components/schemas/ResponseFormats\'\n          default: text\n      additionalProperties: false\n      type: object\n      title: ResponseFormat\n    ResponseFormats:\n      type: string\n      enum:\n        - text\n        - json_object\n      title: ResponseFormats\n      description: >-\n        An object specifying the format that the model must output. Setting to\n        `{ \"type\": \"json_object\" }` enables JSON mode, which guarantees the\n        message the model generates is in JSON. When using JSON mode you MUST\n        also instruct the model to produce JSON yourself with a system or a user\n        message.\n    SystemMessage:\n      properties:\n        content:\n          anyOf:\n            - type: string\n            - items:\n                $ref: \'#/components/schemas/ContentChunk\'\n              type: array\n          title: Content\n        role:\n          type: string\n          default: system\n          enum:\n            - system\n      additionalProperties: false\n      type: object\n      required:\n        - content\n      title: SystemMessage\n    TextChunk:\n      properties:\n        type:\n          const: text\n          title: Type\n          default: text\n        text:\n          type: string\n          title: Text\n      additionalProperties: false\n      type: object\n      required:\n        - text\n      title: TextChunk\n    Tool:\n      properties:\n        type:\n          allOf:\n            - $ref: \'#/components/schemas/ToolTypes\'\n          default: function\n        function:\n          $ref: \'#/components/schemas/Function\'\n      additionalProperties: false\n      type: object\n      required:\n        - function\n      title: Tool\n    ToolCall:\n      properties:\n        id:\n          type: string\n          title: Id\n          default: \'null\'\n        type:\n          allOf:\n            - $ref: \'#/components/schemas/ToolTypes\'\n          default: function\n        function:\n          $ref: \'#/components/schemas/FunctionCall\'\n      additionalProperties: false\n      type: object\n      required:\n        - function\n      title: ToolCall\n    ToolChoice:\n      type: string\n      enum:\n        - auto\n        - none\n        - any\n      title: ToolChoice\n    ToolMessage:\n      properties:\n        content:\n          type: string\n          title: Content\n        tool_call_id:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Tool Call Id\n        name:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Name\n        role:\n          type: string\n          default: tool\n          enum:\n            - tool\n      additionalProperties: false\n      type: object\n      required:\n        - content\n      title: ToolMessage\n    ToolTypes:\n      type: string\n      const: function\n      title: ToolTypes\n    UserMessage:\n      properties:\n        content:\n          title: Content\n          anyOf:\n            - type: string\n            - items:\n                $ref: \'#/components/schemas/TextChunk\'\n              type: array\n        role:\n          type: string\n          default: user\n          enum:\n            - user\n      additionalProperties: false\n      type: object\n      required:\n        - content\n      title: UserMessage\n    AgentsCompletionRequest:\n      properties:\n        max_tokens:\n          anyOf:\n            - type: integer\n              minimum: 300\n            - type: \'null\'\n          title: Max Tokens\n          default: 300\n          description: >-\n            The maximum number of tokens to generate in the completion. The\n            token count of your prompt plus `max_tokens` cannot exceed the\n            model\'s context length.\n        min_tokens:\n          anyOf:\n            - type: integer\n              minimum: 0\n            - type: \'null\'\n          title: Min Tokens\n          description: The minimum number of tokens to generate in the completion.\n        stream:\n          type: boolean\n          title: Stream\n          default: false\n          description: >-\n            Whether to stream back partial progress. If set, tokens will be sent\n            as data-only server-side events as they become available, with the\n            stream terminated by a data: [DONE] message. Otherwise, the server\n            will hold the request open until the timeout or until completion,\n            with the response containing the full result as JSON.\n        stop:\n          anyOf:\n            - type: string\n            - items:\n                type: string\n              type: array\n          title: Stop\n          description: >-\n            Stop generation if this token is detected. Or if one of these tokens\n            is detected when providing an array\n        random_seed:\n          anyOf:\n            - type: integer\n              minimum: 0\n            - type: \'null\'\n          title: Random Seed\n          description: >-\n            The seed to use for random sampling. If set, different calls will\n            generate deterministic results.\n        messages:\n          type: array\n          title: Messages\n          items:\n            oneOf:\n              - $ref: \'#/components/schemas/UserMessage\'\n              - $ref: \'#/components/schemas/AssistantMessage\'\n              - $ref: \'#/components/schemas/ToolMessage\'\n            discriminator:\n              propertyName: role\n              mapping:\n                assistant: \'#/components/schemas/AssistantMessage\'\n                tool: \'#/components/schemas/ToolMessage\'\n                user: \'#/components/schemas/UserMessage\'\n          description: >-\n            The prompt(s) to generate completions for, encoded as a list of dict\n            with role and content.\n          examples:\n            - - role: user\n                content: Who is the best French painter? Answer in one short sentence.\n        response_format:\n          $ref: \'#/components/schemas/ResponseFormat\'\n        tools:\n          anyOf:\n            - items:\n                $ref: \'#/components/schemas/Tool\'\n              type: array\n            - type: \'null\'\n          title: Tools\n        tool_choice:\n          allOf:\n            - $ref: \'#/components/schemas/ToolChoice\'\n          default: auto\n        agent_id:\n          type: string\n          description: The ID of the agent to use for this completion.\n      additionalProperties: false\n      type: object\n      required:\n        - messages\n        - agent_id\n      title: AgentsCompletionRequest\n    EmbeddingRequest:\n      properties:\n        input:\n          anyOf:\n            - type: string\n            - items:\n                type: string\n              type: array\n          title: Input\n          description: Text to embed.\n        model:\n          type: string\n          title: Model\n          description: ID of the model to use.\n        encoding_format:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Encoding Format\n          description: The format to return the embeddings in.\n          default: float\n      additionalProperties: false\n      type: object\n      required:\n        - input\n        - model\n      title: EmbeddingRequest\n    UsageInfo:\n      title: UsageInfo\n      type: object\n      properties:\n        prompt_tokens:\n          type: integer\n          example: 16\n        completion_tokens:\n          type: integer\n          example: 34\n        total_tokens:\n          type: integer\n          example: 50\n      required:\n        - prompt_tokens\n        - completion_tokens\n        - total_tokens\n    ResponseBase:\n      type: object\n      title: ResponseBase\n      properties:\n        id:\n          type: string\n          example: cmpl-e5cc70bb28c444948073e77776eb30ef\n        object:\n          type: string\n          example: chat.completion\n        model:\n          type: string\n          example: mistral-small-latest\n        usage:\n          $ref: \'#/components/schemas/UsageInfo\'\n    ChatCompletionChoice:\n      title: ChatCompletionChoice\n      type: object\n      required:\n        - index\n        - finish_reason\n        - message\n      properties:\n        index:\n          type: integer\n          example: 0\n        message:\n          $ref: \'#/components/schemas/AssistantMessage\'\n        finish_reason:\n          type: string\n          enum:\n            - stop\n            - length\n            - model_length\n            - error\n            - tool_calls\n          example: stop\n    ChatCompletionResponseBase:\n      allOf:\n        - $ref: \'#/components/schemas/ResponseBase\'\n        - type: object\n          title: ChatCompletionResponseBase\n          properties:\n            created:\n              type: integer\n              example: 1702256327\n    ChatCompletionResponse:\n      allOf:\n        - $ref: \'#/components/schemas/ChatCompletionResponseBase\'\n        - type: object\n          title: ChatCompletionResponse\n          properties:\n            choices:\n              type: array\n              items:\n                $ref: \'#/components/schemas/ChatCompletionChoice\'\n          required:\n            - id\n            - object\n            - data\n            - model\n            - usage\n    FIMCompletionResponse:\n      allOf:\n        - $ref: \'#/components/schemas/ChatCompletionResponse\'\n        - type: object\n          properties:\n            model:\n              type: string\n              example: codestral-latest\n    EmbeddingResponseData:\n      title: EmbeddingResponseData\n      type: object\n      properties:\n        object:\n          type: string\n          example: embedding\n        embedding:\n          type: array\n          items:\n            type: number\n          examples:\n            - 0.1\n            - 0.2\n            - 0.3\n        index:\n          type: integer\n          example: 0\n      examples:\n        - object: embedding\n          embedding:\n            - 0.1\n            - 0.2\n            - 0.3\n          index: 0\n        - object: embedding\n          embedding:\n            - 0.4\n            - 0.5\n            - 0.6\n          index: 1\n    EmbeddingResponse:\n      allOf:\n        - $ref: \'#/components/schemas/ResponseBase\'\n        - type: object\n          properties:\n            data:\n              type: array\n              items:\n                $ref: \'#/components/schemas/EmbeddingResponseData\'\n          required:\n            - id\n            - object\n            - data\n            - model\n            - usage\n    CompletionEvent:\n      type: object\n      required:\n        - data\n      properties:\n        data:\n          $ref: \'#/components/schemas/CompletionChunk\'\n    CompletionChunk:\n      type: object\n      required:\n        - id\n        - model\n        - choices\n      properties:\n        id:\n          type: string\n        object:\n          type: string\n        created:\n          type: integer\n        model:\n          type: string\n        usage:\n          $ref: \'#/components/schemas/UsageInfo\'\n        choices:\n          type: array\n          items:\n            $ref: \'#/components/schemas/CompletionResponseStreamChoice\'\n    CompletionResponseStreamChoice:\n      type: object\n      required:\n        - index\n        - delta\n        - finish_reason\n      properties:\n        index:\n          type: integer\n        delta:\n          $ref: \'#/components/schemas/DeltaMessage\'\n        finish_reason:\n          type:\n            - string\n            - \'null\'\n          enum:\n            - stop\n            - length\n            - error\n            - tool_calls\n            - null\n    DeltaMessage:\n      type: object\n      properties:\n        role:\n          type: string\n        content:\n          anyOf:\n            - type: string\n            - type: \'null\'\n        tool_calls:\n          anyOf:\n            - type: \'null\'\n            - type: array\n              items:\n                $ref: \'#/components/schemas/ToolCall\'\n  securitySchemes:\n    ApiKey:\n      type: http\n      scheme: bearer\ntags:\n  - name: chat\n    x-displayName: Chat\n    description: Chat Completion API.\n  - name: fim\n    x-displayName: FIM\n    description: Fill-in-the-middle API.\n  - name: agents\n    x-displayName: Agents\n    description: Agents API.\n  - name: embeddings\n    x-displayName: Embeddings\n    description: Embeddings API.\n  - name: files\n    x-displayName: Files\n    description: Files API\n  - name: fine-tuning\n    x-displayName: Fine Tuning\n    description: Fine-tuning API\n  - name: models\n    x-displayName: Models\n    description: Model Management API\nsecurity:\n  - ApiKey: []\nservers:\n  - url: https://api.mistral.ai\n    description: Production server\n','false');
INSERT INTO `AM_LLM_PROVIDER` VALUES ('54135459-5e24-414f-88fa-d60164d09c03','AzureAIFoundry','1.0.0','carbon.super','true','Azure AI Foundry service',_binary '{\"connectorType\":\"azureAiFoundry_1.0.0\",\"metadata\":[{\"attributeName\":\"requestModel\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.model\",\"required\":false},{\"attributeName\":\"responseModel\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.model\",\"required\":true},{\"attributeName\":\"promptTokenCount\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.usage.prompt_tokens\",\"required\":true},{\"attributeName\":\"completionTokenCount\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.usage.completion_tokens\",\"required\":true},{\"attributeName\":\"totalTokenCount\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.usage.total_tokens\",\"required\":true},{\"attributeName\":\"remainingTokenCount\",\"inputSource\":\"header\",\"attributeIdentifier\":\"x-ratelimit-remaining-tokens\",\"required\":false}],\"authHeader\":\"api-key\",\"authenticationConfiguration\":{\"enabled\":true,\"type\":\"apikey\",\"parameters\":{\"headerEnabled\":true,\"headerName\":\"api-key\",\"queryParameterEnabled\":false}}}',_binary 'openapi: 3.1.0\ninfo:\n  title: Azure AI Foundry API\n  description: |\n    This OpenAPI specification defines the Azure AI Foundry API.\n    It is a stateful, resource-oriented API for creating, managing, and running sophisticated AI agents (also known as Assistants).[9, 10]\n    The API follows the same protocol as the Azure OpenAI Assistants API, allowing for the use of compatible tools and SDKs.[9]\n  version: \"2025-04-01-preview\"\nservers:\n  - url: https://{resource-name}.services.ai.azure.com\n    variables:\n      resource-name:\n        default: your-resource-name\nsecurity:\n  - bearer:\n      - api.read\n  - apiKey: []\npaths:\n  /api/projects/{project-name}/assistants:\n    get:\n      operationId: List_Assistants\n      tags:\n        - AI Agents\n          - Assistants\n      summary: Returns a list of assistants.\n      parameters:\n        - name: project-name\n          in: path\n          description: The name of the project.\n          required: true\n          schema:\n            type: string\n        - name: limit\n          in: query\n          description: &pagination_limit_param_description |\n            A limit on the number of objects to be returned. Limit can range between 1 and 100, and the default is 20.\n          required: false\n          schema:\n            type: integer\n            default: 20\n        - name: order\n          in: query\n          description: &pagination_order_param_description |\n            Sort order by the `created_at` timestamp of the objects. `asc` for ascending order and `desc` for descending order.\n          schema:\n            type: string\n            default: desc\n            enum:\n              - asc\n              - desc\n            x-ms-enum:\n              name: ListAssistantsOrder\n              modelAsString: true\n              values:\n                - value: asc\n                  description: Order results in ascending order\n                - value: desc\n                  description: Order results in descending order\n        - name: after\n          in: query\n          description: &pagination_after_param_description |\n            A cursor for use in pagination. `after` is an object ID that defines your place in the list. For instance, if you make a list request and receive 100 objects, ending with obj_foo, your subsequent call can include after=obj_foo in order to fetch the next page of the list.\n          schema:\n            type: string\n        - name: before\n          in: query\n          description: &pagination_before_param_description |\n            A cursor for use in pagination. `before` is an object ID that defines your place in the list. For instance, if you make a list request and receive 100 objects, starting with obj_foo, your subsequent call can include before=obj_foo in order to fetch the previous page of the list.\n          schema:\n            type: string\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            default: \"2025-05-15-preview\"\n          description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/listAssistantsResponse\"\n    post:\n      operationId: Create_Assistant\n      tags:\n        - AI Agents\n          - Assistants\n      summary: Create an assistant with a model and instructions.\n      parameters:\n        - name: project-name\n          in: path\n          description: The name of the project.\n          required: true\n          schema:\n            type: string\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            default: \"2025-05-15-preview\"\n          description: api version\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/createAssistantRequest\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/assistantObject\"\n  /api/projects/{project-name}/assistants/{assistant_id}:\n    get:\n      operationId: Get_Assistant\n      tags:\n        - AI Agents\n          - Assistants\n      summary: Retrieves an assistant.\n      parameters:\n        - name: project-name\n          in: path\n          description: The name of the project.\n          required: true\n          schema:\n            type: string\n        - in: path\n          name: assistant_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the assistant to retrieve.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            default: \"2025-05-15-preview\"\n          description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/assistantObject\"\n    post:\n      operationId: Modify_Assistant\n      tags:\n        - AI Agents\n          - Assistants\n      summary: Modifies an assistant.\n      parameters:\n        - name: project-name\n          in: path\n          description: The name of the project.\n          required: true\n          schema:\n            type: string\n        - in: path\n          name: assistant_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the assistant to modify.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            default: \"2025-05-15-preview\"\n          description: api version\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/modifyAssistantRequest\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/assistantObject\"\n    delete:\n      operationId: Delete_Assistant\n      tags:\n        - AI Agents\n          - Assistants\n      summary: Delete an assistant.\n      parameters:\n        - name: project-name\n          in: path\n          description: The name of the project.\n          required: true\n          schema:\n            type: string\n        - in: path\n          name: assistant_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the assistant to delete.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            default: \"2025-05-15-preview\"\n          description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/deleteAssistantResponse\"\n  /api/projects/{project-name}/files:\n    get:\n      operationId: List_Files\n      tags:\n        - AI Agents\n          - Files\n      summary: Gets a list of previously uploaded files.\n      parameters:\n        - name: project-name\n          in: path\n          description: The name of the project.\n          required: true\n          schema:\n            type: string\n        - name: purpose\n          in: query\n          description: The purpose of the file.\n          required: false\n          schema:\n            $ref: \"#/components/schemas/FilePurpose\"\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            default: \"2025-05-15-preview\"\n          description: api version\n      responses:\n        \"200\":\n          description: The requested list of files.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/FileListResponse\"\n    post:\n      operationId: Upload_File\n      tags:\n        - AI Agents\n          - Files\n      summary: Uploads a file for use by other operations.\n      parameters:\n        - name: project-name\n          in: path\n          description: The name of the project.\n          required: true\n          schema:\n            type: string\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            default: \"2025-05-15-preview\"\n          description: api version\n      requestBody:\n        required: true\n        content:\n          multipart/form-data:\n            schema:\n              type: object\n              properties:\n                file:\n                  type: string\n                  format: binary\n                  description: The file data, in bytes.\n                purpose:\n                  $ref: \"#/components/schemas/FilePurpose\"\n                  description: The intended purpose of the uploaded file. Use assistants for Agents and Message files, vision for Agents image file inputs, batch for Batch API, and fine-tune for Fine-tuning.\n                filename:\n                  type: string\n                  description: The name of the file.\n              required:\n                - file\n                - purpose\n      responses:\n        \"200\":\n          description: A representation of the uploaded file.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/FileInfo\"\n  /api/projects/{project-name}/files/{fileId}:\n    get:\n      operationId: Get_File\n      tags:\n        - AI Agents\n          - Files\n      summary: Returns information about a specific file. Does not retrieve file content.\n      parameters:\n        - name: project-name\n          in: path\n          description: The name of the project.\n          required: true\n          schema:\n            type: string\n        - name: fileId\n          in: path\n          description: The ID of the file to retrieve.\n          required: true\n          schema:\n            type: string\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            default: \"2025-05-15-preview\"\n          description: api version\n      responses:\n        \"200\":\n          description: The request has succeeded.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/FileInfo\"\n    delete:\n      operationId: Delete_File\n      tags:\n        - AI Agents\n          - Files\n      summary: Delete a previously uploaded file.\n      parameters:\n        - name: project-name\n          in: path\n          description: The name of the project.\n          required: true\n          schema:\n            type: string\n        - name: fileId\n          in: path\n          description: The ID of the file to delete.\n          required: true\n          schema:\n            type: string\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            default: \"2025-05-15-preview\"\n          description: api version\n      responses:\n        \"200\":\n          description: Status of the deletion operation.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/FileDeletionStatus\"\n  /api/projects/{project-name}/files/{fileId}/content:\n    get:\n      operationId: Get_File_Content\n      tags:\n        - AI Agents\n          - Files\n      summary: Retrieves the raw content of a specific file.\n      parameters:\n        - name: project-name\n          in: path\n          description: The name of the project.\n          required: true\n          schema:\n            type: string\n        - name: fileId\n          in: path\n          description: The ID of the file to retrieve.\n          required: true\n          schema:\n            type: string\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            default: \"2025-05-15-preview\"\n          description: api version\n      responses:\n        \"200\":\n          description: The request has succeeded.\n          content:\n            application/octet-stream:\n              schema:\n   