id}:\n    get:\n      operationId: Get_Vector_Store_File_Batch\n      tags:\n        - AI Agents\n          - Vector Stores\n      summary: Retrieves a vector store file batch.\n      parameters:\n        - name: project-name\n          in: path\n          description: The name of the project.\n          required: true\n          schema:\n            type: string\n        - in: path\n          name: vector_store_id\n          required: true\n          schema:\n            type: string\n            example: vs_abc123\n          description: The ID of the vector store that the file batch belongs to.\n        - in: path\n          name: batch_id\n          required: true\n          schema:\n            type: string\n            example: vsfb_abc123\n          description: The ID of the file batch being retrieved.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            default: \"2025-05-15-preview\"\n          description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/vectorStoreFileBatchObject\"\n  /api/projects/{project-name}/vector_stores/{vector_store_id}/file_batches/{batch_id}/cancel:\n    post:\n      operationId: Cancel_Vector_Store_File_Batch\n      tags:\n        - AI Agents\n          - Vector Stores\n      summary: Cancel a vector store file batch. This attempts to cancel the processing of files in this batch as soon as possible.\n      parameters:\n        - name: project-name\n          in: path\n          description: The name of the project.\n          required: true\n          schema:\n            type: string\n        - in: path\n          name: vector_store_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the vector store that the file batch belongs to.\n        - in: path\n          name: batch_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the file batch to cancel.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            default: \"2025-05-15-preview\"\n          description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/vectorStoreFileBatchObject\"\n  /api/projects/{project-name}/vector_stores/{vector_store_id}/file_batches/{batch_id}/files:\n    get:\n      operationId: List_Vector_Store_File_Batch_Files\n      tags:\n        - AI Agents\n          - Vector Stores\n      summary: Returns a list of vector store files in a batch.\n      parameters:\n        - name: project-name\n          in: path\n          description: The name of the project.\n          required: true\n          schema:\n            type: string\n        - name: vector_store_id\n          in: path\n          description: The ID of the vector store that the files belong to.\n          required: true\n          schema:\n            type: string\n        - name: batch_id\n          in: path\n          description: The ID of the file batch that the files belong to.\n          required: true\n          schema:\n            type: string\n        - name: limit\n          in: query\n          description: *pagination_limit_param_description\n          required: false\n          schema:\n            type: integer\n            default: 20\n        - name: order\n          in: query\n          description: *pagination_order_param_description\n          schema:\n            type: string\n            default: desc\n            enum: [\"asc\", \"desc\"]\n            x-ms-enum:\n              name: ListVectorStoreFilesOrder\n              modelAsString: true\n              values:\n          