cription = await openai.audio.transcriptions.create({\n                    file: fs.createReadStream(\"audio.mp3\"),\n                    model: \"whisper-1\",\n                    response_format: \"verbose_json\",\n                    timestamp_granularities: [\"segment\"]\n                  });\n\n                  console.log(transcription.text);\n                }\n                main();\n            response: |\n              {\n                \"task\": \"transcribe\",\n                \"language\": \"english\",\n                \"duration\": 8.470000267028809,\n                \"text\": \"The beach was a popular spot on a hot summer day. People were swimming in the ocean, building sandcastles, and playing beach volleyball.\",\n                \"segments\": [\n                  {\n                    \"id\": 0,\n                    \"seek\": 0,\n                    \"start\": 0.0,\n                    \"end\": 3.319999933242798,\n                    \"text\": \" The beach was a popular spot on a hot summer day.\",\n                    \"tokens\": [\n                      50364, 440, 7534, 390, 257, 3743, 4008, 322, 257, 2368, 4266, 786, 13, 50530\n                    ],\n                    \"temperature\": 0.0,\n                    \"avg_logprob\": -0.2860786020755768,\n                    \"compression_ratio\": 1.2363636493682861,\n                    \"no_speech_prob\": 0.00985979475080967\n                  },\n                  ...\n                ]\n              }\n  /audio/translations:\n    post:\n      operationId: createTranslation\n      tags:\n        - Audio\n      summary: Translates audio into English.\n      requestBody:\n        required: true\n        content:\n          multipart/form-data:\n            schema:\n              $ref: \'#/components/schemas/CreateTranslationRequest\'\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                oneOf:\n                  - $ref: \'#/components/schemas/CreateTranslationResponseJson\'\n                  - $ref: \'#/components/schemas/CreateTranslationResponseVerboseJson\'\n      x-oaiMeta:\n        name: Create translation\n        group: audio\n        returns: The translated text.\n        examples:\n          request:\n            curl: |\n              curl https://api.openai.com/v1/audio/translations \\\n                -H \"Authorization: Bearer $OPENAI_API_KEY\" \\\n                -H \"Content-Type: multipart/form-data\" \\\n                -F file=\"@/path/to/file/german.m4a\" \\\n                -F model=\"whisper-1\"\n            python: |\n              from openai import OpenAI\n              client = OpenAI()\n\n              audio_file = open(\"speech.mp3\", \"rb\")\n              transcript = client.audio.translations.create(\n                model=\"whisper-1\",\n                file=audio_file\n              )\n            node: |\n              import fs from \"fs\";\n              import OpenAI from \"openai\";\n\n              const openai = new OpenAI();\n\n              async function main() {\n                  const translation = await openai.audio.translations.create({\n                      file: fs.createReadStream(\"speech.mp3\"),\n                      model: \"whisper-1\",\n                  });\n\n                  console.log(translation.text);\n              }\n              main();\n          response: |\n            {\n              \"text\": \"Hello, my name is Wolfgang and I come from Germany. Where are you heading today?\"\n            }\n  /files:\n    get:\n      operationId: listFiles\n      tags:\n        - Files\n      summary: Returns a list of files that belong to the user\'s organization.\n      parameters:\n        - in: query\n          name: purpose\n          required: false\n          schema:\n            type: string\n          description: Only return files with the given purpose.\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/ListFilesResponse\'\n      x-oaiMeta:\n        name: List files\n        group: files\n        returns: A list of [File](/docs/api-reference/files/object) objects.\n        examples:\n          request:\n            curl: |\n              curl https://api.openai.com/v1/files \\\n                -H \"Authorization: Bearer $OPENAI_API_KEY\"\n            python: |\n              from openai import OpenAI\n              client = OpenAI()\n\n              client.files.list()\n            node.js: |-\n              import OpenAI from \"openai\";\n\n              const openai = new OpenAI();\n\n              async function main() {\n                const list = await openai.files.list();\n\n                for await (const file of list) {\n                  console.log(file);\n                }\n              }\n\n              main();\n          response: |\n            {\n              \"data\": [\n                {\n                  \"id\": \"file-abc123\",\n                  \"object\": \"file\",\n                  \"bytes\": 175,\n                  \"created_at\": 1613677385,\n                  \"filename\": \"salesOverview.pdf\",\n                  \"purpose\": \"assistants\",\n                },\n                {\n                  \"id\": \"file-abc123\",\n                  \"object\": \"file\",\n                  \"bytes\": 140,\n                  \"created_at\": 1613779121,\n                  \"filename\": \"puppy.jsonl\",\n                  \"purpose\": \"fine-tune\",\n                }\n              ],\n              \"object\": \"list\"\n            }\n    post:\n      operationId: createFile\n      tags:\n        - Files\n      summary: |\n        Upload a file that can be used across various endpoints. Individual files can be up to 512 MB, and the size of all files uploaded by one organization can be up to 100 GB.\n\n        The Assistants API supports files up to 2 million tokens and of specific file types. See the [Assistants Tools guide](/docs/assistants/tools) for details.\n\n        The Fine-tuning API only supports `.jsonl` files. The input also has certain required formats for fine-tuning [chat](/docs/api-reference/fine-tuning/chat-input) or [completions](/docs/api-reference/fine-tuning/completions-input) models.\n\n        The Batch API only supports `.jsonl` files up to 100 MB in size. The input also has a specific required [format](/docs/api-reference/batch/request-input).\n\n        Please [contact us](https://help.openai.com/) if you need to increase these storage limits.\n      requestBody:\n        required: true\n        content:\n          multipart/form-data:\n            schema:\n              $ref: \'#/components/schemas/CreateFileRequest\'\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/OpenAIFile\'\n      x-oaiMeta:\n        name: Upload file\n        group: files\n        returns: The uploaded [File](/docs/api-reference/files/object) object.\n        examples:\n          request:\n            curl: |\n              curl https://api.openai.com/v1/files \\\n                -H \"Authorization: Bearer $OPENAI_API_KEY\" \\\n                -F purpose=\"fine-tune\" \\\n                -F file=\"@mydata.jsonl\"\n            python: |\n              from openai import OpenAI\n              client = OpenAI()\n\n              client.files.create(\n                file=open(\"mydata.jsonl\", \"rb\"),\n                purpose=\"fine-tune\"\n              )\n            node.js: |-\n              import fs from \"fs\";\n              import OpenAI from \"openai\";\n\n              const openai = new OpenAI();\n\n              async function main() {\n                const file = await openai.files.create({\n                  file: fs.createReadStream(\"mydata.jsonl\"),\n                  purpose: \"fine-tune\",\n                });\n\n                console.log(file);\n              }\n\n              main();\n          response: |\n            {\n              \"id\": \"file-abc123\",\n              \"object\": \"file\",\n              \"bytes\": 120000,\n              \"created_at\": 1677610602,\n              \"filename\": \"mydata.jsonl\",\n              \"purpose\": \"fine-tune\",\n            }\n  /files/{file_id}:\n    delete:\n      operationId: deleteFile\n      tags:\n        - Files\n      summary: Delete a file.\n      parameters:\n        - in: path\n          name: file_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the file to use for this request.\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/DeleteFileResponse\'\n      x-oaiMeta:\n        name: Delete file\n        group: files\n        returns: Deletion status.\n        examples:\n          request:\n            curl: |\n              curl https://api.openai.com/v1/files/file-abc123 \\\n                -X DELETE \\\n                -H \"Authorization: Bearer $OPENAI_API_KEY\"\n            python: |\n              from openai import OpenAI\n              client = OpenAI()\n\n              client.files.delete(\"file-abc123\")\n            node.js: |-\n              import OpenAI from \"openai\";\n\n              const openai = new OpenAI();\n\n              async function main() {\n                const file = await openai.files.del(\"file-abc123\");\n\n                console.log(file);\n              }\n\n              main();\n          response: |\n            {\n              \"id\": \"file-abc123\",\n              \"object\": \"file\",\n              \"deleted\": true\n            }\n    get:\n      operationId: retrieveFile\n      tags:\n        - Files\n      summary: Returns information about a specific file.\n      parameters:\n        - in: path\n          name: file_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the file to use for this request.\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/OpenAIFile\'\n      x-oaiMeta:\n        name: Retrieve file\n        group: files\n        returns: The [File](/docs/api-reference/files/object) object matching the specified ID.\n        examples:\n          request:\n            curl: |\n              curl https://api.openai.com/v1/files/file-abc123 \\\n                -H \"Authorization: Bearer $OPENAI_API_KEY\"\n            python: |\n              from openai import OpenAI\n              client = OpenAI()\n\n              client.files.retrieve(\"file-abc123\")\n            node.js: |-\n              import OpenAI from \"openai\";\n\n              const openai = new OpenAI();\n\n              async function main() {\n                const file = await openai.files.retrieve(\"file-abc123\");\n\n                console.log(file);\n              }\n\n              main();\n          response: |\n            {\n              \"id\": \"file-abc123\",\n              \"object\": \"file\",\n              \"bytes\": 120000,\n              \"created_at\": 1677610602,\n              \"filename\": \"mydata.jsonl\",\n              \"purpose\": \"fine-tune\",\n            }\n  /files/{file_id}/content:\n    get:\n      operationId: downloadFile\n      tags:\n        - Files\n      summary: Returns the contents of the specified file.\n      parameters:\n        - in: path\n          name: file_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the file to use for this request.\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                type: string\n      x-oaiMeta:\n        name: Retrieve file content\n        group: files\n        returns: The file content.\n        examples:\n          request:\n            curl: |\n              curl https://api.openai.com/v1/files/file-abc123/content \\\n                -H \"Authorization: Bearer $OPENAI_API_KEY\" > file.jsonl\n            python: |\n              from openai import OpenAI\n              client = OpenAI()\n\n              content = client.files.content(\"file-abc123\")\n            node.js: |\n              import OpenAI from \"openai\";\n\n              const openai = new OpenAI();\n\n              async function main() {\n                const file = await openai.files.content(\"file-abc123\");\n\n                console.log(file);\n              }\n\n              main();\n  /uploads:\n    post:\n      operationId: createUpload\n      tags:\n        - Uploads\n      summary: |\n        Creates an intermediate [Upload](/docs/api-reference/uploads/object) object that you can add [Parts](/docs/api-reference/uploads/part-object) to. Currently, an Upload can accept at most 8 GB in total and expires after an hour after you create it.\n\n        Once you complete the Upload, we will create a [File](/docs/api-reference/files/object) object that contains all the parts you uploaded. This File is usable in the rest of our platform as a regular File object.\n\n        For certain `purpose`s, the correct `mime_type` must be specified. Please refer to documentation for the supported MIME types for your use case:\n        - [Assistants](/docs/assistants/tools/file-search/supported-files)\n\n        For guidance on the proper filename extensions for each purpose, please follow the documentation on [creating a File](/docs/api-reference/files/create).\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \'#/components/schemas/CreateUploadRequest\'\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/Upload\'\n      x-oaiMeta:\n        name: Create upload\n        group: uploads\n        returns: The [Upload](/docs/api-reference/uploads/object) object with status `pending`.\n        examples:\n          request:\n            curl: |\n              curl https://api.openai.com/v1/uploads \\\n                -H \"Authorization: Bearer $OPENAI_API_KEY\" \\\n                -d \'{\n                  \"purpose\": \"fine-tune\",\n                  \"filename\": \"training_examples.jsonl\",\n                  \"bytes\": 2147483648,\n                  \"mime_type\": \"text/jsonl\"\n                }\'\n          response: |\n            {\n              \"id\": \"upload_abc123\",\n              \"object\": \"upload\",\n              \"bytes\": 2147483648,\n              \"created_at\": 1719184911,\n              \"filename\": \"training_examples.jsonl\",\n              \"purpose\": \"fine-tune\",\n              \"status\": \"pending\",\n              \"expires_at\": 1719127296\n            }\n  /uploads/{upload_id}/parts:\n    post:\n      operationId: addUploadPart\n      tags:\n        - Uploads\n      summary: |\n        Adds a [Part](/docs/api-reference/uploads/part-object) to an [Upload](/docs/api-reference/uploads/object) object. A Part represents a chunk of bytes from the file you are trying to upload. \n\n        Each Part can be at most 64 MB, and you can add Parts until you hit the Upload maximum of 8 GB.\n\n        It is possible to add multiple Parts in parallel. You can decide the intended order of the Parts when you [complete the Upload](/docs/api-reference/uploads/complete).\n      parameters:\n        - in: path\n          name: upload_id\n          required: true\n          schema:\n            type: string\n            example: upload_abc123\n          description: |\n            The ID of the Upload.\n      requestBody:\n        required: true\n        content:\n          multipart/form-data:\n            schema:\n              $ref: \'#/components/schemas/AddUploadPartRequest\'\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/UploadPart\'\n      x-oaiMeta:\n        name: Add upload part\n        group: uploads\n        returns: The upload [Part](/docs/api-reference/uploads/part-object) object.\n        examples:\n          request:\n            curl: |\n              curl https://api.openai.com/v1/uploads/upload_abc123/parts\n                -F data=\"aHR0cHM6Ly9hcGkub3BlbmFpLmNvbS92MS91cGxvYWRz...\"\n          response: |\n            {\n              \"id\": \"part_def456\",\n              \"object\": \"upload.part\",\n              \"created_at\": 1719185911,\n              \"upload_id\": \"upload_abc123\"\n            }\n  /uploads/{upload_id}/complete:\n    post:\n      operationId: completeUpload\n      tags:\n        - Uploads\n      summary: |\n        Completes the [Upload](/docs/api-reference/uploads/object). \n\n        Within the returned Upload object, there is a nested [File](/docs/api-reference/files/object) object that is ready to use in the rest of the platform.\n\n        You can specify the order of the Parts by passing in an ordered list of the Part IDs.\n\n        The number of bytes uploaded upon completion must match the number of bytes initially specified when creating the Upload object. No Parts may be added after an Upload is completed.\n      parameters:\n        - in: path\n          name: upload_id\n          required: true\n          schema:\n            type: string\n            example: upload_abc123\n          description: |\n            The ID of the Upload.\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \'#/components/schemas/CompleteUploadRequest\'\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/Upload\'\n      x-oaiMeta:\n        name: Complete upload\n        group: uploads\n        returns: The [Upload](/docs/api-reference/uploads/object) object with status `completed` with an additional `file` property containing the created usable File object.\n        examples:\n          request:\n            curl: |\n              curl https://api.openai.com/v1/uploads/upload_abc123/complete\n                -d \'{\n                  \"part_ids\": [\"part_def456\", \"part_ghi789\"]\n                }\'\n          response: |\n            {\n              \"id\": \"upload_abc123\",\n              \"object\": \"upload\",\n              \"bytes\": 2147483648,\n              \"created_at\": 1719184911,\n              \"filename\": \"training_examples.jsonl\",\n              \"purpose\": \"fine-tune\",\n              \"status\": \"completed\",\n              \"expires_at\": 1719127296,\n              \"file\": {\n                \"id\": \"file-xyz321\",\n                \"object\": \"file\",\n                \"bytes\": 2147483648,\n                \"created_at\": 1719186911,\n                \"filename\": \"training_examples.jsonl\",\n                \"purpose\": \"fine-tune\",\n              }\n            }\n  /uploads/{upload_id}/cancel:\n    post:\n      operationId: cancelUpload\n      tags:\n        - Uploads\n      summary: |\n        Cancels the Upload. No Parts may be added after an Upload is cancelled.\n      parameters:\n        - in: path\n          name: upload_id\n          required: true\n          schema:\n            type: string\n            example: upload_abc123\n          description: |\n            The ID of the Upload.\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/Upload\'\n      x-oaiMeta:\n        name: Cancel upload\n        group: uploads\n        returns: The [Upload](/docs/api-reference/uploads/object) object with status `cancelled`.\n        examples:\n          request:\n            curl: |\n              curl https://api.openai.com/v1/uploads/upload_abc123/cancel\n          response: |\n            {\n              \"id\": \"upload_abc123\",\n              \"object\": \"upload\",\n              \"bytes\": 2147483648,\n              \"created_at\": 1719184911,\n              \"filename\": \"training_examples.jsonl\",\n              \"purpose\": \"fine-tune\",\n              \"status\": \"cancelled\",\n              \"expires_at\": 1719127296\n            }\n  /fine_tuning/jobs:\n    post:\n      operationId: createFineTuningJob\n      tags:\n        - Fine-tuning\n      summary: |\n        Creates a fine-tuning job which begins the process of creating a new model from a given dataset.\n\n        Response includes details of the enqueued job including job status and the name of the fine-tuned models once complete.\n\n        [Learn more about fine-tuning](/docs/guides/fine-tuning)\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \'#/components/schemas/CreateFineTuningJobRequest\'\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/FineTuningJob\'\n      x-oaiMeta:\n        name: Create fine-tuning job\n        group: fine-tuning\n        returns: A [fine-tuning.job](/docs/api-reference/fine-tuning/object) object.\n        examples:\n          - title: Default\n            request:\n              curl: |\n                curl https://api.openai.com/v1/fine_tuning/jobs \\\n                  -H \"Content-Type: application/json\" \\\n                  -H \"Authorization: Bearer $OPENAI_API_KEY\" \\\n                  -d \'{\n                    \"training_file\": \"file-BK7bzQj3FfZFXr7DbL6xJwfo\",\n                    \"model\": \"gpt-4o-mini\"\n                  }\'\n              python: |\n                from openai import OpenAI\n                client = OpenAI()\n\n                client.fine_tuning.jobs.create(\n                  training_file=\"file-abc123\",\n                  model=\"gpt-4o-mini\"\n                )\n              node.js: |\n                import OpenAI from \"openai\";\n\n                const openai = new OpenAI();\n\n                async function main() {\n                  const fineTune = await openai.fineTuning.jobs.create({\n                    training_file: \"file-abc123\"\n                  });\n\n                  console.log(fineTune);\n                }\n\n                main();\n            response: |\n              {\n                \"object\": \"fine_tuning.job\",\n                \"id\": \"ftjob-abc123\",\n                \"model\": \"gpt-4o-mini-2024-07-18\",\n                \"created_at\": 1721764800,\n                \"fine_tuned_model\": null,\n                \"organization_id\": \"org-123\",\n                \"result_files\": [],\n                \"status\": \"queued\",\n                \"validation_file\": null,\n                \"training_file\": \"file-abc123\",\n              }\n          - title: Epochs\n            request:\n              curl: |\n                curl https://api.openai.com/v1/fine_tuning/jobs \\\n                  -H \"Content-Type: application/json\" \\\n                  -H \"Authorization: Bearer $OPENAI_API_KEY\" \\\n                  -d \'{\n                    \"training_file\": \"file-abc123\",\n                    \"model\": \"gpt-4o-mini\",\n                    \"hyperparameters\": {\n                      \"n_epochs\": 2\n                    }\n                  }\'\n              python: |\n                from openai import OpenAI\n                client = OpenAI()\n\n                client.fine_tuning.jobs.create(\n                  training_file=\"file-abc123\",\n                  model=\"gpt-4o-mini\",\n                  hyperparameters={\n                    \"n_epochs\":2\n                  }\n                )\n              node.js: |\n                import OpenAI from \"openai\";\n\n                const openai = new OpenAI();\n\n                async function main() {\n                  const fineTune = await openai.fineTuning.jobs.create({\n                    training_file: \"file-abc123\",\n                    model: \"gpt-4o-mini\",\n                    hyperparameters: { n_epochs: 2 }\n                  });\n\n                  console.log(fineTune);\n                }\n\n                main();\n            response: |\n              {\n                \"object\": \"fine_tuning.job\",\n                \"id\": \"ftjob-abc123\",\n                \"model\": \"gpt-4o-mini-2024-07-18\",\n                \"created_at\": 1721764800,\n                \"fine_tuned_model\": null,\n                \"organization_id\": \"org-123\",\n                \"result_files\": [],\n                \"status\": \"queued\",\n                \"validation_file\": null,\n                \"training_file\": \"file-abc123\",\n                \"hyperparameters\": {\"n_epochs\": 2},\n              }\n          - title: Validation file\n            request:\n              curl: |\n                curl https://api.openai.com/v1/fine_tuning/jobs \\\n                  -H \"Content-Type: application/json\" \\\n                  -H \"Authorization: Bearer $OPENAI_API_KEY\" \\\n                  -d \'{\n                    \"training_file\": \"file-abc123\",\n                    \"validation_file\": \"file-abc123\",\n                    \"model\": \"gpt-4o-mini\"\n                  }\'\n              python: |\n                from openai import OpenAI\n                client = OpenAI()\n\n                client.fine_tuning.jobs.create(\n                  training_file=\"file-abc123\",\n                  validation_file=\"file-def456\",\n                  model=\"gpt-4o-mini\"\n                )\n              node.js: |\n                import OpenAI from \"openai\";\n\n                const openai = new OpenAI();\n\n                async function main() {\n                  const fineTune = await openai.fineTuning.jobs.create({\n                    training_file: \"file-abc123\",\n                    validation_file: \"file-abc123\"\n                  });\n\n                  console.log(fineTune);\n                }\n\n                main();\n            response: |\n              {\n                \"object\": \"fine_tuning.job\",\n                \"id\": \"ftjob-abc123\",\n                \"model\": \"gpt-4o-mini-2024-07-18\",\n                \"created_at\": 1721764800,\n                \"fine_tuned_model\": null,\n                \"organization_id\": \"org-123\",\n                \"result_files\": [],\n                \"status\": \"queued\",\n                \"validation_file\": \"file-abc123\",\n                \"training_file\": \"file-abc123\",\n              }\n          - title: W&B Integration\n            request:\n              curl: |\n                curl https://api.openai.com/v1/fine_tuning/jobs \\\n                  -H \"Content-Type: application/json\" \\\n                  -H \"Authorization: Bearer $OPENAI_API_KEY\" \\\n                  -d \'{\n                    \"training_file\": \"file-abc123\",\n                    \"validation_file\": \"file-abc123\",\n                    \"model\": \"gpt-4o-mini\",\n                    \"integrations\": [\n                      {\n                        \"type\": \"wandb\",\n                        \"wandb\": {\n                          \"project\": \"my-wandb-project\",\n                          \"name\": \"ft-run-display-name\"\n                          \"tags\": [\n                            \"first-experiment\", \"v2\"\n                          ]\n                        }\n                      }\n                    ]\n                  }\'\n            response: |\n              {\n                \"object\": \"fine_tuning.job\",\n                \"id\": \"ftjob-abc123\",\n                \"model\": \"gpt-4o-mini-2024-07-18\",\n                \"created_at\": 1721764800,\n                \"fine_tuned_model\": null,\n                \"organization_id\": \"org-123\",\n                \"result_files\": [],\n                \"status\": \"queued\",\n                \"validation_file\": \"file-abc123\",\n                \"training_file\": \"file-abc123\",\n                \"integrations\": [\n                  {\n                    \"type\": \"wandb\",\n                    \"wandb\": {\n                      \"project\": \"my-wandb-project\",\n                      \"entity\": None,\n                      \"run_id\": \"ftjob-abc123\"\n                    }\n                  }\n                ]\n              }\n    get:\n      operationId: listPaginatedFineTuningJobs\n      tags:\n        - Fine-tuning\n      summary: |\n        List your organization\'s fine-tuning jobs\n      parameters:\n        - name: after\n          in: query\n          description: Identifier for the last job from the previous pagination request.\n          required: false\n          schema:\n            type: string\n        - name: limit\n          in: query\n          description: Number of fine-tuning jobs to retrieve.\n          required: false\n          schema:\n            type: integer\n            default: 20\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/ListPaginatedFineTuningJobsResponse\'\n    