n                -H \"Authorization: Bearer $OPENAI_API_KEY\" \\\n                -F purpose=\"fine-tune\" \\\n                -F file=\"@mydata.jsonl\"\n                -F expires_after[anchor]=\"created_at\"\n                -F expires_after[seconds]=3600\n            python: |-\n              from openai import OpenAI\n\n              client = OpenAI(\n                  api_key=\"My API Key\",\n              )\n              file_object = client.files.create(\n                  file=b\"raw file contents\",\n                  purpose=\"assistants\",\n              )\n              print(file_object.id)\n            node.js: |-\n              import OpenAI from \'openai\';\n\n              const client = new OpenAI({\n                apiKey: \'My API Key\',\n              });\n\n              const fileObject = await client.files.create({\n                file: fs.createReadStream(\'fine-tune.jsonl\'),\n                purpose: \'assistants\',\n              });\n\n              console.log(fileObject.id);\n            go: |\n              package main\n\n              import (\n                \"bytes\"\n                \"context\"\n                \"fmt\"\n                \"io\"\n\n                \"github.com/openai/openai-go\"\n                \"github.com/openai/openai-go/option\"\n              )\n\n              func main() {\n                client := openai.NewClient(\n                  option.WithAPIKey(\"My API Key\"),\n                )\n                fileObject, err := client.Files.New(context.TODO(), openai.FileNewParams{\n                  File: io.Reader(bytes.NewBuffer([]byte(\"some file contents\"))),\n                  Purpose: openai.FilePurposeAssistants,\n                })\n                if err != nil {\n                  panic(err.Error())\n                }\n                fmt.Printf(\"%+v\\n\", fileObject.ID)\n              }\n            java: |-\n              package com.openai.example;\n\n              import com.openai.client.Ope