\'#/components/schemas/UrlCitationBody-2\'\n        - $ref: \'#/components/schemas/ContainerFileCitationBody-2\'\n    TopLogProb-2:\n      properties:\n        token:\n          type: string\n        logprob:\n          type: number\n        bytes:\n          items:\n            type: integer\n          type: array\n      type: object\n      required:\n        - token\n        - logprob\n        - bytes\n      title: Top log probability\n    LogProb-2:\n      properties:\n        token:\n          type: string\n        logprob:\n          type: number\n        bytes:\n          items:\n            type: integer\n          type: array\n        top_logprobs:\n          items:\n            $ref: \'#/components/schemas/TopLogProb-2\'\n          type: array\n      type: object\n      required:\n        - token\n        - logprob\n        - bytes\n        - top_logprobs\n      title: Log probability\n    OutputTextContent-2:\n      properties:\n        type:\n          type: string\n          enum:\n            - output_text\n          description: The type of the output text. Always `output_text`.\n          default: output_text\n          x-stainless-const: true\n        text:\n          type: string\n          description: The text output from the model.\n        annotations:\n          items:\n            $ref: \'#/components/schemas/Annotation-2\'\n          type: array\n          description: The annotations of the text output.\n        logprobs:\n          items:\n            $ref: \'#/components/schemas/LogProb-2\'\n          type: array\n      type: object\n      required:\n        - type\n        - text\n        - annotations\n      title: Output text\n    TextContent:\n      properties:\n        type:\n          type: string\n          enum:\n            - text\n          default: text\n          x-stainless-const: true\n        text:\n          type: string\n      type: object\n      required:\n        - type\n        - text\n      title: Text Content\n    SummaryTextContent:\n      properties:\n        type:\n          type: string\n          enum:\n            - summary_text\n          default: summary_text\n          x-stainless-const: true\n        text:\n          type: string\n      type: object\n      required:\n        - type\n        - text\n      title: Summary text\n    RefusalContent-2:\n      properties:\n        type:\n          type: string\n          enum:\n            - refusal\n          description: The type of the refusal. Always `refusal`.\n          default: refusal\n          x-stainless-const: true\n        refusal:\n          type: string\n          description: The refusal explanation from the model.\n      type: object\n      required:\n        - type\n        - refusal\n      title: Refusal\n    InputImageContent-2:\n      properties:\n        type:\n          type: string\n          enum:\n            - input_image\n          description: The type of the input item. Always `input_image`.\n          default: input_image\n          x-stainless-const: true\n        image_url:\n          anyOf:\n            - type: string\n              description: >-\n                The URL of the image to be sent to the model. A fully qualified URL or base64 encoded image in\n                a data URL.\n            - type: \'null\'\n        file_id:\n          anyOf:\n            - type: string\n              description: The ID of the file to be sent to the model.\n            - type: \'null\'\n        detail:\n          type: string\n          enum:\n            - low\n            - high\n            - auto\n          description: >-\n            The detail level of the image to be sent to the model. One of `high`, `low`, or `auto`. Defaults\n            to `auto`.\n      type: object\n      required:\n        - type\n        - image_url\n        - file_id\n        - detail\n      title: Input image\n    ComputerScreenshotContent:\n      properties:\n        type:\n          type: string\n          enum:\n            - computer_screenshot\n          description: >-\n            Specifies the event type. For a computer screenshot, this property is always set to\n            `computer_screenshot`.\n          default: computer_screenshot\n          x-stainless-const: true\n        image_url:\n          anyOf:\n            - type: string\n              description: The URL of the screenshot image.\n            - type: \'null\'\n        file_id:\n          anyOf:\n            - type: string\n              description: The identifier of an uploaded file that contains the screenshot.\n            - type: \'null\'\n      type: object\n      required:\n        - type\n        - image_url\n        - file_id\n      title: Computer screenshot\n    InputFileContent-2:\n      properties:\n        type:\n          type: string\n          enum:\n            - input_file\n          description: The type of the input item. Always `input_file`.\n          default: input_file\n          x-stainless-const: true\n        file_id:\n          anyOf:\n            - type: string\n              description: The ID of the file to be sent to the model.\n            - type: \'null\'\n        filename:\n          type: string\n          description: The name of the file to be sent to the model.\n        file_url:\n          type: string\n          description: The URL of the file to be sent to the model.\n      type: object\n      required:\n        - type\n        - file_id\n      title: Input file\n    Message:\n      properties:\n        type:\n          type: string\n          enum:\n            - message\n          description: The type of the message. Always set to `message`.\n          default: message\n          x-stainless-const: true\n        id:\n          type: string\n          description: The unique ID of the message.\n        status:\n          type: string\n          enum:\n            - in_progress\n            - completed\n            - incomplete\n          description: >-\n            The status of item. One of `in_progress`, `completed`, or `incomplete`. Populated when items are\n            returned via API.\n        role:\n          type: string\n          enum:\n            - unknown\n            - user\n            - assistant\n            - system\n            - critic\n            - discriminator\n            - developer\n            - tool\n          description: >-\n            The role of the message. One of `unknown`, `user`, `assistant`, `system`, `critic`,\n            `discriminator`, `developer`, or `tool`.\n        content:\n          items:\n            discriminator:\n              propertyName: type\n            anyOf:\n              - $ref: \'#/components/schemas/InputTextContent-2\'\n              - $ref: \'#/components/schemas/OutputTextContent-2\'\n              - $ref: \'#/components/schemas/TextContent\'\n              - $ref: \'#/components/schemas/SummaryTextContent\'\n              - $ref: \'#/components/schemas/RefusalContent-2\'\n              - $ref: \'#/components/schemas/InputImageContent-2\'\n              - $ref: \'#/components/schemas/ComputerScreenshotContent\'\n              - $ref: \'#/components/schemas/InputFileContent-2\'\n          type: array\n          description: The content of the message\n      type: object\n      required:\n        - type\n        - id\n        - status\n        - role\n        - content\n      title: Message\n    FunctionTool:\n      properties:\n        type:\n          type: string\n          enum:\n            - function\n          description: The type of the function tool. Always `function`.\n          default: function\n          x-stainless-const: true\n        name:\n          type: string\n          description: The name of the function to call.\n        description:\n          anyOf:\n            - type: string\n              description: >-\n                A description of the function. Used by the model to determine whether or not to call the\n                function.\n            - type: \'null\'\n        parameters:\n          anyOf:\n            - additionalProperties: {}\n              type: object\n              description: A JSON schema object describing the parameters of the function.\n            - type: \'null\'\n        strict:\n          anyOf:\n            - type: boolean\n              description: Whether to enforce strict parameter validation. Default `true`.\n            - type: \'null\'\n      type: object\n      required:\n        - type\n        - name\n        - strict\n        - parameters\n      title: Function\n      description: >-\n        Defines a function in your own code the model can choose to call. Learn more about [function\n        calling](https://platform.openai.com/docs/guides/function-calling).\n    RankingOptions:\n      properties:\n        ranker:\n          type: string\n          enum:\n            - auto\n            - default-2024-11-15\n          description: The ranker to use for the file search.\n        score_threshold:\n          type: number\n          description: >-\n            The score threshold for the file search, a number between 0 and 1. Numbers closer to 1 will\n            attempt to return only the most relevant results, but may return fewer results.\n      type: object\n      required: []\n    Filters:\n      anyOf:\n        - $ref: \'#/components/schemas/ComparisonFilter\'\n        - $ref: \'#/components/schemas/CompoundFilter\'\n    FileSearchTool:\n      properties:\n        type:\n          type: string\n          enum:\n            - file_search\n          description: The type of the file search tool. Always `file_search`.\n          default: file_search\n          x-stainless-const: true\n        vector_store_ids:\n          items:\n            type: string\n          type: array\n          description: The IDs of the vector stores to search.\n        max_num_results:\n          type: integer\n          description: The maximum number of results to return. This number should be between 1 and 50 inclusive.\n        ranking_options:\n          $ref: \'#/components/schemas/RankingOptions\'\n          description: Ranking options for search.\n        filters:\n          anyOf:\n            - $ref: \'#/components/schemas/Filters\'\n              description: A filter to apply.\n            - type: \'null\'\n      type: object\n      required:\n        - type\n        - vector_store_ids\n      title: File search\n      description: >-\n        A tool that searches for relevant content from uploaded files. Learn more about the [file search\n        tool](https://platform.openai.com/docs/guides/tools-file-search).\n    ComputerUsePreviewTool:\n      properties:\n        type:\n          type: string\n          enum:\n            - computer_use_preview\n          description: The type of the computer use tool. Always `computer_use_preview`.\n          default: computer_use_preview\n          x-stainless-const: true\n        environment:\n          type: string\n          enum:\n            - windows\n            - mac\n            - linux\n            - ubuntu\n            - browser\n          description: The type of computer environment to control.\n        display_width:\n          type: integer\n          description: The width of the computer display.\n        display_height:\n          type: integer\n          description: The height of the computer display.\n      type: object\n      required:\n        - type\n        - environment\n        - display_width\n        - display_height\n      title: Computer use preview\n      description: >-\n        A tool that controls a virtual computer. Learn more about the [computer\n        tool](https://platform.openai.com/docs/guides/tools-computer-use).\n    ApproximateLocation:\n      properties:\n        type:\n          type: string\n          enum:\n            - approximate\n          description: The type of location approximation. Always `approximate`.\n          default: approximate\n          x-stainless-const: true\n        country:\n          anyOf:\n            - type: string\n              description: >-\n                The two-letter [ISO country code](https://en.wikipedia.org/wiki/ISO_3166-1) of the user, e.g.\n                `US`.\n            - type: \'null\'\n        region:\n          anyOf:\n            - type: string\n              description: Free text input for the region of the user, e.g. `California`.\n            - type: \'null\'\n        city:\n          anyOf:\n            - type: string\n              description: Free text input for the city of the user, e.g. `San Francisco`.\n            - type: \'null\'\n        timezone:\n          anyOf:\n            - type: string\n              description: >-\n                The [IANA timezone](https://timeapi.io/documentation/iana-timezones) of the user, e.g.\n                `America/Los_Angeles`.\n            - type: \'null\'\n      type: object\n      required:\n        - type\n    WebSearchPreviewTool:\n      properties:\n        type:\n          type: string\n          enum:\n            - web_search_preview\n            - web_search_preview_2025_03_11\n          description: The type of the web search tool. One of `web_search_preview` or `web_search_preview_2025_03_11`.\n          default: web_search_preview\n          x-stainless-const: true\n        user_location:\n          anyOf:\n            - $ref: \'#/components/schemas/ApproximateLocation\'\n              description: The user\'s location.\n            - type: \'null\'\n        search_context_size:\n          type: string\n          enum:\n            - low\n            - medium\n            - high\n          description: >-\n            High level guidance for the amount of context window space to use for the search. One of `low`,\n            `medium`, or `high`. `medium` is the default.\n      type: object\n      required:\n        - type\n      title: Web search preview\n      description: >-\n        This tool searches the web for relevant results to use in a response. Learn more about the [web search\n        tool](https://platform.openai.com/docs/guides/tools-web-search).\n    ImageGenInputUsageDetails:\n      properties:\n        text_tokens:\n          type: integer\n          description: The number of text tokens in the input prompt.\n        image_tokens:\n          type: integer\n          description: The number of image tokens in the input prompt.\n      type: object\n      required:\n        - text_tokens\n        - image_tokens\n      title: Input usage details\n      description: The input tokens detailed information for the image generation.\n    ImageGenUsage:\n      properties:\n        input_tokens:\n          type: integer\n          description: The number of tokens (images and text) in the input prompt.\n        total_tokens:\n          type: integer\n          description: The total number of tokens (images and text) used for the image generation.\n        output_tokens:\n          type: integer\n          description: The number of output tokens generated by the model.\n        input_tokens_details:\n          $ref: \'#/components/schemas/ImageGenInputUsageDetails\'\n      type: object\n      required:\n        - input_tokens\n        - total_tokens\n        - output_tokens\n        - input_tokens_details\n      title: Image generation usage\n      description: For `gpt-image-1` only, the token usage information for the image generation.\n    ConversationParam:\n      properties:\n        id:\n          type: string\n          description: The unique ID of the conversation.\n      type: object\n      required:\n        - id\n      title: Conversation object\n      description: The conversation that this response belongs to.\n    Conversation-2:\n      properties:\n        id:\n          type: string\n          description: The unique ID of the conversation.\n      type: object\n      required:\n        - id\n      title: Conversation\n      description: >-\n        The conversation that this response belongs to. Input items and output items from this response are\n        automatically added to this conversation.\n    RealtimeConversationItemContent:\n      type: object\n      properties:\n        type:\n          type: string\n          enum:\n            - input_text\n            - input_audio\n            - item_reference\n            - text\n            - audio\n          description: |\n            The content type (`input_text`, `input_audio`, `item_reference`, `text`, `audio`).\n        text:\n          type: string\n          description: |\n            The text content, used for `input_text` and `text` content types.\n        id:\n          type: string\n          description: |\n            ID of a previous conversation item to reference (for `item_reference`\n            content types in `response.create` events). These can reference both\n            client and server created items.\n        audio:\n          type: string\n          description: |\n            Base64-encoded audio bytes, used for `input_audio` content type.\n        transcript:\n          type: string\n          description: |\n            The transcript of the audio, used for `input_audio` and `audio` \n            content types.\n    RealtimeConnectParams:\n      type: object\n      properties:\n        model:\n          type: string\n      required:\n        - model\n    ModerationImageURLInput:\n      type: object\n      description: An object describing an image to classify.\n      properties:\n        type:\n          description: Always `image_url`.\n          type: string\n          enum:\n            - image_url\n          x-stainless-const: true\n        image_url:\n          type: object\n          description: Contains either an image URL or a data URL for a base64 encoded image.\n          properties:\n            url:\n              type: string\n              description: Either a URL of the image or the base64 encoded image data.\n              format: uri\n              example: https://example.com/image.jpg\n          required:\n            - url\n      required:\n        - type\n        - image_url\n    ModerationTextInput:\n      type: object\n      description: An object describing text to classify.\n      properties:\n        type:\n          description: Always `text`.\n          type: string\n          enum:\n            - text\n          x-stainless-const: true\n        text:\n          description: A string of text to classify.\n          type: string\n          example: I want to kill them\n      required:\n        - type\n        - text\n    ChunkingStrategyResponse:\n      type: object\n      description: The strategy used to chunk the file.\n      anyOf:\n        - $ref: \'#/components/schemas/StaticChunkingStrategyResponseParam\'\n        - $ref: \'#/components/schemas/OtherChunkingStrategyResponseParam\'\n      discriminator:\n        propertyName: type\n    FilePurpose:\n      description: >\n        The intended purpose of the uploaded file. One of: - `assistants`: Used in the Assistants API -\n        `batch`: Used in the Batch API - `fine-tune`: Used for fine-tuning - `vision`: Images used for vision\n        fine-tuning - `user_data`: Flexible file type for any purpose - `evals`: Used for eval data sets\n      type: string\n      enum:\n        - assistants\n        - batch\n        - fine-tune\n        - vision\n        - user_data\n        - evals\n    BatchError:\n      type: object\n      properties:\n        code:\n          type: string\n          description: An error code identifying the error type.\n        message:\n          type: string\n          description: A human-readable message providing more details about the error.\n        param:\n          type: string\n          description: The name of the parameter that caused the error, if applicable.\n          nullable: true\n        line:\n          type: integer\n          description: The line number of the input file where the error occurred, if applicable.\n          nullable: true\n    BatchRequestCounts:\n      type: object\n      properties:\n        total:\n          type: integer\n          description: Total number of requests in the batch.\n        completed:\n          type: integer\n          description: Number of requests that have been completed successfully.\n        failed:\n          type: integer\n          description: Number of requests that have failed.\n      required:\n        - total\n        - completed\n        - failed\n      description: The request counts for different statuses within the batch.\n    AssistantTool:\n      anyOf:\n        - $ref: \'#/components/schemas/AssistantToolsCode\'\n        - $ref: \'#/components/schemas/AssistantToolsFileSearch\'\n        - $ref: \'#/components/schemas/AssistantToolsFunction\'\n      discriminator:\n        propertyName: type\n    TextAnnotationDelta:\n      anyOf:\n        - $ref: \'#/components/schemas/MessageDeltaContentTextAnnotationsFileCitationObject\'\n        - $ref: \'#/components/schemas/MessageDeltaContentTextAnnotationsFilePathObject\'\n      discriminator:\n        propertyName: type\n    TextAnnotation:\n      anyOf:\n        - $ref: \'#/components/schemas/MessageContentTextAnnotationsFileCitationObject\'\n        - $ref: \'#/components/schemas/MessageContentTextAnnotationsFilePathObject\'\n      discriminator:\n        propertyName: type\n    RunStepDetailsToolCall:\n      anyOf:\n        - $ref: \'#/components/schemas/RunStepDetailsToolCallsCodeObject\'\n        - $ref: \'#/components/schemas/RunStepDetailsToolCallsFileSearchObject\'\n        - $ref: \'#/components/schemas/RunStepDetailsToolCallsFunctionObject\'\n      discriminator:\n        propertyName: type\n    RunStepDeltaStepDetailsToolCall:\n      anyOf:\n        - $ref: \'#/components/schemas/RunStepDeltaStepDetailsToolCallsCodeObject\'\n        - $ref: \'#/components/schemas/RunStepDeltaStepDetailsToolCallsFileSearchObject\'\n        - $ref: \'#/components/schemas/RunStepDeltaStepDetailsToolCallsFunctionObject\'\n      discriminator:\n        propertyName: type\n    MessageContent:\n      anyOf:\n        - $ref: \'#/components/schemas/MessageContentImageFileObject\'\n        - $ref: \'#/components/schemas/MessageContentImageUrlObject\'\n        - $ref: \'#/components/schemas/MessageContentTextObject\'\n        - $ref: \'#/components/schemas/MessageContentRefusalObject\'\n      discriminator:\n        propertyName: type\n    MessageContentDelta:\n      anyOf:\n        - $ref: \'#/components/schemas/MessageDeltaContentImageFileObject\'\n        - $ref: \'#/components/schemas/MessageDeltaContentTextObject\'\n        - $ref: \'#/components/schemas/MessageDeltaContentRefusalObject\'\n        - $ref: \'#/components/schemas/MessageDeltaContentImageUrlObject\'\n      discriminator:\n        propertyName: type\n    ChatModel:\n      type: string\n      enum:\n        - gpt-5\n        - gpt-5-mini\n        - gpt-5-nano\n        - gpt-5-2025-08-07\n        - gpt-5-mini-2025-08-07\n        - gpt-5-nano-2025-08-07\n        - gpt-5-chat-latest\n        - gpt-4.1\n        - gpt-4.1-mini\n        - gpt-4.1-nano\n        - gpt-4.1-2025-04-14\n        - gpt-4.1-mini-2025-04-14\n        - gpt-4.1-nano-2025-04-14\n        - o4-mini\n        - o4-mini-2025-04-16\n        - o3\n        - o3-2025-04-16\n        - o3-mini\n        - o3-mini-2025-01-31\n        - o1\n        - o1-2024-12-17\n        - o1-preview\n        - o1-preview-2024-09-12\n        - o1-mini\n        - o1-mini-2024-09-12\n        - gpt-4o\n        - gpt-4o-2024-11-20\n        - gpt-4o-2024-08-06\n        - gpt-4o-2024-05-13\n        - gpt-4o-audio-preview\n        - gpt-4o-audio-preview-2024-10-01\n        - gpt-4o-audio-preview-2024-12-17\n        - gpt-4o-audio-preview-2025-06-03\n        - gpt-4o-mini-audio-preview\n        - gpt-4o-mini-audio-preview-2024-12-17\n        - gpt-4o-search-preview\n        - gpt-4o-mini-search-preview\n        - gpt-4o-search-preview-2025-03-11\n        - gpt-4o-mini-search-preview-2025-03-11\n        - chatgpt-4o-latest\n        - codex-mini-latest\n        - gpt-4o-mini\n        - gpt-4o-mini-2024-07-18\n        - gpt-4-turbo\n        - gpt-4-turbo-2024-04-09\n        - gpt-4-0125-preview\n        - gpt-4-turbo-preview\n        - gpt-4-1106-preview\n        - gpt-4-vision-preview\n        - gpt-4\n        - gpt-4-0314\n        - gpt-4-0613\n        - gpt-4-32k\n        - gpt-4-32k-0314\n        - gpt-4-32k-0613\n        - gpt-3.5-turbo\n        - gpt-3.5-turbo-16k\n        - gpt-3.5-turbo-0301\n        - gpt-3.5-turbo-0613\n        - gpt-3.5-turbo-1106\n        - gpt-3.5-turbo-0125\n        - gpt-3.5-turbo-16k-0613\n      x-stainless-nominal: false\n    CreateThreadAndRunRequestWithoutStream:\n      type: object\n      additionalProperties: false\n      properties:\n        assistant_id:\n          description: >-\n            The ID of the [assistant](https://platform.openai.com/docs/api-reference/assistants) to use to\n            execute this run.\n          type: string\n        thread:\n          $ref: \'#/components/schemas/CreateThreadRequest\'\n        model:\n          description: >-\n            The ID of the [Model](https://platform.openai.com/docs/api-reference/models) to be used to execute\n            this run. If a value is provided here, it will override the model associated with the assistant.\n            If not, the model associated with the assistant will be used.\n          anyOf:\n            - type: string\n            - type: string\n              enum:\n                - gpt-5\n                - gpt-5-mini\n                - gpt-5-nano\n                - gpt-5-2025-08-07\n                - gpt-5-mini-2025-08-07\n                - gpt-5-nano-2025-08-07\n                - gpt-4.1\n                - gpt-4.1-mini\n                - gpt-4.1-nano\n                - gpt-4.1-2025-04-14\n                - gpt-4.1-mini-2025-04-14\n                - gpt-4.1-nano-2025-04-14\n                - gpt-4o\n                - gpt-4o-2024-11-20\n                - gpt-4o-2024-08-06\n                - gpt-4o-2024-05-13\n                - gpt-4o-mini\n                - gpt-4o-mini-2024-07-18\n                - gpt-4.5-preview\n                - gpt-4.5-preview-2025-02-27\n                - gpt-4-turbo\n                - gpt-4-turbo-2024-04-09\n                - gpt-4-0125-preview\n                - gpt-4-turbo-preview\n                - gpt-4-1106-preview\n                - gpt-4-vision-preview\n                - gpt-4\n                - gpt-4-0314\n                - gpt-4-0613\n                - gpt-4-32k\n                - gpt-4-32k-0314\n                - gpt-4-32k-0613\n                - gpt-3.5-turbo\n                - gpt-3.5-turbo-16k\n                - gpt-3.5-turbo-0613\n                - gpt-3.5-turbo-1106\n                - gpt-3.5-turbo-0125\n                - gpt-3.5-turbo-16k-0613\n          x-oaiTypeLabel: string\n          nullable: true\n        instructions:\n          description: >-\n            Override the default system message of the assistant. This is useful for modifying the behavior on\n            a per-run basis.\n          type: string\n          nullable: true\n        tools:\n          description: >-\n            Override the tools the assistant can use for this run. This is useful for modifying the behavior\n            on a per-run basis.\n          nullable: true\n          type: array\n          maxItems: 20\n          items:\n            $ref: \'#/components/schemas/AssistantTool\'\n        tool_resources:\n          type: object\n          description: >\n            A set of resources that are used by the assistant\'s tools. The resources are specific to the type\n            of tool. For example, the `code_interpreter` tool requires a list of file IDs, while the\n            `file_search` tool requires a list of vector store IDs.\n          properties:\n            code_interpreter:\n              type: object\n              properties:\n                file_ids:\n                  type: array\n                  description: >\n                    A list of [file](https://platform.openai.com/docs/api-reference/files) IDs made available\n                    to the `code_interpreter` tool. There can be a maximum of 20 files associated with the\n                    tool.\n                  default: []\n                  maxItems: 20\n                  items:\n                    type: string\n            file_search:\n              type: object\n              properties:\n                vector_store_ids:\n                  type: array\n                  description: >\n                    The ID of the [vector\n                    store](https://platform.openai.com/docs/api-reference/vector-stores/object) attached to\n                    this assistant. There can be a maximum of 1 vector store attached to the assistant.\n                  maxItems: 1\n                  items:\n                    type: string\n          nullable: true\n        metadata:\n          $ref: \'#/components/schemas/Metadata\'\n        temperature:\n          type: number\n          minimum: 0\n          maximum: 2\n          default: 1\n          example: 1\n          nullable: true\n          description: >\n            What sampling temperature to use, between 0 and 2. Higher values like 0.8 will make the output\n            more random, while lower values like 0.2 will make it more focused and deterministic.\n        top_p:\n          type: number\n          minimum: 0\n          maximum: 1\n          default: 1\n          example: 1\n          nullable: true\n          description: >\n            An alternative to sampling with temperature, called nucleus sampling, where the model considers\n            the results of the tokens with top_p probability mass. So 0.1 means only the tokens comprising the\n            top 10% probability mass are considered.\n\n\n            We generally recommend altering this or temperature but not both.\n        max_prompt_tokens:\n          type: integer\n          nullable: true\n          description: >\n            The maximum number of prompt tokens that may be used over the course of the run. The run will make\n            a best effort to use only the number of prompt tokens specified, across multiple turns of the run.\n            If the run exceeds the number of prompt tokens specified, the run will end with status\n            `incomplete`. See `incomplete_details` for more info.\n          minimum: 256\n        max_completion_tokens:\n          type: integer\n          nullable: true\n          description: >\n            The maximum number of completion tokens that may be used over the course of the run. The run will\n            make a best effort to use only the number of completion tokens specified, across multiple turns of\n            the run. If the run exceeds the number of completion tokens specified, the run will end with\n            status `incomplete`. See `incomplete_details` for more info.\n          minimum: 256\n        truncation_strategy:\n          allOf:\n            - $ref: \'#/components/schemas/TruncationObject\'\n            - nullable: true\n        tool_choice:\n          allOf:\n            - $ref: \'#/components/schemas/AssistantsApiToolChoiceOption\'\n            - nullable: true\n        parallel_tool_calls:\n          $ref: \'#/components/schemas/ParallelToolCalls\'\n        response_format:\n          $ref: \'#/components/schemas/AssistantsApiResponseFormatOption\'\n          nullable: true\n      required: *ref_0\n    CreateRunRequestWithoutStream:\n      type: object\n      additionalProperties: false\n      properties:\n        assistant_id:\n          description: >-\n            The ID of the [assistant](https://platform.openai.com/docs/api-reference/assistants) to use to\n            execute this run.\n          type: string\n        model:\n          description: >-\n            The ID of the [Model](https://platform.openai.com/docs/api-reference/models) to be used to execute\n            this run. If a value is provided here, it will override the model associated with the assistant.\n            If not, the model associated with the assistant will be used.\n          anyOf:\n            - type: string\n            - $ref: \'#/components/schemas/AssistantSupportedModels\'\n          x-oaiTypeLabel: string\n          nullable: true\n        reasoning_effort:\n          $ref: \'#/components/schemas/ReasoningEffort\'\n        instructions:\n          description: >-\n            Overrides the\n            [instructions](https://platform.openai.com/docs/api-reference/assistants/createAssistant) of the\n            assistant. This is useful for modifying the behavior on a per-run basis.\n          type: string\n          nullable: true\n        additional_instructions:\n          description: >-\n            Appends additional instructions at the end of the instructions for the run. This is useful for\n            modifying the behavior on a per-run basis without overriding other instructions.\n          type: string\n          nullable: true\n        additional_messages:\n          description: Adds additional messages to the thread before creating the run.\n          type: array\n          items:\n            $ref: \'#/components/schemas/CreateMessageRequest\'\n          nullable: true\n        tools:\n          description: >-\n            Override the tools the assistant can use for this run. This is useful for modifying the behavior\n            on a per-run basis.\n          nullable: true\n          type: array\n          maxItems: 20\n          items:\n            $ref: \'#/components/schemas/AssistantTool\'\n        metadata:\n          $ref: \'#/components/schemas/Metadata\'\n        temperature:\n          type: number\n          minimum: 0\n          maximum: 2\n          default: 1\n          example: 1\n          nullable: true\n          description: >\n            What sampling temperature to use, between 0 and 2. Higher values like 0.8 will make the output\n            more random, while lower values like 0.2 will make it more focused and deterministic.\n        top_p:\n          type: number\n          minimum: 0\n          maximum: 1\n          default: 1\n          example: 1\n          nullable: true\n          description: >\n            An alternative to sampling with temperature, called nucleus sampling, where the model considers\n            the results of the tokens with top_p probability mass. So 0.1 means only the tokens comprising the\n            top 10% probability mass are considered.\n\n\n            We generally recommend altering this or temperature but not both.\n        max_prompt_tokens:\n          type: integer\n          nullable: true\n          description: >\n            The maximum number of prompt tokens that may be used over the course of the run. The run will make\n            a best effort to use only the number of prompt tokens specified, across multiple turns of the run.\n            If the run exceeds the number of prompt tokens specified, the run will end with status\n            `incomplete`. See `incomplete_details` for more info.\n          minimum: 256\n        max_completion_tokens:\n          type: integer\n          nullable: true\n          description: >\n            The maximum number of completion tokens that may be used over the course of the run. The run will\n            make a best effort to use only the number of completion tokens specified, across multiple turns of\n            the run. If the run exceeds the number of completion tokens specified, the run will end with\n            status `incomplete`. See `incomplete_details` for more info.\n          minimum: 256\n        truncation_strategy:\n          allOf:\n            - $ref: \'#/components/schemas/TruncationObject\'\n            - nullable: true\n        tool_choice:\n          allOf:\n            - $ref: \'#/components/schemas/AssistantsApiToolChoiceOption\'\n            - nullable: true\n        parallel_tool_calls:\n          $ref: \'#/components/schemas/ParallelToolCalls\'\n        response_format:\n          $ref: \'#/components/schemas/AssistantsApiResponseFormatOption\'\n          nullable: true\n      required: *ref_0\n    SubmitToolOutputsRunRequestWithoutStream:\n      type: object\n      additionalProperties: false\n      properties:\n        tool_outputs:\n          description: A list of tools for which the outputs are being submitted.\n          type: array\n          items:\n            type: object\n            properties:\n              tool_call_id:\n                type: string\n                description: >-\n                  The ID of the tool call in the `required_action` object within the run object the output is\n                  being submitted for.\n              output:\n                type: string\n                description: The output of the tool call to be submitted to continue the run.\n      required:\n        - tool_outputs\n    RunStatus:\n      description: >-\n        The status of the run, which can be either `queued`, `in_progress`, `requires_action`, `cancelling`,\n        `cancelled`, `failed`, `completed`, `incomplete`, or `expired`.\n      type: string\n      enum:\n        - queued\n        - in_progress\n        - requires_action\n        - cancelling\n        - cancelled\n        - failed\n        - completed\n        - incomplete\n        - expired\n    RunStepDeltaObjectDelta:\n      description: The delta containing the fields that have changed on the run step.\n      type: object\n      properties:\n        step_details:\n          type: object\n          description: The details of the run step.\n          anyOf:\n            - $ref: \'#/components/schemas/RunStepDeltaStepDetailsMessageCreationObject\'\n            - $ref: \'#/components/schemas/RunStepDeltaStepDetailsToolCallsObject\'\n          discriminator:\n            propertyName: type\n  securitySchemes:\n    ApiKeyAuth:\n      type: http\n      scheme: bearer\nx-oaiMeta:\n  navigationGroups:\n    - id: responses\n      title: Responses API\n    - id: webhooks\n      title: Webhooks\n    - id: endpoints\n      title: Platform APIs\n    - id: vector_stores\n      title: Vector stores\n    - id: containers\n      title: Containers\n    - id: realtime\n      title: Realtime\n      beta: true\n    - id: chat\n      title: Chat Completions\n    - id: assistants\n      title: Assistants\n      beta: true\n    - id: administration\n      title: Administration\n    - id: legacy\n      title: Legacy\n  groups:\n    - id: responses\n      title: Responses\n      description: |\n        OpenAI\'s most advanced interface for generating model responses. Supports\n        text and image inputs, and text outputs. Create stateful interactions\n        with the model, using the output of previous responses as input. Extend\n        the model\'s capabilities with built-in tools for file search, web search,\n        computer use, and more. Allow the model access to external systems and data\n        using function calling.\n\n        Related guides:\n        - [Quickstart](https://platform.openai.com/docs/quickstart?api-mode=responses)\n        - [Text inputs and outputs](https://platform.openai.com/docs/guides/text?api-mode=responses)\n        - [Image inputs](https://platform.openai.com/docs/guides/images?api-mode=responses)\n        - [Structured Outputs](https://platform.openai.com/docs/guides/structured-outputs?api-mode=responses)\n        - [Function calling](https://platform.openai.com/docs/guides/function-calling?api-mode=responses)\n        - [Conversation state](https://platform.openai.com/docs/guides/conversation-state?api-mode=responses)\n        - [Extend the models with tools](https://platform.openai.com/docs/guides/tools?api-mode=responses)\n      navigationGroup: responses\n      sections:\n        - type: endpoint\n          key: createResponse\n          path: create\n        - type: endpoint\n          key: getResponse\n          path: get\n        - type: endpoint\n          key: deleteResponse\n          path: delete\n        - type: endpoint\n          key: cancelResponse\n          path: cancel\n        - type: endpoint\n          key: listInputItems\n          path: input-items\n        - type: object\n          key: Response\n          path: object\n        - type: object\n          key: ResponseItemList\n          path: list\n    - id: conversations\n      title: Conversations\n      description: |\n        Create and manage conversations to store and retrieve conversation state across Response API calls.\n      navigationGroup: responses\n      sections:\n        - type: endpoint\n          key: createConversation\n          path: create\n        - type: endpoint\n          key: getConversation\n          path: retrieve\n        - type: endpoint\n          key: updateConversation\n          path: update\n        - type: endpoint\n          key: deleteConversation\n          path: delete\n        - type: endpoint\n          key: listConversationItems\n          path: list-items\n        - type: endpoint\n          key: createConversationItems\n          path: create-items\n        - type: endpoint\n          key: getConversationItem\n          path: get-item\n        - type: endpoint\n          key: deleteConversationItem\n          path: delete-item\n        - type: object\n          key: Conversation\n          path: object\n        - type: object\n          key: ConversationItemList\n          path: list-items-object\n    - id: responses-streaming\n      title: Streaming events\n      description: >\n        When you [create a Response](https://platform.openai.com/docs/api-reference/responses/create) with\n\n        `stream` set to `true`, the server will emit server-sent events to the\n\n        client as the Response is generated. This section contains the events that\n\n        are emitted by the server.\n\n\n        [Learn more about streaming\n        responses](https://platform.openai.com/docs/guides/streaming-responses?api-mode=responses).\n      navigationGroup: responses\n      sections:\n        - type: object\n          key: ResponseCreatedEvent\n          path: <auto>\n        - type: object\n          key: ResponseInProgressEvent\n          path: <auto>\n        - type: object\n          key: ResponseCompletedEvent\n          path: <auto>\n        - type: object\n          key: ResponseFailedEvent\n          path: <auto>\n        - type: object\n          key: ResponseIncompleteEvent\n          path: <auto>\n        - type: object\n          key: ResponseOutputItemAddedEvent\n          path: <auto>\n        - type: object\n          key: ResponseOutputItemDoneEvent\n          path: <auto>\n        - type: object\n          key: ResponseContentPartAddedEvent\n          path: <auto>\n        - type: object\n          key: ResponseContentPartDoneEvent\n          path: <auto>\n        - type: object\n          key: ResponseTextDeltaEvent\n          path: response/output_text/delta\n        - type: object\n          key: ResponseTextDoneEvent\n          path: response/output_text/done\n        - type: object\n          key: ResponseRefusalDeltaEvent\n          path: <auto>\n        - type: object\n          key: ResponseRefusalDoneEvent\n          path: <auto>\n        - type: object\n          key: ResponseFunctionCallArgumentsDeltaEvent\n          path: <auto>\n        - type: object\n          key: ResponseFunctionCallArgumentsDoneEvent\n          path: <auto>\n        - type: object\n          key: ResponseFileSearchCallInProgressEvent\n          path: <auto>\n        - type: object\n          key: ResponseFileSearchCallSearchingEvent\n          path: <auto>\n        - type: object\n          key: ResponseFileSearchCallCompletedEvent\n          path: <auto>\n        - type: object\n          key: ResponseWebSearchCallInProgressEvent\n          path: <auto>\n        - type: object\n          key: ResponseWebSearchCallSearchingEvent\n          path: <auto>\n        - type: object\n          key: ResponseWebSearchCallCompletedEvent\n          path: <auto>\n        - type: object\n          key: ResponseReasoningSummaryPartAddedEvent\n          path: <auto>\n        - type: object\n          key: ResponseReasoningSummaryPartDoneEvent\n          path: <auto>\n        - type: object\n          key: ResponseReasoningSummaryTextDeltaEvent\n          path: <auto>\n        - type: object\n          key: ResponseReasoningSummaryTextDoneEvent\n          path: <auto>\n        - type: object\n          key: ResponseReasoningTextDeltaEvent\n          path: <auto>\n        - type: object\n          key: ResponseReasoningTextDoneEvent\n          path: <auto>\n        - type: object\n          key: ResponseImageGenCallCompletedEvent\n          path: <auto>\n        - type: object\n          key: ResponseImageGenCallGeneratingEvent\n          path: <auto>\n        - type: object\n          key: ResponseImageGenCallInProgressEvent\n          path: <auto>\n        - type: object\n          key: ResponseImageGenCallPartialImageEvent\n          path: <auto>\n        - type: object\n          key: ResponseMCPCallArgumentsDeltaEvent\n          path: <auto>\n        - type: object\n          key: ResponseMCPCallArgumentsDoneEvent\n          path: <auto>\n        - type: object\n          key: ResponseMCPCallCompletedEvent\n          path: <auto>\n        - type: object\n          key: ResponseMCPCallFailedEvent\n          path: <auto>\n        - type: object\n          key: ResponseMCPCallInProgressEvent\n          path: <auto>\n        - type: object\n          key: ResponseMCPListToolsCompletedEvent\n          path: <auto>\n        - type: object\n          key: ResponseMCPListToolsFailedEvent\n          path: <auto>\n        - type: object\n          key: ResponseMCPListToolsInProgressEvent\n          path: <auto>\n        - type: object\n          key: ResponseCodeInterpreterCallInProgressEvent\n          path: <auto>\n        - type: object\n          key: ResponseCodeInterpreterCallInterpretingEvent\n          path: <auto>\n        - type: object\n          key: ResponseCodeInterpreterCallCompletedEvent\n          path: <auto>\n        - type: object\n          key: ResponseCodeInterpreterCallCodeDeltaEvent\n          path: <auto>\n        - type: object\n          key: ResponseCodeInterpreterCallCodeDoneEvent\n          path: <auto>\n        - type: object\n          key: ResponseOutputTextAnnotationAddedEvent\n          path: <auto>\n        - type: object\n          key: ResponseQueuedEvent\n          path: <auto>\n        - type: object\n          key: ResponseCustomToolCallInputDeltaEvent\n          path: <auto>\n        - type: object\n          key: ResponseCustomToolCallInputDoneEvent\n          path: <auto>\n        - type: object\n          key: ResponseErrorEvent\n          path: <auto>\n    - id: webhook-events\n      title: Webhook Events\n      description: |\n        Webhooks are HTTP requests sent by OpenAI to a URL you specify when certain\n        events happen during the course of API usage.\n\n        [Learn more about webhooks](https://platform.openai.com/docs/guides/webhooks).\n      navigationGroup: webhooks\n      sections:\n        - type: object\n          key: WebhookResponseCompleted\n          path: <auto>\n        - type: object\n          key: WebhookResponseCancelled\n          path: <auto>\n        - type: object\n          key: WebhookResponseFailed\n          path: <auto>\n        - type: object\n          key: WebhookResponseIncomplete\n          path: <auto>\n        - type: object\n          key: WebhookBatchCompleted\n          path: <auto>\n        - type: object\n          key: WebhookBatchCancelled\n          path: <auto>\n        - type: object\n          key: WebhookBatchExpired\n          path: <auto>\n        - type: object\n          key: WebhookBatchFailed\n          path: <auto>\n        - type: object\n          key: WebhookFineTuningJobSucceeded\n          path: <auto>\n        - type: object\n          key: WebhookFineTuningJobFailed\n          path: <auto>\n        - type: object\n          key: WebhookFineTuningJobCancelled\n          path: <auto>\n        - type: object\n          key: WebhookEvalRunSucceeded\n          path: <auto>\n        - type: object\n          key: WebhookEvalRunFailed\n          path: <auto>\n        - type: object\n          key: WebhookEvalRunCanceled\n          path: <auto>\n    - id: audio\n      title: Audio\n      description: |\n        Learn how to turn audio into text or text into audio.\n\n        Related guide: [Speech to text](https://platform.openai.com/docs/guides/speech-to-text)\n      navigationGroup: endpoints\n      sections:\n        - type: endpoint\n          key: createSpeech\n          path: createSpeech\n        - type: endpoint\n          key: createTranscription\n          path: createTranscription\n        - type: endpoint\n          key: createTranslation\n          path: createTranslation\n        - type: object\n          key: CreateTranscriptionResponseJson\n          path: json-object\n        - type: object\n          key: CreateTranscriptionResponseVerboseJson\n          path: verbose-json-object\n        - type: object\n          key: SpeechAudioDeltaEvent\n          path: speech-audio-delta-event\n        - type: object\n          key: SpeechAudioDoneEvent\n          path: speech-audio-done-event\n        - type: object\n          key: TranscriptTextDeltaEvent\n          path: transcript-text-delta-event\n        - type: object\n          key: TranscriptTextDoneEvent\n          path: transcript-text-done-event\n    - id: images\n      title: Images\n      description: |\n        Given a prompt and/or an input image, the model will generate a new image.\n        Related guide: [Image generation](https://platform.openai.com/docs/guides/images)\n      navigationGroup: endpoints\n      sections:\n        - type: endpoint\n          key: createImage\n          path: create\n        - type: endpoint\n          key: createImageEdit\n          path: createEdit\n        - type: endpoint\n          key: createImageVariation\n          path: createVariation\n        - type: object\n          key: ImagesResponse\n          path: object\n    - id: images-streaming\n      title: Image Streaming\n      description: |\n        Stream image generation and editing in real time with server-sent events.\n        [Learn more about image streaming](https://platform.openai.com/docs/guides/image-generation).\n      navigationGroup: endpoints\n      sections:\n        - type: object\n          key: ImageGenPartialImageEvent\n          path: <auto>\n        - type: object\n          key: ImageGenCompletedEvent\n          path: <auto>\n        - type: object\n          key: ImageEditPartialImageEvent\n          path: <auto>\n        - type: object\n          key: ImageEditCompletedEvent\n          path: <auto>\n    - id: embeddings\n      title: Embeddings\n      description: >\n        Get a vector representation of a given input that can be easily consumed by machine learning models\n        and algorithms.\n\n        Related guide: [Embeddings](https://platform.openai.com/docs/guides/embeddings)\n      navigationGroup: endpoints\n      sections:\n        - type: endpoint\n          key: createEmbedding\n          path: create\n        - type: object\n          key: Embedding\n          path: object\n    - id: evals\n      title: Evals\n      description: |\n        Create, manage, and run evals in the OpenAI platform.\n        Related guide: [Evals](https://platform.openai.com/docs/guides/evals)\n      navigationGroup: endpoints\n      sections:\n        - type: endpoint\n          key: createEval\n          path: create\n        - type: endpoint\n          key: getEval\n          path: get\n        - type: endpoint\n          key: updateEval\n          path: update\n        - type: endpoint\n          key: deleteEval\n          path: delete\n        - type: endpoint\n          key: listEvals\n          path: list\n        - type: endpoint\n          key: getEvalRuns\n          path: getRuns\n        - type: endpoint\n          key: getEvalRun\n          path: getRun\n        - type: endpoint\n          key: createEvalRun\n          path: createRun\n        - type: endpoint\n          key: cancelEvalRun\n          path: cancelRun\n        - type: endpoint\n          key: deleteEvalRun\n          path: deleteRun\n        - type: endpoint\n          key: getEvalRunOutputItem\n          path: getRunOutputItem\n        - type: endpoint\n          key: getEvalRunOutputItems\n          path: getRunOutputItems\n        - type: object\n          key: Eval\n          path: object\n        - type: object\n          key: EvalRun\n          path: run-object\n        - type: object\n          key: EvalRunOutputItem\n          path: run-output-item-object\n    - id: fine-tuning\n      title: Fine-tuning\n      description: |\n        Manage fine-tuning jobs to tailor a model to your specific training data.\n        Related guide: [Fine-tune models](https://platform.openai.com/docs/guides/fine-tuning)\n      navigationGroup: endpoints\n      sections:\n        - type: endpoint\n          key: createFineTuningJob\n          path: create\n        - type: endpoint\n          key: listPaginatedFineTuningJobs\n          path: list\n        - type: endpoint\n          key: listFineTuningEvents\n          path: list-events\n        - type: endpoint\n          key: listFineTuningJobCheckpoints\n          path: list-checkpoints\n        - type: endpoint\n          key: listFineTuningCheckpointPermissions\n          path: list-permissions\n        - type: endpoint\n          key: createFineTuningCheckpointPermission\n          path: create-permission\n        - type: endpoint\n          key: deleteFineTuningCheckpointPermission\n          path: delete-permission\n        - type: endpoint\n          key: retrieveFineTuningJob\n          path: retrieve\n        - type: endpoint\n          key: cancelFineTuningJob\n          path: cancel\n        - type: endpoint\n          key: resumeFineTuningJob\n          path: resume\n        - type: endpoint\n          key: pauseFineTuningJob\n          path: pause\n        - type: object\n          key: FineTuneChatRequestInput\n          path: chat-input\n        - type: object\n          key: FineTunePreferenceRequestInput\n          path: preference-input\n        - type: object\n          key: FineTuneReinforcementRequestInput\n          path: reinforcement-input\n        - type: object\n          key: FineTuningJob\n          path: object\n        - type: object\n          key: FineTuningJobEvent\n          path: event-object\n        - type: object\n          key: FineTuningJobCheckpoint\n          path: checkpoint-object\n        - type: object\n          key: FineTuningCheckpointPermission\n          path: permission-object\n    - id: graders\n      title: Graders\n      description: |\n        Manage and run graders in the OpenAI platform.\n        Related guide: [Graders](https://platform.openai.com/docs/guides/graders)\n      navigationGroup: endpoints\n      sections:\n        - type: object\n          key: GraderStringCheck\n          path: string-check\n        - type: object\n          key: GraderTextSimilarity\n          path: text-similarity\n        - type: object\n          key: GraderScoreModel\n          path: score-model\n        - type: object\n          key: GraderLabelModel\n          path: label-model\n        - type: object\n          key: GraderPython\n          path: python\n        - type: object\n          key: GraderMulti\n          path: multi\n        - type: endpoint\n          key: runGrader\n          path: run\n        - type: endpoint\n          key: validateGrader\n          path: validate\n          beta: true\n    - id: batch\n      title: Batch\n      description: >\n        Create large batches of API requests for asynchronous processing. The Batch API returns completions\n        within 24 hours for a 50% discount.\n\n        Related guide: [Batch](https://platform.openai.com/docs/guides/batch)\n      navigationGroup: endpoints\n      sections:\n        - type: endpoint\n          key: createBatch\n          path: create\n        - type: endpoint\n          key: retrieveBatch\n          path: retrieve\n        - type: endpoint\n          key: cancelBatch\n          path: cancel\n        - type: endpoint\n          key: listBatches\n          path: list\n        - type: object\n          key: Batch\n          path: object\n        - type: object\n          key: BatchRequestInput\n          path: request-input\n        - type: object\n          key: BatchRequestOutput\n          path: request-output\n    - id: files\n      title: Files\n      description: >\n        Files are used to upload documents that can be used with features like\n        [Assistants](https://platform.openai.com/docs/api-reference/assistants),\n        [Fine-tuning](https://platform.openai.com/docs/api-reference/fine-tuning), and [Batch\n        API](https://platform.openai.com/docs/guides/batch).\n      navigationGroup: endpoints\n      sections:\n        - type: endpoint\n          key: createFile\n          path: create\n        - type: endpoint\n          key: listFiles\n          path: list\n        - type: endpoint\n          key: retrieveFile\n          path: retrieve\n        - type: endpoint\n          key: deleteFile\n          path: delete\n        - type: endpoint\n          key: downloadFile\n          path: retrieve-contents\n        - type: object\n          key: OpenAIFile\n          path: object\n    - id: uploads\n      title: Uploads\n      description: |\n        Allows you to upload large files in multiple parts.\n      navigationGroup: endpoints\n      sections:\n        - type: endpoint\n          key: createUpload\n          path: create\n        - type: endpoint\n          key: addUploadPart\n          path: add-part\n        - type: endpoint\n          key: completeUpload\n          path: complete\n        - type: endpoint\n          key: cancelUpload\n          path: cancel\n        - type: object\n          key: Upload\n          path: object\n        - type: object\n          key: UploadPart\n          path: part-object\n    - id: models\n      title: Models\n      description: >\n        List and describe the various models available in the API. You can refer to the\n        [Models](https://platform.openai.com/docs/models) documentation to understand what models are\n        available and the differences between them.\n      navigationGroup: endpoints\n      sections:\n        - type: endpoint\n          key: listModels\n          path: list\n        - type: endpoint\n          key: retrieveModel\n          path: retrieve\n        - type: endpoint\n          key: deleteModel\n          path: delete\n        - type: object\n          key: Model\n          path: object\n    - id: moderations\n      title: Moderations\n      description: >\n        Given text and/or image inputs, classifies if those inputs are potentially harmful across several\n        categories.\n\n        Related guide: [Moderations](https://platform.openai.com/docs/guides/moderation)\n      navigationGroup: endpoints\n      sections:\n        - type: endpoint\n          key: createModeration\n          path: create\n        - type: object\n          key: CreateModerationResponse\n          path: object\n    - id: vector-stores\n      title: Vector stores\n      description: >\n        Vector stores power semantic search for the Retrieval API and the `file_search` tool in the Responses\n        and Assistants APIs.\n\n\n        Related guide: [File Search](https://platform.openai.com/docs/assistants/tools/file-search)\n      navigationGroup: vector_stores\n      sections:\n        - type: endpoint\n          key: createVectorStore\n          path: create\n        - type: endpoint\n          key: listVectorStores\n          path: list\n        - type: endpoint\n          key: getVectorStore\n          path: retrieve\n        - type: endpoint\n          key: modifyVectorStore\n          path: modify\n        - type: endpoint\n          key: deleteVectorStore\n          path: delete\n        - type: endpoint\n          key: searchVectorStore\n          path: search\n        - type: object\n          key: VectorStoreObject\n          path: object\n    - id: vector-stores-files\n      title: Vector store files\n      description: |\n        Vector store files represent files inside a vector store.\n\n        Related guide: [File Search](https://platform.openai.com/docs/assistants/tools/file-search)\n      navigationGroup: vector_stores\n      sections:\n        - type: endpoint\n          key: createVectorStoreFile\n          path: createFile\n        - type: endpoint\n          key: listVectorStoreFiles\n          path: listFiles\n        - type: endpoint\n          key: getVectorStoreFile\n          path: getFile\n        - type: endpoint\n          key: retrieveVectorStoreFileContent\n          path: getContent\n        - type: endpoint\n          key: updateVectorStoreFileAttributes\n          path: updateAttributes\n        - type: endpoint\n          key: deleteVectorStoreFile\n          path: deleteFile\n        - type: object\n          key: VectorStoreFileObject\n          path: file-object\n    - id: vector-stores-file-batches\n      title: Vector store file batches\n      description: |\n        Vector store file batches represent operations to add multiple files to a vector store.\n        Related guide: [File Search](https://platform.openai.com/docs/assistants/tools/file-search)\n      navigationGroup: vector_stores\n      sections:\n        - type: endpoint\n          key: createVectorStoreFileBatch\n          path: createBatch\n        - type: endpoint\n          key: getVectorStoreFileBatch\n          path: getBatch\n        - type: endpoint\n          key: cancelVectorStoreFileBatch\n          path: cancelBatch\n        - type: endpoint\n          key: listFilesInVectorStoreBatch\n          path: listBatchFiles\n        - type: object\n          key: VectorStoreFileBatchObject\n          path: batch-object\n    - id: containers\n      title: Containers\n      description: |\n        Create and manage containers for use with the Code Interpreter tool.\n      navigationGroup: containers\n      sections:\n        - type: endpoint\n          key: CreateContainer\n          path: createContainers\n        - type: endpoint\n          key: ListContainers\n          path: listContainers\n        - type: endpoint\n          key: RetrieveContainer\n          path: retrieveContainer\n        - type: endpoint\n          key: DeleteContainer\n          path: deleteContainer\n        - type: object\n          key: ContainerResource\n          path: object\n    - id: container-files\n      title: Container Files\n      description: |\n        Create and manage container files for use with the Code Interpreter tool.\n      navigationGroup: containers\n      sections:\n        - type: endpoint\n          key: CreateContainerFile\n          path: createContainerFile\n        - type: endpoint\n          key: ListContainerFiles\n          path: listContainerFiles\n        - type: endpoint\n          key: RetrieveContainerFile\n          path: retrieveContainerFile\n        - type: endpoint\n          key: RetrieveContainerFileContent\n          path: retrieveContainerFileContent\n        - type: endpoint\n          key: DeleteContainerFile\n          path: deleteContainerFile\n        - type: object\n          key: ContainerFileResource\n          path: object\n    - id: realtime\n      title: Realtime\n      beta: true\n      description: |\n        Communicate with a GPT-4o class model in real time using WebRTC or\n        WebSockets. Supports text and audio inputs and ouputs, along with audio\n        transcriptions.\n        [Learn more about the Realtime API](https://platform.openai.com/docs/guides/realtime).\n      navigationGroup: realtime\n    - id: realtime-sessions\n      title: Session tokens\n      description: |\n        REST API endpoint to generate ephemeral session tokens for use in client-side\n        applications.\n      navigationGroup: realtime\n      sections:\n        - type: endpoint\n          key: create-realtime-session\n          path: create\n        - type: endpoint\n          key: create-realtime-transcription-session\n          path: create-transcription\n        - type: object\n          key: RealtimeSessionCreateResponse\n          path: session_object\n        - type: object\n          key: RealtimeTranscriptionSessionCreateResponse\n          path: transcription_session_object\n    - id: realtime-client-events\n      title: Client events\n      description: |\n        These are events that the OpenAI Realtime WebSocket server will accept from the client.\n      navigationGroup: realtime\n      sections:\n        - type: object\n          key: RealtimeClientEventSessionUpdate\n          path: <auto>\n        - type: object\n          key: RealtimeClientEventInputAudioBufferAppend\n          path: <auto>\n        - type: object\n          key: RealtimeClientEventInputAudioBufferCommit\n          path: <auto>\n        - type: object\n          key: RealtimeClientEventInputAudioBufferClear\n          path: <auto>\n        - type: object\n          key: RealtimeClientEventConversationItemCreate\n          path: <auto>\n        - type: object\n          key: RealtimeClientEventConversationItemRetrieve\n          path: <auto>\n        - type: object\n          key: RealtimeClientEventConversationItemTruncate\n          path: <auto>\n        - type: object\n          key: RealtimeClientEventConversationItemDelete\n          path: <auto>\n        - type: object\n          key: RealtimeClientEventResponseCreate\n          path: <auto>\n        - type: object\n          key: RealtimeClientEventResponseCancel\n          path: <auto>\n        - type: object\n          key: RealtimeClientEventTranscriptionSessionUpdate\n          path: <auto>\n        - type: object\n          key: RealtimeClientEventOutputAudioBufferClear\n          path: <auto>\n    - id: realtime-server-events\n      title: Server events\n      description: |\n        These are events emitted from the OpenAI Realtime WebSocket server to the client.\n      navigationGroup: realtime\n      sections:\n        - type: object\n          key: RealtimeServerEventError\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventSessionCreated\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventSessionUpdated\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventConversationCreated\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventConversationItemCreated\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventConversationItemRetrieved\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventConversationItemInputAudioTranscriptionCompleted\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventConversationItemInputAudioTranscriptionDelta\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventConversationItemInputAudioTranscriptionFailed\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventConversationItemTruncated\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventConversationItemDeleted\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventInputAudioBufferCommitted\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventInputAudioBufferCleared\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventInputAudioBufferSpeechStarted\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventInputAudioBufferSpeechStopped\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventResponseCreated\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventResponseDone\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventResponseOutputItemAdded\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventResponseOutputItemDone\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventResponseContentPartAdded\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventResponseContentPartDone\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventResponseTextDelta\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventResponseTextDone\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventResponseAudioTranscriptDelta\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventResponseAudioTranscriptDone\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventResponseAudioDelta\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventResponseAudioDone\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventResponseFunctionCallArgumentsDelta\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventResponseFunctionCallArgumentsDone\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventTranscriptionSessionUpdated\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventRateLimitsUpdated\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventOutputAudioBufferStarted\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventOutputAudioBufferStopped\n          path: <auto>\n        - type: object\n          key: RealtimeServerEventOutputAudioBufferCleared\n          path: <auto>\n    - id: chat\n      title: Chat Completions\n      description: >\n        The Chat Completions API endpoint will generate a model response from a\n\n        list of messages comprising a conversation.\n\n\n        Related guides:\n\n        - [Quickstart](https://platform.openai.com/docs/quickstart?api-mode=chat)\n\n        - [Text inputs and outputs](https://platform.openai.com/docs/guides/text?api-mode=chat)\n\n        - [Image inputs](https://platform.openai.com/docs/guides/images?api-mode=chat)\n\n        - [Audio inputs and outputs](https://platform.openai.com/docs/guides/audio?api-mode=chat)\n\n        - [Structured Outputs](https://platform.openai.com/docs/guides/structured-outputs?api-mode=chat)\n\n        - [Function calling](https://platform.openai.com/docs/guides/function-calling?api-mode=chat)\n\n        - [Conversation state](https://platform.openai.com/docs/guides/conversation-state?api-mode=chat)\n\n\n        **Starting a new project?** We recommend trying\n        [Responses](https://platform.openai.com/docs/api-reference/responses)\n\n        to take advantage of the latest OpenAI platform features. Compare\n\n        [Chat Completions with\n        Responses](https://platform.openai.com/docs/guides/responses-vs-chat-completions?api-mode=responses).\n      navigationGroup: chat\n      sections:\n        - type: endpoint\n          key: createChatCompletion\n          path: create\n        - type: endpoint\n          key: getChatCompletion\n          path: get\n        - type: endpoint\n          key: getChatCompletionMessages\n          path: getMessages\n        - type: endpoint\n          key: listChatCompletions\n          path: list\n        - type: endpoint\n          key: updateChatCompletion\n          path: update\n        - type: endpoint\n          key: deleteChatCompletion\n          path: delete\n        - type: object\n          key: CreateChatCompletionResponse\n          path: object\n        - type: object\n          key: ChatCompletionList\n          path: list-object\n        - type: object\n          key: ChatCompletionMessageList\n          path: message-list\n    - id: chat-streaming\n      title: Streaming\n      description: |\n        Stream Chat Completions in real time. Receive chunks of completions\n        returned from the model using server-sent events.\n        [Learn more](https://platform.openai.com/docs/guides/streaming-responses?api-mode=chat).\n      navigationGroup: chat\n      sections:\n        - type: object\n          key: CreateChatCompletionStreamResponse\n          path: streaming\n    - id: assistants\n      title: Assistants\n      beta: true\n      description: |\n        Build assistants that can call models and use tools to perform tasks.\n\n        [Get started with the Assistants API](https://platform.openai.com/docs/assistants)\n      navigationGroup: assistants\n      sections:\n        - type: endpoint\n          key: createAssistant\n          path: createAssistant\n        - type: endpoint\n          key: listAssistants\n          path: listAssistants\n        - type: endpoint\n          key: getAssistant\n          path: getAssistant\n        - type: endpoint\n          key: modifyAssistant\n          path: modifyAssistant\n        - type: endpoint\n          key: deleteAssistant\n          path: deleteAssistant\n        - type: object\n          key: AssistantObject\n          path: object\n    - id: threads\n      title: Threads\n      beta: true\n      description: |\n        Create threads that assistants can interact with.\n\n        Related guide: [Assistants](https://platform.openai.com/docs/assistants/overview)\n      navigationGroup: assistants\n      sections:\n        - type: endpoint\n          key: createThread\n          path: createThread\n        - type: endpoint\n          key: getThread\n          path: getThread\n        - type: endpoint\n          key: modifyThread\n          path: modifyThread\n        - type: endpoint\n          key: deleteThread\n          path: deleteThread\n        - type: object\n          key: ThreadObject\n          path: object\n    - id: messages\n      title: Messages\n      beta: true\n      description: |\n        Create messages within threads\n\n        Related guide: [Assistants](https://platform.openai.com/docs/assistants/overview)\n      navigationGroup: assistants\n      sections:\n        - type: endpoint\n          key: createMessage\n          path: createMessage\n        - type: endpoint\n          key: listMessages\n          path: listMessages\n        - type: endpoint\n          key: getMessage\n          path: getMessage\n        - type: endpoint\n          key: modifyMessage\n          path: modifyMessage\n        - type: endpoint\n          key: deleteMessage\n          path: deleteMessage\n        - type: object\n          key: MessageObject\n          path: object\n    - id: runs\n      title: Runs\n      beta: true\n      description: |\n        Represents an execution run on a thread.\n\n        Related guide: [Assistants](https://platform.openai.com/docs/assistants/overview)\n      navigationGroup: assistants\n      sections:\n        - type: endpoint\n          key: createRun\n          path: createRun\n        - type: endpoint\n          key: createThreadAndRun\n          path: createThreadAndRun\n        - type: endpoint\n          key: listRuns\n          path: listRuns\n        - type: endpoint\n          key: getRun\n          path: getRun\n        - type: endpoint\n          key: modifyRun\n          path: modifyRun\n        - type: endpoint\n          key: submitToolOuputsToRun\n          path: submitToolOutputs\n        - type: endpoint\n          key: cancelRun\n          path: cancelRun\n        - type: object\n          key: RunObject\n          path: object\n    - id: run-steps\n      title: Run steps\n      beta: true\n      description: |\n        Represents the steps (model and tool calls) taken during the run.\n\n        Related guide: [Assistants](https://platform.openai.com/docs/assistants/overview)\n      navigationGroup: assistants\n      sections:\n        - type: endpoint\n          key: listRunSteps\n          path: listRunSteps\n        - type: endpoint\n          key: getRunStep\n          path: getRunStep\n        - type: object\n          key: RunStepObject\n          path: step-object\n    - id: assistants-streaming\n      title: Streaming\n      beta: true\n      description: >\n        Stream the result of executing a Run or resuming a Run after submitting tool outputs.\n\n        You can stream events from the [Create Thread and\n        Run](https://platform.openai.com/docs/api-reference/runs/createThreadAndRun),\n\n        [Create Run](https://platform.openai.com/docs/api-reference/runs/createRun), and [Submit Tool\n        Outputs](https://platform.openai.com/docs/api-reference/runs/submitToolOutputs)\n\n        endpoints by passing `\"stream\": true`. The response will be a [Server-Sent\n        events](https://html.spec.whatwg.org/multipage/server-sent-events.html#server-sent-events) stream.\n\n        Our Node and Python SDKs provide helpful utilities to make streaming easy. Reference the\n\n        [Assistants API quickstart](https://platform.openai.com/docs/assistants/overview) to learn more.\n      navigationGroup: assistants\n      sections:\n        - type: object\n          key: MessageDeltaObject\n          path: message-delta-object\n        - type: object\n          key: RunStepDeltaObject\n          path: run-step-delta-object\n        - type: object\n          key: AssistantStreamEvent\n          path: events\n    - id: administration\n      title: Administration\n      description: >\n        Programmatically manage your organization.\n\n        The Audit Logs endpoint provides a log of all actions taken in the organization for security and\n        monitoring purposes.\n\n        To access these endpoints please generate an Admin API Key through the [API Platform Organization\n        overview](/organization/admin-keys). Admin API keys cannot be used for non-administration endpoints.\n\n        For best practices on setting up your organization, please refer to this\n        [guide](https://platform.openai.com/docs/guides/production-best-practices#setting-up-your-organization)\n      navigationGroup: administration\n    - id: admin-api-keys\n      title: Admin API Keys\n      description: >\n        Admin API keys enable Organization Owners to programmatically manage various aspects of their\n        organization, including users, projects, and API keys. These keys provide administrative capabilities,\n        such as creating, updating, and deleting users; managing projects; and overseeing API key lifecycles.\n\n\n        Key Features of Admin API Keys:\n\n\n        - User Management: Invite new users, update roles, and remove users from the organization.\n\n\n        - Project Management: Create, update, archive projects, and manage user assignments within projects.\n\n\n        - API Key Oversight: List, retrieve, and delete API keys associated with projects.\n\n\n        Only Organization Owners have the authority to create and utilize Admin API keys. To manage these\n        keys, Organization Owners can navigate to the Admin Keys section of their API Platform dashboard.\n\n\n        For direct access to the Admin Keys management page, Organization Owners can use the following link:\n\n\n        [https://platform.openai.com/settings/organization/admin-keys](https://platform.openai.com/settings/organization/admin-keys)\n\n\n        It\'s crucial to handle Admin API keys with care due to their elevated permissions. Adhering to best\n        practices, such as regular key rotation and assigning appropriate permissions, enhances security and\n        ensures proper governance within the organization.\n      navigationGroup: administration\n      sections:\n        - type: endpoint\n          key: admin-api-keys-list\n          path: list\n        - type: endpoint\n          key: admin-api-keys-create\n          path: create\n        - type: endpoint\n          key: admin-api-keys-get\n          path: listget\n        - type: endpoint\n          key: admin-api-keys-delete\n          path: delete\n        - type: object\n          key: AdminApiKey\n          path: object\n    - id: invite\n      title: Invites\n      description: Invite and manage invitations for an organization.\n      navigationGroup: administration\n      sections:\n        - type: endpoint\n          key: list-invites\n          path: list\n        - type: endpoint\n          key: inviteUser\n          path: create\n        - type: endpoint\n          key: retrieve-invite\n          path: retrieve\n        - type: endpoint\n          key: delete-invite\n          path: delete\n        - type: object\n          key: Invite\n          path: object\n    - id: users\n      title: Users\n      description: |\n        Manage users and their role in an organization.\n      navigationGroup: administration\n      sections:\n        - type: endpoint\n          key: list-users\n          path: list\n        - type: endpoint\n          key: modify-user\n          path: modify\n        - type: endpoint\n          key: retrieve-user\n          path: retrieve\n        - type: endpoint\n          key: delete-user\n          path: delete\n        - type: object\n          key: User\n          path: object\n    - id: projects\n      title: Projects\n      description: |\n        Manage the projects within an orgnanization includes creation, updating, and archiving or projects.\n        The Default project cannot be archived.\n      navigationGroup: administration\n      sections:\n        - type: endpoint\n          key: list-projects\n          path: list\n        - type: endpoint\n          key: create-project\n          path: create\n        - type: endpoint\n          key: retrieve-project\n          path: retrieve\n        - type: endpoint\n          key: modify-project\n          path: modify\n        - type: endpoint\n          key: archive-project\n          path: archive\n        - type: object\n          key: Project\n          path: object\n    - id: project-users\n      title: Project users\n      description: |\n        Manage users within a project, including adding, updating roles, and removing users.\n      navigationGroup: administration\n      sections:\n        - type: endpoint\n          key: list-project-users\n          path: list\n        - type: endpoint\n          key: create-project-user\n          path: create\n        - type: endpoint\n          key: retrieve-project-user\n          path: retrieve\n        - type: endpoint\n          key: modify-project-user\n          path: modify\n        - type: endpoint\n          key: delete-project-user\n          path: delete\n        - type: object\n          key: ProjectUser\n          path: object\n    - id: project-service-accounts\n      title: Project service accounts\n      description: >\n        Manage service accounts within a project. A service account is a bot user that is not associated with\n        a user.\n\n        If a user leaves an organization, their keys and membership in projects will no longer work. Service\n        accounts\n\n        do not have this limitation. However, service accounts can also be deleted from a project.\n      navigationGroup: administration\n      sections:\n        - type: endpoint\n          key: list-project-service-accounts\n          path: list\n        - type: endpoint\n          key: create-project-service-account\n          path: create\n        - type: endpoint\n          key: retrieve-project-service-account\n          path: retrieve\n        - type: endpoint\n          key: delete-project-service-account\n          path: delete\n        - type: object\n          key: ProjectServiceAccount\n          path: object\n    - id: project-api-keys\n      title: Project API keys\n      description: >\n        Manage API keys for a given project. Supports listing and deleting keys for users.\n\n        This API does not allow issuing keys for users, as users need to authorize themselves to generate\n        keys.\n      navigationGroup: administration\n      sections:\n        - type: endpoint\n          key: list-project-api-keys\n          path: list\n        - type: endpoint\n          key: retrieve-project-api-key\n          path: retrieve\n        - type: endpoint\n          key: delete-project-api-key\n          path: delete\n        - type: object\n          key: ProjectApiKey\n          path: object\n    - id: project-rate-limits\n      title: Project rate limits\n      description: >\n        Manage rate limits per model for projects. Rate limits may be configured to be equal to or lower than\n        the organization\'s rate limits.\n      navigationGroup: administration\n      sections:\n        - type: endpoint\n          key: list-project-rate-limits\n          path: list\n        - type: endpoint\n          key: update-project-rate-limits\n          path: update\n        - type: object\n          key: ProjectRateLimit\n          path: object\n    - id: audit-logs\n      title: Audit logs\n      description: >\n        Logs of user actions and configuration changes within this organization.\n\n        To log events, an Organization Owner must activate logging in the [Data Controls\n        Settings](/settings/organization/data-controls/data-retention).\n\n        Once activated, for security reasons, logging cannot be deactivated.\n      navigationGroup: administration\n      sections:\n        - type: endpoint\n          key: list-audit-logs\n          path: list\n        - type: object\n          key: AuditLog\n          path: object\n    - id: usage\n      title: Usage\n      description: >\n        The **Usage API** provides detailed insights into your activity across the OpenAI API. It also\n        includes a separate [Costs endpoint](https://platform.openai.com/docs/api-reference/usage/costs),\n        which offers visibility into your spend, breaking down consumption by invoice line items and project\n        IDs.\n\n\n        While the Usage API delivers granular usage data, it may not always reconcile perfectly with the Costs\n        due to minor differences in how usage and spend are recorded. For financial purposes, we recommend\n        using the [Costs endpoint](https://platform.openai.com/docs/api-reference/usage/costs) or the [Costs\n        tab](/settings/organization/usage) in the Usage Dashboard, which will reconcile back to your billing\n        invoice.\n      navigationGroup: administration\n      sections:\n        - type: endpoint\n          key: usage-completions\n          path: completions\n        - type: object\n          key: UsageCompletionsResult\n          path: completions_object\n        - type: endpoint\n          key: usage-embeddings\n          path: embeddings\n        - type: object\n          key: UsageEmbeddingsResult\n          path: embeddings_object\n        - type: endpoint\n          key: usage-moderations\n          path: moderations\n        - type: object\n          key: UsageModerationsResult\n          path: moderations_object\n        - type: endpoint\n          key: usage-images\n          path: images\n        - type: object\n          key: UsageImagesResult\n          path: images_object\n        - type: endpoint\n          key: usage-audio-speeches\n          path: audio_speeches\n        - type: object\n          key: UsageAudioSpeechesResult\n          path: audio_speeches_object\n        - type: endpoint\n          key: usage-audio-transcriptions\n          path: audio_transcriptions\n        - type: object\n          key: UsageAudioTranscriptionsResult\n          path: audio_transcriptions_object\n        - type: endpoint\n          key: usage-vector-stores\n          path: vector_stores\n        - type: object\n          key: UsageVectorStoresResult\n          path: vector_stores_object\n        - type: endpoint\n          key: usage-code-interpreter-sessions\n          path: code_interpreter_sessions\n        - type: object\n          key: UsageCodeInterpreterSessionsResult\n          path: code_interpreter_sessions_object\n        - type: endpoint\n          key: usage-costs\n          path: costs\n        - type: object\n          key: CostsResult\n          path: costs_object\n    - id: certificates\n      beta: true\n      title: Certificates\n      description: >\n        Manage Mutual TLS certificates across your organization and projects.\n\n\n        [Learn more about Mutual\n        TLS.](https://help.openai.com/en/articles/10876024-openai-mutual-tls-beta-program)\n      navigationGroup: administration\n      sections:\n        - type: endpoint\n          key: uploadCertificate\n          path: uploadCertificate\n        - type: endpoint\n          key: getCertificate\n          path: getCertificate\n        - type: endpoint\n          key: modifyCertificate\n          path: modifyCertificate\n        - type: endpoint\n          key: deleteCertificate\n          path: deleteCertificate\n        - type: endpoint\n          key: listOrganizationCertificates\n          path: listOrganizationCertificates\n        - type: endpoint\n          key: listProjectCertificates\n          path: listProjectCertificates\n        - type: endpoint\n          key: activateOrganizationCertificates\n          path: activateOrganizationCertificates\n        - type: endpoint\n          key: deactivateOrganizationCertificates\n          path: deactivateOrganizationCertificates\n        - type: endpoint\n          key: activateProjectCertificates\n          path: activateProjectCertificates\n        - type: endpoint\n          key: deactivateProjectCertificates\n          path: deactivateProjectCertificates\n        - type: object\n          key: Certificate\n          path: object\n    - id: completions\n      title: Completions\n      legacy: true\n      navigationGroup: legacy\n      description: >\n        Given a prompt, the model will return one or more predicted completions along with the probabilities\n        of alternative tokens at each position. Most developer should use our [Chat Completions\n        API](https://platform.openai.com/docs/guides/text-generation#text-generation-models) to leverage our\n        best and newest models.\n      sections:\n        - type: endpoint\n          key: createCompletion\n          path: create\n        - type: object\n          key: CreateCompletionResponse\n          path: object\n','false');
INSERT INTO `AM_LLM_PROVIDER` VALUES ('d45c1654-d2f7-46a7-b2ab-e283f368918e','MistralAI','1.0.0','carbon.super','true','Mistral AI service',_binary '{\"connectorType\":\"mistralAi_1.0.0\",\"metadata\":[{\"attributeName\":\"requestModel\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.model\",\"required\":false},{\"attributeName\":\"responseModel\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.model\",\"required\":true},{\"attributeName\":\"promptTokenCount\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.usage.prompt_tokens\",\"required\":true},{\"attributeName\":\"completionTokenCount\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.usage.completion_tokens\",\"required\":true},{\"attributeName\":\"totalTokenCount\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.usage.total_tokens\",\"required\":true},{\"attributeName\":\"remainingTokenCount\",\"inputSource\":\"header\",\"attributeIdentifier\":\"x-ratelimit-remaining-tokens\",\"required\":false}],\"authHeader\":\"Authorization\"}',_binary 'openapi: 3.1.0\ninfo:\n  title: Mistral AI API\n  description: >-\n    Our Chat Completion and Embeddings APIs specification. Create your account\n    on [La Plateforme](https://console.mistral.ai) to get access and read the\n    [docs](https://docs.mistral.ai) to learn how to use it.\n  version: 0.0.2\npaths:\n  /v1/models:\n    get:\n      summary: List Models\n      description: List all models available to the user.\n      operationId: list_models_v1_models_get\n      responses:\n        \'200\':\n          description: Successful Response\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/ModelList\'\n        \'422\':\n          description: Validation Error\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/HTTPValidationError\'\n      tags:\n        - models\n  /v1/models/{model_id}:\n    get:\n      summary: Retrieve Model\n      description: Retrieve a model information.\n      operationId: retrieve_model_v1_models__model_id__get\n      parameters:\n        - name: model_id\n          in: path\n          required: true\n          schema:\n            type: string\n            title: Model Id\n          example: ft:open-mistral-7b:587a6b29:20240514:7e773925\n          description: The ID of the model to retrieve.\n      responses:\n        \'200\':\n          description: Successful Response\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/ModelCard\'\n        \'422\':\n          description: Validation Error\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/HTTPValidationError\'\n      tags:\n        - models\n    delete:\n      summary: Delete Model\n      description: Delete a fine-tuned model.\n      operationId: delete_model_v1_models__model_id__delete\n      parameters:\n        - name: model_id\n          in: path\n          required: true\n          schema:\n            type: string\n            title: Model Id\n          example: ft:open-mistral-7b:587a6b29:20240514:7e773925\n          description: The ID of the model to delete.\n      responses:\n        \'200\':\n          description: Successful Response\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/DeleteModelOut\'\n        \'422\':\n          description: Validation Error\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/HTTPValidationError\'\n      tags:\n        - models\n  /v1/files:\n    post:\n      operationId: files_api_routes_upload_file\n      summary: Upload File\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/UploadFileOut\'\n      description: >-\n        Upload a file that can be used across various endpoints.\n\n\n        The size of individual files can be a maximum of 512 MB. The Fine-tuning\n        API only supports .jsonl files.\n\n\n        Please contact us if you need to increase these storage limits.\n      requestBody:\n        content:\n          multipart/form-data:\n            schema:\n              title: MultiPartBodyParams\n              type: object\n              properties:\n                purpose:\n                  const: fine-tune\n                  default: fine-tune\n                  enum:\n                    - fine-tune\n                  title: Purpose\n                  type: string\n                file:\n                  format: binary\n                  title: File\n                  type: string\n                  description: |-\n                    The File object (not file name) to be uploaded.\n                     To upload a file and specify a custom file name you should format your request as such:\n                     ```bash\n                     file=@path/to/your/file.jsonl;filename=custom_name.jsonl\n                     ```\n                     Otherwise, you can just keep the original file name:\n                     ```bash\n                     file=@path/to/your/file.jsonl\n                     ```\n              required:\n                - file\n        required: true\n      tags:\n        - files\n    get:\n      operationId: files_api_routes_list_files\n      summary: List Files\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/ListFilesOut\'\n      description: Returns a list of files that belong to the user\'s organization.\n      tags:\n        - files\n  /v1/files/{file_id}:\n    get:\n      operationId: files_api_routes_retrieve_file\n      summary: Retrieve File\n      parameters:\n        - in: path\n          name: file_id\n          schema:\n            title: File Id\n            type: string\n          required: true\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/RetrieveFileOut\'\n      description: Returns information about a specific file.\n      tags:\n        - files\n    delete:\n      operationId: files_api_routes_delete_file\n      summary: Delete File\n      parameters:\n        - in: path\n          name: file_id\n          schema:\n            title: File Id\n            type: string\n          required: true\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/DeleteFileOut\'\n      description: Delete a file.\n      tags:\n        - files\n  /v1/fine_tuning/jobs:\n    get:\n      operationId: jobs_api_routes_fine_tuning_get_fine_tuning_jobs\n      summary: Get Fine Tuning Jobs\n      parameters:\n        - in: query\n          name: page\n          schema:\n            default: 0\n            title: Page\n            type: integer\n          required: false\n          description: The page number of the results to be returned.\n        - in: query\n          name: page_size\n          schema:\n            default: 100\n            title: Page Size\n            type: integer\n          required: false\n          description: The number of items to return per page.\n        - in: query\n          name: model\n          schema:\n            anyOf:\n              - type: string\n              - type: \'null\'\n            title: Model\n          required: false\n          description: >-\n            The model name used for fine-tuning to filter on. When set, the\n            other results are not displayed.\n        - in: query\n          name: created_after\n          schema:\n            anyOf:\n              - format: date-time\n                type: string\n              - type: \'null\'\n            title: Created After\n          required: false\n          description: >-\n            The date/time to filter on. When set, the results for previous\n            creation times are not displayed.\n        - in: query\n          name: created_by_me\n          schema:\n            default: false\n            title: Created By Me\n            type: boolean\n          required: false\n          description: >-\n            When set, only return results for jobs created by the API caller.\n            Other results are not displayed.\n        - in: query\n          name: status\n          schema:\n            anyOf:\n              - enum:\n                  - QUEUED\n                  - STARTED\n                  - VALIDATING\n                  - VALIDATED\n                  - RUNNING\n                  - FAILED_VALIDATION\n                  - FAILED\n                  - SUCCESS\n                  - CANCELLED\n                  - CANCELLATION_REQUESTED\n                type: string\n              - type: \'null\'\n            title: Status\n          required: false\n          description: >-\n            The current job state to filter on. When set, the other results are\n            not displayed.\n        - in: query\n          name: wandb_project\n          schema:\n            anyOf:\n              - type: string\n              - type: \'null\'\n            title: Wandb Project\n          required: false\n          description: >-\n            The Weights and Biases project to filter on. When set, the other\n            results are not displayed.\n        - in: query\n          name: wandb_name\n          schema:\n            anyOf:\n              - type: string\n              - type: \'null\'\n            title: Wandb Name\n          required: false\n          description: >-\n            The Weight and Biases run name to filter on. When set, the other\n            results are not displayed.\n        - in: query\n          name: suffix\n          schema:\n            anyOf:\n              - type: string\n              - type: \'null\'\n            title: Suffix\n          required: false\n          description: >-\n            The model suffix to filter on. When set, the other results are not\n            displayed.\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/JobsOut\'\n      description: Get a list of fine-tuning jobs for your organization and user.\n      tags:\n        - fine-tuning\n    post:\n      operationId: jobs_api_routes_fine_tuning_create_fine_tuning_job\n      summary: Create Fine Tuning Job\n      parameters:\n        - in: query\n          name: dry_run\n          schema:\n            anyOf:\n              - type: boolean\n              - type: \'null\'\n            title: Dry Run\n          required: false\n          description: >\n            * If `true` the job is not spawned, instead the query returns a\n            handful of useful metadata\n              for the user to perform sanity checks (see `LegacyJobMetadataOut` response).\n            * Otherwise, the job is started and the query returns the job ID\n            along with some of the\n              input parameters (see `JobOut` response).\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                anyOf:\n                  - $ref: \'#/components/schemas/JobOut\'\n                  - $ref: \'#/components/schemas/LegacyJobMetadataOut\'\n                title: Response\n      description: Create a new fine-tuning job, it will be queued for processing.\n      requestBody:\n        content:\n          application/json:\n            schema:\n              $ref: \'#/components/schemas/JobIn\'\n        required: true\n      tags:\n        - fine-tuning\n  /v1/fine_tuning/jobs/{job_id}:\n    get:\n      operationId: jobs_api_routes_fine_tuning_get_fine_tuning_job\n      summary: Get Fine Tuning Job\n      parameters:\n        - in: path\n          name: job_id\n          schema:\n            format: uuid\n            title: Job Id\n            type: string\n          required: true\n          description: The ID of the job to analyse.\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/DetailedJobOut\'\n      description: Get a fine-tuned job details by its UUID.\n      tags:\n        - fine-tuning\n  /v1/fine_tuning/jobs/{job_id}/cancel:\n    post:\n      operationId: jobs_api_routes_fine_tuning_cancel_fine_tuning_job\n      summary: Cancel Fine Tuning Job\n      parameters:\n        - in: path\n          name: job_id\n          schema:\n            format: uuid\n            title: Job Id\n            type: string\n          required: true\n          description: The ID of the job to cancel.\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/DetailedJobOut\'\n      description: Request the cancellation of a fine tuning job.\n      tags:\n        - fine-tuning\n  /v1/fine_tuning/jobs/{job_id}/start:\n    post:\n      operationId: jobs_api_routes_fine_tuning_start_fine_tuning_job\n      summary: Start Fine Tuning Job\n      parameters:\n        - in: path\n          name: job_id\n          schema:\n            format: uuid\n            title: Job Id\n            type: string\n          required: true\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/DetailedJobOut\'\n      description: Request the start of a validated fine tuning job.\n      tags:\n        - fine-tuning\n  /v1/fine_tuning/models/{model_id}:\n    patch:\n      operationId: jobs_api_routes_fine_tuning_update_fine_tuned_model\n      summary: Update Fine Tuned Model\n      parameters:\n        - in: path\n          name: model_id\n          schema:\n            title: Model Id\n            type: string\n          required: true\n          example: ft:open-mistral-7b:587a6b29:20240514:7e773925\n          description: The ID of the model to update.\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/FTModelOut\'\n      description: Update a model name or description.\n      requestBody:\n        content:\n          application/json:\n            schema:\n              $ref: \'#/components/schemas/UpdateFTModelIn\'\n        required: true\n      tags:\n        - models\n  /v1/fine_tuning/models/{model_id}/archive:\n    post:\n      operationId: jobs_api_routes_fine_tuning_archive_fine_tuned_model\n      summary: Archive Fine Tuned Model\n      parameters:\n        - in: path\n          name: model_id\n          schema:\n            title: Model Id\n            type: string\n          required: true\n          example: ft:open-mistral-7b:587a6b29:20240514:7e773925\n          description: The ID of the model to archive.\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/ArchiveFTModelOut\'\n      description: Archive a fine-tuned model.\n      tags:\n        - models\n    delete:\n      operationId: jobs_api_routes_fine_tuning_unarchive_fine_tuned_model\n      summary: Unarchive Fine Tuned Model\n      parameters:\n        - in: path\n          name: model_id\n          schema:\n            title: Model Id\n            type: string\n          required: true\n          example: ft:open-mistral-7b:587a6b29:20240514:7e773925\n          description: The ID of the model to unarchive.\n      responses:\n        \'200\':\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/UnarchiveFTModelOut\'\n      description: Un-archive a fine-tuned model.\n      tags:\n        - models\n  /v1/chat/completions:\n    post:\n      summary: Chat Completion\n      operationId: chat_completion_v1_chat_completions_post\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \'#/components/schemas/ChatCompletionRequest\'\n      responses:\n        \'200\':\n          description: Successful Response\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/ChatCompletionResponse\'\n            text/event-stream:\n              schema:\n                $ref: \'#/components/schemas/CompletionEvent\'\n        \'422\':\n          description: Validation Error\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/HTTPValidationError\'\n      tags:\n        - chat\n  /v1/fim/completions:\n    post:\n      summary: Fim Completion\n      description: FIM completion.\n      operationId: fim_completion_v1_fim_completions_post\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \'#/components/schemas/FIMCompletionRequest\'\n      responses:\n        \'200\':\n          description: Successful Response\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/FIMCompletionResponse\'\n            text/event-stream:\n              schema:\n                $ref: \'#/components/schemas/CompletionEvent\'\n        \'422\':\n          description: Validation Error\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/HTTPValidationError\'\n      tags:\n        - fim\n  /v1/agents/completions:\n    post:\n      summary: Agents Completion\n      operationId: agents_completion_v1_agents_completions_post\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \'#/components/schemas/AgentsCompletionRequest\'\n      responses:\n        \'200\':\n          description: Successful Response\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/ChatCompletionResponse\'\n        \'422\':\n          description: Validation Error\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/HTTPValidationError\'\n      tags:\n        - agents\n  /v1/embeddings:\n    post:\n      summary: Embeddings\n      description: Embeddings\n      operationId: embeddings_v1_embeddings_post\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \'#/components/schemas/EmbeddingRequest\'\n      responses:\n        \'200\':\n          description: Successful Response\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/EmbeddingResponse\'\n        \'422\':\n          description: Validation Error\n          content:\n            application/json:\n              schema:\n                $ref: \'#/components/schemas/HTTPValidationError\'\n      tags:\n        - embeddings\ncomponents:\n  schemas:\n    DeleteModelOut:\n      properties:\n        id:\n          type: string\n          title: Id\n          description: The ID of the deleted model.\n          examples:\n            - ft:open-mistral-7b:587a6b29:20240514:7e773925\n        object:\n          type: string\n          title: Object\n          default: model\n          description: The object type that was deleted\n        deleted:\n          type: boolean\n          title: Deleted\n          default: true\n          description: The deletion status\n          examples:\n            - true\n      type: object\n      required:\n        - id\n      title: DeleteModelOut\n    HTTPValidationError:\n      properties:\n        detail:\n          items:\n            $ref: \'#/components/schemas/ValidationError\'\n          type: array\n          title: Detail\n      type: object\n      title: HTTPValidationError\n    ModelCapabilities:\n      properties:\n        completion_chat:\n          type: boolean\n          title: Completion Chat\n          default: true\n        completion_fim:\n          type: boolean\n          title: Completion Fim\n          default: false\n        function_calling:\n          type: boolean\n          title: Function Calling\n          default: true\n        fine_tuning:\n          type: boolean\n          title: Fine Tuning\n          default: false\n      type: object\n      title: ModelCapabilities\n    ModelCard:\n      properties:\n        id:\n          type: string\n          title: Id\n        object:\n          type: string\n          title: Object\n          default: model\n        created:\n          type: integer\n          title: Created\n        owned_by:\n          type: string\n          title: Owned By\n          default: mistralai\n        root:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Root\n        archived:\n          type: boolean\n          title: Archived\n          default: false\n        name:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Name\n        description:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Description\n        capabilities:\n          $ref: \'#/components/schemas/ModelCapabilities\'\n        max_context_length:\n          type: integer\n          title: Max Context Length\n          default: 32768\n        aliases:\n          items:\n            type: string\n          type: array\n          title: Aliases\n          default: []\n        deprecation:\n          anyOf:\n            - type: string\n              format: date-time\n            - type: \'null\'\n          title: Deprecation\n      type: object\n      required:\n        - id\n        - capabilities\n      title: ModelCard\n    ModelList:\n      properties:\n        object:\n          type: string\n          title: Object\n          default: list\n        data:\n          items:\n            $ref: \'#/components/schemas/ModelCard\'\n          type: array\n          title: Data\n      type: object\n      title: ModelList\n    ValidationError:\n      properties:\n        loc:\n          items:\n            anyOf:\n              - type: string\n              - type: integer\n          type: array\n          title: Location\n        msg:\n          type: string\n          title: Message\n        type:\n          type: string\n          title: Error Type\n      type: object\n      required:\n        - loc\n        - msg\n        - type\n      title: ValidationError\n    SampleType:\n      enum:\n        - pretrain\n        - instruct\n      title: SampleType\n      type: string\n    Source:\n      enum:\n        - upload\n        - repository\n      title: Source\n      type: string\n    UploadFileOut:\n      properties:\n        id:\n          format: uuid\n          title: Id\n          type: string\n          description: The unique identifier of the file.\n          examples:\n            - 497f6eca-6276-4993-bfeb-53cbbbba6f09\n        object:\n          title: Object\n          type: string\n          description: The object type, which is always \"file\".\n          examples:\n            - file\n        bytes:\n          title: Bytes\n          type: integer\n          description: The size of the file, in bytes.\n          examples:\n            - 13000\n        created_at:\n          title: Created At\n          type: integer\n          description: The UNIX timestamp (in seconds) of the event.\n          examples:\n            - 1716963433\n        filename:\n          title: Filename\n          type: string\n          description: The name of the uploaded file.\n          examples:\n            - files_upload.jsonl\n        purpose:\n          const: fine-tune\n          enum:\n            - fine-tune\n          title: Purpose\n          type: string\n          description: >-\n            The intended purpose of the uploaded file. Only accepts fine-tuning\n            (`fine-tune`) for now.\n          examples:\n            - fine-tune\n        sample_type:\n          $ref: \'#/components/schemas/SampleType\'\n        num_lines:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Num Lines\n        source:\n          $ref: \'#/components/schemas/Source\'\n      required:\n        - id\n        - object\n        - bytes\n        - created_at\n        - filename\n        - purpose\n        - sample_type\n        - source\n      title: UploadFileOut\n      type: object\n    FileSchema:\n      properties:\n        id:\n          format: uuid\n          title: Id\n          type: string\n          description: The unique identifier of the file.\n          examples:\n            - 497f6eca-6276-4993-bfeb-53cbbbba6f09\n        object:\n          title: Object\n          type: string\n          description: The object type, which is always \"file\".\n          examples:\n            - file\n        bytes:\n          title: Bytes\n          type: integer\n          description: The size of the file, in bytes.\n          examples:\n            - 13000\n        created_at:\n          title: Created At\n          type: integer\n          description: The UNIX timestamp (in seconds) of the event.\n          examples:\n            - 1716963433\n        filename:\n          title: Filename\n          type: string\n          description: The name of the uploaded file.\n          examples:\n            - files_upload.jsonl\n        purpose:\n          const: fine-tune\n          enum:\n            - fine-tune\n          title: Purpose\n          type: string\n          description: >-\n            The intended purpose of the uploaded file. Only accepts fine-tuning\n            (`fine-tune`) for now.\n          examples:\n            - fine-tune\n        sample_type:\n          $ref: \'#/components/schemas/SampleType\'\n        num_lines:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Num Lines\n        source:\n          $ref: \'#/components/schemas/Source\'\n      required:\n        - id\n        - object\n        - bytes\n        - created_at\n        - filename\n        - purpose\n        - sample_type\n        - source\n      title: FileSchema\n      type: object\n    ListFilesOut:\n      properties:\n        data:\n          items:\n            $ref: \'#/components/schemas/FileSchema\'\n          title: Data\n          type: array\n        object:\n          title: Object\n          type: string\n      required:\n        - data\n        - object\n      title: ListFilesOut\n      type: object\n    RetrieveFileOut:\n      properties:\n        id:\n          format: uuid\n          title: Id\n          type: string\n          description: The unique identifier of the file.\n          examples:\n            - 497f6eca-6276-4993-bfeb-53cbbbba6f09\n        object:\n          title: Object\n          type: string\n          description: The object type, which is always \"file\".\n          examples:\n            - file\n        bytes:\n          title: Bytes\n          type: integer\n          description: The size of the file, in bytes.\n          examples:\n            - 13000\n        created_at:\n          title: Created At\n          type: integer\n          description: The UNIX timestamp (in seconds) of the event.\n          examples:\n            - 1716963433\n        filename:\n          title: Filename\n          type: string\n          description: The name of the uploaded file.\n          examples:\n            - files_upload.jsonl\n        purpose:\n          const: fine-tune\n          enum:\n            - fine-tune\n          title: Purpose\n          type: string\n          description: >-\n            The intended purpose of the uploaded file. Only accepts fine-tuning\n            (`fine-tune`) for now.\n          examples:\n            - fine-tune\n        sample_type:\n          $ref: \'#/components/schemas/SampleType\'\n        num_lines:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Num Lines\n        source:\n          $ref: \'#/components/schemas/Source\'\n      required:\n        - id\n        - object\n        - bytes\n        - created_at\n        - filename\n        - purpose\n        - sample_type\n        - source\n      title: RetrieveFileOut\n      type: object\n    DeleteFileOut:\n      properties:\n        id:\n          format: uuid\n          title: Id\n          type: string\n          description: The ID of the deleted file.\n          examples:\n            - 497f6eca-6276-4993-bfeb-53cbbbba6f09\n        object:\n          title: Object\n          type: string\n          description: The object type that was deleted\n          examples:\n            - file\n        deleted:\n          title: Deleted\n          type: boolean\n          description: The deletion status.\n          examples:\n            - false\n      required:\n        - id\n        - object\n        - deleted\n      title: DeleteFileOut\n      type: object\n    FineTuneableModel:\n      enum:\n        - open-mistral-7b\n        - mistral-small-latest\n        - codestral-latest\n        - mistral-large-latest\n        - open-mistral-nemo\n      title: FineTuneableModel\n      type: string\n      description: The name of the model to fine-tune.\n    GithubRepositoryOut:\n      properties:\n        type:\n          const: github\n          default: github\n          enum:\n            - github\n          title: Type\n          type: string\n        name:\n          title: Name\n          type: string\n        owner:\n          title: Owner\n          type: string\n        ref:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Ref\n        weight:\n          default: 1\n          exclusiveMinimum: 0\n          title: Weight\n          type: number\n        commit_id:\n          maxLength: 40\n          minLength: 40\n          title: Commit Id\n          type: string\n      required:\n        - name\n        - owner\n        - commit_id\n      title: GithubRepositoryOut\n      type: object\n    JobMetadataOut:\n      properties:\n        expected_duration_seconds:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Expected Duration Seconds\n        cost:\n          anyOf:\n            - type: number\n            - type: \'null\'\n          title: Cost\n        cost_currency:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Cost Currency\n        train_tokens_per_step:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Train Tokens Per Step\n        train_tokens:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Train Tokens\n        data_tokens:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Data Tokens\n        estimated_start_time:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Estimated Start Time\n      title: JobMetadataOut\n      type: object\n    JobOut:\n      properties:\n        id:\n          format: uuid\n          title: Id\n          type: string\n          description: The ID of the job.\n        auto_start:\n          title: Auto Start\n          type: boolean\n        hyperparameters:\n          $ref: \'#/components/schemas/TrainingParameters\'\n        model:\n          $ref: \'#/components/schemas/FineTuneableModel\'\n        status:\n          enum:\n            - QUEUED\n            - STARTED\n            - VALIDATING\n            - VALIDATED\n            - RUNNING\n            - FAILED_VALIDATION\n            - FAILED\n            - SUCCESS\n            - CANCELLED\n            - CANCELLATION_REQUESTED\n          title: Status\n          type: string\n          description: The current status of the fine-tuning job.\n        job_type:\n          title: Job Type\n          type: string\n          description: The type of job (`FT` for fine-tuning).\n        created_at:\n          title: Created At\n          type: integer\n          description: >-\n            The UNIX timestamp (in seconds) for when the fine-tuning job was\n            created.\n        modified_at:\n          title: Modified At\n          type: integer\n          description: >-\n            The UNIX timestamp (in seconds) for when the fine-tuning job was\n            last modified.\n        training_files:\n          items:\n            format: uuid\n            type: string\n          title: Training Files\n          type: array\n          description: >-\n            A list containing the IDs of uploaded files that contain training\n            data.\n        validation_files:\n          anyOf:\n            - items:\n                format: uuid\n                type: string\n              type: array\n            - type: \'null\'\n          default: []\n          title: Validation Files\n          description: >-\n            A list containing the IDs of uploaded files that contain validation\n            data.\n        object:\n          const: job\n          default: job\n          enum:\n            - job\n          title: Object\n          type: string\n          description: The object type of the fine-tuning job.\n        fine_tuned_model:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Fine Tuned Model\n          description: >-\n            The name of the fine-tuned model that is being created. The value\n            will be `null` if the fine-tuning job is still running.\n        suffix:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Suffix\n          description: >-\n            Optional text/code that adds more context for the model. When given\n            a `prompt` and a `suffix` the model will fill what is between them.\n            When `suffix` is not provided, the model will simply execute\n            completion starting with `prompt`.\n        integrations:\n          anyOf:\n            - items:\n                discriminator:\n                  mapping:\n                    wandb: \'#/components/schemas/WandbIntegrationOut\'\n                  propertyName: type\n                oneOf:\n                  - $ref: \'#/components/schemas/WandbIntegrationOut\'\n              type: array\n            - type: \'null\'\n          title: Integrations\n          description: A list of integrations enabled for your fine-tuning job.\n        trained_tokens:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Trained Tokens\n          description: Total number of tokens trained.\n        repositories:\n          default: []\n          items:\n            discriminator:\n              mapping:\n                github: \'#/components/schemas/GithubRepositoryOut\'\n              propertyName: type\n            oneOf:\n              - $ref: \'#/components/schemas/GithubRepositoryOut\'\n          maxItems: 20\n          title: Repositories\n          type: array\n        metadata:\n          anyOf:\n            - $ref: \'#/components/schemas/JobMetadataOut\'\n            - type: \'null\'\n      required:\n        - id\n        - auto_start\n        - hyperparameters\n        - model\n        - status\n        - job_type\n        - created_at\n        - modified_at\n        - training_files\n      title: JobOut\n      type: object\n    JobsOut:\n      properties:\n        data:\n          default: []\n          items:\n            $ref: \'#/components/schemas/JobOut\'\n          title: Data\n          type: array\n        object:\n          const: list\n          default: list\n          enum:\n            - list\n          title: Object\n          type: string\n        total:\n          title: Total\n          type: integer\n      required:\n        - total\n      title: JobsOut\n      type: object\n    TrainingParameters:\n      properties:\n        training_steps:\n          anyOf:\n            - minimum: 1\n              type: integer\n            - type: \'null\'\n          title: Training Steps\n        learning_rate:\n          default: 0.0001\n          maximum: 1\n          minimum: 1.e-8\n          title: Learning Rate\n          type: number\n        weight_decay:\n          anyOf:\n            - maximum: 1\n              minimum: 0\n              type: number\n            - type: \'null\'\n          default: 0.1\n          title: Weight Decay\n        warmup_fraction:\n          anyOf:\n            - maximum: 1\n              minimum: 0\n              type: number\n            - type: \'null\'\n          default: 0.05\n          title: Warmup Fraction\n        epochs:\n          anyOf:\n            - minimum: 0.01\n              type: number\n            - type: \'null\'\n          title: Epochs\n        fim_ratio:\n          anyOf:\n            - maximum: 1\n              minimum: 0\n              type: number\n            - type: \'null\'\n          default: 0.9\n          title: Fim Ratio\n      title: TrainingParameters\n      type: object\n    WandbIntegrationOut:\n      properties:\n        type:\n          const: wandb\n          default: wandb\n          enum:\n            - wandb\n          title: Type\n          type: string\n        project:\n          title: Project\n          type: string\n          description: The name of the project that the new run will be created under.\n        name:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Name\n          description: >-\n            A display name to set for the run. If not set, will use the job ID\n            as the name.\n        run_name:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Run Name\n      required:\n        - project\n      title: WandbIntegrationOut\n      type: object\n    LegacyJobMetadataOut:\n      properties:\n        expected_duration_seconds:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Expected Duration Seconds\n          description: >-\n            The approximated time (in seconds) for the fine-tuning process to\n            complete.\n          examples:\n            - 220\n        cost:\n          anyOf:\n            - type: number\n            - type: \'null\'\n          title: Cost\n          description: The cost of the fine-tuning job.\n          examples:\n            - 10\n        cost_currency:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Cost Currency\n          description: The currency used for the fine-tuning job cost.\n          examples:\n            - EUR\n        train_tokens_per_step:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Train Tokens Per Step\n          description: The number of tokens consumed by one training step.\n          examples:\n            - 131072\n        train_tokens:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Train Tokens\n          description: The total number of tokens used during the fine-tuning process.\n          examples:\n            - 1310720\n        data_tokens:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Data Tokens\n          description: The total number of tokens in the training dataset.\n          examples:\n            - 305375\n        estimated_start_time:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Estimated Start Time\n        deprecated:\n          default: true\n          title: Deprecated\n          type: boolean\n        details:\n          title: Details\n          type: string\n        epochs:\n          anyOf:\n            - type: number\n            - type: \'null\'\n          title: Epochs\n          description: The number of complete passes through the entire training dataset.\n          examples:\n            - 4.2922\n        training_steps:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Training Steps\n          description: >-\n            The number of training steps to perform. A training step refers to a\n            single update of the model weights during the fine-tuning process.\n            This update is typically calculated using a batch of samples from\n            the training dataset.\n          examples:\n            - 10\n        object:\n          const: job.metadata\n          default: job.metadata\n          enum:\n            - job.metadata\n          title: Object\n          type: string\n      required:\n        - details\n      title: LegacyJobMetadataOut\n      type: object\n    GithubRepositoryIn:\n      properties:\n        type:\n          const: github\n          default: github\n          enum:\n            - github\n          title: Type\n          type: string\n        name:\n          title: Name\n          type: string\n        owner:\n          title: Owner\n          type: string\n        ref:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Ref\n        weight:\n          default: 1\n          exclusiveMinimum: 0\n          title: Weight\n          type: number\n        token:\n          title: Token\n          type: string\n      required:\n        - name\n        - owner\n        - token\n      title: GithubRepositoryIn\n      type: object\n    JobIn:\n      properties:\n        model:\n          $ref: \'#/components/schemas/FineTuneableModel\'\n        training_files:\n          default: []\n          items:\n            $ref: \'#/components/schemas/TrainingFile\'\n          title: Training Files\n          type: array\n        validation_files:\n          anyOf:\n            - items:\n                format: uuid\n                type: string\n              type: array\n            - type: \'null\'\n          title: Validation Files\n          description: >-\n            A list containing the IDs of uploaded files that contain validation\n            data. If you provide these files, the data is used to generate\n            validation metrics periodically during fine-tuning. These metrics\n            can be viewed in `checkpoints` when getting the status of a running\n            fine-tuning job. The same data should not be present in both train\n            and validation files.\n        hyperparameters:\n          $ref: \'#/components/schemas/TrainingParametersIn\'\n        suffix:\n          anyOf:\n            - maxLength: 18\n              type: string\n            - type: \'null\'\n          title: Suffix\n          description: >-\n            A string that will be added to your fine-tuning model name. For\n            example, a suffix of \"my-great-model\" would produce a model name\n            like `ft:open-mistral-7b:my-great-model:xxx...`\n        integrations:\n          anyOf:\n            - items:\n                discriminator:\n                  mapping:\n                    wandb: \'#/components/schemas/WandbIntegration\'\n                  propertyName: type\n                oneOf:\n                  - $ref: \'#/components/schemas/WandbIntegration\'\n              type: array\n            - type: \'null\'\n          title: Integrations\n          description: A list of integrations to enable for your fine-tuning job.\n        repositories:\n          default: []\n          items:\n            discriminator:\n              mapping:\n                github: \'#/components/schemas/GithubRepositoryIn\'\n              propertyName: type\n            oneOf:\n              - $ref: \'#/components/schemas/GithubRepositoryIn\'\n          title: Repositories\n          type: array\n        auto_start:\n          description: This field will be required in a future release.\n          title: Auto Start\n          type: boolean\n      required:\n        - model\n        - hyperparameters\n      title: JobIn\n      type: object\n    TrainingFile:\n      properties:\n        file_id:\n          format: uuid\n          title: File Id\n          type: string\n        weight:\n          default: 1\n          exclusiveMinimum: 0\n          title: Weight\n          type: number\n      required:\n        - file_id\n      title: TrainingFile\n      type: object\n    TrainingParametersIn:\n      properties:\n        training_steps:\n          anyOf:\n            - minimum: 1\n              type: integer\n            - type: \'null\'\n          title: Training Steps\n          description: >-\n            The number of training steps to perform. A training step refers to a\n            single update of the model weights during the fine-tuning process.\n            This update is typically calculated using a batch of samples from\n            the training dataset.\n        learning_rate:\n          default: 0.0001\n          maximum: 1\n          minimum: 1.e-8\n          title: Learning Rate\n          type: number\n          description: >-\n            A parameter describing how much to adjust the pre-trained model\'s\n            weights in response to the estimated error each time the weights are\n            updated during the fine-tuning process.\n        weight_decay:\n          anyOf:\n            - maximum: 1\n              minimum: 0\n              type: number\n            - type: \'null\'\n          default: 0.1\n          title: Weight Decay\n          description: >-\n            (Advanced Usage) Weight decay adds a term to the loss function that\n            is proportional to the sum of the squared weights. This term reduces\n            the magnitude of the weights and prevents them from growing too\n            large.\n        warmup_fraction:\n          anyOf:\n            - maximum: 1\n              minimum: 0\n              type: number\n            - type: \'null\'\n          default: 0.05\n          title: Warmup Fraction\n          description: >-\n            (Advanced Usage) A parameter that specifies the percentage of the\n            total training steps at which the learning rate warm-up phase ends.\n            During this phase, the learning rate gradually increases from a\n            small value to the initial learning rate, helping to stabilize the\n            training process and improve convergence. Similar to `pct_start` in\n            [mistral-finetune](https://github.com/mistralai/mistral-finetune)\n        epochs:\n          anyOf:\n            - minimum: 0.01\n              type: number\n            - type: \'null\'\n          title: Epochs\n        fim_ratio:\n          anyOf:\n            - maximum: 1\n              minimum: 0\n              type: number\n            - type: \'null\'\n          default: 0.9\n          title: Fim Ratio\n      title: TrainingParametersIn\n      type: object\n      description: The fine-tuning hyperparameter settings used in a fine-tune job.\n    WandbIntegration:\n      properties:\n        type:\n          const: wandb\n          default: wandb\n          enum:\n            - wandb\n          title: Type\n          type: string\n        project:\n          title: Project\n          type: string\n          description: The name of the project that the new run will be created under.\n        name:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Name\n          description: >-\n            A display name to set for the run. If not set, will use the job ID\n            as the name.\n        api_key:\n          maxLength: 40\n          minLength: 40\n          title: Api Key\n          type: string\n          description: The WandB API key to use for authentication.\n        run_name:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Run Name\n      required:\n        - project\n        - api_key\n      title: WandbIntegration\n      type: object\n    CheckpointOut:\n      properties:\n        metrics:\n          $ref: \'#/components/schemas/MetricOut\'\n        step_number:\n          title: Step Number\n          type: integer\n          description: The step number that the checkpoint was created at.\n        created_at:\n          title: Created At\n          type: integer\n          description: The UNIX timestamp (in seconds) for when the checkpoint was created.\n          examples:\n            - 1716963433\n      required:\n        - metrics\n        - step_number\n        - created_at\n      title: CheckpointOut\n      type: object\n    DetailedJobOut:\n      properties:\n        id:\n          format: uuid\n          title: Id\n          type: string\n        auto_start:\n          title: Auto Start\n          type: boolean\n        hyperparameters:\n          $ref: \'#/components/schemas/TrainingParameters\'\n        model:\n          $ref: \'#/components/schemas/FineTuneableModel\'\n        status:\n          enum:\n            - QUEUED\n            - STARTED\n            - VALIDATING\n            - VALIDATED\n            - RUNNING\n            - FAILED_VALIDATION\n            - FAILED\n            - SUCCESS\n            - CANCELLED\n            - CANCELLATION_REQUESTED\n          title: Status\n          type: string\n        job_type:\n          title: Job Type\n          type: string\n        created_at:\n          title: Created At\n          type: integer\n        modified_at:\n          title: Modified At\n          type: integer\n        training_files:\n          items:\n            format: uuid\n            type: string\n          title: Training Files\n          type: array\n        validation_files:\n          anyOf:\n            - items:\n                format: uuid\n                type: string\n              type: array\n            - type: \'null\'\n          default: []\n          title: Validation Files\n        object:\n          const: job\n          default: job\n          enum:\n            - job\n          title: Object\n          type: string\n        fine_tuned_model:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Fine Tuned Model\n        suffix:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Suffix\n        integrations:\n          anyOf:\n            - items:\n                discriminator:\n                  mapping:\n                    wandb: \'#/components/schemas/WandbIntegrationOut\'\n                  propertyName: type\n                oneOf:\n                  - $ref: \'#/components/schemas/WandbIntegrationOut\'\n              type: array\n            - type: \'null\'\n          title: Integrations\n        trained_tokens:\n          anyOf:\n            - type: integer\n            - type: \'null\'\n          title: Trained Tokens\n        repositories:\n          default: []\n          items:\n            discriminator:\n              mapping:\n                github: \'#/components/schemas/GithubRepositoryOut\'\n              propertyName: type\n            oneOf:\n              - $ref: \'#/components/schemas/GithubRepositoryOut\'\n          maxItems: 20\n          title: Repositories\n          type: array\n        metadata:\n          anyOf:\n            - $ref: \'#/components/schemas/JobMetadataOut\'\n            - type: \'null\'\n        events:\n          default: []\n          items:\n            $ref: \'#/components/schemas/EventOut\'\n          title: Events\n          type: array\n          description: >-\n            Event items are created every time the status of a fine-tuning job\n            changes. The timestamped list of all events is accessible here.\n        checkpoints:\n          default: []\n          items:\n            $ref: \'#/components/schemas/CheckpointOut\'\n          title: Checkpoints\n          type: array\n      required:\n        - id\n        - auto_start\n        - hyperparameters\n        - model\n        - status\n        - job_type\n        - created_at\n        - modified_at\n        - training_files\n      title: DetailedJobOut\n      type: object\n    EventOut:\n      properties:\n        name:\n          title: Name\n          type: string\n          description: The name of the event.\n        data:\n          anyOf:\n            - type: object\n              additionalProperties: true\n            - type: \'null\'\n          title: Data\n        created_at:\n          title: Created At\n          type: integer\n          description: The UNIX timestamp (in seconds) of the event.\n      required:\n        - name\n        - created_at\n      title: EventOut\n      type: object\n    MetricOut:\n      properties:\n        train_loss:\n          anyOf:\n            - type: number\n            - type: \'null\'\n          title: Train Loss\n        valid_loss:\n          anyOf:\n            - type: number\n            - type: \'null\'\n          title: Valid Loss\n        valid_mean_token_accuracy:\n          anyOf:\n            - type: number\n            - type: \'null\'\n          title: Valid Mean Token Accuracy\n      title: MetricOut\n      type: object\n      description: >-\n        Metrics at the step number during the fine-tuning job. Use these metrics\n        to assess if the training is going smoothly (loss should decrease, token\n        accuracy should increase).\n    FTModelCapabilitiesOut:\n      properties:\n        completion_chat:\n          default: true\n          title: Completion Chat\n          type: boolean\n        completion_fim:\n          default: false\n          title: Completion Fim\n          type: boolean\n        function_calling:\n          default: false\n          title: Function Calling\n          type: boolean\n        fine_tuning:\n          default: false\n          title: Fine Tuning\n          type: boolean\n      title: FTModelCapabilitiesOut\n      type: object\n    FTModelOut:\n      properties:\n        id:\n          title: Id\n          type: string\n        object:\n          const: model\n          default: model\n          enum:\n            - model\n          title: Object\n          type: string\n        created:\n          title: Created\n          type: integer\n        owned_by:\n          title: Owned By\n          type: string\n        root:\n          title: Root\n          type: string\n        archived:\n          title: Archived\n          type: boolean\n        name:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Name\n        description:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Description\n        capabilities:\n          $ref: \'#/components/schemas/FTModelCapabilitiesOut\'\n        max_context_length:\n          default: 32768\n          title: Max Context Length\n          type: integer\n        aliases:\n          default: []\n          items:\n            type: string\n          title: Aliases\n          type: array\n        job:\n          format: uuid\n          title: Job\n          type: string\n      required:\n        - id\n        - created\n        - owned_by\n        - root\n        - archived\n        - capabilities\n        - job\n      title: FTModelOut\n      type: object\n    UpdateFTModelIn:\n      properties:\n        name:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Name\n        description:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Description\n      title: UpdateFTModelIn\n      type: object\n    ArchiveFTModelOut:\n      properties:\n        id:\n          title: Id\n          type: string\n        object:\n          const: model\n          default: model\n          enum:\n            - model\n          title: Object\n          type: string\n        archived:\n          default: true\n          title: Archived\n          type: boolean\n      required:\n        - id\n      title: ArchiveFTModelOut\n      type: object\n    UnarchiveFTModelOut:\n      properties:\n        id:\n          title: Id\n          type: string\n        object:\n          const: model\n          default: model\n          enum:\n            - model\n          title: Object\n          type: string\n        archived:\n          default: false\n          title: Archived\n          type: boolean\n      required:\n        - id\n      title: UnarchiveFTModelOut\n      type: object\n    AssistantMessage:\n      properties:\n        content:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Content\n        tool_calls:\n          anyOf:\n            - items:\n                $ref: \'#/components/schemas/ToolCall\'\n              type: array\n            - type: \'null\'\n          title: Tool Calls\n        prefix:\n          type: boolean\n          title: Prefix\n          default: false\n          description: >-\n            Set this to `true` when adding an assistant message as prefix to\n            condition the model response. The role of the prefix message is to\n            force the model to start its answer by the content of the message.\n        role:\n          type: string\n          default: assistant\n          title: Role\n          enum:\n            - assistant\n      additionalProperties: false\n      type: object\n      title: AssistantMessage\n    ChatCompletionRequest:\n      properties:\n        model:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Model\n          description: >-\n            ID of the model to use. You can use the [List Available\n            Models](/api/#tag/models/operation/list_models_v1_models_get) API to\n            see all of your available models, or see our [Model\n            overview](/models) for model descriptions.\n          examples:\n            - mistral-small-latest\n        temperature:\n          type: number\n          maximum: 1.5\n          minimum: 0\n          title: Temperature\n          default: 0.7\n          description: >-\n            What sampling temperature to use, between 0.0 and 1.0. Higher values\n            like 0.8 will make the output more random, while lower values like\n            0.2 will make it more focused and deterministic. We generally\n            recommend altering this or `top_p` but not both.\n        top_p:\n          type: number\n          maximum: 1\n          minimum: 0\n          title: Top P\n          default: 1\n          description: >-\n            Nucleus sampling, where the model considers the results of the\n            tokens with `top_p` probability mass. So 0.1 means only the tokens\n            comprising the top 10% probability mass are considered. We generally\n            recommend altering this or `temperature` but not both.\n        max_tokens:\n          anyOf:\n            - type: integer\n              minimum: 300\n            - type: \'null\'\n          title: Max Tokens\n          default: 300\n          description: >-\n            The maximum number of tokens to generate in the completion. The\n            token count of your prompt plus `max_tokens` cannot exceed the\n            model\'s context length.\n        min_tokens:\n          anyOf:\n            - type: integer\n              minimum: 0\n            - type: \'null\'\n          title: Min Tokens\n          description: The minimum number of tokens to generate in the completion.\n        stream:\n          type: boolean\n          title: Stream\n          default: false\n          description: >-\n            Whether to stream back partial progress. If set, tokens will be sent\n            as data-only server-side events as they become available, with the\n            stream terminated by a data: [DONE] message. Otherwise, the server\n            will hold the request open until the timeout or until completion,\n            with the response containing the full result as JSON.\n        stop:\n          anyOf:\n            - type: string\n            - items:\n                type: string\n              type: array\n          title: Stop\n          description: >-\n            Stop generation if this token is detected. Or if one of these tokens\n            is detected when providing an array\n        random_seed:\n          anyOf:\n            - type: integer\n              minimum: 0\n            - type: \'null\'\n          title: Random Seed\n          description: >-\n            The seed to use for random sampling. If set, different calls will\n            generate deterministic results.\n        messages:\n          items:\n            oneOf:\n              - $ref: \'#/components/schemas/SystemMessage\'\n              - $ref: \'#/components/schemas/UserMessage\'\n              - $ref: \'#/components/schemas/AssistantMessage\'\n              - $ref: \'#/components/schemas/ToolMessage\'\n            discriminator:\n              propertyName: role\n              mapping:\n                assistant: \'#/components/schemas/AssistantMessage\'\n                system: \'#/components/schemas/SystemMessage\'\n                tool: \'#/components/schemas/ToolMessage\'\n                user: \'#/components/schemas/UserMessage\'\n          type: array\n          title: Messages\n          description: >-\n            The prompt(s) to generate completions for, encoded as a list of dict\n            with role and content.\n          examples:\n            - - role: user\n                content: Who is the best French painter? Answer in one short sentence.\n        response_format:\n          $ref: \'#/components/schemas/ResponseFormat\'\n        tools:\n          anyOf:\n            - items:\n                $ref: \'#/components/schemas/Tool\'\n              type: array\n            - type: \'null\'\n          title: Tools\n        tool_choice:\n          allOf:\n            - $ref: \'#/components/schemas/ToolChoice\'\n          default: auto\n        safe_prompt:\n          type: boolean\n          description: Whether to inject a safety prompt before all conversations.\n          default: false\n      additionalProperties: false\n      type: object\n      required:\n        - messages\n        - model\n      title: ChatCompletionRequest\n    ChunkTypes:\n      type: string\n      const: text\n      title: ChunkTypes\n    ContentChunk:\n      properties:\n        type:\n          allOf:\n            - $ref: \'#/components/schemas/ChunkTypes\'\n          default: text\n        text:\n          type: string\n          title: Text\n      additionalProperties: false\n      type: object\n      required:\n        - text\n      title: ContentChunk\n    FIMCompletionRequest:\n      properties:\n        model:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Model\n          default: codestral-2405\n          description: |-\n            ID of the model to use. Only compatible for now with:\n              - `codestral-2405`\n              - `codestral-latest`\n          examples:\n            - codestral-2405\n        temperature:\n          type: number\n          maximum: 1.5\n          minimum: 0\n          title: Temperature\n          default: 0.7\n          description: >-\n            What sampling temperature to use, between 0.0 and 1.0. Higher values\n            like 0.8 will make the output more random, while lower values like\n            0.2 will make it more focused and deterministic. We generally\n            recommend altering this or `top_p` but not both.\n        top_p:\n          type: number\n          maximum: 1\n          minimum: 0\n          title: Top P\n          default: 1\n          description: >-\n            Nucleus sampling, where the model considers the results of the\n            tokens with `top_p` probability mass. So 0.1 means only the tokens\n            comprising the top 10% probability mass are considered. We generally\n            recommend altering this or `temperature` but not both.\n        max_tokens:\n          anyOf:\n            - type: integer\n              minimum: 300\n            - type: \'null\'\n          title: Max Tokens\n          default: 300\n          description: >-\n            The maximum number of tokens to generate in the completion. The\n            token count of your prompt plus `max_tokens` cannot exceed the\n            model\'s context length.\n        min_tokens:\n          anyOf:\n            - type: integer\n              minimum: 0\n            - type: \'null\'\n          title: Min Tokens\n          description: The minimum number of tokens to generate in the completion.\n        stream:\n          type: boolean\n          title: Stream\n          default: false\n          description: >-\n            Whether to stream back partial progress. If set, tokens will be sent\n            as data-only server-side events as they become available, with the\n            stream terminated by a data: [DONE] message. Otherwise, the server\n            will hold the request open until the timeout or until completion,\n            with the response containing the full result as JSON.\n        stop:\n          anyOf:\n            - type: string\n            - items:\n                type: string\n              type: array\n          title: Stop\n          description: >-\n            Stop generation if this token is detected. Or if one of these tokens\n            is detected when providing an array\n        random_seed:\n          anyOf:\n            - type: integer\n              minimum: 0\n            - type: \'null\'\n          title: Random Seed\n          description: >-\n            The seed to use for random sampling. If set, different calls will\n            generate deterministic results.\n        prompt:\n          type: string\n          title: Prompt\n          description: The text/code to complete.\n          examples:\n            - def\n        suffix:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Suffix\n          default: \'\'\n          description: >-\n            Optional text/code that adds more context for the model. When given\n            a `prompt` and a `suffix` the model will fill what is between them.\n            When `suffix` is not provided, the model will simply execute\n            completion starting with `prompt`.\n          examples:\n            - return a+b\n      additionalProperties: false\n      type: object\n      required:\n        - prompt\n        - model\n      title: FIMCompletionRequest\n    Function:\n      properties:\n        name:\n          type: string\n          title: Name\n        description:\n          type: string\n          title: Description\n          default: \'\'\n        parameters:\n          type: object\n          title: Parameters\n          additionalProperties: true\n      additionalProperties: false\n      type: object\n      required:\n        - name\n        - parameters\n      title: Function\n    FunctionCall:\n      properties:\n        name:\n          type: string\n          title: Name\n        arguments:\n          title: Arguments\n          anyOf:\n            - type: object\n              additionalProperties: true\n            - type: string\n      additionalProperties: false\n      type: object\n      required:\n        - name\n        - arguments\n      title: FunctionCall\n    ResponseFormat:\n      properties:\n        type:\n          allOf:\n            - $ref: \'#/components/schemas/ResponseFormats\'\n          default: text\n      additionalProperties: false\n      type: object\n      title: ResponseFormat\n    ResponseFormats:\n      type: string\n      enum:\n        - text\n        - json_object\n      title: ResponseFormats\n      description: >-\n        An object specifying the format that the model must output. Setting to\n        `{ \"type\": \"json_object\" }` enables JSON mode, which guarantees the\n        message the model generates is in JSON. When using JSON mode you MUST\n        also instruct the model to produce JSON yourself with a system or a user\n        message.\n    SystemMessage:\n      properties:\n        content:\n          anyOf:\n            - type: string\n            - items:\n                $ref: \'#/components/schemas/ContentChunk\'\n              type: array\n          title: Content\n        role:\n          type: string\n          default: system\n          enum:\n            - system\n      additionalProperties: false\n      type: object\n      required:\n        - content\n      title: SystemMessage\n    TextChunk:\n      properties:\n        type:\n          const: text\n          title: Type\n          default: text\n        text:\n          type: string\n          title: Text\n      additionalProperties: false\n      type: object\n      required:\n        - text\n      title: TextChunk\n    Tool:\n      properties:\n        type:\n          allOf:\n            - $ref: \'#/components/schemas/ToolTypes\'\n          default: function\n        function:\n          $ref: \'#/components/schemas/Function\'\n      additionalProperties: false\n      type: object\n      required:\n        - function\n      title: Tool\n    ToolCall:\n      properties:\n        id:\n          type: string\n          title: Id\n          default: \'null\'\n        type:\n          allOf:\n            - $ref: \'#/components/schemas/ToolTypes\'\n          default: function\n        function:\n          $ref: \'#/components/schemas/FunctionCall\'\n      additionalProperties: false\n      type: object\n      required:\n        - function\n      title: ToolCall\n    ToolChoice:\n      type: string\n      enum:\n        - auto\n        - none\n        - any\n      title: ToolChoice\n    ToolMessage:\n      properties:\n        content:\n          type: string\n          title: Content\n        tool_call_id:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Tool Call Id\n        name:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Name\n        role:\n          type: string\n          default: tool\n          enum:\n            - tool\n      additionalProperties: false\n      type: object\n      required:\n        - content\n      title: ToolMessage\n    ToolTypes:\n      type: string\n      const: function\n      title: ToolTypes\n    UserMessage:\n      properties:\n        content:\n          title: Content\n          anyOf:\n            - type: string\n            - items:\n                $ref: \'#/components/schemas/TextChunk\'\n              type: array\n        role:\n          type: string\n          default: user\n          enum:\n            - user\n      additionalProperties: false\n      type: object\n      required:\n        - content\n      title: UserMessage\n    AgentsCompletionRequest:\n      properties:\n        max_tokens:\n          anyOf:\n            - type: integer\n              minimum: 300\n            - type: \'null\'\n          title: Max Tokens\n          default: 300\n          description: >-\n            The maximum number of tokens to generate in the completion. The\n            token count of your prompt plus `max_tokens` cannot exceed the\n            model\'s context length.\n        min_tokens:\n          anyOf:\n            - type: integer\n              minimum: 0\n            - type: \'null\'\n          title: Min Tokens\n          description: The minimum number of tokens to generate in the completion.\n        stream:\n          type: boolean\n          title: Stream\n          default: false\n          description: >-\n            Whether to stream back partial progress. If set, tokens will be sent\n            as data-only server-side events as they become available, with the\n            stream terminated by a data: [DONE] message. Otherwise, the server\n            will hold the request open until the timeout or until completion,\n            with the response containing the full result as JSON.\n        stop:\n          anyOf:\n            - type: string\n            - items:\n                type: string\n              type: array\n          title: Stop\n          description: >-\n            Stop generation if this token is detected. Or if one of these tokens\n            is detected when providing an array\n        random_seed:\n          anyOf:\n            - type: integer\n              minimum: 0\n            - type: \'null\'\n          title: Random Seed\n          description: >-\n            The seed to use for random sampling. If set, different calls will\n            generate deterministic results.\n        messages:\n          type: array\n          title: Messages\n          items:\n            oneOf:\n              - $ref: \'#/components/schemas/UserMessage\'\n              - $ref: \'#/components/schemas/AssistantMessage\'\n              - $ref: \'#/components/schemas/ToolMessage\'\n            discriminator:\n              propertyName: role\n              mapping:\n                assistant: \'#/components/schemas/AssistantMessage\'\n                tool: \'#/components/schemas/ToolMessage\'\n                user: \'#/components/schemas/UserMessage\'\n          description: >-\n            The prompt(s) to generate completions for, encoded as a list of dict\n            with role and content.\n          examples:\n            - - role: user\n                content: Who is the best French painter? Answer in one short sentence.\n        response_format:\n          $ref: \'#/components/schemas/ResponseFormat\'\n        tools:\n          anyOf:\n            - items:\n                $ref: \'#/components/schemas/Tool\'\n              type: array\n            - type: \'null\'\n          title: Tools\n        tool_choice:\n          allOf:\n            - $ref: \'#/components/schemas/ToolChoice\'\n          default: auto\n        agent_id:\n          type: string\n          description: The ID of the agent to use for this completion.\n      additionalProperties: false\n      type: object\n      required:\n        - messages\n        - agent_id\n      title: AgentsCompletionRequest\n    EmbeddingRequest:\n      properties:\n        input:\n          anyOf:\n            - type: string\n            - items:\n                type: string\n              type: array\n          title: Input\n          description: Text to embed.\n        model:\n          type: string\n          title: Model\n          description: ID of the model to use.\n        encoding_format:\n          anyOf:\n            - type: string\n            - type: \'null\'\n          title: Encoding Format\n          description: The format to return the embeddings in.\n          default: float\n      additionalProperties: false\n      type: object\n      required:\n        - input\n        - model\n      title: EmbeddingRequest\n    UsageInfo:\n      title: UsageInfo\n      type: object\n      properties:\n        prompt_tokens:\n          type: integer\n          example: 16\n        completion_tokens:\n          type: integer\n          example: 34\n        total_tokens:\n          type: integer\n          example: 50\n      required:\n        - prompt_tokens\n        - completion_tokens\n        - total_tokens\n    ResponseBase:\n      type: object\n      title: ResponseBase\n      properties:\n        id:\n          type: string\n          example: cmpl-e5cc70bb28c444948073e77776eb30ef\n        object:\n          type: string\n          example: chat.completion\n        model:\n          type: string\n          example: mistral-small-latest\n        usage:\n          $ref: \'#/components/schemas/UsageInfo\'\n    ChatCompletionChoice:\n      title: ChatCompletionChoice\n      type: object\n      required:\n        - index\n        - finish_reason\n        - message\n      properties:\n        index:\n          type: integer\n          example: 0\n        message:\n          $ref: \'#/components/schemas/AssistantMessage\'\n        finish_reason:\n          type: string\n          enum:\n            - stop\n            - length\n            - model_length\n            - error\n            - tool_calls\n          example: stop\n    ChatCompletionResponseBase:\n      allOf:\n        - $ref: \'#/components/schemas/ResponseBase\'\n        - type: object\n          title: ChatCompletionResponseBase\n          properties:\n            created:\n              type: integer\n              example: 1702256327\n    ChatCompletionResponse:\n      allOf:\n        - $ref: \'#/components/schemas/ChatCompletionResponseBase\'\n        - type: object\n          title: ChatCompletionResponse\n          properties:\n            choices:\n              type: array\n              items:\n                $ref: \'#/components/schemas/ChatCompletionChoice\'\n          required:\n            - id\n            - object\n            - data\n            - model\n            - usage\n    FIMCompletionResponse:\n      allOf:\n        - $ref: \'#/components/schemas/ChatCompletionResponse\'\n        - type: object\n          properties:\n            model:\n              type: string\n              example: codestral-latest\n    EmbeddingResponseData:\n      title: EmbeddingResponseData\n      type: object\n      properties:\n        object:\n          type: string\n          example: embedding\n        embedding:\n          type: array\n          items:\n            type: number\n          examples:\n            - 0.1\n            - 0.2\n            - 0.3\n        index:\n          type: integer\n          example: 0\n      examples:\n        - object: embedding\n          embedding:\n            - 0.1\n            - 0.2\n            - 0.3\n          index: 0\n        - object: embedding\n          embedding:\n            - 0.4\n            - 0.5\n            - 0.6\n          index: 1\n    EmbeddingResponse:\n      allOf:\n        - $ref: \'#/components/schemas/ResponseBase\'\n        - type: object\n          properties:\n            data:\n              type: array\n              items:\n                $ref: \'#/components/schemas/EmbeddingResponseData\'\n          required:\n            - id\n            - object\n            - data\n            - model\n            - usage\n    CompletionEvent:\n      type: object\n      required:\n        - data\n      properties:\n        data:\n          $ref: \'#/components/schemas/CompletionChunk\'\n    CompletionChunk:\n      type: object\n      required:\n        - id\n        - model\n        - choices\n      properties:\n        id:\n          type: string\n        object:\n          type: string\n        created:\n          type: integer\n        model:\n          type: string\n        usage:\n          $ref: \'#/components/schemas/UsageInfo\'\n        choices:\n          type: array\n          items:\n            $ref: \'#/components/schemas/CompletionResponseStreamChoice\'\n    CompletionResponseStreamChoice:\n      type: object\n      required:\n        - index\n        - delta\n        - finish_reason\n      properties:\n        index:\n          type: integer\n        delta:\n          $ref: \'#/components/schemas/DeltaMessage\'\n        finish_reason:\n          type:\n            - string\n            - \'null\'\n          enum:\n            - stop\n            - length\n            - error\n            - tool_calls\n            - null\n    DeltaMessage:\n      type: object\n      properties:\n        role:\n          type: string\n        content:\n          anyOf:\n            - type: string\n            - type: \'null\'\n        tool_calls:\n          anyOf:\n            - type: \'null\'\n            - type: array\n              items:\n                $ref: \'#/components/schemas/ToolCall\'\n  securitySchemes:\n    ApiKey:\n      type: http\n      scheme: bearer\ntags:\n  - name: chat\n    x-displayName: Chat\n    description: Chat Completion API.\n  - name: fim\n    x-displayName: FIM\n    description: Fill-in-the-middle API.\n  - name: agents\n    x-displayName: Agents\n    description: Agents API.\n  - name: embeddings\n    x-displayName: Embeddings\n    description: Embeddings API.\n  - name: files\n    x-displayName: Files\n    description: Files API\n  - name: fine-tuning\n    x-displayName: Fine Tuning\n    description: Fine-tuning API\n  - name: models\n    x-displayName: Models\n    description: Model Management API\nsecurity:\n  - ApiKey: []\nservers:\n  - url: https://api.mistral.ai\n    description: Production server\n','false'),('d7123dce-716a-4da5-87ea-2a5d55d09cb6','AzureOpenAI','2.0.0','carbon.super','true','Azure OpenAI service',_binary '{\"connectorType\":\"azureOpenAi_2.0.0\",\"metadata\":[{\"attributeName\":\"requestModel\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.model\",\"required\":false},{\"attributeName\":\"responseModel\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.model\",\"required\":true},{\"attributeName\":\"promptTokenCount\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.usage.input_tokens\",\"required\":true},{\"attributeName\":\"completionTokenCount\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.usage.output_tokens\",\"required\":true},{\"attributeName\":\"totalTokenCount\",\"inputSource\":\"payload\",\"attributeIdentifier\":\"$.usage.total_tokens\",\"required\":true},{\"attributeName\":\"remainingTokenCount\",\"inputSource\":\"header\",\"attributeIdentifier\":\"x-ratelimit-remaining-tokens\",\"required\":false}],\"authHeader\":\"api-key\",\"authenticationConfiguration\":{\"enabled\":true,\"type\":\"apikey\",\"parameters\":{\"headerEnabled\":true,\"headerName\":\"api-key\",\"queryParameterEnabled\":false}}}',_binary 'openapi: 3.1.0\ninfo:\n  title: Azure OpenAI Service API\n  description: Azure OpenAI APIs for completions and search\n  version: 2025-04-01-preview\nservers:\n  - url: https://{resource-name}.openai.azure.com\n    variables:\n      resource-name:\n        default: your-resource-name\nsecurity:\n  - bearer:\n      - api.read\n  - apiKey: []\npaths:\n  /openai/assistants:\n    get:\n      operationId: List_Assistants\n      tags:\n        - Assistants\n      summary: Returns a list of assistants.\n      parameters:\n        - name: limit\n          in: query\n          description: &pagination_limit_param_description |\n            A limit on the number of objects to be returned. Limit can range between 1 and 100, and the default is 20.\n          required: false\n          schema:\n            type: integer\n            default: 20\n        - name: order\n          in: query\n          description: &pagination_order_param_description |\n            Sort order by the `created_at` timestamp of the objects. `asc` for ascending order and `desc` for descending order.\n          schema:\n            type: string\n            default: desc\n            enum:\n              - asc\n              - desc\n            x-ms-enum:\n              name: ListAssistantsOrder\n              modelAsString: true\n              values:\n                - value: asc\n                  description: Order results in ascending order\n                - value: desc\n                  description: Order results in descending order\n        - name: after\n          in: query\n          description: &pagination_after_param_description |\n            A cursor for use in pagination. `after` is an object ID that defines your place in the list. For instance, if you make a list request and receive 100 objects, ending with obj_foo, your subsequent call can include after=obj_foo in order to fetch the next page of the list.\n          schema:\n            type: string\n        - name: before\n          in: query\n          description: &pagination_before_param_description |\n            A cursor for use in pagination. `before` is an object ID that defines your place in the list. For instance, if you make a list request and receive 100 objects, starting with obj_foo, your subsequent call can include before=obj_foo in order to fetch the previous page of the list.\n          schema:\n            type: string\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/listAssistantsResponse\"\n    post:\n      operationId: Create_Assistant\n      tags:\n        - Assistants\n      summary: Create an assistant with a model and instructions.\n      parameters:\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n          description: api version\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/createAssistantRequest\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/assistantObject\"\n  /openai/assistants/{assistant_id}:\n    get:\n      operationId: Get_Assistant\n      tags:\n        - Assistants\n      summary: Retrieves an assistant.\n      parameters:\n        - in: path\n          name: assistant_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the assistant to retrieve.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/assistantObject\"\n    post:\n      operationId: Modify_Assistant\n      tags:\n        - Assistants\n      summary: Modifies an assistant.\n      parameters:\n        - in: path\n          name: assistant_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the assistant to modify.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/modifyAssistantRequest\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/assistantObject\"\n    delete:\n      operationId: Delete_Assistant\n      tags:\n        - Assistants\n      summary: Delete an assistant.\n      parameters:\n        - in: path\n          name: assistant_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the assistant to delete.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/deleteAssistantResponse\"\n  /openai/threads:\n    post:\n      operationId: Create_Thread\n      tags:\n        - Assistants\n      summary: Create a thread.\n      parameters:\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/createThreadRequest\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/threadObject\"\n  /openai/threads/{thread_id}:\n    get:\n      operationId: Get_Thread\n      tags:\n        - Assistants\n      summary: Retrieves a thread.\n      parameters:\n        - in: path\n          name: thread_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the thread to retrieve.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/threadObject\"\n    post:\n      operationId: Modify_Thread\n      tags:\n        - Assistants\n      summary: Modifies a thread.\n      parameters:\n        - in: path\n          name: thread_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the thread to modify. Only the `metadata` can be modified.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/modifyThreadRequest\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/threadObject\"\n    delete:\n      operationId: Delete_Thread\n      tags:\n        - Assistants\n      summary: Delete a thread.\n      parameters:\n        - in: path\n          name: thread_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the thread to delete.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/deleteThreadResponse\"\n  /openai/threads/{thread_id}/messages:\n    get:\n      operationId: List_Messages\n      tags:\n        - Assistants\n      summary: Returns a list of messages for a given thread.\n      parameters:\n        - in: path\n          name: thread_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the [thread](/docs/api-reference/threads) the messages belong to.\n        - name: limit\n          in: query\n          description: *pagination_limit_param_description\n          required: false\n          schema:\n            type: integer\n            default: 20\n        - name: order\n          in: query\n          description: |\n            Sort order by the `created_at` timestamp of the objects. `asc` for ascending order and `desc` for descending order.\n          schema:\n            type: string\n            default: desc\n            enum:\n              - asc\n              - desc\n            x-ms-enum:\n              name: ListMessagesOrder\n              modelAsString: true\n              values:\n                - value: asc\n                  description: Order results in ascending order\n                - value: desc\n                  description: Order results in descending order\n        - name: after\n          in: query\n          description: |\n            A cursor for use in pagination. `after` is an object ID that defines your place in the list. For instance, if you make a list request and receive 100 objects, ending with obj_foo, your subsequent call can include after=obj_foo in order to fetch the next page of the list.\n          schema:\n            type: string\n        - name: before\n          in: query\n          description: |\n            A cursor for use in pagination. `before` is an object ID that defines your place in the list. For instance, if you make a list request and receive 100 objects, ending with obj_foo, your subsequent call can include before=obj_foo in order to fetch the previous page of the list.\n          schema:\n            type: string\n        - name: run_id\n          in: query\n          description: |\n            Filter messages by the run ID that generated them.\n          schema:\n            type: string\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/listMessagesResponse\"\n    post:\n      operationId: Create_Message\n      tags:\n        - Assistants\n      summary: Create a message.\n      parameters:\n        - in: path\n          name: thread_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the [thread](/docs/api-reference/threads) to create a message for.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/createMessageRequest\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/messageObject\"\n  /openai/threads/{thread_id}/messages/{message_id}:\n    get:\n      operationId: Get_Message\n      tags:\n        - Assistants\n      summary: Retrieve a message.\n      parameters:\n        - in: path\n          name: thread_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the [thread](/docs/api-reference/threads) to which this message belongs.\n        - in: path\n          name: message_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the message to retrieve.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/messageObject\"\n    post:\n      operationId: Modify_Message\n      tags:\n        - Assistants\n      summary: Modifies a message.\n      parameters:\n        - in: path\n          name: thread_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the thread to which this message belongs.\n        - in: path\n          name: message_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the message to modify.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/modifyMessageRequest\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/messageObject\"\n  /openai/threads/runs:\n    post:\n      operationId: Create_Thread_And_Run\n      tags:\n        - Assistants\n      summary: Create a thread and run it in one request.\n      parameters:\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/createThreadAndRunRequest\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/runObject\"\n  /openai/threads/{thread_id}/runs:\n    get:\n      operationId: List_Runs\n      tags:\n        - Assistants\n      summary: Returns a list of runs belonging to a thread.\n      parameters:\n        - name: thread_id\n          in: path\n          required: true\n          schema:\n            type: string\n          description: The ID of the thread the run belongs to.\n        - name: limit\n          in: query\n          description: *pagination_limit_param_description\n          required: false\n          schema:\n            type: integer\n            default: 20\n        - name: order\n          in: query\n          description: *pagination_order_param_description\n          schema:\n            type: string\n            default: desc\n            enum:\n              - asc\n              - desc\n            x-ms-enum:\n              name: ListRunsOrder\n              modelAsString: true\n              values:\n                - value: asc\n                  description: Order results in ascending order\n                - value: desc\n                  description: Order results in descending order\n        - name: after\n          in: query\n          description: *pagination_after_param_description\n          schema:\n            type: string\n        - name: before\n          in: query\n          description: *pagination_before_param_description\n          schema:\n            type: string\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/listRunsResponse\"\n    post:\n      operationId: Create_Run\n      tags:\n        - Assistants\n      summary: Create a run.\n      parameters:\n        - in: path\n          name: thread_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the thread to run.\n        - name: include[]\n          in: query\n          description: >\n            A list of additional fields to include in the response. Currently\n            the only supported value is\n            `step_details.tool_calls[*].file_search.results[*].content` to fetch\n            the file search result content.\n\n          schema:\n            type: array\n            items:\n              type: string\n              enum:\n                - step_details.tool_calls[*].file_search.results[*].content\n              x-ms-enum:\n                name: Include\n                modelAsString: true\n                values:\n                  - value: step_details.tool_calls[*].file_search.results[*].content\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/createRunRequest\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/runObject\"\n  /openai/threads/{thread_id}/runs/{run_id}:\n    get:\n      operationId: Get_Run\n      tags:\n        - Assistants\n      summary: Retrieves a run.\n      parameters:\n        - in: path\n          name: thread_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the [thread](/docs/api-reference/threads) that was run.\n        - in: path\n          name: run_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the run to retrieve.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/runObject\"\n    post:\n      operationId: Modify_Run\n      tags:\n        - Assistants\n      summary: Modifies a run.\n      parameters:\n        - in: path\n          name: thread_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the [thread](/docs/api-reference/threads) that was run.\n        - in: path\n          name: run_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the run to modify.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/modifyRunRequest\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/runObject\"\n  /openai/threads/{thread_id}/runs/{run_id}/submit_tool_outputs:\n    post:\n      operationId: Submit_Tool_Outputs_To_Run\n      tags:\n        - Assistants\n      summary: |\n        When a run has the `status: \"requires_action\"` and `required_action.type` is `submit_tool_outputs`, this endpoint can be used to submit the outputs from the tool calls once they\'re all completed. All outputs must be submitted in a single request.\n      parameters:\n        - in: path\n          name: thread_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the [thread](/docs/api-reference/threads) to which this run belongs.\n        - in: path\n          name: run_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the run that requires the tool output submission.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/submitToolOutputsRunRequest\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/runObject\"\n  /openai/threads/{thread_id}/runs/{run_id}/cancel:\n    post:\n      operationId: Cancel_Run\n      tags:\n        - Assistants\n      summary: Cancels a run that is `in_progress`.\n      parameters:\n        - in: path\n          name: thread_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the thread to which this run belongs.\n        - in: path\n          name: run_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the run to cancel.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n          description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/runObject\"\n  /openai/threads/{thread_id}/runs/{run_id}/steps:\n    get:\n      operationId: List_Run_Steps\n      tags:\n        - Assistants\n      summary: Returns a list of run steps belonging to a run.\n      parameters:\n        - name: thread_id\n          in: path\n          required: true\n          schema:\n            type: string\n          description: The ID of the thread the run and run steps belong to.\n        - name: run_id\n          in: path\n          required: true\n          schema:\n            type: string\n          description: The ID of the run the run steps belong to.\n        - name: limit\n          in: query\n          description: *pagination_limit_param_description\n          required: false\n          schema:\n            type: integer\n            default: 20\n        - name: order\n          in: query\n          description: *pagination_order_param_description\n          schema:\n            type: string\n            default: desc\n            enum:\n              - asc\n              - desc\n            x-ms-enum:\n              name: ListRunStepsOrder\n              modelAsString: true\n              values:\n                - value: asc\n                  description: Order results in ascending order\n                - value: desc\n                  description: Order results in descending order\n        - name: after\n          in: query\n          description: *pagination_after_param_description\n          schema:\n            type: string\n        - name: before\n          in: query\n          description: *pagination_before_param_description\n          schema:\n            type: string\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n          description: api version\n        - name: include[]\n          in: query\n          description: >\n            A list of additional fields to include in the response. Currently\n            the only supported value is\n            `step_details.tool_calls[*].file_search.results[*].content` to fetch\n            the file search result content.\n\n          schema:\n            type: array\n            items:\n              type: string\n              enum:\n                - step_details.tool_calls[*].file_search.results[*].content\n              x-ms-enum:\n                name: Include\n                modelAsString: true\n                values:\n                  - value: step_details.tool_calls[*].file_search.results[*].content\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/listRunStepsResponse\"\n  /openai/threads/{thread_id}/runs/{run_id}/steps/{step_id}:\n    get:\n      operationId: Get_Run_Step\n      tags:\n        - Assistants\n      summary: Retrieves a run step.\n      parameters:\n        - in: path\n          name: thread_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the thread to which the run and run step belongs.\n        - in: path\n          name: run_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the run to which the run step belongs.\n        - in: path\n          name: step_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the run step to retrieve.\n        - name: include[]\n          in: query\n          description: >\n            A list of additional fields to include in the response. Currently\n            the only supported value is\n            `step_details.tool_calls[*].file_search.results[*].content` to fetch\n            the file search result content.\n\n          schema:\n            type: array\n            items:\n              type: string\n              enum:\n                - step_details.tool_calls[*].file_search.results[*].content\n              x-ms-enum:\n                name: Include\n                modelAsString: true\n                values:\n                  - value: step_details.tool_calls[*].file_search.results[*].content\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n          description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/runStepObject\"\n  /openai/vector_stores:\n    get:\n      operationId: List_Vector_Stores\n      tags:\n        - Vector Stores\n      summary: Returns a list of vector stores.\n      parameters:\n        - name: limit\n          in: query\n          description: *pagination_limit_param_description\n          required: false\n          schema:\n            type: integer\n            default: 20\n        - name: order\n          in: query\n          description: *pagination_order_param_description\n          schema:\n            type: string\n            default: desc\n            enum: [\"asc\", \"desc\"]\n            x-ms-enum:\n              name: ListVectorStoresOrder\n              modelAsString: true\n              values:\n                - value: asc\n                - value: desc\n        - name: after\n          in: query\n          description: *pagination_after_param_description\n          schema:\n            type: string\n        - name: before\n          in: query\n          description: *pagination_before_param_description\n          schema:\n            type: string\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n          description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/listVectorStoresResponse\"\n    post:\n      operationId: Create_Vector_Store\n      tags:\n        - Vector Stores\n      summary: Create a vector store.\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/createVectorStoreRequest\"\n      parameters:\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n          description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/vectorStoreObject\"\n\n  /openai/vector_stores/{vector_store_id}:\n    get:\n      operationId: Get_Vector_Store\n      tags:\n        - Vector Stores\n      summary: Retrieves a vector store.\n      parameters:\n        - in: path\n          name: vector_store_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the vector store to retrieve.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n          description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/vectorStoreObject\"\n    post:\n      operationId: Modify_Vector_Store\n      tags:\n        - Vector Stores\n      summary: Modifies a vector store.\n      parameters:\n        - in: path\n          name: vector_store_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the vector store to modify.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n          description: api version\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/updateVectorStoreRequest\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/vectorStoreObject\"\n\n    delete:\n      operationId: Delete_Vector_Store\n      tags:\n        - Vector Stores\n      summary: Delete a vector store.\n      parameters:\n        - in: path\n          name: vector_store_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the vector store to delete.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n          description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/deleteVectorStoreResponse\"\n\n  /openai/vector_stores/{vector_store_id}/files:\n    get:\n      operationId: List_Vector_Store_Files\n      tags:\n        - Vector Stores\n      summary: Returns a list of vector store files.\n      parameters:\n        - name: vector_store_id\n          in: path\n          description: The ID of the vector store that the files belong to.\n          required: true\n          schema:\n            type: string\n        - name: limit\n          in: query\n          description: *pagination_limit_param_description\n          required: false\n          schema:\n            type: integer\n            default: 20\n        - name: order\n          in: query\n          description: *pagination_order_param_description\n          schema:\n            type: string\n            default: desc\n            enum: [\"asc\", \"desc\"]\n            x-ms-enum:\n              name: ListVectorStoreFilesOrder\n              modelAsString: true\n              values:\n                - value: asc\n                - value: desc\n        - name: after\n          in: query\n          description: *pagination_after_param_description\n          schema:\n            type: string\n        - name: before\n          in: query\n          description: *pagination_before_param_description\n          schema:\n            type: string\n        - name: filter\n          in: query\n          description: \"Filter by file status. One of `in_progress`, `completed`, `failed`, `cancelled`.\"\n          schema:\n            type: string\n            enum: [\"in_progress\", \"completed\", \"failed\", \"cancelled\"]\n            x-ms-enum:\n              name: ListVectorStoreFilesFilter\n              modelAsString: true\n              values:\n                - value: in_progress\n                - value: completed\n                - value: failed\n                - value: cancelled\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n          description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/listVectorStoreFilesResponse\"\n    post:\n      operationId: Create_Vector_Store_File\n      tags:\n        - Vector Stores\n      summary: Create a vector store file by attaching a [File](/docs/api-reference/files) to a [vector store](/docs/api-reference/vector-stores/object).\n      parameters:\n        - in: path\n          name: vector_store_id\n          required: true\n          schema:\n            type: string\n            example: vs_abc123\n          description: |\n            The ID of the vector store for which to create a File.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n          description: api version\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/createVectorStoreFileRequest\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/vectorStoreFileObject\"\n\n  /openai/vector_stores/{vector_store_id}/files/{file_id}:\n    get:\n      operationId: Get_Vector_Store_File\n      tags:\n        - Vector Stores\n      summary: Retrieves a vector store file.\n      parameters:\n        - in: path\n          name: vector_store_id\n          required: true\n          schema:\n            type: string\n            example: vs_abc123\n          description: The ID of the vector store that the file belongs to.\n        - in: path\n          name: file_id\n          required: true\n          schema:\n            type: string\n            example: file-abc123\n          description: The ID of the file being retrieved.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n          description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/vectorStoreFileObject\"\n    delete:\n      operationId: Delete_Vector_Store_File\n      tags:\n        - Vector Stores\n      summary: Delete a vector store file. This will remove the file from the vector store but the file itself will not be deleted. To delete the file, use the [delete file](/docs/api-reference/files/delete) endpoint.\n      parameters:\n        - in: path\n          name: vector_store_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the vector store that the file belongs to.\n        - in: path\n          name: file_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the file to delete.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n          description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/deleteVectorStoreFileResponse\"\n    post:\n      operationId: updateVectorStoreFileAttributes\n      tags:\n        - Vector Stores\n      summary: Update attributes on a vector store file.\n      parameters:\n        - in: path\n          name: vector_store_id\n          required: true\n          schema:\n            type: string\n            example: vs_abc123\n          description: The ID of the vector store the file belongs to.\n        - in: path\n          name: file_id\n          required: true\n          schema:\n            type: string\n            example: file-abc123\n          description: The ID of the file to update attributes.\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/UpdateVectorStoreFileAttributesRequest\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/vectorStoreFileObject\"\n  /openai/vector_stores/{vector_store_id}/files/{file_id}/content:\n    get:\n      operationId: retrieveVectorStoreFileContent\n      tags:\n        - Vector Stores\n      summary: Retrieve the parsed contents of a vector store file.\n      parameters:\n        - in: path\n          name: vector_store_id\n          required: true\n          schema:\n            type: string\n            example: vs_abc123\n          description: The ID of the vector store.\n        - in: path\n          name: file_id\n          required: true\n          schema:\n            type: string\n            example: file-abc123\n          description: The ID of the file within the vector store.\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/VectorStoreFileContentResponse\"\n  /openai/vector_stores/{vector_store_id}/search:\n    post:\n      operationId: searchVectorStore\n      tags:\n        - Vector Stores\n      summary: Search a vector store for relevant chunks based on a query and file\n        attributes filter.\n      parameters:\n        - in: path\n          name: vector_store_id\n          required: true\n          schema:\n            type: string\n            example: vs_abc123\n          description: The ID of the vector store to search.\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/VectorStoreSearchRequest\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/VectorStoreSearchResultsPage\"\n\n  /openai/vector_stores/{vector_store_id}/file_batches:\n    post:\n      operationId: Create_Vector_Store_File_Batch\n      tags:\n        - Vector Stores\n      summary: Create a vector store file batch.\n      parameters:\n        - in: path\n          name: vector_store_id\n          required: true\n          schema:\n            type: string\n            example: vs_abc123\n          description: |\n            The ID of the vector store for which to create a File Batch.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n          description: api version\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/createVectorStoreFileBatchRequest\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/vectorStoreFileBatchObject\"\n\n  /openai/vector_stores/{vector_store_id}/file_batches/{batch_id}:\n    get:\n      operationId: Get_Vector_Store_File_Batch\n      tags:\n        - Vector Stores\n      summary: Retrieves a vector store file batch.\n      parameters:\n        - in: path\n          name: vector_store_id\n          required: true\n          schema:\n            type: string\n            example: vs_abc123\n          description: The ID of the vector store that the file batch belongs to.\n        - in: path\n          name: batch_id\n          required: true\n          schema:\n            type: string\n            example: vsfb_abc123\n          description: The ID of the file batch being retrieved.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n          description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/vectorStoreFileBatchObject\"\n\n  /openai/vector_stores/{vector_store_id}/file_batches/{batch_id}/cancel:\n    post:\n      operationId: Cancel_Vector_Store_File_Batch\n      tags:\n        - Vector Stores\n      summary: Cancel a vector store file batch. This attempts to cancel the processing of files in this batch as soon as possible.\n      parameters:\n        - in: path\n          name: vector_store_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the vector store that the file batch belongs to.\n        - in: path\n          name: batch_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the file batch to cancel.\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n          description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/vectorStoreFileBatchObject\"\n\n  /openai/vector_stores/{vector_store_id}/file_batches/{batch_id}/files:\n    get:\n      operationId: List_Vector_Store_File_Batch_Files\n      tags:\n        - Vector Stores\n      summary: Returns a list of vector store files in a batch.\n      parameters:\n        - name: vector_store_id\n          in: path\n          description: The ID of the vector store that the files belong to.\n          required: true\n          schema:\n            type: string\n        - name: batch_id\n          in: path\n          description: The ID of the file batch that the files belong to.\n          required: true\n          schema:\n            type: string\n        - name: limit\n          in: query\n          description: *pagination_limit_param_description\n          required: false\n          schema:\n            type: integer\n            default: 20\n        - name: order\n          in: query\n          description: *pagination_order_param_description\n          schema:\n            type: string\n            default: desc\n            enum: [\"asc\", \"desc\"]\n            x-ms-enum:\n              name: ListVectorStoreFilesOrder\n              modelAsString: true\n              values:\n                - value: asc\n                - value: desc\n        - name: after\n          in: query\n          description: *pagination_after_param_description\n          schema:\n            type: string\n        - name: before\n          in: query\n          description: *pagination_before_param_description\n          schema:\n            type: string\n        - name: filter\n          in: query\n          description: \"Filter by file status. One of `in_progress`, `completed`, `failed`, `cancelled`.\"\n          schema:\n            type: string\n            enum: [\"in_progress\", \"completed\", \"failed\", \"cancelled\"]\n            x-ms-enum:\n              name: ListVectorStoreFilesFilter\n              modelAsString: true\n              values:\n                - value: in_progress\n                - value: completed\n                - value: failed\n                - value: cancelled\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n          description: api version\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/listVectorStoreFilesResponse\"\n  /openai/realtimeapi/sessions:\n    post:\n      summary: >\n        Create an ephemeral API token for use in client-side applications with\n        the Realtime API. Can be configured with the same session parameters as the\n        `session.update` client event.\n\n        It responds with a session object, plus a `client_secret` key which\n        contains a usable ephemeral API token that can be used to authenticate browser\n        clients for the Realtime API.\n      operationId: create_realtimeSession\n      tags:\n        - Realtime\n      parameters:\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      requestBody:\n        description: Create an ephemeral API key with the given session configuration.\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/RealtimeSessionCreateRequest\"\n      responses:\n        \"200\":\n          description: Session created successfully.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/RealtimeSessionCreateResponse\"\n  /openai/realtimeapi/transcription_sessions:\n    post:\n      summary: >\n        Create an ephemeral API token for use in client-side applications with\n        the Realtime API specifically for realtime transcriptions. \n\n        Can be configured with the same session parameters as the\n        `transcription_session.update` client event.\n\n        It responds with a session object, plus a `client_secret` key which\n        contains a usable ephemeral API token that can be used to authenticate browser\n        clients for the Realtime API.\n      operationId: create_transcriptionRealtimeSession\n      tags:\n        - Realtime\n      parameters:\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      requestBody:\n        description: Create an ephemeral API key with the given session configuration.\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/RealtimeTranscriptionSessionCreateRequest\"\n      responses:\n        \"200\":\n          description: Session created successfully.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/RealtimeTranscriptionSessionCreateResponse\"\n  /openai/responses:\n    post:\n      summary: >\n        Creates a model response. Provide [text](/docs/guides/text) or\n\n        [image](/docs/guides/images) inputs to generate\n        [text](/docs/guides/text)\n\n        or [JSON](/docs/guides/structured-outputs) outputs. Have the model call\n\n        your own [custom code](/docs/guides/function-calling) or use built-in\n\n        [tools](/docs/guides/tools) like [web\n        search](/docs/guides/tools-web-search)\n\n        or [file search](/docs/guides/tools-file-search) to use your own data\n\n        as input for the model\'s response.\n      tags:\n        - Responses\n      parameters:\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/createResponse\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/response\"\n            text/event-stream:\n              schema:\n                $ref: \"#/components/schemas/responseStreamEvent\"\n        default:\n          description: Service unavailable\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/errorResponse\"\n          headers:\n            apim-request-id:\n              description: Request ID for troubleshooting purposes\n              schema:\n                type: string\n\n  /openai/responses/{response_id}:\n    get:\n      summary: |\n        Retrieves a model response with the given ID.\n      tags:\n        - Responses\n      parameters:\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n        - in: path\n          name: response_id\n          required: true\n          schema:\n            type: string\n            example: resp_677efb5139a88190b512bc3fef8e535d\n          description: The ID of the response to retrieve.\n        - in: query\n          name: include\n          schema:\n            type: array\n            items:\n              $ref: \"#/components/schemas/includable\"\n          description: |\n            Additional fields to include in the response. See the `include`\n            parameter for Response creation above for more information.\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/response\"\n        default:\n          description: Service unavailable\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/errorResponse\"\n          headers:\n            apim-request-id:\n              description: Request ID for troubleshooting purposes\n              schema:\n                type: string\n    delete:\n      operationId: deleteResponse\n      tags:\n        - Responses\n      summary: |\n        Deletes a model response with the given ID.\n      parameters:\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n        - in: path\n          name: response_id\n          required: true\n          schema:\n            type: string\n            example: resp_677efb5139a88190b512bc3fef8e535d\n          description: The ID of the response to delete.\n      responses:\n        \"200\":\n          description: OK\n        \"404\":\n          description: Not Found\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/error\"\n        default:\n          description: Service unavailable\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/errorResponse\"\n          headers:\n            apim-request-id:\n              description: Request ID for troubleshooting purposes\n              schema:\n                type: string\n  /openai/responses/{response_id}/input_items:\n    get:\n      summary: Returns a list of input items for a given response.\n      tags:\n        - Responses\n      parameters:\n        - in: query\n          name: api-version\n          required: true\n          schema:\n            type: string\n            example: 2025-04-01-preview\n            description: api version\n        - in: path\n          name: response_id\n          required: true\n          schema:\n            type: string\n          description: The ID of the response to retrieve input items for.\n        - name: limit\n          in: query\n          description: >\n            A limit on the number of objects to be returned. Limit can range\n            between\n\n            1 and 100, and the default is 20.\n          required: false\n          schema:\n            type: integer\n            default: 20\n        - in: query\n          name: order\n          schema:\n            type: string\n            enum:\n              - asc\n              - desc\n          description: |\n            The order to return the input items in. Default is `asc`.\n            - `asc`: Return the input items in ascending order.\n            - `desc`: Return the input items in descending order.\n        - in: query\n          name: after\n          schema:\n            type: string\n          description: |\n            An item ID to list items after, used in pagination.\n        - in: query\n          name: before\n          schema:\n            type: string\n          description: |\n            An item ID to list items before, used in pagination.\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/responseItemList\"\n\ncomponents:\n  schemas:\n    errorResponse:\n      type: object\n      properties:\n        error:\n          $ref: \"#/components/schemas/error\"\n    errorBase:\n      type: object\n      properties:\n        code:\n          type: string\n        message:\n          type: string\n    error:\n      type: object\n      allOf:\n        - $ref: \"#/components/schemas/errorBase\"\n      properties:\n        param:\n          type: string\n        type:\n          type: string\n        inner_error:\n          $ref: \"#/components/schemas/innerError\"\n    innerError:\n      description: Inner error with additional details.\n      type: object\n      properties:\n        code:\n          $ref: \"#/components/schemas/innerErrorCode\"\n        content_filter_results:\n          $ref: \"#/components/schemas/contentFilterPromptResults\"\n    innerErrorCode:\n      description: Error codes for the inner error object.\n      enum:\n        - ResponsibleAIPolicyViolation\n      type: string\n      x-ms-enum:\n        name: InnerErrorCode\n        modelAsString: true\n        values:\n          - value: ResponsibleAIPolicyViolation\n            description: The prompt violated one of more content filter rules.\n    contentFilterCompletionTextSpan:\n      description: Describes a span within generated completion text.  Offset 0 is the first UTF32 code point of the completion text.\n      type: object\n      properties:\n        completion_start_offset:\n          description: Offset of the UTF32 code point which begins the span.\n          type: integer\n        completion_end_offset:\n          description: Offset of the first UTF32 code point which is excluded from the span. This field is always equal to completion_start_offset for empty spans. This field is always larger than completion_start_offset for non-empty spans.\n          type: integer\n      required:\n        - completion_start_offset\n        - completion_end_offset\n    contentFilterResultBase:\n      type: object\n      properties:\n        filtered:\n          type: boolean\n      required:\n        - filtered\n    contentFilterSeverityResult:\n      type: object\n      allOf:\n        - $ref: \"#/components/schemas/contentFilterResultBase\"\n        - properties:\n            severity:\n              type: string\n              enum:\n                - safe\n                - low\n                - medium\n                - high\n              x-ms-enum:\n                name: ContentFilterSeverity\n                modelAsString: true\n                values:\n                  - value: safe\n                    description: General content or related content in generic or non-harmful contexts.\n                  - value: low\n                    description: Harmful content at a low intensity and risk level.\n                  - value: medium\n                    description: Harmful content at a medium intensity and risk level.\n                  - value: high\n                    description: Harmful content at a high intensity and risk level.\n      required:\n        - severity\n        - filtered\n    contentFilterDetectedResult:\n      type: object\n      allOf:\n        - $ref: \"#/components/schemas/contentFilterResultBase\"\n        - properties:\n            detected:\n              type: boolean\n      required:\n        - detected\n        - filtered\n    contentFilterDetectedWithCitationResult:\n      type: object\n      allOf:\n        - $ref: \"#/components/schemas/contentFilterDetectedResult\"\n        - properties:\n            citation:\n              type: object\n              properties:\n                URL:\n                  type: string\n                license:\n                  type: string\n      required:\n        - detected\n        - filtered\n    contentFilterDetectedWithCompletionTextSpansResult:\n      type: object\n      allOf:\n        - $ref: \"#/components/schemas/contentFilterDetectedResult\"\n        - properties:\n            details:\n              type: array\n              items:\n                $ref: \"#/components/schemas/contentFilterCompletionTextSpan\"\n      required:\n        - detected\n        - filtered\n        - details\n    contentFilterIdResult:\n      type: object\n      allOf:\n        - $ref: \"#/components/schemas/contentFilterResultBase\"\n        - properties:\n            id:\n              type: string\n      required:\n        - id\n        - filtered\n    contentFilterResultsBase:\n      type: object\n      description: Information about the content filtering results.\n      properties:\n        sexual:\n          $ref: \"#/components/schemas/contentFilterSeverityResult\"\n        violence:\n          $ref: \"#/components/schemas/contentFilterSeverityResult\"\n        hate:\n          $ref: \"#/components/schemas/contentFilterSeverityResult\"\n        self_harm:\n          $ref: \"#/components/schemas/contentFilterSeverityResult\"\n        profanity:\n          $ref: \"#/components/schemas/contentFilterDetectedResult\"\n        custom_blocklists:\n          $ref: \"#/components/schemas/contentFilterDetailedResults\"\n        error:\n          $ref: \"#/components/schemas/errorBase\"\n    contentFilterPromptResults:\n      type: object\n      description: Information about the content filtering category (hate, sexual, violence, self_harm), if it has been detected, as well as the severity level (very_low, low, medium, high-scale that determines the intensity and risk level of harmful content) and if it has been filtered or not. Information about jailbreak content and profanity, if it has been detected, and if it has been filtered or not. And information about customer block list, if it has been filtered and its id.\n      allOf:\n        - $ref: \"#/components/schemas/contentFilterResultsBase\"\n        - properties:\n            jailbreak:\n              $ref: \"#/components/schemas/contentFilterDetectedResult\"\n            indirect_attack:\n              $ref: \"#/components/schemas/contentFilterDetectedResult\"\n    contentFilterChoiceResults:\n      type: object\n      description: Information about the content filtering category (hate, sexual, violence, self_harm), if it has been detected, as well as the severity level (very_low, low, medium, high-scale that determines the intensity and risk level of harmful content) and if it has been filtered or not. Information about third party text and profanity, if it has been detected, and if it has been filtered or not. And information about customer block list, if it has been filtered and its id.\n      allOf:\n        - $ref: \"#/components/schemas/contentFilterResultsBase\"\n        - properties:\n            protected_material_text:\n              $ref: \"#/components/schemas/contentFilterDetectedResult\"\n        - properties:\n            protected_material_code:\n              $ref: \"#/components/schemas/contentFilterDetectedWithCitationResult\"\n        - properties:\n            ungrounded_material:\n              $ref: \"#/components/schemas/contentFilterDetectedWithCompletionTextSpansResult\"\n    contentFilterDetailedResults:\n      type: object\n      description: Content filtering results with a detail of content filter ids for the filtered segments.\n      allOf:\n        - $ref: \"#/components/schemas/contentFilterResultBase\"\n        - properties:\n            details:\n              items:\n                $ref: \"#/components/schemas/contentFilterIdResult\"\n              type: array\n      required:\n        - filtered\n        - details\n    dalleContentFilterResults:\n      type: object\n      description: Information about the content filtering results.\n      properties:\n        sexual:\n          $ref: \"#/components/schemas/contentFilterSeverityResult\"\n        violence:\n          $ref: \"#/components/schemas/contentFilterSeverityResult\"\n        hate:\n          $ref: \"#/components/schemas/contentFilterSeverityResult\"\n        self_harm:\n          $ref: \"#/components/schemas/contentFilterSeverityResult\"\n    dalleFilterResults:\n      type: object\n      description: Information about the content filtering category (hate, sexual, violence, self_harm), if it has been detected, as well as the severity level (very_low, low, medium, high-scale that determines the intensity and risk level of harmful content) and if it has been filtered or not. Information about jailbreak content and profanity, if it has been detected, and if it has been filtered or not. And information about customer block list, if it has been filtered and its id.\n      allOf:\n        - $ref: \"#/components/schemas/dalleContentFilterResults\"\n        - properties:\n            profanity:\n              $ref: \"#/components/schemas/contentFilterDetectedResult\"\n            jailbreak:\n              $ref: \"#/components/schemas/contentFilterDetectedResult\"\n            custom_blocklists:\n              $ref: \"#/components/schemas/contentFilterDetailedResults\"\n\n    chatCompletionFunctionParameters:\n      type: object\n      description: The parameters the functions accepts, described as a JSON Schema object. See the [guide/](https://learn.microsoft.com/en-us/azure/ai-services/openai/how-to/function-calling) for examples, and the [JSON Schema reference](https://json-schema.org/understanding-json-schema/) for documentation about the format.\n      additionalProperties: true\n\n    chatCompletionRequestMessage:\n      oneOf:\n        - $ref: \"#/components/schemas/ChatCompletionRequestDeveloperMessage\"\n        - $ref: \"#/components/schemas/chatCompletionRequestSystemMessage\"\n        - $ref: \"#/components/schemas/chatCompletionRequestUserMessage\"\n        - $ref: \"#/components/schemas/chatCompletionRequestAssistantMessage\"\n        - $ref: \"#/components/schemas/chatCompletionRequestToolMessage\"\n        - $ref: \"#/components/schemas/chatCompletionRequestFunctionMessage\"\n\n    ChatCompletionRequestDeveloperMessage:\n      type: object\n      title: Developer message\n      description: >\n        Developer-provided instructions that the model should follow, regardless\n        of\n\n        messages sent by the user. With o1 models and newer, `developer`\n        messages\n\n        replace the previous `system` messages.\n      properties:\n        content:\n          description: The contents of the developer message.\n          oneOf:\n            - type: string\n              description: The contents of the developer message.\n              title: Text content\n            - type: array\n              description: An array of content parts with a defined type. For developer\n                messages, only type `text` is supported.\n              title: Array of content parts\n              items:\n                $ref: \"#/components/schemas/chatCompletionRequestDeveloperMessageContentPart\"\n              minItems: 1\n        role:\n          type: string\n          enum:\n            - developer\n          description: The role of the messages author, in this case `developer`.\n        name:\n          type: string\n          description: An optional name for the participant. Provides the model\n            information to differentiate between participants of the same role.\n      required:\n        - content\n        - role\n\n    chatCompletionRequestSystemMessage:\n      type: object\n      title: System message\n      properties:\n        content:\n          description: The contents of the system message.\n          oneOf:\n            - type: string\n              description: The contents of the system message.\n              title: Text content\n            - type: array\n              description: An array of content parts with a defined type. For system messages, only type `text` is supported.\n              title: Array of content parts\n              items:\n                $ref: \"#/components/schemas/chatCompletionRequestSystemMessageContentPart\"\n              minItems: 1\n        role:\n          type: string\n          enum: [\"system\"]\n          description: The role of the messages author, in this case `system`.\n        name:\n          type: string\n          description: An optional name for the participant. Provides the model information to differentiate between participants of the same role.\n      required:\n        - content\n        - role\n\n    chatCompletionRequestUserMessage:\n      type: object\n      title: User message\n      properties:\n        content:\n          description: |\n            The contents of the user message.\n          oneOf:\n            - type: string\n              description: The text contents of the message.\n              title: Text content\n            - type: array\n              description: An array of content parts with a defined type, each can be of type `text` or `image_url` when passing in images. You can pass multiple images by adding multiple `image_url` content parts. Image input is only supported when using the `gpt-4o` model.\n              title: Array of content parts\n              items:\n                $ref: \"#/components/schemas/chatCompletionRequestUserMessageContentPart\"\n              minItems: 1\n          x-oaiExpandable: true\n        role:\n          type: string\n          enum: [\"user\"]\n          description: The role of the messages author, in this case `user`.\n        name:\n          type: string\n          description: An optional name for the participant. Provides the model information to differentiate between participants of the same role.\n      required:\n        - content\n        - role\n\n    chatCompletionRequestAssistantMessage:\n      type: object\n      title: Assistant message\n      properties:\n        content:\n          nullable: true\n          oneOf:\n            - type: string\n              description: The contents of the assistant message.\n              title: Text content\n            - type: array\n              description: An array of content parts with a defined type. Can be one or more of type `text`, or exactly one of type `refusal`.\n              title: Array of content parts\n              items:\n                $ref: \"#/components/schemas/chatCompletionRequestAssistantMessageContentPart\"\n              minItems: 1\n          description: |\n            The contents of the assistant message. Required unless `tool_calls` or `function_call` is specified.\n        refusal:\n          nullable: true\n          type: string\n          description: The refusal message by the assistant.\n        role:\n          type: string\n          enum: [\"assistant\"]\n          description: The role of the messages author, in this case `assistant`.\n        name:\n          type: string\n          description: An optional name for the participant. Provides the model information to differentiate between participants of the same role.\n        tool_calls:\n          $ref: \"#/components/schemas/chatCompletionMessageToolCalls\"\n        function_call:\n          type: object\n          deprecated: true\n          description: \"Deprecated and replaced by `tool_calls`. The name and arguments of a function that should be called, as generated by the model.\"\n          nullable: true\n          properties:\n            arguments:\n              type: string\n              description: The arguments to call the function with, as generated by the model in JSON format. Note that the model does not always generate valid JSON, and may hallucinate parameters not defined by your function schema. Validate the arguments in your code before calling your function.\n            name:\n              type: string\n              description: The name of the function to call.\n          required:\n            - arguments\n            - name\n      required:\n        - role\n\n    chatCompletionRequestToolMessage:\n      type: object\n      title: Tool message\n      properties:\n        role:\n          type: string\n          enum: [\"tool\"]\n          description: The role of the messages author, in this case `tool`.\n        content:\n          oneOf:\n            - type: string\n              description: The contents of the tool message.\n              title: Text content\n            - type: array\n              description: An array of content parts with a defined type. For tool messages, only type `text` is supported.\n              title: Array of content parts\n              items:\n                $ref: \"#/components/schemas/chatCompletionRequestToolMessageContentPart\"\n              minItems: 1\n          description: The contents of the tool message.\n        tool_call_id:\n          type: string\n          description: Tool call that this message is responding to.\n      required:\n        - role\n        - content\n        - tool_call_id\n\n    chatCompletionRequestFunctionMessage:\n      type: object\n      title: Function message\n      deprecated: true\n      properties:\n        role:\n          type: string\n          enum: [\"function\"]\n          description: The role of the messages author, in this case `function`.\n        content:\n          nullable: true\n          type: string\n          description: The contents of the function message.\n        name:\n          type: string\n          description: The name of the function to call.\n      required:\n        - role\n        - content\n        - name\n\n    chatCompletionRequestDeveloperMessageContentPart:\n      oneOf:\n        - $ref: \"#/components/schemas/chatCompletionRequestMessageContentPartText\"\n\n    chatCompletionRequestSystemMessageContentPart:\n      oneOf:\n        - $ref: \"#/components/schemas/chatCompletionRequestMessageContentPartText\"\n\n    chatCompletionRequestUserMessageContentPart:\n      oneOf:\n        - $ref: \"#/components/schemas/chatCompletionRequestMessageContentPartText\"\n        - $ref: \"#/components/schemas/chatCompletionRequestMessageContentPartImage\"\n        - $ref: \"#/components/schemas/chatCompletionRequestMessageContentPartAudio\"\n\n    chatCompletionRequestAssistantMessageContentPart:\n      oneOf:\n        - $ref: \"#/components/schemas/chatCompletionRequestMessageContentPartText\"\n        - $ref: \"#/components/schemas/chatCompletionRequestMessageContentPartRefusal\"\n\n    chatCompletionRequestToolMessageContentPart:\n      oneOf:\n        - $ref: \"#/components/schemas/chatCompletionRequestMessageContentPartText\"\n\n    chatCompletionRequestMessageContentPartText:\n      type: object\n      title: Text content part\n      properties:\n        type:\n          type: string\n          enum: [\"text\"]\n          description: The type of the content part.\n        text:\n          type: string\n          description: The text content.\n      required:\n        - type\n        - text\n\n    chatCompletionRequestMessageContentPartAudio:\n      type: object\n      title: Audio content part\n      description: |\n        Learn about [audio inputs](/docs/guides/audio).\n      properties:\n   