pe: string\n      description: Optional settings to control how fields are processed when using a configured Mongo DB resource.\n\n    pineconeChatExtensionConfiguration:\n      required:\n        - parameters\n      description: |-\n        A specific representation of configurable options for Pinecone when using it as an Azure OpenAI chat\n        extension.\n      allOf:\n        - $ref: \"#/components/schemas/azureChatExtensionConfiguration\"\n        - properties:\n            parameters:\n              $ref: \"#/components/schemas/pineconeChatExtensionParameters\"\n      x-ms-discriminator-value: pinecone\n    pineconeChatExtensionParameters:\n      required:\n        - authentication\n        - embedding_dependency\n        - environment\n        - fields_mapping\n        - index_name\n      type: object\n      properties:\n        authentication:\n          $ref: \"#/components/schemas/onYourDataApiKeyAuthenticationOptions\"\n        top_n_documents:\n          type: integer\n          description: The configured top number of documents to feature for the configured query.\n          format: int32\n        max_search_queries:\n          type: integer\n          description: The max number of rewritten queries should be send to search provider for one user message. If not specified, the system will decide the number of queries to send.\n          format: int32\n        allow_partial_result:\n          type: boolean\n          default: false\n          description: If specified as true, the system will allow partial search results to be used and the request fails if all the queries fail. If not specified, or specified as false, the request will fail if any search query fails.\n        in_scope:\n          type: boolean\n          description: Whether queries should be restricted to use of indexed data.\n        strictness:\n          maximum: 5\n          minimum: 1\n          type: integer\n          description: The configured strictness of the search relevance filtering. The higher of strictness, the higher of the precision but lower recall of the answer.\n          format: int32\n        environment:\n          type: string\n          description: The environment name of Pinecone.\n        index_name:\n          type: string\n          description: The name of the Pinecone database index.\n        fields_mapping:\n          $ref: \"#/components/schemas/pineconeFieldMappingOptions\"\n        embedding_dependency:\n          $ref: \"#/components/schemas/onYourDataDeploymentNameVectorizationSource\"\n        include_contexts:\n          type: array\n          description: The included properties of the output context. If not specified, the default value is `citations` and `intent`.\n          items:\n            $ref: \"#/components/schemas/onYourDataContextProperty\"\n      description: Parameters for configuring Azure OpenAI Pinecone chat extensions.\n    pineconeFieldMappingOptions:\n      required:\n        - content_fields\n      type: object\n      properties:\n        title_field:\n          type: string\n          description: The name of the index field to use as a title.\n        url_field:\n          type: string\n          description: The name of the index field to use as a URL.\n        filepath_field:\n          type: string\n          description: The name of the index field to use as a filepath.\n        content_fields:\n          type: array\n          description: The names of index fields that should be treated as content.\n          items:\n            type: string\n        content_fields_separator:\n          type: string\n          description: The separator pattern that content fields should use.\n      description: Optional settings to control how fields are processed when using a configured Pinecone resource.\n    onYourDataAuthenticationOptions:\n      required:\n        - type\n      type: object\n      properties:\n        type:\n          $ref: \"#/components/schemas/onYourDataAuthenticationType\"\n      description: The authentication options for Azure OpenAI On Your Data.\n      discriminator:\n        propertyName: type\n        mapping:\n          api_key: \"#/components/schemas/onYourDataApiKeyAuthenticationOptions\"\n          connection_string: \"#/components/schemas/onYourDataConnectionStringAuthenticationOptions\"\n          key_and_key_id: \"#/components/schemas/onYourDataKeyAndKeyIdAuthenticationOptions\"\n          encoded_api_key: \"#/components/schemas/onYourDataEncodedApiKeyAuthenticationOptions\"\n          access_token: \"#/components/schemas/onYourDataAccessTokenAuthenticationOptions\"\n          system_assigned_managed_identity: \"#/components/schemas/onYourDataSystemAssignedManagedIdentityAuthenticationOptions\"\n          user_assigned_managed_identity: \"#/components/schemas/onYourDataUserAssignedManagedIdentityAuthenticationOptions\"\n          username_and_password: \"#/components/schemas/onYourDataUsernameAndPasswordAuthenticationOptions\"\n    onYourDataContextProperty:\n      type: string\n      description: The context property.\n      enum:\n        - citations\n        - intent\n        - all_retrieved_documents\n      x-ms-enum:\n        name: OnYourDataContextProperty\n        modelAsString: true\n        values:\n          - name: citations\n            value: citations\n            description: The `citations` property.\n          - name: intent\n            value: intent\n            description: The `intent` property.\n          - name: allRetrievedDocuments\n            value: all_retrieved_documents\n            description: The `all_retrieved_documents` property.\n    onYourDataAuthenticationType:\n      type: string\n      description: The authentication types supported with Azure OpenAI On Your Data.\n      enum:\n        - api_key\n        - connection_string\n        - key_and_key_id\n        - encoded_api_key\n        - access_token\n        - system_assigned_managed_identity\n        - user_assigned_managed_identity\n        - username_and_password\n      x-ms-enum:\n        name: OnYourDataAuthenticationType\n        modelAsString: true\n        values:\n          - name: apiKey\n            value: api_key\n            description: Authentication via API key.\n          - name: connectionString\n            value: connection_string\n            description: Authentication via connection string.\n          - name: keyAndKeyId\n            value: key_and_key_id\n            description: Authentication via key and key ID pair.\n          - name: encodedApiKey\n            value: encoded_api_key\n            description: Authentication via encoded API key.\n          - name: accessToken\n            value: access_token\n            description: Authentication via access token.\n          - name: systemAssignedManagedIdentity\n            value: system_assigned_managed_identity\n            description: Authentication via system-assigned managed identity.\n          - name: userAssignedManagedIdentity\n            value: user_assigned_managed_identity\n            description: Authentication via user-assigned managed identity.\n          - name: usernameAndPassword\n            value: username_and_password\n            description: Authentication via username and password.\n    onYourDataApiKeyAuthenticationOptions:\n      required:\n        - key\n      description: The authentication options for Azure OpenAI On Your Data when using an API key.\n      allOf:\n        - $ref: \"#/components/schemas/onYourDataAuthenticationOptions\"\n        - properties:\n            key:\n              type: string\n              description: The API key to use for authentication.\n      x-ms-discriminator-value: api_key\n    onYourDataConnectionStringAuthenticationOptions:\n      required:\n        - connection_string\n      description: The authentication options for Azure OpenAI On Your Data when using a connection string.\n      allOf:\n        - $ref: \"#/components/schemas/onYourDataAuthenticationOptions\"\n        - properties:\n            connection_string:\n              type: string\n              description: The connection string to use for authentication.\n      x-ms-discriminator-value: connection_string\n    onYourDataKeyAndKeyIdAuthenticationOptions:\n      required:\n        - key\n        - key_id\n      description: The authentication options for Azure OpenAI On Your Data when using an Elasticsearch key and key ID pair.\n      allOf:\n        - $ref: \"#/components/schemas/onYourDataAuthenticationOptions\"\n        - properties:\n            key:\n              type: string\n              description: The Elasticsearch key to use for authentication.\n            key_id:\n              type: string\n              description: The Elasticsearch key ID to use for authentication.\n      x-ms-discriminator-value: key_and_key_id\n    onYourDataEncodedApiKeyAuthenticationOptions:\n      required:\n        - encoded_api_key\n      description: The authentication options for Azure OpenAI On Your Data when using an Elasticsearch encoded API key.\n      allOf:\n        - $ref: \"#/components/schemas/onYourDataAuthenticationOptions\"\n        - properties:\n            encoded_api_key:\n              type: string\n              description: The Elasticsearch encoded API key to use for authentication.\n      x-ms-discriminator-value: encoded_api_key\n    onYourDataAccessTokenAuthenticationOptions:\n      required:\n        - access_token\n      description: The authentication options for Azure OpenAI On Your Data when using access token.\n      allOf:\n        - $ref: \"#/components/schemas/onYourDataAuthenticationOptions\"\n        - properties:\n            access_token:\n              type: string\n              description: The access token to use for authentication.\n      x-ms-discriminator-value: access_token\n    onYourDataSystemAssignedManagedIdentityAuthenticationOptions:\n      description: The authentication options for Azure OpenAI On Your Data when using a system-assigned managed identity.\n      allOf:\n        - $ref: \"#/components/schemas/onYourDataAuthenticationOptions\"\n      x-ms-discriminator-value: system_assigned_managed_identity\n    onYourDataUserAssignedManagedIdentityAuthenticationOptions:\n      required:\n        - managed_identity_resource_id\n      description: The authentication options for Azure OpenAI On Your Data when using a user-assigned managed identity.\n      allOf:\n        - $ref: \"#/components/schemas/onYourDataAuthenticationOptions\"\n        - properties:\n            managed_identity_resource_id:\n              type: string\n              description: The resource ID of the user-assigned managed identity to use for authentication.\n      x-ms-discriminator-value: user_assigned_managed_identity\n    onYourDataUsernameAndPasswordAuthenticationOptions:\n      required:\n        - username\n        - password\n      description: The authentication options for Azure OpenAI On Your Data when using a username and a password.\n      allOf:\n        - $ref: \"#/components/schemas/onYourDataAuthenticationOptions\"\n        - properties:\n            username:\n              type: string\n              description: The username to use for authentication.\n            password:\n              type: string\n              description: The password. to use for authentication.\n      x-ms-discriminator-value: username_and_password\n    onYourDataVectorizationSource:\n      required:\n        - type\n      type: object\n      properties:\n        type:\n          $ref: \"#/components/schemas/onYourDataVectorizationSourceType\"\n      description: An abstract representation of a vectorization source for Azure OpenAI On Your Data with vector search.\n      discriminator:\n        propertyName: type\n        mapping:\n          endpoint: \"#/components/schemas/onYourDataEndpointVectorizationSource\"\n          deployment_name: \"#/components/schemas/onYourDataDeploymentNameVectorizationSource\"\n          integrated: \"#/components/schemas/onYourDataIntegratedVectorizationSource\"\n          model_id: \"#/components/schemas/onYourDataModelIdVectorizationSource\"\n    onYourDataVectorizationSourceType:\n      type: string\n      description: |-\n        Represents the available sources Azure OpenAI On Your Data can use to configure vectorization of data for use with\n        vector search.\n      enum:\n        - endpoint\n        - deployment_name\n        - integrated\n        - model_id\n      x-ms-enum:\n        name: OnYourDataVectorizationSourceType\n        modelAsString: true\n        values:\n          - name: endpoint\n            value: endpoint\n            description: Represents vectorization performed by public service calls to an Azure OpenAI embedding model.\n          - name: deploymentName\n            value: deployment_name\n            description: |-\n              Represents an Ada model deployment name to use. This model deployment must be in the same Azure OpenAI resource, but\n              On Your Data will use this model deployment via an internal call rather than a public one, which enables vector\n              search even in private networks.\n          - name: integrated\n            value: integrated\n            description: Represents the integrated vectorizer defined within the search resource.\n          - name: modelId\n            value: model_id\n            description: |-\n              Represents a specific embedding model ID as defined in the search service.\n              Currently only supported by ElasticsearchÂ®.\n    onYourDataEndpointVectorizationSource:\n      required:\n        - authentication\n        - endpoint\n      description: |-\n        The details of a a vectorization source, used by Azure OpenAI On Your Data when applying vector search, that is based\n        on a public Azure OpenAI endpoint call for embeddings.\n      allOf:\n        - $ref: \"#/components/schemas/onYourDataVectorizationSource\"\n        - properties:\n            endpoint:\n              type: string\n              description: Specifies the resource endpoint URL from which embeddings should be retrieved. It should be in the format of https://YOUR_RESOURCE_NAME.openai.azure.com/openai/deployments/YOUR_DEPLOYMENT_NAME/embeddings. The api-version query parameter is not allowed.\n              format: uri\n            authentication:\n              oneOf:\n                - $ref: \"#/components/schemas/onYourDataApiKeyAuthenticationOptions\"\n                - $ref: \"#/components/schemas/onYourDataAccessTokenAuthenticationOptions\"\n            dimensions:\n              type: integer\n              description: The number of dimensions the embeddings should have. Only supported in `text-embedding-3` and later models.\n              format: int32\n      x-ms-discriminator-value: endpoint\n    onYourDataDeploymentNameVectorizationSource:\n      required:\n        - deployment_name\n      description: |-\n        The details of a a vectorization source, used by Azure OpenAI On Your Data when applying vector search, that is based\n        on an internal embeddings model deployment name in the same Azure OpenAI resource.\n      allOf:\n        - $ref: \"#/components/schemas/onYourDataVectorizationSource\"\n        - properties:\n            deployment_name:\n              type: string\n              description: Specifies the name of the model deployment to use for vectorization. This model deployment must be in the same Azure OpenAI resource, but On Your Data will use this model deployment via an internal call rather than a public one, which enables vector search even in private networks.\n            dimensions:\n              type: integer\n              description: The number of dimensions the embeddings should have. Only supported in `text-embedding-3` and later models.\n              format: int32\n      x-ms-discriminator-value: deployment_name\n    onYourDataIntegratedVectorizationSource:\n      description: |-\n        Represents the integrated vectorizer defined within the search resource.\n      allOf:\n        - $ref: \"#/components/schemas/onYourDataVectorizationSource\"\n      x-ms-discriminator-value: integrated\n    onYourDataModelIdVectorizationSource:\n      required:\n        - model_id\n      description: |-\n        The details of a a vectorization source, used by Azure OpenAI On Your Data when applying vector search, that is based\n        on a search service model ID. Currently only supported by ElasticsearchÂ®.\n      allOf:\n        - $ref: \"#/components/schemas/onYourDataVectorizationSource\"\n        - properties:\n            model_id:\n              type: string\n              description: Specifies the model ID to use for vectorization. This model ID must be defined in the search service.\n      x-ms-discriminator-value: model_id\n    citation:\n      required:\n        - content\n      type: object\n      properties:\n        content:\n          type: string\n          description: The content of the citation.\n        title:\n          type: string\n          description: The title of the citation.\n        url:\n          type: string\n          description: The URL of the citation.\n        filepath:\n          type: string\n          description: The file path of the citation.\n        chunk_id:\n          type: string\n          description: The chunk ID of the citation.\n        rerank_score:\n          type: number\n          description: The rerank score of the retrieved document.\n          format: double\n      description: citation information for a chat completions response message.\n    retrievedDocument:\n      type: object\n      description: The retrieved document.\n      required:\n        - search_queries\n        - data_source_index\n      allOf:\n        - $ref: \"#/components/schemas/citation\"\n        - properties:\n            search_queries:\n              type: array\n              description: The search queries used to retrieve the document.\n              items:\n                type: string\n            data_source_index:\n              type: integer\n              description: The index of the data source.\n              format: int32\n            original_search_score:\n              type: number\n              description: The original search score of the retrieved document.\n              format: double\n            filter_reason:\n              $ref: \"#/components/schemas/filterReason\"\n              description: Represents the rationale for filtering the document. If the document does not undergo filtering, this field will remain unset.\n\n    filterReason:\n      type: string\n      description: The filtering reason of the retrieved document.\n      enum:\n        - score\n        - rerank\n      x-ms-enum:\n        name: FilterReason\n        modelAsString: true\n        values:\n          - name: score\n            value: score\n            description: The document is filtered by original search score threshold defined by `strictness` configure.\n          - name: rerank\n            value: rerank\n            description: The document is not filtered by original search score threshold, but is filtered by rerank score and `top_n_documents` configure.\n\n    chatCompletionMessageToolCall:\n      type: object\n      properties:\n        id:\n          type: string\n          description: The ID of the tool call.\n        type:\n          $ref: \"#/components/schemas/toolCallType\"\n        function:\n          type: object\n          description: The function that the model called.\n          properties:\n            name:\n              type: string\n              description: The name of the function to call.\n            arguments:\n              type: string\n              description: The arguments to call the function with, as generated by the model in JSON format. Note that the model does not always generate valid JSON, and may hallucinate parameters not defined by your function schema. Validate the arguments in your code before calling your function.\n          required:\n            - name\n            - arguments\n      required:\n        - id\n        - type\n        - function\n    toolCallType:\n      type: string\n      enum:\n        - function\n      description: The type of the tool call, in this case `function`.\n      x-ms-enum:\n        name: ToolCallType\n        modelAsString: true\n        values:\n          - value: function\n            description: The tool call type is function.\n    chatCompletionRequestMessageTool:\n      allOf:\n        - $ref: \"#/components/schemas/chatCompletionRequestMessage\"\n        - type: object\n          nullable: true\n          properties:\n            tool_call_id:\n              type: string\n              description: Tool call that this message is responding to.\n            content:\n              type: string\n              description: The contents of the message.\n              nullable: true\n      required:\n        - tool_call_id\n        - content\n    chatCompletionRequestMessageFunction:\n      allOf:\n        - $ref: \"#/components/schemas/chatCompletionRequestMessage\"\n        - type: object\n          description: Deprecated. Message that represents a function.\n          nullable: true\n          properties:\n            role:\n              type: string\n              enum:\n                - function\n              description: The role of the messages author, in this case `function`.\n            name:\n              type: string\n              description: The contents of the message.\n            content:\n              type: string\n              description: The contents of the message.\n              nullable: true\n      required:\n        - function_call_id\n        - content\n\n    ParallelToolCalls:\n      description: Whether to enable parallel function calling during tool use.\n      type: boolean\n      default: true\n\n    chatCompletionMessageToolCalls:\n      type: array\n      description: The tool calls generated by the model, such as function calls.\n      items:\n        $ref: \"#/components/schemas/chatCompletionMessageToolCall\"\n\n    ResponseFormatText:\n      type: object\n      properties:\n        type:\n          type: string\n          description: \"The type of response format being defined: `text`\"\n          enum:\n            - text\n      required:\n        - type\n\n    ResponseFormatJsonObject:\n      type: object\n      properties:\n        type:\n          type: string\n          description: \"The type of response format being defined: `json_object`\"\n          enum:\n            - json_object\n      required:\n        - type\n\n    ResponseFormatJsonSchemaSchema:\n      type: object\n      description: \"The schema for the response format, described as a JSON Schema object.\"\n      additionalProperties: true\n\n    ResponseFormatJsonSchema:\n      type: object\n      properties:\n        type:\n          type: string\n          description: \"The type of response format being defined: `json_schema`\"\n          enum:\n            - json_schema\n        json_schema:\n          type: object\n          properties:\n            description:\n              type: string\n              description: A description of what the response format is for, used by the model to determine how to respond in the format.\n            name:\n              type: string\n              description: The name of the response format. Must be a-z, A-Z, 0-9, or contain underscores and dashes, with a maximum length of 64.\n            schema:\n              $ref: \"#/components/schemas/ResponseFormatJsonSchemaSchema\"\n            strict:\n              type: boolean\n              nullable: true\n              default: false\n              description: Whether to enable strict schema adherence when generating the output. If set to true, the model will always follow the exact schema defined in the `schema` field. Only a subset of JSON Schema is supported when `strict` is `true`.\n          required:\n            - schema\n            - name\n      required:\n        - type\n        - json_schema\n\n    runCompletionUsage:\n      type: object\n      description: Usage statistics related to the run. This value will be `null` if the run is not in a terminal state (i.e. `in_progress`, `queued`, etc.).\n      properties:\n        completion_tokens:\n          type: integer\n          description: Number of completion tokens used over the course of the run.\n        prompt_tokens:\n          type: integer\n          description: Number of prompt tokens used over the course of the run.\n        total_tokens:\n          type: integer\n          description: Total number of tokens used (prompt + completion).\n      required:\n        - prompt_tokens\n        - completion_tokens\n        - total_tokens\n      nullable: true\n\n    assistantsApiResponseFormatOption:\n      description: |\n        Specifies the format that the model must output. Compatible with\n        GPT-4o, GPT-4 Turbo, \n        and all GPT-3.5 Turbo models since `gpt-3.5-turbo-1106`.\n\n        Setting to `{ \"type\": \"json_schema\", \"json_schema\": {...} }`\n        enables Structured Outputs which ensures the model \n        will match your supplied JSON schema. \n        Learn more in the [Structured Outputs guide](/docs/guides/structured-outputs).\n\n        Setting to `{ \"type\": \"json_object\" }` enables \n        JSON mode, which ensures the message the model generates is valid JSON.\n\n        **Important:** when using JSON mode, \n        you **must** also instruct the model to produce JSON yourself \n        via a system or user message. Without this, the model may \n        generate an unending stream of whitespace until the generation \n        reaches the token limit, resulting in a long-running and \n        seemingly \"stuck\" request. Also note that the message content \n        may be partially cut off if `finish_reason=\"length\"`, which indicates \n        the generation exceeded `max_tokens` or the conversation exceeded \n        the max context length.\n      oneOf:\n        - type: string\n          description: >\n            `auto` is the default value\n          enum:\n            - auto\n          x-ms-enum:\n            name: AssistantsApiResponseFormatOption\n            modelAsString: true\n            values:\n              - value: auto\n        - $ref: \"#/components/schemas/ResponseFormatText\"\n        - $ref: \"#/components/schemas/ResponseFormatJsonObject\"\n        - $ref: \"#/components/schemas/ResponseFormatJsonSchema\"\n\n    assistantObject:\n      type: object\n      title: Assistant\n      description: Represents an `assistant` that can call the model and use tools.\n      properties:\n        id:\n          description: The identifier, which can be referenced in API endpoints.\n          type: string\n        object:\n          description: The object type, which is always `assistant`.\n          type: string\n          enum:\n            - assistant\n          x-ms-enum:\n            name: AssistantObjectType\n            modelAsString: true\n            values:\n              - value: assistant\n        created_at:\n          type: integer\n          description: The Unix timestamp (in seconds) for when the assistant was created.\n        name:\n          description: &assistant_name_param_description |\n            The name of the assistant. The maximum length is 256 characters.\n          type: string\n          maxLength: 256\n          nullable: true\n        description:\n          description: &assistant_description_param_description |\n            The description of the assistant. The maximum length is 512 characters.\n          type: string\n          maxLength: 512\n          nullable: true\n        model:\n          description: |\n            ID of the model to use. You can use the [List models](/docs/api-reference/models/list) API to see all of your available models, or see our [Model overview](/docs/models/overview) for descriptions of them.\n          type: string\n        instructions:\n          description: &assistant_instructions_param_description |\n            The system instructions that the assistant uses. The maximum length is 256,000 characters.\n          type: string\n          maxLength: 256000\n          nullable: true\n        tools:\n          description: &assistant_tools_param_description |\n            A list of tool enabled on the assistant. There can be a maximum of 128 tools per assistant. Tools can be of types `code_interpreter`, `file_search`, or `function`.\n          default: []\n          type: array\n          maxItems: 128\n          items:\n            oneOf:\n              - $ref: \"#/components/schemas/assistantToolsCode\"\n              - $ref: \"#/components/schemas/assistantToolsFileSearch\"\n              - $ref: \"#/components/schemas/assistantToolsFunction\"\n        tool_resources:\n          type: object\n          description: |\n            A set of resources that are used by the assistant\'s tools. The resources are specific to the type of tool. For example, the `code_interpreter` tool requires a list of file IDs, while the `file_search` tool requires a list of vector store IDs.\n          properties:\n            code_interpreter:\n              type: object\n              properties:\n                file_ids:\n                  type: array\n                  description: |\n                    A list of file IDs made available to the `code_interpreter`` tool. There can be a maximum of 20 files associated with the tool.\n                  default: []\n                  maxItems: 20\n                  items:\n                    type: string\n            file_search:\n              type: object\n              properties:\n                vector_store_ids:\n                  type: array\n                  description: |\n                    The ID of the vector store attached to this assistant. There can be a maximum of 1 vector store attached to the assistant.\n                  maxItems: 1\n                  items:\n                    type: string\n        metadata:\n          description: &metadata_description |\n            Set of 16 key-value pairs that can be attached to an object. This can be useful for storing additional information about the object in a structured format. Keys can be a maximum of 64 characters long and values can be a maximum of 512 characters long.\n          type: object\n          nullable: true\n        temperature:\n          description: &run_temperature_description |\n            What sampling temperature to use, between 0 and 2. Higher values like 0.8 will make the output more random, while lower values like 0.2 will make it more focused and deterministic.\n          type: number\n          minimum: 0\n          maximum: 2\n          default: 1\n          example: 1\n          nullable: true\n        top_p:\n          type: number\n          minimum: 0\n          maximum: 1\n          default: 1\n          example: 1\n          nullable: true\n          description: &run_top_p_description |\n            An alternative to sampling with temperature, called nucleus sampling, where the model considers the results of the tokens with top_p probability mass. So 0.1 means only the tokens comprising the top 10% probability mass are considered.\n\n            We generally recommend altering this or temperature but not both.\n        response_format:\n          $ref: \"#/components/schemas/assistantsApiResponseFormatOption\"\n          nullable: true\n      required:\n        - id\n        - object\n        - created_at\n        - name\n        - description\n        - model\n        - instructions\n        - tools\n        - metadata\n\n    createAssistantRequest:\n      type: object\n      additionalProperties: false\n      properties:\n        model:\n          description: |\n            ID of the model to use. You can use the [List models](/docs/api-reference/models/list) API to see all of your available models, or see our [Model overview](/docs/models/overview) for descriptions of them.\n          anyOf:\n            - type: string\n        name:\n          description: *assistant_name_param_description\n          type: string\n          nullable: true\n          maxLength: 256\n        description:\n          description: *assistant_description_param_description\n          type: string\n          nullable: true\n          maxLength: 512\n        instructions:\n          description: *assistant_instructions_param_description\n          type: string\n          nullable: true\n          maxLength: 256000\n        tools:\n          description: *assistant_tools_param_description\n          default: []\n          type: array\n          maxItems: 128\n          items:\n            oneOf:\n              - $ref: \"#/components/schemas/assistantToolsCode\"\n              - $ref: \"#/components/schemas/assistantToolsFileSearch\"\n              - $ref: \"#/components/schemas/assistantToolsFunction\"\n        tool_resources:\n          type: object\n          description: |\n            A set of resources that are used by the assistant\'s tools. The resources are specific to the type of tool. For example, the `code_interpreter` tool requires a list of file IDs, while the `file_search` tool requires a list of vector store IDs.\n          properties:\n            code_interpreter:\n              type: object\n              properties:\n                file_ids:\n                  type: array\n                  description: |\n                    A list of file IDs made available to the `code_interpreter` tool. There can be a maximum of 20 files associated with the tool.\n                  default: []\n                  maxItems: 20\n                  items:\n                    type: string\n            file_search:\n              type: object\n              properties:\n                vector_store_ids:\n                  type: array\n                  description: |\n                    The vector store attached to this assistant. There can be a maximum of 1 vector store attached to the assistant.\n                  maxItems: 1\n                  items:\n                    type: string\n                vector_stores:\n                  type: array\n                  description: |\n                    A helper to create a vector store with file_ids and attach it to this assistant. There can be a maximum of 1 vector store attached to the assistant.\n                  maxItems: 1\n                  items:\n                    type: object\n                    properties:\n                      file_ids:\n                        type: array\n                        description: |\n                          A list of file IDs to add to the vector store. There can be a maximum of 10000 files in a vector store.\n                        maxItems: 10000\n                        items:\n                          type: string\n                      chunking_strategy:\n                        # Ideally we\'d reuse the chunking strategy schema here, but it doesn\'t expand properly\n                        type: object\n                        description: The chunking strategy used to chunk the file(s). If not set, will use the `auto` strategy.\n                        oneOf:\n                          - type: object\n                            title: Auto Chunking Strategy\n                            description: The default strategy. This strategy currently uses a `max_chunk_size_tokens` of `800` and `chunk_overlap_tokens` of `400`.\n                            additionalProperties: false\n                            properties:\n                              type:\n                                type: string\n                                description: Always `auto`.\n                                enum: [\"auto\"]\n                                x-ms-enum:\n                                  name: AutoChunkingStrategyType\n                                  modelAsString: true\n                                  values:\n                                    - value: auto\n                            required:\n                              - type\n                          - type: object\n                            title: Static Chunking Strategy\n                            additionalProperties: false\n                            properties:\n                              type:\n                                type: string\n                                description: Always `static`.\n                                enum: [\"static\"]\n                                x-ms-enum:\n                                  name: StaticChunkingStrategyType\n                                  modelAsString: true\n                                  values:\n                                    - value: static\n                              static:\n                                type: object\n                                additionalProperties: false\n                                properties:\n                                  max_chunk_size_tokens:\n                                    type: integer\n                                    minimum: 100\n                                    maximum: 4096\n                                    description: The maximum number of tokens in each chunk. The default value is `800`. The minimum value is `100` and the maximum value is `4096`.\n                                  chunk_overlap_tokens:\n                                    type: integer\n                                    description: |\n                                      The number of tokens that overlap between chunks. The default value is `400`.\n\n                                      Note that the overlap must not exceed half of `max_chunk_size_tokens`.\n                                required:\n                                  - max_chunk_size_tokens\n                                  - chunk_overlap_tokens\n                            required:\n                              - type\n                              - static\n                      metadata:\n                        type: object\n                        description: |\n                          Set of 16 key-value pairs that can be attached to a vector store. This can be useful for storing additional information about the vector store in a structured format. Keys can be a maximum of 64 characters long and values can be a maximum of 512 characters long.\n              oneOf:\n                - required: [vector_store_ids]\n                - required: [vector_stores]\n          nullable: true\n        metadata:\n          description: *metadata_description\n          type: object\n          nullable: true\n        temperature:\n          description: *run_temperature_description\n          type: number\n          minimum: 0\n          maximum: 2\n          default: 1\n          example: 1\n          nullable: true\n        top_p:\n          type: number\n          minimum: 0\n          maximum: 1\n          default: 1\n          example: 1\n          nullable: true\n          description: *run_top_p_description\n        response_format:\n          $ref: \"#/components/schemas/assistantsApiResponseFormatOption\"\n          nullable: true\n      required:\n        - model\n\n    modifyAssistantRequest:\n      type: object\n      additionalProperties: false\n      properties:\n        model:\n          description: |\n            ID of the model to use. You can use the [List models](/docs/api-reference/models/list) API to see all of your available models, or see our [Model overview](/docs/models/overview) for descriptions of them.\n          anyOf:\n            - type: string\n        name:\n          description: |\n            The name of the assistant. The maximum length is 256 characters.\n          type: string\n          nullable: true\n          maxLength: 256\n        description:\n          description: |\n            The description of the assistant. The maximum length is 512 characters.\n          type: string\n          nullable: true\n          maxLength: 512\n        instructions:\n          description: |\n            The system instructions that the assistant uses. The maximum length is 32768 characters.\n          type: string\n          nullable: true\n          maxLength: 32768\n        tools:\n          description: |\n            A list of tool enabled on the assistant. There can be a maximum of 128 tools per assistant. Tools can be of types `code_interpreter`, `retrieval`, or `function`.\n          default: []\n          type: array\n          maxItems: 128\n          items:\n            oneOf:\n              - $ref: \"#/components/schemas/assistantToolsCode\"\n              - $ref: \"#/components/schemas/assistantToolsFileSearch\"\n              - $ref: \"#/components/schemas/assistantToolsFunction\"\n        tool_resources:\n          type: object\n          description: |\n            A set of resources that are used by the assistant\'s tools. The resources are specific to the type of tool. For example, the `code_interpreter` tool requires a list of file IDs, while the `file_search` tool requires a list of vector store IDs.\n          properties:\n            code_interpreter:\n              type: object\n              properties:\n                file_ids:\n                  type: array\n                  description: |\n                    Overrides the list of file IDs made available to the `code_interpreter` tool. There can be a maximum of 20 files associated with the tool.\n                  default: []\n                  maxItems: 20\n                  items:\n                    type: string\n            file_search:\n              type: object\n              properties:\n                vector_store_ids:\n                  type: array\n                  description: |\n                    Overrides the vector store attached to this assistant. There can be a maximum of 1 vector store attached to the assistant.\n                  maxItems: 1\n                  items:\n                    type: string\n        metadata:\n          description: *metadata_description\n          type: object\n          nullable: true\n        temperature:\n          description: *run_temperature_description\n          type: number\n          minimum: 0\n          maximum: 2\n          default: 1\n          example: 1\n          nullable: true\n        top_p:\n          type: number\n          minimum: 0\n          maximum: 1\n          default: 1\n          example: 1\n          nullable: true\n          description: *run_top_p_description\n        response_format:\n          $ref: \"#/components/schemas/assistantsApiResponseFormatOption\"\n          nullable: true\n\n    deleteAssistantResponse:\n      type: object\n      properties:\n        id:\n          type: string\n        deleted:\n          type: boolean\n        object:\n          type: string\n          enum:\n            - assistant.deleted\n          x-ms-enum:\n            name: DeleteAssistantResponseState\n            modelAsString: true\n            values:\n              - value: assistant.deleted\n      required:\n        - id\n        - object\n        - deleted\n\n    listAssistantsResponse:\n      type: object\n      properties:\n        object:\n          type: string\n          example: list\n        data:\n          type: array\n          items:\n            $ref: \"#/components/schemas/assistantObject\"\n        first_id:\n          type: string\n          example: asst_hLBK7PXBv5Lr2NQT7KLY0ag1\n        last_id:\n          type: string\n          example: asst_QLoItBbqwyAJEzlTy4y9kOMM\n        has_more:\n          type: boolean\n          example: false\n      required:\n        - object\n        - data\n        - first_id\n        - last_id\n        - has_more\n\n    assistantToolsCode:\n      type: object\n      title: Code interpreter tool\n      properties:\n        type:\n          type: string\n          description: \"The type of tool being defined: `code_interpreter`\"\n          enum:\n            - code_interpreter\n          x-ms-enum:\n            name: assistantToolsCodeType\n            modelAsString: true\n            values:\n              - value: code_interpreter\n      required:\n        - type\n\n    assistantToolsFileSearch:\n      type: object\n      title: FileSearch tool\n      properties:\n        type:\n          type: string\n          description: \"The type of tool being defined: `file_search`\"\n          enum:\n            - file_search\n          x-ms-enum:\n            name: assistantToolsFileSearchType\n            modelAsString: true\n            values:\n              - value: file_search\n        file_search:\n          type: object\n          description: Overrides for the file search tool.\n          properties:\n            max_num_results:\n              type: integer\n              minimum: 1\n              maximum: 50\n              description: |\n                The maximum number of results the file search tool should output. The\n                default is 20 for gpt-4* models and 5 for gpt-3.5-turbo. This number\n                should be between 1 and 50 inclusive.\n\n\n                Note that the file search tool may output fewer than `max_num_results`\n                results.\n    assistantToolsFileSearchTypeOnly:\n      type: object\n      title: FileSearch tool\n      properties:\n        type:\n          type: string\n          description: \"The type of tool being defined: `file_search`\"\n          enum:\n            - file_search\n          x-ms-enum:\n            name: assistantToolsFileSearchType\n            modelAsString: true\n            values:\n              - value: file_search\n      required:\n        - type\n\n    assistantToolsFunction:\n      type: object\n      title: Function tool\n      properties:\n        type:\n          type: string\n          description: \"The type of tool being defined: `function`\"\n          enum:\n            - function\n          x-ms-enum:\n            name: assistantToolsFunction\n            modelAsString: true\n            values:\n              - value: function\n        function:\n          type: object\n          description: The function definition.\n          properties:\n            description:\n              type: string\n              description: A description of what the function does, used by the model to choose when and how to call the function.\n            name:\n              type: string\n              description: The name of the function to be called. Must be a-z, A-Z, 0-9, or contain underscores and dashes, with a maximum length of 64.\n            parameters:\n              $ref: \"#/components/schemas/chatCompletionFunctionParameters\"\n          required:\n            - name\n            - parameters\n            - description\n      required:\n        - type\n        - function\n\n    truncationObject:\n      type: object\n      title: Thread Truncation Controls\n      description: Controls for how a thread will be truncated prior to the run. Use this to control the intial context window of the run.\n      properties:\n        type:\n          type: string\n          description: The truncation strategy to use for the thread. The default is `auto`. If set to `last_messages`, the thread will be truncated to the n most recent messages in the thread. When set to `auto`, messages in the middle of the thread will be dropped to fit the context length of the model, `max_prompt_tokens`.\n          enum: [\"auto\", \"last_messages\"]\n          x-ms-enum:\n            name: TruncationType\n            modelAsString: true\n            values:\n              - value: auto\n              - value: last_messages\n        last_messages:\n          type: integer\n          description: The number of most recent messages from the thread when constructing the context for the run.\n          minimum: 1\n          nullable: true\n      required:\n        - type\n\n    assistantsApiToolChoiceOption:\n      description: |\n        Controls which (if any) tool is called by the model.\n        `none` means the model will not call any tools and instead generates a message.\n        `auto` is the default value and means the model can pick between generating a message or calling a tool.\n        Specifying a particular tool like `{\"type\": \"file_search\"}` or `{\"type\": \"function\", \"function\": {\"name\": \"my_function\"}}` forces the model to call that tool.\n      oneOf:\n        - type: string\n          description: >\n            `none` means the model will not call a function and instead generates a message.\n            `auto` means the model can pick between generating a message or calling a function.\n          enum: [none, auto]\n          x-ms-enum:\n            name: AssistantsApiToolChoiceOption\n            modelAsString: true\n            values:\n              - value: none\n              - value: auto\n        - $ref: \"#/components/schemas/assistantsNamedToolChoice\"\n\n    assistantsNamedToolChoice:\n      type: object\n      description: Specifies a tool the model should use. Use to force the model to call a specific tool.\n      properties:\n        type:\n          type: string\n          enum: [\"function\", \"code_interpreter\", \"file_search\"]\n          description: The type of the tool. If type is `function`, the function name must be set\n          x-ms-enum:\n            name: AssistantsNamedToolChoiceType\n            modelAsString: true\n            values:\n              - value: function\n              - value: code_interpreter\n              - value: file_search\n        function:\n          type: object\n          properties:\n            name:\n              type: string\n              description: The name of the function to call.\n          required:\n            - name\n      required:\n        - type\n\n    runObject:\n      type: object\n      title: A run on a thread\n      description: Represents an execution run on a [thread](/docs/api-reference/threads).\n      properties:\n        id:\n          description: The identifier, which can be referenced in API endpoints.\n          type: string\n        object:\n          description: The object type, which is always `thread.run`.\n          type: string\n          enum:\n            - thread.run\n          x-ms-enum:\n            name: runObjectType\n            modelAsString: true\n            values:\n              - value: thread.run\n                description: The run object type which is always thread.run\n        created_at:\n          description: The Unix timestamp (in seconds) for when the run was created.\n          type: integer\n        thread_id:\n          description: The ID of the [thread](/docs/api-reference/threads) that was executed on as a part of this run.\n          type: string\n        assistant_id:\n          description: The ID of the assistant used for execution of this run.\n          type: string\n        status:\n          description: The status of the run, which can be either `queued`, `in_progress`, `requires_action`, `cancelling`, `cancelled`, `failed`, `completed`, or `expired`.\n          type: string\n          enum:\n            - queued\n            - in_progress\n            - requires_action\n            - cancelling\n            - cancelled\n            - failed\n            - completed\n            - expired\n          x-ms-enum:\n            name: RunObjectStatus\n            modelAsString: true\n            values:\n              - value: queued\n                description: The queued state\n              - value: in_progress\n                description: The in_progress state\n              - value: requires_action\n                description: The required_action state\n              - value: cancelling\n                description: The cancelling state\n              - value: cancelled\n                description: The cancelled state\n              - value: failed\n                description: The failed state\n              - value: completed\n                description: The completed state\n              - value: expired\n                description: The expired state\n        required_action:\n          type: object\n          description: Details on the action required to continue the run. Will be `null` if no action is required.\n          nullable: true\n          properties:\n            type:\n              description: For now, this is always `submit_tool_outputs`.\n              type: string\n              enum:\n                - submit_tool_outputs\n            submit_tool_outputs:\n              type: object\n              description: Details on the tool outputs needed for this run to continue.\n              properties:\n                tool_calls:\n                  type: array\n                  description: A list of the relevant tool calls.\n                  items:\n                    $ref: \"#/components/schemas/runToolCallObject\"\n              required:\n                - tool_calls\n          required:\n            - type\n            - submit_tool_outputs\n        last_error:\n          type: object\n          description: The last error associated with this run. Will be `null` if there are no errors.\n          nullable: true\n          properties:\n            code:\n              type: string\n              description: One of `server_error` or `rate_limit_exceeded`.\n              enum:\n                - server_error\n                - rate_limit_exceeded\n              x-ms-enum:\n                name: LastErrorCode\n                modelAsString: true\n                values:\n                  - value: server_error\n                    description: The server failed to respond to request due to server error\n                  - value: rate_limit_exceeded\n                    description: The server failed to respond to request due to rate limit exceeded\n            message:\n              type: string\n              description: A human-readable description of the error.\n          required:\n            - code\n            - message\n        expires_at:\n          description: The Unix timestamp (in seconds) for when the run will expire.\n          type: integer\n        started_at:\n          description: The Unix timestamp (in seconds) for when the run was started.\n          type: integer\n          nullable: true\n        cancelled_at:\n          description: The Unix timestamp (in seconds) for when the run was cancelled.\n          type: integer\n          nullable: true\n        failed_at:\n          description: The Unix timestamp (in seconds) for when the run failed.\n          type: integer\n          nullable: true\n        completed_at:\n          description: The Unix timestamp (in seconds) for when the run was completed.\n          type: integer\n          nullable: true\n        incomplete_details:\n          description: Details on why the run is incomplete. Will be `null` if the run is not incomplete.\n          type: object\n          nullable: true\n          properties:\n            reason:\n              description: The reason why the run is incomplete. This will point to which specific token limit was reached over the course of the run.\n              type: string\n              enum: [\"max_completion_tokens\", \"max_prompt_tokens\"]\n              x-ms-enum:\n                name: IncompleteDetailsReason\n                modelAsString: true\n                values:\n                  - value: max_completion_tokens\n                  - value: max_prompt_tokens\n        model:\n          description: The model that the assistant used for this run.\n          type: string\n        instructions:\n          description: The instructions that the assistant used for this run.\n          type: string\n        tools:\n          description: The list of tools that the assistant used for this run.\n          default: []\n          type: array\n          maxItems: 20\n          items:\n            oneOf:\n              - $ref: \"#/components/schemas/assistantToolsCode\"\n              - $ref: \"#/components/schemas/assistantToolsFileSearch\"\n              - $ref: \"#/components/schemas/assistantToolsFunction\"\n        metadata:\n          description: *metadata_description\n          type: object\n          nullable: true\n        usage:\n          $ref: \"#/components/schemas/runCompletionUsage\"\n        temperature:\n          description: The sampling temperature used for this run. If not set, defaults to 1.\n          type: number\n          nullable: true\n        top_p:\n          description: The nucleus sampling value used for this run. If not set, defaults to 1.\n          type: number\n          nullable: true\n        max_prompt_tokens:\n          type: integer\n          nullable: true\n          description: |\n            The maximum number of prompt tokens specified to have been used over the course of the run.\n          minimum: 256\n        max_completion_tokens:\n          type: integer\n          nullable: true\n          description: |\n            The maximum number of completion tokens specified to have been used over the course of the run.\n          minimum: 256\n        truncation_strategy:\n          $ref: \"#/components/schemas/truncationObject\"\n          nullable: true\n        tool_choice:\n          $ref: \"#/components/schemas/assistantsApiToolChoiceOption\"\n          nullable: true\n        parallel_tool_calls:\n          $ref: \"#/components/schemas/ParallelToolCalls\"\n        response_format:\n          $ref: \"#/components/schemas/assistantsApiResponseFormatOption\"\n          nullable: true\n      required:\n        - id\n        - object\n        - created_at\n        - thread_id\n        - assistant_id\n        - status\n        - required_action\n        - last_error\n        - expires_at\n        - started_at\n        - cancelled_at\n        - failed_at\n        - completed_at\n        - model\n        - instructions\n        - tools\n        - metadata\n        - usage\n        - incomplete_details\n        - max_prompt_tokens\n        - max_completion_tokens\n        - truncation_strategy\n        - tool_choice\n        - response_format\n\n    createRunRequest:\n      type: object\n      additionalProperties: false\n      properties:\n        assistant_id:\n          description: The ID of the assistant to use to execute this run.\n          type: string\n        model:\n          description: The ID of the Model to be used to execute this run. If a value is provided here, it will override the model associated with the assistant. If not, the model associated with the assistant will be used.\n          type: string\n          nullable: true\n        instructions:\n          description: Override the default system message of the assistant. This is useful for modifying the behavior on a per-run basis.\n          type: string\n          nullable: true\n        additional_instructions:\n          description: Appends additional instructions at the end of the instructions for the run. This is useful for modifying the behavior on a per-run basis without overriding other instructions.\n          type: string\n          nullable: true\n        additional_messages:\n          description: Adds additional messages to the thread before creating the run.\n          type: array\n          items:\n            $ref: \"#/components/schemas/createMessageRequest\"\n          nullable: true\n        tools:\n          description: Override the tools the assistant can use for this run. This is useful for modifying the behavior on a per-run basis.\n          nullable: true\n          type: array\n          maxItems: 20\n          items:\n            oneOf:\n              - $ref: \"#/components/schemas/assistantToolsCode\"\n              - $ref: \"#/components/schemas/assistantToolsFileSearch\"\n              - $ref: \"#/components/schemas/assistantToolsFunction\"\n        metadata:\n          description: *metadata_description\n          type: object\n          nullable: true\n        temperature:\n          type: number\n          minimum: 0\n          maximum: 2\n          default: 1\n          example: 1\n          nullable: true\n          description: *run_temperature_description\n        top_p:\n          type: number\n          minimum: 0\n          maximum: 1\n          default: 1\n          example: 1\n          nullable: true\n          description: *run_top_p_description\n        stream:\n          type: boolean\n          nullable: true\n          description: |\n            If `true`, returns a stream of events that happen during the Run as server-sent events, terminating when the Run enters a terminal state with a `data: [DONE]` message.\n        max_prompt_tokens:\n          type: integer\n          nullable: true\n          description: |\n            The maximum number of prompt tokens that may be used over the course of the run. The run will make a best effort to use only the number of prompt tokens specified, across multiple turns of the run. If the run exceeds the number of prompt tokens specified, the run will end with status `incomplete`. See `incomplete_details` for more info.\n          minimum: 256\n        max_completion_tokens:\n          type: integer\n          nullable: true\n          description: |\n            The maximum number of completion tokens that may be used over the course of the run. The run will make a best effort to use only the number of completion tokens specified, across multiple turns of the run. If the run exceeds the number of completion tokens specified, the run will end with status `incomplete`. See `incomplete_details` for more info.\n          minimum: 256\n        truncation_strategy:\n          $ref: \"#/components/schemas/truncationObject\"\n          nullable: true\n        tool_choice:\n          $ref: \"#/components/schemas/assistantsApiToolChoiceOption\"\n          nullable: true\n        parallel_tool_calls:\n          $ref: \"#/components/schemas/ParallelToolCalls\"\n        response_format:\n          $ref: \"#/components/schemas/assistantsApiResponseFormatOption\"\n          nullable: true\n      required:\n        - thread_id\n        - assistant_id\n\n    listRunsResponse:\n      type: object\n      properties:\n        object:\n          type: string\n          example: list\n        data:\n          type: array\n          items:\n            $ref: \"#/components/schemas/runObject\"\n        first_id:\n          type: string\n          example: run_hLBK7PXBv5Lr2NQT7KLY0ag1\n        last_id:\n          type: string\n          example: run_QLoItBbqwyAJEzlTy4y9kOMM\n        has_more:\n          type: boolean\n          example: false\n      required:\n        - object\n        - data\n        - first_id\n        - last_id\n        - has_more\n\n    modifyRunRequest:\n      type: object\n      additionalProperties: false\n      properties:\n        metadata:\n          description: *metadata_description\n          type: object\n          nullable: true\n\n    submitToolOutputsRunRequest:\n      type: object\n      additionalProperties: false\n      properties:\n        tool_outputs:\n          description: A list of tools for which the outputs are being submitted.\n          type: array\n          items:\n            type: object\n            properties:\n              tool_call_id:\n                type: string\n                description: The ID of the tool call in the `required_action` object within the run object the output is being submitted for.\n              output:\n                type: string\n                description: The output of the tool call to be submitted to continue the run.\n        stream:\n          type: boolean\n          nullable: true\n          description: |\n            If `true`, returns a stream of events that happen during the Run as server-sent events, terminating when the Run enters a terminal state with a `data: [DONE]` message.\n      required:\n        - tool_outputs\n\n    runToolCallObject:\n      type: object\n      description: Tool call objects\n      properties:\n        id:\n          type: string\n          description: The ID of the tool call. This ID must be referenced when you submit the tool outputs in using the [Submit tool outputs to run](/docs/api-reference/runs/submitToolOutputs) endpoint.\n        type:\n          type: string\n          description: The type of tool call the output is required for. For now, this is always `function`.\n          enum:\n            - function\n          x-ms-enum:\n            name: RunToolCallObjectType\n            modelAsString: true\n            values:\n              - value: function\n        function:\n          type: object\n          description: The function definition.\n          properties:\n            name:\n              type: string\n              description: The name of the function.\n            arguments:\n              type: string\n              description: The arguments that the model expects you to pass to the function.\n          required:\n            - name\n            - arguments\n      required:\n        - id\n        - type\n        - function\n\n    createThreadAndRunRequest:\n      type: object\n      additionalProperties: false\n      properties:\n        assistant_id:\n          description: The ID of the assistant to use to execute this run.\n          type: string\n        thread:\n          $ref: \"#/components/schemas/createThreadRequest\"\n          description: If no thread is provided, an empty thread will be created.\n        model:\n          description: The ID of the [Model](/docs/api-reference/models) to be used to execute this run. If a value is provided here, it will override the model associated with the assistant. If not, the model associated with the assistant will be used.\n          type: string\n          nullable: true\n        instructions:\n          description: Override the default system message of the assistant. This is useful for modifying the behavior on a per-run basis.\n          type: string\n          nullable: true\n        tools:\n          description: Override the tools the assistant can use for this run. This is useful for modifying the behavior on a per-run basis.\n          nullable: true\n          type: array\n          maxItems: 20\n          items:\n            oneOf:\n              - $ref: \"#/components/schemas/assistantToolsCode\"\n              - $ref: \"#/components/schemas/assistantToolsFileSearch\"\n              - $ref: \"#/components/schemas/assistantToolsFunction\"\n        tool_resources:\n          type: object\n          description: |\n            A set of resources that are used by the assistant\'s tools. The resources are specific to the type of tool. For example, the `code_interpreter` tool requires a list of file IDs, while the `file_search` tool requires a list of vector store IDs.\n          properties:\n            code_interpreter:\n              type: object\n              properties:\n                file_ids:\n                  type: array\n                  description: |\n                    A list of file IDs made available to the `code_interpreter` tool. There can be a maximum of 20 files associated with the tool.\n                  default: []\n                  maxItems: 20\n                  items:\n                    type: string\n            file_search:\n              type: object\n              properties:\n                vector_store_ids:\n                  type: array\n                  description: |\n                    The ID of the vector store attached to this assistant. There can be a maximum of 1 vector store attached to the assistant.\n                  maxItems: 1\n                  items:\n                    type: string\n          nullable: true\n        metadata:\n          description: *metadata_description\n          type: object\n          nullable: true\n        temperature:\n          type: number\n          minimum: 0\n          maximum: 2\n          default: 1\n          example: 1\n          nullable: true\n          description: *run_temperature_description\n        top_p:\n          type: number\n          minimum: 0\n          maximum: 1\n          default: 1\n          example: 1\n          nullable: true\n          description: *run_top_p_description\n        stream:\n          type: boolean\n          nullable: true\n          description: |\n            If `true`, returns a stream of events that happen during the Run as server-sent events, terminating when the Run enters a terminal state with a `data: [DONE]` message.\n        max_prompt_tokens:\n          type: integer\n          nullable: true\n          description: |\n            The maximum number of prompt tokens that may be used over the course of the run. The run will make a best effort to use only the number of prompt tokens specified, across multiple turns of the run. If the run exceeds the number of prompt tokens specified, the run will end with status `incomplete`. See `incomplete_details` for more info.\n          minimum: 256\n        max_completion_tokens:\n          type: integer\n          nullable: true\n          description: |\n            The maximum number of completion tokens that may be used over the course of the run. The run will make a best effort to use only the number of completion tokens specified, across multiple turns of the run. If the run exceeds the number of completion tokens specified, the run will end with status `incomplete`. See `incomplete_details` for more info.\n          minimum: 256\n        truncation_strategy:\n          $ref: \"#/components/schemas/truncationObject\"\n          nullable: true\n        tool_choice:\n          $ref: \"#/components/schemas/assistantsApiToolChoiceOption\"\n          nullable: true\n        parallel_tool_calls:\n          $ref: \"#/components/schemas/ParallelToolCalls\"\n        response_format:\n          $ref: \"#/components/schemas/assistantsApiResponseFormatOption\"\n          nullable: true\n      required:\n        - thread_id\n        - assistant_id\n\n    threadObject:\n      type: object\n      title: Thread\n      description: Represents a thread that contains [messages](/docs/api-reference/messages).\n      properties:\n        id:\n          description: The identifier, which can be referenced in API endpoints.\n          type: string\n        object:\n          description: The object type, which is always `thread`.\n          type: string\n          enum:\n            - thread\n          x-ms-enum:\n            name: ThreadObjectType\n            modelAsString: true\n            values:\n              - value: thread\n                description: The type of thread object which is always `thread`\n        created_at:\n          description: The Unix timestamp (in seconds) for when the thread was created.\n          type: integer\n        tool_resources:\n          type: object\n          description: |\n            A set of resources that are made available to the assistant\'s tools in this thread. The resources are specific to the type of tool. For example, the `code_interpreter` tool requires a list of file IDs, while the `file_search` tool requires a list of vector store IDs.\n          properties:\n            code_interpreter:\n              type: object\n              properties:\n                file_ids:\n                  type: array\n                  description: |\n                    A list of file IDs made available to the `code_interpreter` tool. There can be a maximum of 20 files associated with the tool.\n                  default: []\n                  maxItems: 20\n                  items:\n                    type: string\n            file_search:\n              type: object\n              properties:\n                vector_store_ids:\n                  type: array\n                  description: |\n                    The vector store attached to this thread. There can be a maximum of 1 vector store attached to the thread.\n                  maxItems: 1\n                  items:\n                    type: string\n          nullable: true\n        metadata:\n          description: *metadata_description\n          type: object\n          nullable: true\n      required:\n        - id\n        - object\n        - created_at\n        - tool_resources\n        - metadata\n\n    createThreadRequest:\n      type: object\n      additionalProperties: false\n      properties:\n        messages:\n          description: A list of messages to start the thread with.\n          type: array\n          items:\n            $ref: \"#/components/schemas/createMessageRequest\"\n        tool_resources:\n          type: object\n          description: |\n            A set of resources that are made available to the assistant\'s tools in this thread. The resources are specific to the type of tool. For example, the `code_interpreter` tool requires a list of file IDs, while the `file_search` tool requires a list of vector store IDs.\n          properties:\n            code_interpreter:\n              type: object\n              properties:\n                file_ids:\n                  type: array\n                  description: |\n                    A list of file IDs made available to the `code_interpreter` tool. There can be a maximum of 20 files associated with the tool.\n                  default: []\n                  maxItems: 20\n                  items:\n                    type: string\n            file_search:\n              type: object\n              properties:\n                vector_store_ids:\n                  type: array\n                  description: |\n                    The vector store attached to this thread. There can be a maximum of 1 vector store attached to the thread.\n                  maxItems: 1\n                  items:\n                    type: string\n                vector_stores:\n                  type: array\n                  description: |\n                    A helper to create a vector store with file_ids and attach it to this thread. There can be a maximum of 1 vector store attached to the thread.\n                  maxItems: 1\n                  items:\n                    type: object\n                    properties:\n                      file_ids:\n                        type: array\n                        description: |\n                          A list of file IDs to add to the vector store. There can be a maximum of 10000 files in a vector store.\n                        maxItems: 10000\n                        items:\n                          type: string\n                      chunking_strategy:\n                        # Ideally we\'d reuse the chunking strategy schema here, but it doesn\'t expand properly\n                        type: object\n                        description: The chunking strategy used to chunk the file(s). If not set, will use the `auto` strategy.\n                        oneOf:\n                          - type: object\n                            title: Auto Chunking Strategy\n                            description: The default strategy. This strategy currently uses a `max_chunk_size_tokens` of `800` and `chunk_overlap_tokens` of `400`.\n                            additionalProperties: false\n                            properties:\n                              type:\n                                type: string\n                                description: Always `auto`.\n                                enum: [\"auto\"]\n                                x-ms-enum:\n                                  name: AutoChunkingStrategyType\n                                  modelAsString: true\n                                  values:\n                                    - value: auto\n                            required:\n                              - type\n                          - type: object\n                            title: Static Chunking Strategy\n                            additionalProperties: false\n                            properties:\n                              type:\n                                type: string\n                                description: Always `static`.\n                                enum: [\"static\"]\n                                x-ms-enum:\n                                  name: StaticChunkingStrategyType\n                                  modelAsString: true\n                                  values:\n                                    - value: static\n                              static:\n                                type: object\n                                additionalProperties: false\n                                properties:\n                                  max_chunk_size_tokens:\n                                    type: integer\n                                    minimum: 100\n                                    maximum: 4096\n                                    description: The maximum number of tokens in each chunk. The default value is `800`. The minimum value is `100` and the maximum value is `4096`.\n                                  chunk_overlap_tokens:\n                                    type: integer\n                                    description: |\n                                      The number of tokens that overlap between chunks. The default value is `400`.\n\n                                      Note that the overlap must not exceed half of `max_chunk_size_tokens`.\n                                required:\n                                  - max_chunk_size_tokens\n                                  - chunk_overlap_tokens\n                            required:\n                              - type\n                              - static\n                      metadata:\n                        type: object\n                        description: |\n                          Set of 16 key-value pairs that can be attached to a vector store. This can be useful for storing additional information about the vector store in a structured format. Keys can be a maximum of 64 characters long and values can be a maximum of 512 characters long.\n              oneOf:\n                - required: [vector_store_ids]\n                - required: [vector_stores]\n          nullable: true\n        metadata:\n          description: *metadata_description\n          type: object\n          nullable: true\n\n    modifyThreadRequest:\n      type: object\n      additionalProperties: false\n      properties:\n        tool_resources:\n          type: object\n          description: |\n            A set of resources that are made available to the assistant\'s tools in this thread. The resources are specific to the type of tool. For example, the `code_interpreter` tool requires a list of file IDs, while the `file_search` tool requires a list of vector store IDs.\n          properties:\n            code_interpreter:\n              type: object\n              properties:\n                file_ids:\n                  type: array\n                  description: |\n                    A list of File IDs made available to the `code_interpreter` tool. There can be a maximum of 20 files associated with the tool.\n                  default: []\n                  maxItems: 20\n                  items:\n                    type: string\n            file_search:\n              type: object\n              properties:\n                vector_store_ids:\n                  type: array\n                  description: |\n                    The vector store attached to this thread. There can be a maximum of 1 vector store attached to the thread.\n                  maxItems: 1\n                  items:\n                    type: string\n          nullable: true\n        metadata:\n          description: *metadata_description\n          type: object\n          nullable: true\n\n    deleteThreadResponse:\n      type: object\n      properties:\n        id:\n          type: string\n        deleted:\n          type: boolean\n        object:\n          type: string\n          enum:\n            - thread.deleted\n          x-ms-enum:\n            name: DeleteThreadResponseObjectState\n            modelAsString: true\n            values:\n              - value: thread.deleted\n                description: The delete thread response object state which is `thread.deleted`\n      required:\n        - id\n        - object\n        - deleted\n\n    messageObject:\n      type: object\n      title: The message object\n      description: Represents a message within a [thread](/docs/api-reference/threads).\n      properties:\n        id:\n          description: The identifier, which can be referenced in API endpoints.\n          type: string\n        object:\n          description: The object type, which is always `thread.message`.\n          type: string\n          enum:\n            - thread.message\n          x-ms-enum:\n            name: MessageObjectType\n            modelAsString: true\n            values:\n              - value: thread.message\n                description: The message object type which is `thread.message`\n        created_at:\n          description: The Unix timestamp (in seconds) for when the message was created.\n          type: integer\n        thread_id:\n          description: The [thread](/docs/api-reference/threads) ID that this message belongs to.\n          type: string\n        status:\n          description: The status of the message, which can be either `in_progress`, `incomplete`, or `completed`.\n          type: string\n          enum: [\"in_progress\", \"incomplete\", \"completed\"]\n          x-ms-enum:\n            name: MessageObjectStatus\n            modelAsString: true\n            values:\n              - value: in_progress\n              - value: incomplete\n              - value: completed\n        incomplete_details:\n          description: On an incomplete message, details about why the message is incomplete.\n          type: object\n          properties:\n            reason:\n              type: string\n              description: The reason the message is incomplete.\n              enum:\n                [\n                  \"content_filter\",\n                  \"max_tokens\",\n                  \"run_cancelled\",\n                  \"run_expired\",\n                  \"run_failed\",\n                ]\n              x-ms-enum:\n                name: MessageObjectIncompleteReason\n                modelAsString: true\n                values:\n                  - value: content_filter\n                  - value: max_tokens\n                  - value: run_cancelled\n                  - value: run_expired\n                  - value: run_failed\n          nullable: true\n          required:\n            - reason\n        completed_at:\n          description: The Unix timestamp (in seconds) for when the message was completed.\n          type: integer\n          nullable: true\n        incomplete_at:\n          description: The Unix timestamp (in seconds) for when the message was marked as incomplete.\n          type: integer\n          nullable: true\n        role:\n          description: The entity that produced the message. One of `user` or `assistant`.\n          type: string\n          enum:\n            - user\n            - assistant\n          x-ms-enum:\n            name: MessageObjectRole\n            modelAsString: true\n            values:\n              - value: user\n              - value: assistant\n        content:\n          description: The content of the message in array of text and/or images.\n          type: array\n          items:\n            oneOf:\n              - $ref: \"#/components/schemas/messageContentImageFileObject\"\n              - $ref: \"#/components/schemas/messageContentTextObject\"\n        assistant_id:\n          description: If applicable, the ID of the assistant that authored this message.\n          type: string\n          nullable: true\n        run_id:\n          description: If applicable, the ID of the [run](/docs/api-reference/runs) associated with the authoring of this message.\n          type: string\n          nullable: true\n        attachments:\n          type: array\n          items:\n            type: object\n            properties:\n              file_id:\n                type: string\n                description: The ID of the file to attach to the message.\n              tools:\n                description: The tools to add this file to.\n                type: array\n                items:\n                  oneOf:\n                    - $ref: \"#/components/schemas/assistantToolsCode\"\n                    - $ref: \"#/components/schemas/assistantToolsFileSearchTypeOnly\"\n          description: A list of files attached to the message, and the tools they were added to.\n          nullable: true\n        metadata:\n          description: *metadata_description\n          type: object\n          nullable: true\n      required:\n        - id\n        - object\n        - created_at\n        - thread_id\n        - status\n        - incomplete_details\n        - completed_at\n        - incomplete_at\n        - role\n        - content\n        - assistant_id\n        - run_id\n        - attachments\n        - metadata\n\n    createMessageRequest:\n      type: object\n      additionalProperties: false\n      required:\n        - role\n        - content\n      properties:\n        role:\n          type: string\n          enum:\n            - user\n            - assistant\n          x-ms-enum:\n            name: CreateMessageRequestRole\n            modelAsString: true\n            values:\n              - value: user\n              - value: assistant\n          description: |\n            The role of the entity that is creating the message. Allowed values include:\n            - `user`: Indicates the message is sent by an actual user and should be used in most cases to represent user-generated messages.\n            - `assistant`: Indicates the message is generated by the assistant. Use this value to insert messages from the assistant into the conversation.\n        content:\n          type: string\n          minLength: 1\n          maxLength: 256000\n          description: The content of the message.\n        attachments:\n          type: array\n          items:\n            type: object\n            properties:\n              file_id:\n                type: string\n                description: The ID of the file to attach to the message.\n              tools:\n                description: The tools to add this file to.\n                type: array\n                items:\n                  oneOf:\n                    - $ref: \"#/components/schemas/assistantToolsCode\"\n                    - $ref: \"#/components/schemas/assistantToolsFileSearchTypeOnly\"\n                  x-oaiExpandable: true\n          description: A list of files attached to the message, and the tools they should be added to.\n          required:\n            - file_id\n            - tools\n          nullable: true\n        metadata:\n          description: *metadata_description\n          type: object\n          nullable: true\n    modifyMessageRequest:\n      type: object\n      additionalProperties: false\n      properties:\n        metadata:\n          description: *metadata_description\n          type: object\n          nullable: true\n    listMessagesResponse:\n      properties:\n        object:\n          type: string\n          example: list\n        data:\n          type: array\n          items:\n            $ref: \"#/components/schemas/messageObject\"\n        first_id:\n          type: string\n          example: msg_hLBK7PXBv5Lr2NQT7KLY0ag1\n        last_id:\n          type: string\n          example: msg_QLoItBbqwyAJEzlTy4y9kOMM\n        has_more:\n          type: boolean\n          example: false\n      required:\n        - object\n        - data\n        - first_id\n        - last_id\n        - has_more\n\n    messageContentImageFileObject:\n      title: Image file\n      type: object\n      description: References an image file in the content of a message.\n      properties:\n        type:\n          description: Always `image_file`.\n          type: string\n          enum:\n            - image_file\n          x-ms-enum:\n            name: MessageContentImageFileObjectType\n            modelAsString: true\n            values:\n              - value: image_file\n                description: The message content image file type\n        image_file:\n          type: object\n          properties:\n            file_id:\n              description: The file ID of the image in the message content.\n              type: string\n          required:\n            - file_id\n      required:\n        - type\n        - image_file\n\n    messageContentTextObject:\n      title: Text\n      type: object\n      description: The text content that is part of a message.\n      properties:\n        type:\n          description: Always `text`.\n          type: string\n          enum:\n            - text\n          x-ms-enum:\n            name: messageContentTextObjectType\n            modelAsString: true\n            values:\n              - value: text\n                description: The message content text Object type\n        text:\n          type: object\n          properties:\n            value:\n              description: The data that makes up the text.\n              type: string\n            annotations:\n              type: array\n              items:\n                oneOf:\n                  - $ref: \"#/components/schemas/messageContentTextAnnotationsFileCitationObject\"\n                  - $ref: \"#/components/schemas/messageContentTextAnnotationsFilePathObject\"\n          required:\n            - value\n            - annotations\n      required:\n        - type\n        - text\n\n    messageContentTextAnnotationsFileCitationObject:\n      title: File citation\n      type: object\n      description: A citation within the message that points to a specific quote from a specific File associated with the assistant or the message. Generated when the assistant uses the \"retrieval\" tool to search files.\n      properties:\n        type:\n          description: Always `file_citation`.\n          type: string\n          enum:\n            - file_citation\n          x-ms-enum:\n            name: FileCitationObjectType\n            modelAsString: true\n            values:\n              - value: file_citation\n                description: The file citation object type\n        text:\n          description: The text in the message content that needs to be replaced.\n          type: string\n        file_citation:\n          type: object\n          properties:\n            file_id:\n              description: The ID of the specific File the citation is from.\n              type: string\n          required:\n            - file_id\n        start_index:\n          type: integer\n          minimum: 0\n        end_index:\n          type: integer\n          minimum: 0\n      required:\n        - type\n        - text\n        - file_citation\n        - start_index\n        - end_index\n\n    messageContentTextAnnotationsFilePathObject:\n      title: File path\n      type: object\n      description: A URL for the file that\'s generated when the assistant used the `code_interpreter` tool to generate a file.\n      properties:\n        type:\n          description: Always `file_path`.\n          type: string\n          enum:\n            - file_path\n          x-ms-enum:\n            name: FilePathObjectType\n            modelAsString: true\n            values:\n              - value: file_path\n                description: The file path object type\n        text:\n          description: The text in the message content that needs to be replaced.\n          type: string\n        file_path:\n          type: object\n          properties:\n            file_id:\n              description: The ID of the file that was generated.\n              type: string\n          required:\n            - file_id\n        start_index:\n          type: integer\n          minimum: 0\n        end_index:\n          type: integer\n          minimum: 0\n      required:\n        - type\n        - text\n        - file_path\n        - start_index\n        - end_index\n\n    runStepObject:\n      type: object\n      title: Run steps\n      description: |\n        Represents a step in execution of a run.\n      properties:\n        id:\n          description: The identifier of the run step, which can be referenced in API endpoints.\n          type: string\n        object:\n          description: The object type, which is always `assistant.run.step``.\n          type: string\n          enum:\n            - assistant.run.step\n          x-ms-enum:\n            name: RunStepObjectType\n            modelAsString: true\n            values:\n              - value: assistant.run.step\n                description: The object type, which is always `assistant.run.step`\n        created_at:\n          description: The Unix timestamp (in seconds) for when the run step was created.\n          type: integer\n        assistant_id:\n          description: The ID of the assistant associated with the run step.\n          type: string\n        thread_id:\n          description: The ID of the [thread](/docs/api-reference/threads) that was run.\n          type: string\n        run_id:\n          description: The ID of the [run](/docs/api-reference/runs) that this run step is a part of.\n          type: string\n        type:\n          description: The type of run step, which can be either `message_creation` or `tool_calls`.\n          type: string\n          enum:\n            - message_creation\n            - tool_calls\n          x-ms-enum:\n            name: RunStepObjectType\n            modelAsString: true\n            values:\n              - value: message_creation\n                description: The message_creation run step\n              - value: tool_calls\n                description: The tool_calls run step\n        status:\n          description: The status of the run, which can be either `in_progress`, `cancelled`, `failed`, `completed`, or `expired`.\n          type: string\n          enum:\n            - in_progress\n            - cancelled\n            - failed\n            - completed\n            - expired\n          x-ms-enum:\n            name: RunStepObjectStatus\n            modelAsString: true\n            values:\n              - value: in_progress\n                description: The in_progress run status\n              - value: cancelled\n                description: The cancelled run status\n              - value: failed\n                description: The cancelled run status\n              - value: completed\n                description: The cancelled run status\n              - value: expired\n                description: The cancelled run status\n        step_details:\n          type: object\n          description: The details of the run step.\n          oneOf:\n            - $ref: \"#/components/schemas/runStepDetailsMessageCreationObject\"\n            - $ref: \"#/components/schemas/runStepDetailsToolCallsObject\"\n        last_error:\n          type: object\n          description: The last error associated with this run step. Will be `null` if there are no errors.\n          nullable: true\n          properties:\n            code:\n              type: string\n              description: One of `server_error` or `rate_limit_exceeded`.\n              enum:\n                - server_error\n                - rate_limit_exceeded\n              x-ms-enum:\n                name: LastErrorCode\n                modelAsString: true\n                values:\n                  - value: server_error\n                    description: The server_error\n                  - value: rate_limit_exceeded\n                    description: The rate_limit_exceeded status\n            message:\n              type: string\n              description: A human-readable description of the error.\n          required:\n            - code\n            - message\n        expired_at:\n          description: The Unix timestamp (in seconds) for when the run step expired. A step is considered expired if the parent run is expired.\n          type: integer\n          nullable: true\n        cancelled_at:\n          description: The Unix timestamp (in seconds) for when the run step was cancelled.\n          type: integer\n          nullable: true\n        failed_at:\n          description: The Unix timestamp (in seconds) for when the run step failed.\n          type: integer\n          nullable: true\n        completed_at:\n          description: The Unix timestamp (in seconds) for when the run step completed.\n          type: integer\n          nullable: true\n        metadata:\n          description: *metadata_description\n          type: object\n          nullable: true\n      required:\n        - id\n        - object\n        - created_at\n        - assistant_id\n        - thread_id\n        - run_id\n        - type\n        - status\n        - step_details\n        - last_error\n        - expired_at\n        - cancelled_at\n        - failed_at\n        - completed_at\n        - metadata\n\n    listRunStepsResponse:\n      properties:\n        object:\n          type: string\n          example: list\n        data:\n          type: array\n          items:\n            $ref: \"#/components/schemas/runStepObject\"\n        first_id:\n          type: string\n          example: step_hLBK7PXBv5Lr2NQT7KLY0ag1\n        last_id:\n          type: string\n          example: step_QLoItBbqwyAJEzlTy4y9kOMM\n        has_more:\n          type: boolean\n          example: false\n      required:\n        - object\n        - data\n        - first_id\n        - last_id\n        - has_more\n\n    runStepDetailsMessageCreationObject:\n      title: Message creation\n      type: object\n      description: Details of the message creation by the run step.\n      properties:\n        type:\n          description: Always `message_creation``.\n          type: string\n          enum:\n            - message_creation\n          x-ms-enum:\n            name: RunStepDetailsMessageCreationObjectType\n            modelAsString: true\n            values:\n              - value: message_creation\n        message_creation:\n          type: object\n          properties:\n            message_id:\n              type: string\n              description: The ID of the message that was created by this run step.\n          required:\n            - message_id\n      required:\n        - type\n        - message_creation\n\n    runStepDetailsToolCallsObject:\n      title: Tool calls\n      type: object\n      description: Details of the tool call.\n      properties:\n        type:\n          description: Always `tool_calls`.\n          type: string\n          enum:\n            - tool_calls\n          x-ms-enum:\n            name: RunStepDetailsToolCallsObjectType\n            modelAsString: true\n            values:\n              - value: tool_calls\n        tool_calls:\n          type: array\n          description: |\n            An array of tool calls the run step was involved in. These can be associated with one of three types of tools: `code_interpreter`, `retrieval` or `function`.\n          items:\n            type: object\n            oneOf:\n              - $ref: \"#/components/schemas/runStepDetailsToolCallsCodeObject\"\n              - $ref: \"#/components/schemas/runStepDetailsToolCallsFileSearchObject\"\n              - $ref: \"#/components/schemas/runStepDetailsToolCallsFunctionObject\"\n      required:\n        - type\n        - tool_calls\n\n    runStepDetailsToolCallsCodeObject:\n      title: Code interpreter tool call\n      type: object\n      description: Details of the Code Interpreter tool call the run step was involved in.\n      properties:\n        id:\n          type: string\n          description: The ID of the tool call.\n        type:\n          type: string\n          description: The type of tool call. This is always going to be `code_interpreter` for this type of tool call.\n          enum:\n            - code_interpreter\n          x-ms-enum:\n            name: RunStepDetailsToolCallsCodeObjectType\n            modelAsString: true\n            values:\n              - value: code_interpreter\n        code_interpreter:\n          type: object\n          description: The Code Interpreter tool call definition.\n          required:\n            - input\n            - outputs\n          properties:\n            input:\n              type: string\n              description: The input to the Code Interpreter tool call.\n            outputs:\n              type: array\n              description: The outputs from the Code Interpreter tool call. Code Interpreter can output one or more items, including text (`logs`) or images (`image`). Each of these are represented by a different object type.\n              items:\n                type: object\n                oneOf:\n                  - $ref: \"#/components/schemas/runStepDetailsToolCallsCodeOutputLogsObject\"\n                  - $ref: \"#/components/schemas/runStepDetailsToolCallsCodeOutputImageObject\"\n      required:\n        - id\n        - type\n        - code_interpreter\n\n    runStepDetailsToolCallsCodeOutputLogsObject:\n      title: Code interpreter log output\n      type: object\n      description: Text output from the Code Interpreter tool call as part of a run step.\n      properties:\n        type:\n          description: Always `logs`.\n          type: string\n          enum:\n            - logs\n          x-ms-enum:\n            name: RunStepDetailsToolCallsCodeOutputLogsObjectType\n            modelAsString: true\n            values:\n              - value: logs\n        logs:\n          type: string\n          description: The text output from the Code Interpreter tool call.\n      required:\n        - type\n        - logs\n\n    runStepDetailsToolCallsCodeOutputImageObject:\n      title: Code interpreter image output\n      type: object\n      properties:\n        type:\n          description: Always `image`.\n          type: string\n          enum:\n            - image\n          x-ms-enum:\n            name: RunStepDetailsToolCallsCodeOutputImageObjectType\n            modelAsString: true\n            values:\n              - value: image\n        image:\n          type: object\n          properties:\n            file_id:\n              description: The file ID of the image.\n              type: string\n          required:\n            - file_id\n      required:\n        - type\n        - image\n\n    runStepDetailsToolCallsFileSearchObject:\n      title: File search tool call\n      type: object\n      properties:\n        id:\n          type: string\n          description: The ID of the tool call object.\n        type:\n          type: string\n          description: The type of tool call. This is always going to be `file_search` for this type of tool call.\n          enum: [\"file_search\"]\n          x-ms-enum:\n            name: RunStepDetailsToolCallsFileSearchObjectType\n            modelAsString: true\n            values:\n              - value: file_search\n        file_search:\n          type: object\n          description: For now, this is always going to be an empty object.\n          properties:\n            results:\n              type: array\n              description: The results of the file search.\n              items:\n                $ref: \"#/components/schemas/runStepDetailsToolCallsFileSearchResultObject\"\n      required:\n        - id\n        - type\n        - file_search\n\n    runStepDetailsToolCallsFileSearchResultObject:\n      title: File search tool call result\n      type: object\n      description: A result instance of the file search.\n      x-oaiTypeLabel: map\n      properties:\n        file_id:\n          type: string\n          description: The ID of the file that result was found in.\n        file_name:\n          type: string\n          description: The name of the file that result was found in.\n        score:\n          type: number\n          description: The score of the result. All values must be a floating point number between 0 and 1.\n          minimum: 0\n          maximum: 1\n        content:\n          type: array\n          description: The content of the result that was found. The content is only included if requested via the include query parameter.\n          items:\n            type: object\n            properties:\n              type:\n                type: string\n                description: The type of the content.\n                enum: [\"text\"]\n              text:\n                type: string\n                description: The text content of the file.\n      required:\n        - file_id\n        - file_name\n        - score\n\n    runStepDetailsToolCallsFunctionObject:\n      type: object\n      title: Function tool call\n      properties:\n        id:\n          type: string\n          description: The ID of the tool call object.\n        type:\n          type: string\n          description: The type of tool call. This is always going to be `function` for this type of tool call.\n          enum:\n            - function\n          x-ms-enum:\n            name: RunStepDetailsToolCallsFunctionObjectType\n            modelAsString: true\n            values:\n              - value: function\n        function:\n          type: object\n          description: The definition of the function that was called.\n          properties:\n            name:\n              type: string\n              description: The name of the function.\n            arguments:\n              type: string\n              description: The arguments passed to the function.\n            output:\n              type: string\n              description: The output of the function. This will be `null` if the outputs have not been [submitted](/docs/api-reference/runs/submitToolOutputs) yet.\n              nullable: true\n          required:\n            - name\n            - arguments\n            - output\n      required:\n        - id\n        - type\n        - function\n\n    vectorStoreExpirationAfter:\n      type: object\n      title: Vector store expiration policy\n      description: The expiration policy for a vector store.\n      properties:\n        anchor:\n          description: \"Anchor timestamp after which the expiration policy applies. Supported anchors: `last_active_at`.\"\n          type: string\n          enum: [\"last_active_at\"]\n          x-ms-enum:\n            name: VectorStoreExpirationAfterAnchor\n            modelAsString: true\n            values:\n              - value: last_active_at\n                description: The anchor timestamp after which the expiration policy applies.\n        days:\n          description: The number of days after the anchor time that the vector store will expire.\n          type: integer\n          minimum: 1\n          maximum: 365\n      required:\n        - anchor\n        - days\n\n    vectorStoreObject:\n      type: object\n      title: Vector store\n      description: A vector store is a collection of processed files can be used by the `file_search` tool.\n      properties:\n        id:\n          description: The identifier, which can be referenced in API endpoints.\n          type: string\n        object:\n          description: The object type, which is always `vector_store`.\n          type: string\n          enum: [\"vector_store\"]\n        created_at:\n          description: The Unix timestamp (in seconds) for when the vector store was created.\n          type: integer\n        name:\n          description: The name of the vector store.\n          type: string\n        usage_bytes:\n          description: The total number of bytes used by the files in the vector store.\n          type: integer\n        file_counts:\n          type: object\n          properties:\n            in_progress:\n              description: The number of files that are currently being processed.\n              type: integer\n            completed:\n              description: The number of files that have been successfully processed.\n              type: integer\n            failed:\n              description: The number of files that have failed to process.\n              type: integer\n            cancelled:\n              description: The number of files that were cancelled.\n              type: integer\n            total:\n              description: The total number of files.\n              type: integer\n          required:\n            - in_progress\n            - completed\n            - failed\n            - cancelled\n            - total\n        status:\n          description: The status of the vector store, which can be either `expired`, `in_progress`, or `completed`. A status of `completed` indicates that the vector store is ready for use.\n          type: string\n          enum: [\"expired\", \"in_progress\", \"completed\"]\n          x-ms-enum:\n            name: VectorStoreObjectStatus\n            modelAsString: true\n            values:\n              - value: expired\n              - value: in_progress\n              - value: completed\n        expires_after:\n          $ref: \"#/components/schemas/vectorStoreExpirationAfter\"\n        expires_at:\n          description: The Unix timestamp (in seconds) for when the vector store will expire.\n          type: integer\n          nullable: true\n        last_active_at:\n          description: The Unix timestamp (in seconds) for when the vector store was last active.\n          type: integer\n          nullable: true\n        metadata:\n          description: *metadata_description\n          type: object\n          nullable: true\n      required:\n        - id\n        - object\n        - usage_bytes\n        - created_at\n        - status\n        - last_active_at\n        - name\n        - bytes\n        - file_counts\n        - metadata\n\n    createVectorStoreRequest:\n      type: object\n      additionalProperties: false\n      properties:\n        file_ids:\n          description: A list of file IDs that the vector store should use. Useful for tools like `file_search` that can access files.\n          type: array\n          maxItems: 500\n          items:\n            type: string\n        name:\n          description: The name of the vector store.\n          type: string\n        expires_after:\n          $ref: \"#/components/schemas/vectorStoreExpirationAfter\"\n        chunking_strategy:\n          type: object\n          description: >-\n            The chunking strategy used to chunk the file(s). If not set, will use the\n            `auto` strategy. Only applicable if `file_ids` is non-empty.\n          oneOf:\n            - $ref: \"#/components/schemas/autoChunkingStrategyRequestParam\"\n            - $ref: \"#/components/schemas/staticChunkingStrategyRequestParam\"\n        metadata:\n          description: *metadata_description\n          type: object\n          nullable: true\n\n    updateVectorStoreRequest:\n      type: object\n      additionalProperties: false\n      properties:\n        name:\n          description: The name of the vector store.\n          type: string\n          nullable: true\n        expires_after:\n          $ref: \"#/components/schemas/vectorStoreExpirationAfter\"\n          nullable: true\n        metadata:\n          description: *metadata_description\n          type: object\n          nullable: true\n\n    listVectorStoresResponse:\n      properties:\n        object:\n          type: string\n          example: \"list\"\n        data:\n          type: array\n          items:\n            $ref: \"#/components/schemas/vectorStoreObject\"\n        first_id:\n          type: string\n          example: \"vs_abc123\"\n        last_id:\n          type: string\n          example: \"vs_abc456\"\n        has_more:\n          type: boolean\n          example: false\n      required:\n        - object\n        - data\n        - first_id\n        - last_id\n        - has_more\n\n    deleteVectorStoreResponse:\n      type: object\n      properties:\n        id:\n          type: string\n        deleted:\n          type: boolean\n        object:\n          type: string\n          enum: [vector_store.deleted]\n          x-ms-enum:\n            name: DeleteVectorStoreResponseObject\n            modelAsString: true\n            values:\n              - value: vector_store.deleted\n                description: The delete vector store response object state\n      required:\n        - id\n        - object\n        - deleted\n\n    vectorStoreFileObject:\n      type: object\n      title: Vector store files\n      description: A list of files attached to a vector store.\n      properties:\n        id:\n          description: The identifier, which can be referenced in API endpoints.\n          type: string\n        object:\n          description: The object type, which is always `vector_store.file`.\n          type: string\n          enum: [\"vector_store.file\"]\n          x-ms-enum:\n            name: VectorStoreFileObjectType\n            modelAsString: true\n            values:\n              - value: vector_store.file\n        usage_bytes:\n          description: The total vector store usage in bytes. Note that this may be different from the original file size.\n          type: integer\n        created_at:\n          description: The Unix timestamp (in seconds) for when the vector store file was created.\n          type: integer\n        vector_store_id:\n          description: The ID of the vector store that the file is attached to.\n          type: string\n        status:\n          description: The status of the vector store file, which can be either `in_progress`, `completed`, `cancelled`, or `failed`. The status `completed` indicates that the vector store file is ready for use.\n          type: string\n          enum: [\"in_progress\", \"completed\", \"cancelled\", \"failed\"]\n          x-ms-enum:\n            name: VectorStoreFileObjectStatus\n            modelAsString: true\n            values:\n              - value: in_progress\n              - value: completed\n              - value: cancelled\n              - value: failed\n        last_error:\n          type: object\n          description: The last error associated with this vector store file. Will be `null` if there are no errors.\n          nullable: true\n          properties:\n            code:\n              type: string\n              description: One of `server_error` or `invalid_file` or `unsupported_file`.\n              enum:\n                [\n                  \"server_error\",\n                  \"unsupported_file\",\n                  \"invalid_file\"\n                ]\n              x-ms-enum:\n                name: VectorStoreFileObjectLastErrorCode\n                modelAsString: true\n                values:\n                  - value: server_error\n                  - value: unsupported_file\n                  - value: invalid_file\n            message:\n              type: string\n              description: A human-readable description of the error.\n          required:\n            - code\n            - message\n        chunking_strategy:\n          type: object\n          description: |\n            The chunking strategy used to chunk the file(s). If not set, will use the\n            `auto` strategy. Only applicable if `file_ids` is non-empty.\n          oneOf:\n            - $ref: \"#/components/schemas/autoChunkingStrategyRequestParam\"\n            - $ref: \"#/components/schemas/staticChunkingStrategyRequestParam\"\n      required:\n        - id\n        - object\n        - usage_bytes\n        - created_at\n        - vector_store_id\n        - status\n        - last_error\n\n    staticChunkingStrategy:\n      type: object\n      additionalProperties: false\n      properties:\n        max_chunk_size_tokens:\n          type: integer\n          minimum: 100\n          maximum: 4096\n          description: |\n            The maximum number of tokens in each chunk. The default value is `800`.\n            The minimum value is `100` and the maximum value is `4096`.\n        chunk_overlap_tokens:\n          type: integer\n          description: >\n            The number of tokens that overlap between chunks. The default value is\n            `400`.\n            Note that the overlap must not exceed half of `max_chunk_size_tokens`.\n      required:\n        - max_chunk_size_tokens\n        - chunk_overlap_tokens\n\n    autoChunkingStrategyRequestParam:\n      type: object\n      title: Auto Chunking Strategy\n      description: |\n        The default strategy. This strategy currently uses a `max_chunk_size_tokens`\n        of `800` and `chunk_overlap_tokens` of `400`.\n      additionalProperties: false\n      properties:\n        type:\n          type: string\n          description: Always `auto`.\n          enum:\n            - auto\n      required:\n        - type\n\n    staticChunkingStrategyRequestParam:\n      type: object\n      title: Static Chunking Strategy\n      additionalProperties: false\n      properties:\n        type:\n          type: string\n          description: Always `static`.\n          enum:\n            - static\n        static:\n          $ref: \"#/components/schemas/staticChunkingStrategy\"\n      required:\n        - type\n        - static\n\n    chunkingStrategyRequestParam:\n      type: object\n      description: >-\n        The chunking strategy used to chunk the file(s). If not set, will use the\n        `auto` strategy.\n      oneOf:\n        - $ref: \"#/components/schemas/autoChunkingStrategyRequestParam\"\n        - $ref: \"#/components/schemas/staticChunkingStrategyRequestParam\"\n\n    createVectorStoreFileRequest:\n      type: object\n      additionalProperties: false\n      properties:\n        file_id:\n          description: A File ID that the vector store should use. Useful for tools like `file_search` that can access files.\n          type: string\n        chunking_strategy:\n          $ref: \"#/components/schemas/chunkingStrategyRequestParam\"\n      required:\n        - file_id\n\n    listVectorStoreFilesResponse:\n      properties:\n        object:\n          type: string\n          example: \"list\"\n        data:\n          type: array\n          items:\n            $ref: \"#/components/schemas/vectorStoreFileObject\"\n        first_id:\n          type: string\n          example: \"file-abc123\"\n        last_id:\n          type: string\n          example: \"file-abc456\"\n        has_more:\n          type: boolean\n          example: false\n      required:\n        - object\n        - data\n        - first_id\n        - last_id\n        - has_more\n\n    deleteVectorStoreFileResponse:\n      type: object\n      properties:\n        id:\n          type: string\n        deleted:\n          type: boolean\n        object:\n          type: string\n          enum: [vector_store.file.deleted]\n          x-ms-enum:\n            name: DeleteVectorStoreFileResponseObject\n            modelAsString: true\n            values:\n              - value: vector_store.file.deleted\n      required:\n        - id\n        - object\n        - deleted\n\n    vectorStoreFileBatchObject:\n      type: object\n      title: Vector store file batch\n      description: A batch of files attached to a vector store.\n      properties:\n        id:\n          description: The identifier, which can be referenced in API endpoints.\n          type: string\n        object:\n          description: The object type, which is always `vector_store.file_batch`.\n          type: string\n          enum: [\"vector_store.files_batch\"]\n          x-ms-enum:\n            name: VectorStoreFileBatchObjectType\n            modelAsString: true\n            values:\n              - value: vector_store.files_batch\n        created_at:\n          description: The Unix timestamp (in seconds) for when the vector store files batch was created.\n          type: integer\n        vector_store_id:\n          description: The ID of the vector store that the File is attached to.\n          type: string\n        status:\n          description: The status of the vector store files batch, which can be either `in_progress`, `completed`, `cancelled` or `failed`.\n          type: string\n          enum: [\"in_progress\", \"completed\", \"cancelled\", \"failed\"]\n          x-ms-enum:\n            name: VectorStoreFileBatchObjectStatus\n            modelAsString: true\n            values:\n              - value: in_progress\n              - value: completed\n              - value: cancelled\n              - value: failed\n        file_counts:\n          type: object\n          properties:\n            in_progress:\n              description: The number of files that are currently being processed.\n              type: integer\n            completed:\n              description: The number of files that have been processed.\n              type: integer\n            failed:\n              description: The number of files that have failed to process.\n              type: integer\n            cancelled:\n              description: The number of files that where cancelled.\n              type: integer\n            total:\n              description: The total number of files.\n              type: integer\n          required:\n            - in_progress\n            - completed\n            - cancelled\n            - failed\n            - total\n      required:\n        - id\n        - object\n        - created_at\n        - vector_store_id\n        - status\n        - file_counts\n\n    createVectorStoreFileBatchRequest:\n      type: object\n      additionalProperties: false\n      properties:\n        file_ids:\n          description: A list of File IDs that the vector store should use. Useful for tools like `file_search` that can access files.\n          type: array\n          minItems: 1\n          maxItems: 500\n          items:\n            type: string\n        chunking_strategy:\n          $ref: \"#/components/schemas/chunkingStrategyRequestParam\"\n      required:\n        - file_ids\n\n    Annotation:\n      oneOf:\n        - $ref: \"#/components/schemas/FileCitation\"\n        - $ref: \"#/components/schemas/UrlCitation\"\n        - $ref: \"#/components/schemas/FilePath\"\n\n    Click:\n      type: object\n      title: Click\n      description: |\n        A click action.\n      properties:\n        type:\n          type: string\n          enum:\n            - click\n          default: click\n          description: |\n            Specifies the event type. For a click action, this property is \n            always set to `click`.\n          x-stainless-const: true\n        button:\n          type: string\n          enum:\n            - left\n            - right\n            - wheel\n            - back\n            - forward\n          description: >\n            Indicates which mouse button was pressed during the click. One of\n            `left`, `right`, `wheel`, `back`, or `forward`.\n        x:\n          type: integer\n          description: |\n            The x-coordinate where the click occurred.\n        y:\n          type: integer\n          description: |\n            The y-coordinate where the click occurred.\n      required:\n        - type\n        - button\n        - x\n        - y\n    CodeInterpreterFileOutput:\n      type: object\n      title: Code interpreter file output\n      description: |\n        The output of a code interpreter tool call that is a file.\n      properties:\n        type:\n          type: string\n          enum:\n            - files\n          description: |\n            The type of the code interpreter file output. Always `files`.\n          x-stainless-const: true\n        files:\n          type: array\n          items:\n            type: object\n            properties:\n              mime_type:\n                type: string\n                description: |\n                  The MIME type of the file.\n              file_id:\n                type: string\n                description: |\n                  The ID of the file.\n            required:\n              - mime_type\n              - file_id\n      required:\n        - type\n        - files\n    CodeInterpreterTextOutput:\n      type: object\n      title: Code interpreter text output\n      description: |\n        The output of a code interpreter tool call that is text.\n      properties:\n        type:\n          type: string\n          enum:\n            - logs\n          description: |\n            The type of the code interpreter text output. Always `logs`.\n          x-stainless-const: true\n        logs:\n          type: string\n          description: |\n            The logs of the code interpreter tool call.\n      required:\n        - type\n        - logs\n    CodeInterpreterToolCall:\n      type: object\n      title: Code interpreter tool call\n      description: |\n        A tool call to run code.\n      properties:\n        id:\n          type: string\n          description: |\n            The unique ID of the code interpreter tool call.\n        type:\n          type: string\n          enum:\n            - code_interpreter_call\n          description: >\n            The type of the code interpreter tool call. Always\n            `code_interpreter_call`.\n          x-stainless-const: true\n        code:\n          type: string\n          description: |\n            The code to run.\n        status:\n          type: string\n          enum:\n            - in_progress\n            - interpreting\n            - completed\n          description: |\n            The status of the code interpreter tool call.\n        results:\n          type: array\n          items:\n            x-oaiExpandable: true\n            $ref: \"#/components/schemas/CodeInterpreterToolOutput\"\n          description: |\n            The results of the code interpreter tool call.\n      required:\n        - id\n        - type\n        - code\n        - status\n        - results\n    CodeInterpreterToolOutput:\n      oneOf:\n        - $ref: \"#/components/schemas/CodeInterpreterTextOutput\"\n        - $ref: \"#/components/schemas/CodeInterpreterFileOutput\"\n    ComparisonFilter:\n      type: object\n      additionalProperties: false\n      title: Comparison Filter\n      description: >\n        A filter used to compare a specified attribute key to a given value\n        using a defined comparison operation.\n      properties:\n        type:\n          type: string\n          default: eq\n          enum:\n            - eq\n            - ne\n            - gt\n            - gte\n            - lt\n            - lte\n          description: >\n            Specifies the comparison operator: `eq`, `ne`, `gt`, `gte`, `lt`,\n            `lte`.\n\n            - `eq`: equals\n\n            - `ne`: not equal\n\n            - `gt`: greater than\n\n            - `gte`: greater than or equal\n\n            - `lt`: less than\n\n            - `lte`: less than or equal\n        key:\n          type: string\n          description: The key to compare against the value.\n        value:\n          oneOf:\n            - type: string\n            - type: number\n            - type: boolean\n          description: The value to compare against the attribute key; supports string,\n            number, or boolean types.\n      required:\n        - type\n        - key\n        - value\n      x-oaiMeta:\n        name: ComparisonFilter\n\n    CompoundFilter:\n      $recursiveAnchor: true\n      type: object\n      additionalProperties: false\n      title: Compound Filter\n      description: Combine multiple filters using `and` or `or`.\n      properties:\n        type:\n          type: string\n          description: \"Type of operation: `and` or `or`.\"\n          enum:\n            - and\n            - or\n        filters:\n          type: array\n          description: Array of filters to combine. Items can be `ComparisonFilter` or\n            `CompoundFilter`.\n          items:\n            oneOf:\n              - $ref: \"#/components/schemas/ComparisonFilter\"\n              - $recursiveRef: \"#\"\n      required:\n        - type\n        - filters\n      x-oaiMeta:\n        name: CompoundFilter\n    ComputerAction:\n      oneOf:\n        - $ref: \"#/components/schemas/Click\"\n        - $ref: \"#/components/schemas/DoubleClick\"\n        - $ref: \"#/components/schemas/Drag\"\n        - $ref: \"#/components/schemas/KeyPress\"\n        - $ref: \"#/components/schemas/Move\"\n        - $ref: \"#/components/schemas/Screenshot\"\n        - $ref: \"#/components/schemas/Scroll\"\n        - $ref: \"#/components/schemas/Type\"\n        - $ref: \"#/components/schemas/Wait\"\n    ComputerScreenshotImage:\n      type: object\n      description: |\n        A computer screenshot image used with the computer use tool.\n      properties:\n        type:\n          type: string\n          enum:\n            - computer_screenshot\n          default: computer_screenshot\n          description: >\n            Specifies the event type. For a computer screenshot, this property\n            is \n\n            always set to `computer_screenshot`.\n          x-stainless-const: true\n        image_url:\n          type: string\n          description: The URL of the screenshot image.\n        file_id:\n          type: string\n          description: The identifier of an uploaded file that contains the screenshot.\n      required:\n        - type\n    ComputerTool:\n      type: object\n      title: Computer use\n      description: |\n        A tool that controls a virtual computer. Learn more about the \n        [computer tool](/docs/guides/tools-computer-use).\n      properties:\n        type:\n          type: string\n          enum:\n            - computer-preview\n          description: |\n            The type of the computer use tool. Always `computer_use_preview`.\n          x-stainless-const: true\n        display_width:\n          type: number\n          description: |\n            The width of the computer display.\n        display_height:\n          type: number\n          description: |\n            The height of the computer display.\n        environment:\n          type: string\n          description: |\n            The type of computer environment to control.\n          enum:\n            - mac\n            - windows\n            - ubuntu\n            - browser\n      required:\n        - type\n        - display_width\n        - display_height\n        - environment\n    ComputerToolCall:\n      type: object\n      title: Computer tool call\n      description: >\n        A tool call to a computer use tool. See the \n\n        [computer use guide](/docs/guides/tools-computer-use) for more\n        information.\n      properties:\n        type:\n          type: string\n          description: The type of the computer call. Always `computer_call`.\n          enum:\n            - computer_call\n          default: computer_call\n        id:\n          type: string\n          description: The unique ID of the computer call.\n        call_id:\n          type: string\n          description: |\n            An identifier used when responding to the tool call with output.\n        action:\n          $ref: \"#/components/schemas/ComputerAction\"\n          x-oaiExpandable: true\n        pending_safety_checks:\n          type: array\n          x-oaiExpandable: true\n          items:\n            $ref: \"#/components/schemas/ComputerToolCallSafetyCheck\"\n          description: |\n            The pending safety checks for the computer call.\n        status:\n          type: string\n          description: |\n            The status of the item. One of `in_progress`, `completed`, or\n            `incomplete`. Populated when items are returned via API.\n          enum:\n            - in_progress\n            - completed\n            - incomplete\n      required:\n        - type\n        - id\n        - action\n        - call_id\n        - pending_safety_checks\n        - status\n    ComputerToolCallOutput:\n      type: object\n      title: Computer tool call output\n      description: |\n        The output of a computer tool call.\n      properties:\n        type:\n          type: string\n          description: >\n            The type of the computer tool call output. Always\n            `computer_call_output`.\n          enum:\n            - computer_call_output\n          default: computer_call_output\n          x-stainless-const: true\n        id:\n          type: string\n          description: |\n            The ID of the computer tool call output.\n        call_id:\n          type: string\n          description: |\n            The ID of the computer tool call that produced the output.\n        acknowledged_safety_checks:\n          type: array\n          x-oaiExpandable: true\n          description: >\n            The safety checks reported by the API that have been acknowledged by\n            the \n\n            developer.\n          items:\n            $ref: \"#/components/schemas/ComputerToolCallSafetyCheck\"\n        output:\n          $ref: \"#/components/schemas/ComputerScreenshotImage\"\n        status:\n          type: string\n          description: >\n            The status of the message input. One of `in_progress`, `completed`,\n            or\n\n            `incomplete`. Populated when input items are returned via API.\n          enum:\n            - in_progress\n            - completed\n            - incomplete\n      required:\n        - type\n        - call_id\n        - output\n    ComputerToolCallOutputResource:\n      allOf:\n        - $ref: \"#/components/schemas/ComputerToolCallOutput\"\n        - type: object\n          properties:\n            id:\n              type: string\n              description: |\n                The unique ID of the computer call tool output.\n          required:\n            - id\n    ComputerToolCallSafetyCheck:\n      type: object\n      description: |\n        A pending safety check for the computer call.\n      properties:\n        id:\n          type: string\n          description: The ID of the pending safety check.\n        code:\n          type: string\n          description: The type of the pending safety check.\n        message:\n          type: string\n          description: Details about the pending safety check.\n      required:\n        - id\n        - code\n        - message\n    Coordinate:\n      type: object\n      title: Coordinate\n      description: |\n        An x/y coordinate pair, e.g. `{ x: 100, y: 200 }`.\n      properties:\n        x:\n          type: integer\n          description: |\n            The x-coordinate.\n        y:\n          type: integer\n          description: |\n            The y-coordinate.\n      required:\n        - x\n        - y\n\n    CreateModelResponseProperties:\n      allOf:\n        - $ref: \"#/components/schemas/ModelResponseProperties\"\n\n    createResponse:\n      allOf:\n        - $ref: \"#/components/schemas/CreateModelResponseProperties\"\n        - $ref: \"#/components/schemas/ResponseProperties\"\n        - type: object\n          properties:\n            input:\n              description: >\n                Text, image, or file inputs to the model, used to generate a\n                response.\n\n\n                Learn more:\n\n                - [Text inputs and outputs](/docs/guides/text)\n\n                - [Image inputs](/docs/guides/images)\n\n                - [File inputs](/docs/guides/pdf-files)\n\n                - [Conversation state](/docs/guides/conversation-state)\n\n                - [Function calling](/docs/guides/function-calling)\n              x-oaiExpandable: true\n              oneOf:\n                - type: string\n                  title: Text input\n                  description: >\n                    A text input to the model, equivalent to a text input with\n                    the \n\n                    `user` role.\n                - type: array\n                  title: Input item list\n                  description: |\n                    A list of one or many input items to the model, containing \n                    different content types.\n                  items:\n                    x-oaiExpandable: true\n                    $ref: \"#/components/schemas/InputItem\"\n            include:\n              type: array\n              items:\n                x-oaiExpandable: true\n                $ref: \"#/components/schemas/includable\"\n              nullable: true\n            parallel_tool_calls:\n              type: boolean\n              description: |\n                Whether to allow the model to run tool calls in parallel.\n              default: true\n              nullable: true\n            store:\n              type: boolean\n              description: >\n                Whether to store the generated model response for later\n                retrieval via\n\n                API.\n              default: true\n              nullable: true\n            stream:\n              description: >\n                If set to true, the model response data will be streamed to the\n                client\n\n                as it is generated using [server-sent\n                events](https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events/Using_server-sent_events#Event_stream_format).\n\n                See the [Streaming section\n                below](/docs/api-reference/responses-streaming)\n\n                for more information.\n              type: boolean\n              nullable: true\n              default: false\n          required:\n            - model\n            - input\n\n    DoubleClick:\n      type: object\n      title: DoubleClick\n      description: |\n        A double click action.\n      properties:\n        type:\n          type: string\n          enum:\n            - double_click\n          default: double_click\n          description: >\n            Specifies the event type. For a double click action, this property\n            is \n\n            always set to `double_click`.\n          x-stainless-const: true\n        x:\n          type: integer\n          description: |\n            The x-coordinate where the double click occurred.\n        y:\n          type: integer\n          description: |\n            The y-coordinate where the double click occurred.\n      required:\n        - type\n        - x\n        - y\n    Drag:\n      type: object\n      title: Drag\n      description: |\n        A drag action.\n      properties:\n        type:\n          type: string\n          enum:\n            - drag\n          default: drag\n          description: |\n            Specifies the event type. For a drag action, this property is \n            always set to `drag`.\n          x-stainless-const: true\n        path:\n          type: array\n          description: >\n            An array of coordinates representing the path of the drag action.\n            Coordinates will appear as an array\n\n            of objects, eg\n\n            ```\n\n            [\n              { x: 100, y: 200 },\n              { x: 200, y: 300 }\n            ]\n\n            ```\n          x-oaiExpandable: true\n          items:\n            title: Drag path coordinates\n            x-oaiExpandable: true\n            description: |\n              A series of x/y coordinate pairs in the drag path.\n            $ref: \"#/components/schemas/Coordinate\"\n      required:\n        - type\n        - path\n    EasyInputMessage:\n      type: object\n      title: Input message\n      description: >\n        A message input to the model with a role indicating instruction\n        following\n\n        hierarchy. Instructions given with the `developer` or `system` role take\n\n        precedence over instructions given with the `user` role. Messages with\n        the\n\n        `assistant` role are presumed to have been generated by the model in\n        previous\n\n        interactions.\n      properties:\n        role:\n          type: string\n          description: >\n            The role of the message input. One of `user`, `assistant`, `system`,\n            or\n\n            `developer`.\n          enum:\n            - user\n            - assistant\n            - system\n            - developer\n        content:\n          description: >\n            Text, image, or audio input to the model, used to generate a\n            response.\n\n            Can also contain previous assistant responses.\n          x-oaiExpandable: true\n          oneOf:\n            - type: string\n              title: Text input\n              description: |\n                A text input to the model.\n            - $ref: \"#/components/schemas/InputMessageContentList\"\n        type:\n          type: string\n          description: |\n            The type of the message input. Always `message`.\n          enum:\n            - message\n          x-stainless-const: true\n      required:\n        - role\n        - content\n\n    FileCitation:\n      type: object\n      title: File citation\n      description: |\n        A citation to a file.\n      properties:\n        type:\n          type: string\n          description: |\n            The type of the file citation. Always `file_citation`.\n          enum:\n            - file_citation\n          x-stainless-const: true\n        index:\n          type: integer\n          description: |\n            The index of the file in the list of files.\n        file_id:\n          type: string\n          description: |\n            The ID of the file.\n      required:\n        - type\n        - index\n        - file_id\n    FilePath:\n      type: object\n      title: File path\n      description: |\n        A path to a file.\n      properties:\n        type:\n          type: string\n          description: |\n            The type of the file path. Always `file_path`.\n          enum:\n            - file_path\n          x-stainless-const: true\n        file_id:\n          type: string\n          description: |\n            The ID of the file.\n        index:\n          type: integer\n          description: |\n            The index of the file in the list of files.\n      required:\n        - type\n        - file_id\n        - index\n\n    FileSearchTool:\n      type: object\n      title: File search\n      description: |\n        A tool that searches for relevant content from uploaded files.\n        Learn more about the [file search tool](/docs/guides/tools-file-search).\n      properties:\n        type:\n          type: string\n          enum:\n            - file_search\n          description: |\n            The type of the file search tool. Always `file_search`.\n          x-stainless-const: true\n        vector_store_ids:\n          type: array\n          items:\n            type: string\n          description: |\n            The IDs of the vector stores to search.\n        max_num_results:\n          type: integer\n          description: >\n            The maximum number of results to return. This number should be\n            between 1 \n\n            and 50 inclusive.\n        filters:\n          description: A filter to apply based on file attributes.\n          oneOf:\n            - $ref: \"#/components/schemas/ComparisonFilter\"\n            - $ref: \"#/components/schemas/CompoundFilter\"\n          x-oaiExpandable: true\n        ranking_options:\n          description: Ranking options for search.\n          type: object\n          additionalProperties: false\n          properties:\n            ranker:\n              type: string\n              description: The ranker to use for the file search.\n              enum:\n                - auto\n                - default-2024-11-15\n              default: auto\n            score_threshold:\n              type: number\n              description: >\n                The score threshold for the file search, a number between 0 and\n                1.\n\n                Numbers closer to 1 will attempt to return only the most\n                relevant\n\n                results, but may return fewer results.\n              minimum: 0\n              maximum: 1\n              default: 0\n      required:\n        - type\n        - vector_store_ids\n    FileSearchToolCall:\n      type: object\n      title: File search tool call\n      description: >\n        The results of a file search tool call. See the \n\n        [file search guide](/docs/guides/tools-file-search) for more\n        information.\n      properties:\n        id:\n          type: string\n          description: |\n            The unique ID of the file search tool call.\n        type:\n          type: string\n          enum:\n            - file_search_call\n          description: |\n            The type of the file search tool call. Always `file_search_call`.\n          x-stainless-const: true\n        status:\n          type: string\n          description: |\n            The status of the file search tool call. One of `in_progress`, \n            `searching`, `incomplete` or `failed`,\n          enum:\n            - in_progress\n            - searching\n            - completed\n            - incomplete\n            - failed\n        queries:\n          type: array\n          items:\n            type: string\n          description: |\n            The queries used to search for files.\n        results:\n          type: array\n          description: |\n            The results of the file search tool call.\n          items:\n            type: object\n            properties:\n              file_id:\n                type: string\n                description: |\n                  The unique ID of the file.\n              text:\n                type: string\n                description: |\n                  The text that was retrieved from the file.\n              filename:\n                type: string\n                description: |\n                  The name of the file.\n              attributes:\n                $ref: \"#/components/schemas/VectorStoreFileAttributes\"\n              score:\n                type: number\n                format: float\n                description: |\n                  The relevance score of the file - a value between 0 and 1.\n          nullable: true\n      required:\n        - id\n        - type\n        - status\n        - queries\n\n    FunctionTool:\n      type: object\n      title: Function\n      description: >\n        Defines a function in your own code the model can choose to call. Learn\n        more\n\n        about [function calling](/docs/guides/function-calling).\n      properties:\n        type:\n          type: string\n          enum:\n            - function\n          description: |\n            The type of the function tool. Always `function`.\n          x-stainless-const: true\n        name:\n          type: string\n          description: |\n            The name of the function to call.\n        description:\n          type: string\n          nullable: true\n          description: >\n            A description of the function. Used by the model to determine\n            whether\n\n            or not to call the function.\n        parameters:\n          type: object\n          description: |\n            A JSON schema object describing the parameters of the function.\n          additionalProperties: true\n        strict:\n          type: boolean\n          description: |\n            Whether to enforce strict parameter validation. Default `true`.\n      required:\n        - type\n        - name\n        - parameters\n        - strict\n    FunctionToolCall:\n      type: object\n      title: Function tool call\n      description: >\n        A tool call to run a function. See the \n\n        [function calling guide](/docs/guides/function-calling) for more\n        information.\n      properties:\n        id:\n          type: string\n          description: |\n            The unique ID of the function tool call.\n        type:\n          type: string\n          enum:\n            - function_call\n          description: |\n            The type of the function tool call. Always `function_call`.\n          x-stainless-const: true\n        call_id:\n          type: string\n          description: |\n            The unique ID of the function tool call generated by the model.\n        name:\n          type: string\n          description: |\n            The name of the function to run.\n        arguments:\n          type: string\n          description: |\n            A JSON string of the arguments to pass to the function.\n        status:\n          type: string\n          description: |\n            The status of the item. One of `in_progress`, `completed`, or\n            `incomplete`. Populated when items are returned via API.\n          enum:\n            - in_progress\n            - completed\n            - incomplete\n      required:\n        - id\n        - type\n        - call_id\n        - name\n        - arguments\n    FunctionToolCallOutput:\n      type: object\n      title: Function tool call output\n      description: |\n        The output of a function tool call.\n      properties:\n        id:\n          type: string\n          description: >\n            The unique ID of the function tool call output. Populated when this\n            item\n\n            is returned via API.\n        type:\n          type: string\n          enum:\n            - function_call_output\n          description: >\n            The type of the function tool call output. Always\n            `function_call_output`.\n          x-stainless-const: true\n        call_id:\n          type: string\n          description: |\n            The unique ID of the function tool call generated by the model.\n        output:\n          type: string\n          description: |\n            A JSON string of the output of the function tool call.\n        status:\n          type: string\n          description: |\n            The status of the item. One of `in_progress`, `completed`, or\n            `incomplete`. Populated when items are returned via API.\n          enum:\n            - in_progress\n            - completed\n            - incomplete\n      required:\n        - type\n        - call_id\n        - output\n    FunctionToolCallOutputResource:\n      allOf:\n        - $ref: \"#/components/schemas/FunctionToolCallOutput\"\n        - type: object\n          properties:\n            id:\n              type: string\n              description: |\n                The unique ID of the function call tool output.\n          required:\n            - id\n\n    includable:\n      type: string\n      description: >\n        Specify additional output data to include in the model response.\n        Currently\n\n        supported values are:\n\n        - `file_search_call.results`: Include the search results of\n          the file search tool call.\n        - `message.input_image.image_url`: Include image urls from the input\n        message.\n\n        - `computer_call_output.output.image_url`: Include image urls from the\n        computer call output.\n      enum:\n        - file_search_call.results\n        - message.input_image.image_url\n        - computer_call_output.output.image_url\n    InputContent:\n      oneOf:\n        - $ref: \"#/components/schemas/InputText\"\n        - $ref: \"#/components/schemas/InputImage\"\n        - $ref: \"#/components/schemas/InputFile\"\n      x-oaiExpandable: true\n    InputFile:\n      type: object\n      title: File input\n      description: |\n        A file input to the model.\n      properties:\n        type:\n          type: string\n          description: |\n            The type of the input item. Always `input_file`.\n          enum:\n            - input_file\n          x-stainless-const: true\n        file_id:\n          type: string\n          description: |\n            The ID of the file to be sent to the model.\n        filename:\n          type: string\n          description: |\n            The name of the file to be sent to the model.\n        file_data:\n          type: string\n          description: |\n            The content of the file to be sent to the model.\n      required:\n        - type\n    InputImage:\n      type: object\n      title: Image input\n      description: >\n        An image input to the model. Learn about [image\n        inputs](/docs/guides/vision).\n      properties:\n        type:\n          type: string\n          description: |\n            The type of the input item. Always `input_image`.\n          enum:\n            - input_image\n          x-stainless-const: true\n        image_url:\n          type: string\n          description: >\n            The URL of the image to be sent to the model. A fully qualified URL\n            or\n\n            base64 encoded image in a data URL.\n          nullable: true\n        file_id:\n          type: string\n          description: |\n            The ID of the file to be sent to the model.\n          nullable: true\n        detail:\n          type: string\n          description: >\n            The detail level of the image to be sent to the model. One of\n            `high`,\n\n            `low`, or `auto`. Defaults to `auto`.\n          enum:\n            - high\n            - low\n            - auto\n          default: auto\n      required:\n        - type\n        - detail\n    InputItem:\n      oneOf:\n        - $ref: \"#/components/schemas/EasyInputMessage\"\n        - type: object\n          title: Item\n          description: |\n            An item representing part of the context for the response to be \n            generated by the model. Can contain text, images, and audio inputs,\n            as well as previous assistant responses and tool call outputs.\n          $ref: \"#/components/schemas/Item\"\n        - $ref: \"#/components/schemas/ItemReference\"\n      discriminator:\n        propertyName: type\n    InputMessage:\n      type: object\n      title: Input message\n      description: >\n        A message input to the model with a role indicating instruction\n        following\n\n        hierarchy. Instructions given with the `developer` or `system` role take\n\n        precedence over instructions given with the `user` role.\n      properties:\n        type:\n          type: string\n          description: |\n            The type of the message input. Always set to `message`.\n          enum:\n            - message\n          x-stainless-const: true\n        role:\n          type: string\n          description: >\n            The role of the message input. One of `user`, `system`, or\n            `developer`.\n          enum:\n            - user\n            - system\n            - developer\n        status:\n          type: string\n          description: |\n            The status of item. One of `in_progress`, `completed`, or\n            `incomplete`. Populated when items are returned via API.\n          enum:\n            - in_progress\n            - completed\n            - incomplete\n        content:\n          $ref: \"#/components/schemas/InputMessageContentList\"\n      required:\n        - role\n        - content\n    InputMessageContentList:\n      type: array\n      title: Input item content list\n      description: >\n        A list of one or many input items to the model, containing different\n        content \n\n        types.\n      x-oaiExpandable: true\n      items:\n        x-oaiExpandable: true\n        $ref: \"#/components/schemas/InputContent\"\n    InputMessageResource:\n      allOf:\n        - $ref: \"#/components/schemas/InputMessage\"\n        - type: object\n          properties:\n            id:\n              type: string\n              description: |\n                The unique ID of the message input.\n          required:\n            - id\n    InputText:\n      type: object\n      title: Text input\n      description: |\n        A text input to the model.\n      properties:\n        type:\n          type: string\n          description: |\n            The type of the input item. Always `input_text`.\n          enum:\n            - input_text\n          x-stainless-const: true\n        text:\n          type: string\n          description: |\n            The text input to the model.\n      required:\n        - type\n        - text\n\n    Item:\n      type: object\n      description: |\n        Content item used to generate a response.\n      oneOf:\n        - $ref: \"#/components/schemas/InputMessage\"\n        - $ref: \"#/components/schemas/OutputMessage\"\n        - $ref: \"#/components/schemas/FileSearchToolCall\"\n        - $ref: \"#/components/schemas/ComputerToolCall\"\n        - $ref: \"#/components/schemas/ComputerToolCallOutput\"\n        - $ref: \"#/components/schemas/FunctionToolCall\"\n        - $ref: \"#/components/schemas/FunctionToolCallOutput\"\n        - $ref: \"#/components/schemas/ReasoningItem\"\n      x-oaiExpandable: true\n      discriminator:\n        propertyName: type\n    ItemReference:\n      type: object\n      title: Item reference\n      description: |\n        An internal identifier for an item to reference.\n      properties:\n        id:\n          type: string\n          description: |\n            The ID of the item to reference.\n        type:\n          type: string\n          description: |\n            The type of item to reference. Always `item_reference`.\n          enum:\n            - item_reference\n          x-stainless-const: true\n      required:\n        - id\n        - type\n    ItemResource:\n      description: |\n        Content item used to generate a response.\n      oneOf:\n        - $ref: \"#/components/schemas/InputMessageResource\"\n        - $ref: \"#/components/schemas/OutputMessage\"\n        - $ref: \"#/components/schemas/FileSearchToolCall\"\n        - $ref: \"#/components/schemas/ComputerToolCall\"\n        - $ref: \"#/components/schemas/ComputerToolCallOutputResource\"\n        - $ref: \"#/components/schemas/FunctionToolCall\"\n        - $ref: \"#/components/schemas/FunctionToolCallOutputResource\"\n      x-oaiExpandable: true\n      discriminator:\n        propertyName: type\n    KeyPress:\n      type: object\n      title: KeyPress\n      description: |\n        A collection of keypresses the model would like to perform.\n      properties:\n        type:\n          type: string\n          enum:\n            - keypress\n          default: keypress\n          description: |\n            Specifies the event type. For a keypress action, this property is \n            always set to `keypress`.\n          x-stainless-const: true\n        keys:\n          type: array\n          items:\n            type: string\n            description: |\n              One of the keys the model is requesting to be pressed.\n          description: >\n            The combination of keys the model is requesting to be pressed. This\n            is an\n\n            array of strings, each representing a key.\n      required:\n        - type\n        - keys\n\n    Metadata:\n      type: object\n      description: >\n        Set of 16 key-value pairs that can be attached to an object. This can be\n\n        useful for storing additional information about the object in a\n        structured\n\n        format, and querying for objects via API or the dashboard. \n\n\n        Keys are strings with a maximum length of 64 characters. Values are\n        strings\n\n        with a maximum length of 512 characters.\n      additionalProperties:\n        type: string\n      x-oaiTypeLabel: map\n      nullable: true\n\n    ModelResponseProperties:\n      type: object\n      properties:\n        model:\n          type: string\n          description: Model used to generate the responses.\n        metadata:\n          $ref: \"#/components/schemas/Metadata\"\n        temperature:\n          type: number\n          minimum: 0\n          maximum: 2\n          default: 1\n          example: 1\n          nullable: true\n          description: >\n            What sampling temperature to use, between 0 and 2. Higher values\n            like 0.8 will make the output more random, while lower values like\n            0.2 will make it more focused and deterministic.\n\n            We generally recommend altering this or `top_p` but not both.\n        top_p:\n          type: number\n          minimum: 0\n          maximum: 1\n          default: 1\n          example: 1\n          nullable: true\n          description: >\n            An alternative to sampling with temperature, called nucleus\n            sampling,\n\n            where the model considers the results of the tokens with top_p\n            probability\n\n            mass. So 0.1 means only the tokens comprising the top 10%\n            probability mass\n\n            are considered.\n\n\n            We generally recommend altering this or `temperature` but not both.\n        user:\n          type: string\n          example: user-1234\n          description: >\n            A unique identifier representing your end-user, which can help\n            OpenAI to monitor and detect abuse. [Learn\n            more](/docs/guides/safety-best-practices#end-user-ids).\n\n    Move:\n      type: object\n      title: Move\n      description: |\n        A mouse move action.\n      properties:\n        type:\n          type: string\n          enum:\n            - move\n          default: move\n          description: |\n            Specifies the event type. For a move action, this property is \n            always set to `move`.\n          x-stainless-const: true\n        x:\n          type: integer\n          description: |\n            The x-coordinate to move to.\n        y:\n          type: integer\n          description: |\n            The y-coordinate to move to.\n      required:\n        - type\n        - x\n        - y\n    OutputContent:\n      oneOf:\n        - $ref: \"#/components/schemas/OutputText\"\n        - $ref: \"#/components/schemas/Refusal\"\n    OutputItem:\n      anyOf:\n        - $ref: \"#/components/schemas/OutputMessage\"\n        - $ref: \"#/components/schemas/FileSearchToolCall\"\n        - $ref: \"#/components/schemas/FunctionToolCall\"\n        - $ref: \"#/components/schemas/ComputerToolCall\"\n        - $ref: \"#/components/schemas/ReasoningItem\"\n      x-oaiExpandable: true\n      discriminator:\n        propertyName: type\n    OutputMessage:\n      type: object\n      title: Output message\n      description: |\n        An output message from the model.\n      properties:\n        id:\n          type: string\n          description: |\n            The unique ID of the output message.\n        type:\n          type: string\n          description: |\n            The type of the output message. Always `message`.\n          enum:\n            - message\n          x-stainless-const: true\n        role:\n          type: string\n          description: |\n            The role of the output message. Always `assistant`.\n          enum:\n            - assistant\n          x-stainless-const: true\n        content:\n          type: array\n          description: |\n            The content of the output message.\n          x-oaiExpandable: true\n          items:\n            x-oaiExpandable: true\n            $ref: \"#/components/schemas/OutputContent\"\n        status:\n          type: string\n          description: >\n            The status of the message input. One of `in_progress`, `completed`,\n            or\n\n            `incomplete`. Populated when input items are returned via API.\n          enum:\n            - in_progress\n            - completed\n            - incomplete\n      required:\n        - id\n        - type\n        - role\n        - content\n        - status\n    OutputText:\n      type: object\n      title: Output text\n      description: |\n        A text output from the model.\n      properties:\n        type:\n          type: string\n          description: |\n            The type of the output text. Always `output_text`.\n          enum:\n            - output_text\n          x-stainless-const: true\n        text:\n          type: string\n          description: |\n            The text output from the model.\n        annotations:\n          type: array\n          description: |\n            The annotations of the text output.\n          items:\n            x-oaiExpandable: true\n            $ref: \"#/components/schemas/Annotation\"\n      required:\n        - type\n        - text\n        - annotations\n    RealtimeSessionCreateRequest:\n      type: object\n      description: Realtime session object configuration.\n      properties:\n        modalities:\n          description: |\n            The set of modalities the model can respond with. To disable audio,\n            set this to [\"text\"].\n          items:\n            type: string\n            default:\n              - text\n              - audio\n            enum:\n              - text\n              - audio\n        model:\n          type: string\n          description: |\n            The name of the deployment used for this session.\n        instructions:\n          type: string\n          description: >\n            The default system instructions (i.e. system message) prepended to\n            model calls. This field allows the client to guide the model on\n            desired responses. The model can be instructed on response content\n            and format, (e.g. \"be extremely succinct\", \"act friendly\", \"here\n            are examples of good  responses\") and on audio behavior (e.g. \"talk\n            quickly\", \"inject emotion into your voice\", \"laugh frequently\").\n            The instructions are not guaranteed to be followed by the model,\n            but they provide guidance to the model on the desired behavior.\n\n\n            Note that the server sets default instructions which will be used if\n            this  field is not set and are visible in the `session.created`\n            event at the  start of the session.\n        voice:\n          $ref: \"#/components/schemas/VoiceIdsShared\"\n          description: >\n            The voice the model uses to respond. Voice cannot be changed during\n            the session once the model has responded with audio at least once.\n            Current voice options are `alloy`, `ash`, `ballad`, `coral`, `echo`,\n            `fable`, `onyx`, `nova`, `sage`, `shimmer`, and `verse`.\n        input_audio_format:\n          type: string\n          default: pcm16\n          enum:\n            - pcm16\n            - g711_ulaw\n            - g711_alaw\n          description: >\n            The format of input audio. Options are `pcm16`, `g711_ulaw`, or\n            `g711_alaw`.\n\n            For `pcm16`, input audio must be 16-bit PCM at a 24kHz sample rate, \n            single channel (mono), and little-endian byte order.\n        output_audio_format:\n          type: string\n          default: pcm16\n          enum:\n            - pcm16\n            - g711_ulaw\n            - g711_alaw\n          description: >\n            The format of output audio. Options are `pcm16`, `g711_ulaw`, or\n            `g711_alaw`.\n\n            For `pcm16`, output audio is sampled at a rate of 24kHz.\n        input_audio_transcription:\n          type: object\n          description: >\n            Configuration for input audio transcription, defaults to off and can\n            be set to `null` to turn off once on. Input audio transcription is\n            not native to the model, since the model consumes audio directly.\n            Transcription runs asynchronously through [the Transcriptions\n            endpoint](https://learn.microsoft.com/en-us/azure/ai-services/openai/reference-preview#transcriptions---create)\n            and should be treated as guidance of input audio content rather than\n            precisely what the model heard. The client can optionally set the\n            language and prompt for transcription, these offer additional\n            guidance to the transcription service.\n          properties:\n            model:\n              type: string\n              description: >\n                The model to use for transcription, current options are\n                `gpt-4o-transcribe`, `gpt-4o-mini-transcribe`, and `whisper-1`.\n            language:\n              type: string\n              description: >\n                The language of the input audio. Supplying the input language in\n\n                [ISO-639-1](https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes)\n                (e.g. `en`) format will improve accuracy and latency.\n            prompt:\n              type: string\n              description: >\n                An optional text to guide the model\'s style or continue a\n                previous audio segment.\n\n                For `whisper-1`, the [prompt is a list of\n                keywords](/docs/guides/speech-to-text#prompting).\n\n                For `gpt-4o-transcribe` models, the prompt is a free text\n                string, for example \"expect words related to technology\".\n        turn_detection:\n          type: object\n          description: >\n            Configuration for turn detection, ether Server VAD or Semantic VAD.\n            This can be set to `null` to turn off, in which case the client must\n            manually trigger model response.\n\n            Server VAD means that the model will detect the start and end of\n            speech based on audio volume and respond at the end of user speech.\n\n            Semantic VAD is more advanced and uses a turn detection model (in\n            conjunction with VAD) to semantically estimate whether the user has\n            finished speaking, then dynamically sets a timeout based on this\n            probability. For example, if user audio trails off with \"uhhm\", the\n            model will score a low probability of turn end and wait longer for\n            the user to continue speaking. This can be useful for more natural\n            conversations, but may have a higher latency.\n          properties:\n            type:\n              type: string\n              default: server_vad\n              enum:\n                - server_vad\n                - semantic_vad\n              description: |\n                Type of turn detection.\n            eagerness:\n              type: string\n              default: auto\n              enum:\n                - low\n                - medium\n                - high\n                - auto\n              description: >\n                Used only for `semantic_vad` mode. The eagerness of the model to\n                respond. `low` will wait longer for the user to continue\n                speaking, `high` will respond more quickly. `auto` is the\n                default and is equivalent to `medium`.\n            threshold:\n              type: number\n              description: >\n                Used only for `server_vad` mode. Activation threshold for VAD\n                (0.0 to 1.0), this defaults to 0.5. A higher threshold will require\n                louder audio to activate the model, and thus might perform better in\n                noisy environments.\n            prefix_padding_ms:\n              type: integer\n              description: >\n                Used only for `server_vad` mode. Amount of audio to include\n                before the VAD detected speech (in \n\n                milliseconds). Defaults to 300ms.\n            silence_duration_ms:\n              type: integer\n              description: >\n                Used only for `server_vad` mode. Duration of silence to detect\n                speech stop (in milliseconds). Defaults \n\n                to 500ms. With shorter values the model will respond more\n                quickly, \n\n                but may jump in on short pauses from the user.\n            create_response:\n              type: boolean\n              default: true\n              description: >\n                Whether or not to automatically generate a response when a VAD\n                stop event occurs.\n            interrupt_response:\n              type: boolean\n              default: true\n              description: >\n                Whether or not to automatically interrupt any ongoing response\n                with output to the default\n\n                conversation (i.e. `conversation` of `auto`) when a VAD start\n                event occurs.\n        input_audio_noise_reduction:\n          type: object\n          default: null\n          description: >\n            Configuration for input audio noise reduction. This can be set to\n            `null` to turn off.\n\n            Noise reduction filters audio added to the input audio buffer before\n            it is sent to VAD and the model.\n\n            Filtering the audio can improve VAD and turn detection accuracy\n            (reducing false positives) and model performance by improving\n            perception of the input audio.\n          properties:\n            type:\n              type: string\n              enum:\n                - near_field\n                - far_field\n              description: >\n                Type of noise reduction. `near_field` is for close-talking\n                microphones such as headphones, `far_field` is for far-field\n                microphones such as laptop or conference room microphones.\n        tools:\n          type: array\n          description: Tools (functions) available to the model.\n          items:\n            type: object\n            properties:\n              type:\n                type: string\n                enum:\n                  - function\n                description: The type of the tool, i.e. `function`.\n                x-stainless-const: true\n              name:\n                type: string\n                description: The name of the function.\n              description:\n                type: string\n                description: >\n                  The description of the function, including guidance on when\n                  and how \n\n                  to call it, and guidance about what to tell the user when\n                  calling \n\n                  (if anything).\n              parameters:\n                type: object\n                description: Parameters of the function in JSON Schema.\n        tool_choice:\n          type: string\n          default: auto\n          description: >\n            How the model chooses tools. Options are `auto`, `none`, `required`,\n            or \n\n            specify a function.\n        temperature:\n          type: number\n          default: 0.8\n          description: >\n            Sampling temperature for the model, limited to [0.6, 1.2]. For audio\n            models a temperature of 0.8 is highly recommended for best\n            performance.\n        max_response_output_tokens:\n          oneOf:\n            - type: integer\n            - type: string\n              enum:\n                - inf\n              x-stainless-const: true\n          description: |\n            Maximum number of output tokens for a single assistant response,\n            inclusive of tool calls. Provide an integer between 1 and 4096 to\n            limit output tokens, or `inf` for the maximum available tokens for a\n            given model. Defaults to `inf`.\n    RealtimeSessionCreateResponse:\n      type: object\n      description: >\n        A new Realtime session configuration, with an ephemeral key. Default\n        TTL for keys is one minute.\n      properties:\n        client_secret:\n          type: object\n          description: Ephemeral key returned by the API.\n          properties:\n            value:\n              type: string\n              description: >\n                Ephemeral key usable in client environments to authenticate\n                connections to the Realtime API. Use this in client-side\n                environments rather than a standard API token, which should only\n                be used server-side.\n            expires_at:\n              type: integer\n              description: >\n                Timestamp for when the token expires. Currently, all tokens\n                expire after one minute.\n          required:\n            - value\n            - expires_at\n        modalities:\n          description: |\n            The set of modalities the model can respond with. To disable audio,\n            set this to [\"text\"].\n          items:\n            type: string\n            enum:\n              - text\n              - audio\n        instructions:\n          type: string\n          description: >\n            The default system instructions (i.e. system message) prepended to\n            model calls. This field allows the client to guide the model on desired \n            responses. The model can be instructed on response content and\n            format, (e.g. \"be extremely succinct\", \"act friendly\", \"here are examples of\n            good responses\") and on audio behavior (e.g. \"talk quickly\", \"inject\n            emotion into your voice\", \"laugh frequently\"). The instructions are not\n            guaranteed to be followed by the model, but they provide guidance to the model\n            on the desired behavior.\n\n            Note that the server sets default instructions which will be used if\n            this field is not set and are visible in the `session.created` event at\n            the start of the session.\n        voice:\n          $ref: \"#/components/schemas/VoiceIdsShared\"\n          description: >\n            The voice the model uses to respond. Voice cannot be changed during\n            the session once the model has responded with audio at least once.\n            Current voice options are `alloy`, `ash`, `ballad`, `coral`, `echo` `sage`, \n            `shimmer` and `verse`.\n        input_audio_format:\n          type: string\n          description: >\n            The format of input audio. Options are `pcm16`, `g711_ulaw`, or\n            `g711_alaw`.\n        output_audio_format:\n          type: string\n          description: >\n            The format of output audio. Options are `pcm16`, `g711_ulaw`, or\n            `g711_alaw`.\n        input_audio_transcription:\n          type: object\n          description: >\n            Configuration for input audio transcription, defaults to off and can\n            be set to `null` to turn off once on. Input audio transcription is not\n            native to the model, since the model consumes audio directly. Transcription\n            runs asynchronously through Whisper and should be treated as rough\n            guidance rather than the representation understood by the model.\n          properties:\n            model:\n              type: string\n              description: >\n                The model to use for transcription, `whisper-1` is the only\n                currently supported model.\n        turn_detection:\n          type: object\n          description: >\n            Configuration for turn detection. Can be set to `null` to turn off.\n            Server VAD means that the model will detect the start and end of speech\n            based on audio volume and respond at the end of user speech.\n          properties:\n            type:\n              type: string\n              description: >\n                Type of turn detection, only `server_vad` is currently supported.\n            threshold:\n              type: number\n              description: >\n                Activation threshold for VAD (0.0 to 1.0), this defaults to 0.5.\n                A higher threshold will require louder audio to activate the\n                model, and thus might perform better in noisy environments.\n            prefix_padding_ms:\n              type: integer\n              description: |\n                Amount of audio to include before the VAD detected speech (in \n                milliseconds). Defaults to 300ms.\n            silence_duration_ms:\n              type: integer\n              description: >\n                Duration of silence to detect speech stop (in milliseconds).\n                Defaults to 500ms. With shorter values the model will respond more\n                quickly, but may jump in on short pauses from the user.\n        tools:\n          type: array\n          description: Tools (functions) available to the model.\n          items:\n            type: object\n            properties:\n              type:\n                type: string\n                enum:\n                  - function\n                description: The type of the tool, i.e. `function`.\n                x-stainless-const: true\n              name:\n                type: string\n                description: The name of the function.\n              description:\n                type: string\n                description: >\n                  The description of the function, including guidance on when\n                  and how to call it, and guidance about what to tell the user when\n                  calling (if anything).\n              parameters:\n                type: object\n                description: Parameters of the function in JSON Schema.\n        tool_choice:\n          type: string\n          description: >\n            How the model chooses tools. Options are `auto`, `none`, `required`,\n            or specify a function.\n        temperature:\n          type: number\n          description: >\n            Sampling temperature for the model, limited to [0.6, 1.2]. Defaults\n            to 0.8.\n        max_response_output_tokens:\n          oneOf:\n            - type: integer\n            - type: string\n              enum:\n                - inf\n              x-stainless-const: true\n          description: |\n            Maximum number of output tokens for a single assistant response,\n            inclusive of tool calls. Provide an integer between 1 and 4096 to\n            limit output tokens, or `inf` for the maximum available tokens for a\n            given model. Defaults to `inf`.\n      required:\n        - client_secret\n    RealtimeTranscriptionSessionCreateRequest:\n      type: object\n      description: Realtime transcription session object configuration.\n      properties:\n        modalities:\n          description: |\n            The set of modalities the model can respond with. To disable audio,\n            set this to [\"text\"].\n          items:\n            type: string\n            default:\n              - text\n              - audio\n            enum:\n              - text\n              - audio\n        input_audio_format:\n          type: string\n          default: pcm16\n          enum:\n            - pcm16\n            - g711_ulaw\n            - g711_alaw\n          description: >\n            The format of input audio. Options are `pcm16`, `g711_ulaw`, or\n            `g711_alaw`.\n\n            For `pcm16`, input audio must be 16-bit PCM at a 24kHz sample rate, \n            single channel (mono), and little-endian byte order.\n        input_audio_transcription:\n          type: object\n          description: >\n            Configuration for input audio transcription. The client can\n            optionally set the language and prompt for transcription, these\n            offer additional guidance to the transcription service.\n          properties:\n            model:\n              type: string\n              description: >\n                The model to use for transcription, current options are\n                `gpt-4o-transcribe`, `gpt-4o-mini-transcribe`, and `whisper-1`.\n              enum:\n                - gpt-4o-transcribe\n                - gpt-4o-mini-transcribe\n                - whisper-1\n            language:\n              type: string\n              description: >\n                The language of the input audio. Supplying the input language in\n\n                [ISO-639-1](https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes)\n                (e.g. `en`) format will improve accuracy and latency.\n            prompt:\n              type: string\n              description: >\n                An optional text to guide the model\'s style or continue a\n                previous audio segment.\n\n                For `whisper-1`, the prompt is a list of keywords.\n\n                For `gpt-4o-transcribe` models, the prompt is a free text\n                string, for example \"expect words related to technology\".\n        turn_detection:\n          type: object\n          description: >\n            Configuration for turn detection, ether Server VAD or Semantic VAD.\n            This can be set to `null` to turn off, in which case the client must\n            manually trigger model response.\n\n            Server VAD means that the model will detect the start and end of\n            speech based on audio volume and respond at the end of user speech.\n\n            Semantic VAD is more advanced and uses a turn detection model (in\n            conjunction with VAD) to semantically estimate whether the user has\n            finished speaking, then dynamically sets a timeout based on this\n            probability. For example, if user audio trails off with \"uhhm\", the\n            model will score a low probability of turn end and wait longer for\n            the user to continue speaking. This can be useful for more natural\n            conversations, but may have a higher latency.\n          properties:\n            type:\n              type: string\n              default: server_vad\n              enum:\n                - server_vad\n                - semantic_vad\n              description: |\n                Type of turn detection.\n            eagerness:\n              type: string\n              default: auto\n              enum:\n                - low\n                - medium\n                - high\n                - auto\n              description: >\n                Used only for `semantic_vad` mode. The eagerness of the model to\n                respond. `low` will wait longer for the user to continue\n                speaking, `high` will respond more quickly. `auto` is the\n                default and is equivalent to `medium`.\n            threshold:\n              type: number\n              description: >\n                Used only for `server_vad` mode. Activation threshold for VAD\n                (0.0 to 1.0), this defaults to 0.5. A \n\n                higher threshold will require louder audio to activate the\n                model, and \n\n                thus might perform better in noisy environments.\n            prefix_padding_ms:\n              type: integer\n              description: >\n                Used only for `server_vad` mode. Amount of audio to include\n                before the VAD detected speech (in \n\n                milliseconds). Defaults to 300ms.\n            silence_duration_ms:\n              type: integer\n              description: >\n                Used only for `server_vad` mode. Duration of silence to detect\n                speech stop (in milliseconds). Defaults to 500ms. With shorter\n                values the model will respond more quickly, \n                but may jump in on short pauses from the user.\n            create_response:\n              type: boolean\n              default: true\n              description: >\n                Whether or not to automatically generate a response when a VAD\n                stop event occurs. Not available for transcription sessions.\n            interrupt_response:\n              type: boolean\n              default: true\n              description: >\n                Whether or not to automatically interrupt any ongoing response\n                with output to the default conversation (i.e. `conversation`\n                of `auto`) when a VAD start event occurs. Not available for\n                transcription sessions.\n        input_audio_noise_reduction:\n          type: object\n          default: null\n          description: >\n            Configuration for input audio noise reduction. This can be set to\n            `null` to turn off.\n\n            Noise reduction filters audio added to the input audio buffer before\n            it is sent to VAD and the model.\n\n            Filtering the audio can improve VAD and turn detection accuracy\n            (reducing false positives) and model performance by improving\n            perception of the input audio.\n          properties:\n            type:\n              type: string\n              enum:\n                - near_field\n                - far_field\n              description: >\n                Type of noise reduction. `near_field` is for close-talking\n                microphones such as headphones, `far_field` is for far-field\n                microphones such as laptop or conference room microphones.\n        include:\n          type: array\n          items:\n            type: string\n          description: >\n            The set of items to include in the transcription. Current available\n            items are:\n\n            - `item.input_audio_transcription.logprobs`\n    RealtimeTranscriptionSessionCreateResponse:\n      type: object\n      description: >\n        A new Realtime transcription session configuration.\n\n\n        When a session is created on the server via REST API, the session object\n        also contains an ephemeral key. Default TTL for keys is one minute.\n        This property is not present when a session is updated via the WebSocket API.\n      properties:\n        client_secret:\n          type: object\n          description: |\n            Ephemeral key returned by the API. Only present when the session is\n            created on the server via REST API.\n          properties:\n            value:\n              type: string\n              description: >\n                Ephemeral key usable in client environments to authenticate\n                connections to the Realtime API. Use this in client-side environments rather\n                than a standard API token, which should only be used server-side.\n            expires_at:\n              type: integer\n              description: >\n                Timestamp for when the token expires. Currently, all tokens\n                expire after one minute.\n          required:\n            - value\n            - expires_at\n        modalities:\n          description: |\n            The set of modalities the model can respond with. To disable audio,\n            set this to [\"text\"].\n          items:\n            type: string\n            enum:\n              - text\n              - audio\n        input_audio_format:\n          type: string\n          description: >\n            The format of input audio. Options are `pcm16`, `g711_ulaw`, or\n            `g711_alaw`.\n        input_audio_transcription:\n          type: object\n          description: |\n            Configuration of the transcription model.\n          properties:\n            model:\n              type: string\n              description: >\n                The model to use for transcription. Can be `gpt-4o-transcribe`,\n                `gpt-4o-mini-transcribe`, or `whisper-1`.\n              enum:\n                - gpt-4o-transcribe\n                - gpt-4o-mini-transcribe\n                - whisper-1\n            language:\n              type: string\n              description: >\n                The language of the input audio. Supplying the input language in\n                [ISO-639-1](https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes)\n                (e.g. `en`) format will improve accuracy and latency.\n            prompt:\n              type: string\n              description: >\n                An optional text to guide the model\'s style or continue a\n                previous audio segment. The prompt\n                should match the audio language.\n        turn_detection:\n          type: object\n          description: >\n            Configuration for turn detection. Can be set to `null` to turn off.\n            Server VAD means that the model will detect the start and end of speech\n            based on audio volume and respond at the end of user speech.\n          properties:\n            type:\n              type: string\n              description: >\n                Type of turn detection, only `server_vad` is currently supported.\n            threshold:\n              type: number\n              description: >\n                Activation threshold for VAD (0.0 to 1.0), this defaults to 0.5.\n                A higher threshold will require louder audio to activate the\n                model, and thus might perform better in noisy environments.\n            prefix_padding_ms:\n              type: integer\n              description: |\n                Amount of audio to include before the VAD detected speech (in \n                milliseconds). Defaults to 300ms.\n            silence_duration_ms:\n              type: integer\n              description: >\n                Duration of silence to detect speech stop (in milliseconds).\n                Defaults to 500ms. With shorter values the model will respond more\n                quickly, but may jump in on short pauses from the user.\n      required:\n        - client_secret\n    Reasoning:\n      type: object\n      description: |\n        **o-series models only**\n\n        Configuration options for \n        [reasoning models](https://platform.openai.com/docs/guides/reasoning).\n      title: Reasoning\n      x-oaiExpandable: true\n      properties:\n        effort:\n          $ref: \"#/components/schemas/ReasoningEffort\"\n        summary:\n          type: string\n          description: >\n            **o-series models only** \n\n\n            A summary of the reasoning performed by the model. This can be\n\n            useful for debugging and understanding the model\'s reasoning\n            process.\n\n            One of `concise` or `detailed`.\n          enum:\n            - concise\n            - detailed\n          nullable: true\n      required:\n        - effort\n\n    ReasoningItem:\n      type: object\n      description: >\n        A description of the chain of thought used by a reasoning model while\n        generating\n\n        a response.\n      title: Reasoning\n      x-oaiExpandable: true\n      properties:\n        type:\n          type: string\n          description: |\n            The type of the object. Always `reasoning`.\n          enum:\n            - reasoning\n          x-stainless-const: true\n        id:\n          type: string\n          description: |\n            The unique identifier of the reasoning content.\n        content:\n          type: array\n          description: |\n            Reasoning text contents.\n          items:\n            type: object\n            properties:\n              type:\n                type: string\n                description: |\n                  The type of the object. Always `text`.\n                enum:\n                  - reasoning_summary\n                x-stainless-const: true\n              text:\n                type: string\n                description: >\n                  A short summary of the reasoning used by the model when\n                  generating\n\n                  the response.\n            required:\n              - type\n              - text\n        status:\n          type: string\n          description: |\n            The status of the item. One of `in_progress`, `completed`, or\n            `incomplete`. Populated when items are returned via API.\n          enum:\n            - in_progress\n            - completed\n            - incomplete\n      required:\n        - id\n        - content\n        - type\n    Refusal:\n      type: object\n      title: Refusal\n      description: |\n        A refusal from the model.\n      properties:\n        type:\n          type: string\n          description: |\n            The type of the refusal. Always `refusal`.\n          enum:\n            - refusal\n          x-stainless-const: true\n        refusal:\n          type: string\n          description: |\n            The refusal explanationfrom the model.\n      required:\n        - type\n        - refusal\n    response:\n      allOf:\n        - $ref: \"#/components/schemas/ModelResponseProperties\"\n        - $ref: \"#/components/schemas/ResponseProperties\"\n        - type: object\n          properties:\n            id:\n              type: string\n              description: |\n                Unique identifier for this Response.\n            object:\n              type: string\n              description: |\n                The object type of this resource - always set to `response`.\n              enum:\n                - response\n              x-stainless-const: true\n            status:\n              type: string\n              description: >\n                The status of the response generation. One of `completed`,\n                `failed`, \n\n                `in_progress`, or `incomplete`.\n              enum:\n                - completed\n                - failed\n                - in_progress\n                - incomplete\n            created_at:\n              type: number\n              description: |\n                Unix timestamp (in seconds) of when this Response was created.\n            error:\n              $ref: \"#/components/schemas/ResponseError\"\n            incomplete_details:\n              type: object\n              nullable: true\n              description: |\n                Details about why the response is incomplete.\n              properties:\n                reason:\n                  type: string\n                  description: The reason why the response is incomplete.\n                  enum:\n                    - max_output_tokens\n                    - content_filter\n            output:\n              type: array\n              x-oaiExpandable: true\n              description: >\n                An array of content items generated by the model.\n\n\n                - The length and order of items in the `output` array is\n                dependent\n                  on the model\'s response.\n                - Rather than accessing the first item in the `output` array\n                and \n                  assuming it\'s an `assistant` message with the content generated by\n                  the model, you might consider using the `output_text` property where\n                  supported in SDKs.\n              items:\n                $ref: \"#/components/schemas/OutputItem\"\n                x-oaiExpandable: true\n            output_text:\n              type: string\n              nullable: true\n              description: >\n                SDK-only convenience property that contains the aggregated text\n                output \n\n                from all `output_text` items in the `output` array, if any are\n                present. \n\n                Supported in the Python and JavaScript SDKs.\n              x-oaiSupportedSDKs:\n                - python\n                - javascript\n            usage:\n              $ref: \"#/components/schemas/ResponseUsage\"\n            parallel_tool_calls:\n              type: boolean\n              description: |\n                Whether to allow the model to run tool calls in parallel.\n              default: true\n          required:\n            - id\n            - object\n            - created_at\n            - error\n            - incomplete_details\n            - instructions\n            - model\n            - tools\n            - output\n            - parallel_tool_calls\n            - metadata\n            - tool_choice\n            - temperature\n            - top_p\n          x-oaiMeta:\n            name: The response object\n            group: responses\n            example: >\n              {\n                \"id\": \"resp_67ccd3a9da748190baa7f1570fe91ac604becb25c45c1d41\",\n                \"object\": \"response\",\n                \"created_at\": 1741476777,\n                \"status\": \"completed\",\n                \"error\": null,\n                \"incomplete_details\": null,\n                \"instructions\": null,\n                \"max_output_tokens\": null,\n                \"model\": \"gpt-4o-2024-08-06\",\n                \"output\": [\n                  {\n                    \"type\": \"message\",\n                    \"id\": \"msg_67ccd3acc8d48190a77525dc6de64b4104becb25c45c1d41\",\n                    \"status\": \"completed\",\n                    \"role\": \"assistant\",\n                    \"content\": [\n                      {\n                        \"type\": \"output_text\",\n                        \"text\": \"The image depicts a scenic landscape with a wooden boardwalk or pathway leading through lush, green grass under a blue sky with some clouds. The setting suggests a peaceful natural area, possibly a park or nature reserve. There are trees and shrubs in the background.\",\n                        \"annotations\": []\n                      }\n                    ]\n                  }\n                ],\n                \"parallel_tool_calls\": true,\n                \"previous_response_id\": null,\n                \"reasoning\": {\n                  \"effort\": null,\n                  \"summary\": null\n                },\n                \"store\": true,\n                \"temperature\": 1.0,\n                \"text\": {\n                  \"format\": {\n                    \"type\": \"text\"\n                  }\n                },\n                \"tool_choice\": \"auto\",\n                \"tools\": [],\n                \"top_p\": 1.0,\n                \"truncation\": \"disabled\",\n                \"usage\": {\n                  \"input_tokens\": 328,\n                  \"input_tokens_details\": {\n                    \"cached_tokens\": 0\n                  },\n                  \"output_tokens\": 52,\n                  \"output_tokens_details\": {\n                    \"reasoning_tokens\": 0\n                  },\n                  \"total_tokens\": 380\n                },\n                \"user\": null,\n                \"metadata\": {}\n              }\n    ResponseAudioDeltaEvent:\n      type: object\n      description: Emitted when there is a partial audio response.\n      properties:\n        type:\n          type: string\n          description: |\n            The type of the event. Always `response.audio.delta`.\n          enum:\n            - response.audio.delta\n          x-stainless-const: true\n        delta:\n          type: string\n          description: |\n            A chunk of Base64 encoded response audio bytes.\n      required:\n        - type\n        - delta\n      x-oaiMeta:\n        name: response.audio.delta\n        group: responses\n        example: |\n          {\n            \"type\": \"response.audio.delta\",\n            \"response_id\": \"resp_123\",\n            \"delta\": \"base64encoded...\"\n          }\n    ResponseAudioDoneEvent:\n      type: object\n      description: Emitted when the audio response is complete.\n      properties:\n        type:\n          type: string\n          description: |\n            The type of the event. Always `response.audio.done`.\n          enum:\n            - response.audio.done\n          x-stainless-const: true\n      required:\n        - type\n        - response_id\n      x-oaiMeta:\n        name: response.audio.done\n        group: responses\n        example: |\n          {\n            \"type\": \"response.audio.done\",\n            \"response_id\": \"resp-123\"\n          }\n    ResponseAudioTranscriptDeltaEvent:\n      type: object\n      description: Emitted when there is a partial transcript of audio.\n      properties:\n        type:\n          type: string\n          description: |\n            The type of the event. Always `response.audio.transcript.delta`.\n          enum:\n            - response.audio.transcript.delta\n          x-stainless-const: true\n        delta:\n          type: string\n          description: |\n            The partial transcript of the audio response.\n      required:\n        - type\n        - response_id\n        - delta\n      x-oaiMeta:\n        name: response.audio.transcript.delta\n        group: responses\n        example: |\n          {\n    