INSERT INTO `AM_OPERATION_POLICY` VALUES ('03c95afd-6d65-4e38-bdee-3eb83f4599d6','regexPolicy','v1','Regex Policy','This is a predefined Regular Expression policy that validates content based on the pattern you define. The regex policy builds the entire message and performs string processing to find potentially harmful constructs underneath the message body. This drops the performance of 10KB messages for 300 concurrent users by 3.6 times than the normal flow. The performance decrease may accelerate along with the message size','[request]','[Synapse]','[\"HTTP\"]',_binary '[]','carbon.super','Mediation','{\"hash\":\"8029346dedc42f2ec2f3b4f92638684d2a602de3e96b59da3bbb728273079822\",\"algorithm\":\"SHA-256\"}'),('055289ca-02c7-466d-81d9-d42fa56cbfb5','regexPolicy','v1','Regex Policy','This is a predefined Regular Expression policy that validates content based on the pattern you define. The regex policy builds the entire message and performs string processing to find potentially harmful constructs underneath the message body. This drops the performance of 10KB messages for 300 concurrent users by 3.6 times than the normal flow. The performance decrease may accelerate along with the message size','[request]','[Synapse]','[\"HTTP\"]',_binary '[]','adpsample.com','Mediation','{\"hash\":\"8029346dedc42f2ec2f3b4f92638684d2a602de3e96b59da3bbb728273079822\",\"algorithm\":\"SHA-256\"}'),('06d392df-9426-46db-b6f0-124efc043c13','revokeOneTimeToken','v1','Revoke One Time Token','This policy is used to revoke one time tokens. Attach the policy to the required resource and add the \'scope\' defined in the policy to the JWT token to identify the token as a one time token ','[request]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"scope\",\n    \"displayName\": \"Scope\",\n    \"description\": \"The designated scope name for the JWT token in order to identify the token as a One Time Token\",\n    \"validationRegex\": \"^([a-zA-Z_][a-zA-Z\\\\d_\\\\-\\\\ ]*)$\",\n    \"type\": \"String\",\n    \"defaultValue\": \"OTT\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"734cad7194684db41ff22d9a052cf10e5810b18b42ed128cb48c1ceb65c02766\",\"algorithm\":\"SHA-256\"}'),('09021d90-17a0-4447-8891-c446b7746a10','apkAddHeader','v1','Add Header','This policy allows you to add a new header to the request','[request, response]','[ChoreoConnect]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"headerName\",\n    \"displayName\": \"Header Name\",\n    \"description\": \"Name of the header to be added\",\n    \"validationRegex\": \"^([a-zA-Z_\\\\:][a-zA-Z\\\\d_\\\\-\\\\ ]*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"headerValue\",\n    \"displayName\": \"Header Value\",\n    \"description\": \"Value of the header\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','adpsample.com','Mediation','{\"hash\":\"d08ea6eb6cf3f8bd85c5df6125c065470da1eec23bb5cda81923e0af2ad36fb1\",\"algorithm\":\"SHA-256\"}'),('0df1f161-66b9-4658-a38d-eb5a41348f53','opaPolicy','v1','Validate Request with OPA','This policy allows you to validate requests based on the response from OPA policy engine. The Open Policy Agent is an open source, general-purpose policy engine that unifies policy enforcement across different technologies and systems. Before applying the policy, please make sure that the OPA policy engine is configured properly. Once a gateway receives a request, gateway will extract a predefined set of meta-data from the request and query OPA via HTTP/HTTPS. OPA Policy engine will evaluate the request meta-data against the configured policy and return it\'s validation response.Based on the response, gateway will allow or block the request.','[request]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"serverUrl\",\n    \"displayName\": \"OPA server URL\",\n    \"description\": \"OPA server\\u0027s URL. Sample URL: https://opa-server-host:8181/v1/data. This can be an HTTP or HTTPS endpoint. If you are using a HTTPS endpoint, make sure the relevant certificates are added to the trust-store.\",\n    \"validationRegex\": \"([\\\\w+]+\\\\://)?([\\\\w\\\\d-]+\\\\.)*[\\\\w-]+[\\\\.\\\\:]?\\\\w+([/\\\\?\\\\\\u003d\\\\\\u0026\\\\#\\\\.]?[\\\\w-]+)*/?\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"accessKey\",\n    \"displayName\": \"Access Key\",\n    \"description\": \"Access key for the validation request. This is required only if the the token authentication mode is enabled at OPA server. This token will be sent along the OPA validation request as the Authorization header.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"policy\",\n    \"displayName\": \"Policy\",\n    \"description\": \"Policy to be validated\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"rule\",\n    \"displayName\": \"Rule\",\n    \"description\": \"Rule to validate the policy\",\n    \"type\": \"String\",\n    \"defaultValue\": \"allow\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"sendAccessToken\",\n    \"displayName\": \"Send access token\",\n    \"description\": \"Select whether to send access token to the OPA payload.\",\n    \"validationRegex\": \"^(true|false)$\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"additionalProperties\",\n    \"displayName\": \"Additional properties\",\n    \"description\": \"Additional message context (request context) properties to be included in the OPA input. Add these properties in a comma separated list. Provided properties will be added to the OPA input payload after retrieving the values from the message context.\",\n    \"validationRegex\": \"^(([a-zA-Z\\\\d_][a-zA-Z\\\\d_\\\\-]*)(,[a-zA-Z\\\\d_][a-zA-Z\\\\d_\\\\-]*)*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"maxOpenConnections\",\n    \"displayName\": \"Max open connections\",\n    \"description\": \"Maximum number of open HTTP connections between the OPA server and gateway.\",\n    \"validationRegex\": \"^\\\\d{1,3}$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"500\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"connectionTimeout\",\n    \"displayName\": \"Connection timeout\",\n    \"description\": \"Connection timeout in seconds for the connection between the OPA server and gateway.\",\n    \"validationRegex\": \"^\\\\d{1,3}$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"30\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Security','{\"hash\":\"05df2e600847049bcd8210451da79f6dd8c64933067f97399fad81eb75e0e726\",\"algorithm\":\"SHA-256\"}'),('0e27fef4-0460-462c-9f11-b1d8851c858e','jsonFault','v1','JSON Fault','This policy allows you to get an output of the fault message in JSON','[fault]','[Synapse]','[\"HTTP\"]',_binary '[]','adpsample.com','Mediation','{\"hash\":\"af8c04f3e2308afce51a167a606e5bba822028650dd4507abcb3d1676c031bd7\",\"algorithm\":\"SHA-256\"}'),('1074e1f7-7c96-4abc-9241-3c982101c633','azureRateLimit','v1','Rate Limit','This policy prevents API usage spikes on a per subscription basis by limiting the call rate to a specified number per a specified time period. When the call rate is exceeded, the caller receives a 429 Too Many Requests response status code.','[request]','[Azure]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"calls\",\n    \"displayName\": \"Calls\",\n    \"description\": \"The maximum total number of calls allowed during the time interval specified in renewal-period. Policy expressions aren\\u0027t allowed.\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"Integer\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"renewalPeriod\",\n    \"displayName\": \"Renewal Period\",\n    \"description\": \"The length in seconds of the sliding window during which the number of allowed requests should not exceed the value specified in calls. Maximum allowed value: 300 seconds. Policy expressions aren\\u0027t allowed.\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"Integer\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"retryAfterHeaderName\",\n    \"displayName\": \"Retry after header name\",\n    \"description\": \"The name of a custom response header whose value is the recommended retry interval in seconds after the specified call rate is exceeded. Policy expressions aren\\u0027t allowed.\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"retryAfterVariableName\",\n    \"displayName\": \"Retry after variable name\",\n    \"description\": \"The name of a variable that stores the recommended retry interval in seconds after the specified call rate is exceeded. Policy expressions aren\\u0027t allowed.\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"remainingCallsHeaderName\",\n    \"displayName\": \"Remaining calls header name\",\n    \"description\": \"The name of a response header whose value after each policy execution is the number of remaining calls allowed for the time interval specified in the renewal-period. Policy expressions aren\\u0027t allowed.\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"remainingCallsVariableName\",\n    \"displayName\": \"Remaining calls variable name\",\n    \"description\": \"The name of a variable that after each policy execution stores the number of remaining calls allowed for the time interval specified in the renewal-period. Policy expressions aren\\u0027t allowed.\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"totalCallsHeaderName\",\n    \"displayName\": \"Total calls header name\",\n    \"description\": \"The name of a response header whose value is the value specified in calls. Policy expressions aren\\u0027t allowed.\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Mediation','{\"hash\":\"95d3a9767435a5f6dae34826ce7238660516b545528d343a5f650e2a667fb4b8\",\"algorithm\":\"SHA-256\"}'),('11acbbcb-2afd-4f16-b0cd-e80175208bce','jsonFault','v1','JSON Fault','This policy allows you to get an output of the fault message in JSON','[fault]','[Synapse]','[\"HTTP\"]',_binary '[]','carbon.super','Mediation','{\"hash\":\"af8c04f3e2308afce51a167a606e5bba822028650dd4507abcb3d1676c031bd7\",\"algorithm\":\"SHA-256\"}'),('11b61d62-b3c1-4379-b5f3-0c9b70776367','applyAcceptHeader','v1','Apply Accept Header','This policy allows you to apply the Accept header','[request]','[Synapse]','[\"HTTP\"]',_binary '[]','adpsample.com','Mediation','{\"hash\":\"c9b77d52cef54f83231e8d5fdc7ad91de2844932319445ef1e7287b8c3f5b3a7\",\"algorithm\":\"SHA-256\"}'),('1250f043-e176-46d5-a56d-a6eb0015ab7d','validateCsrfCookie','v1','Validate Csrf Cookie','This policy is used to validate CSRF cookies. Attach the policy to the required resource to enforce CSRF cookie validation ','[request]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"csrfCookieName\",\n    \"displayName\": \"CSRF Cookie Name\",\n    \"description\": \"The name of the CSRF cookie to be validated\",\n    \"validationRegex\": \"^([a-zA-Z_][a-zA-Z\\\\d_\\\\-\\\\ ]*)$\",\n    \"type\": \"String\",\n    \"defaultValue\": \"atbv\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"11276ef521841250f5b96432b968a87450ba1a29562017503d9a9f150ee6fc5e\",\"algorithm\":\"SHA-256\"}'),('15930cc2-08d1-4d56-a444-743935df4a98','disableChunking','v1','Disable Chunking','This policy disables chunking of the payload','[request, response]','[Synapse]','[\"HTTP\"]',_binary '[]','carbon.super','Mediation','{\"hash\":\"2de4471fb6f8485bc6bb72bbb1bee1c4bca9704e085c1ba20a41fbe510f99437\",\"algorithm\":\"SHA-256\"}'),('19faae74-5f77-45b7-9221-d2e2b554b0d7','validateCsrfCookie','v1','Validate Csrf Cookie','This policy is used to validate CSRF cookies. Attach the policy to the required resource to enforce CSRF cookie validation ','[request]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"csrfCookieName\",\n    \"displayName\": \"CSRF Cookie Name\",\n    \"description\": \"The name of the CSRF cookie to be validated\",\n    \"validationRegex\": \"^([a-zA-Z_][a-zA-Z\\\\d_\\\\-\\\\ ]*)$\",\n    \"type\": \"String\",\n    \"defaultValue\": \"atbv\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','adpsample.com','Mediation','{\"hash\":\"11276ef521841250f5b96432b968a87450ba1a29562017503d9a9f150ee6fc5e\",\"algorithm\":\"SHA-256\"}'),('200bbce0-d824-49da-a2b6-d8887e2361b2','apkRemoveHeader','v1','Remove Header','This policy allows you to remove a header from the request','[request, response]','[ChoreoConnect]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"headerName\",\n    \"displayName\": \"Header Name\",\n    \"description\": \"Name of the header to be removed\",\n    \"validationRegex\": \"^([a-zA-Z_\\\\:][a-zA-Z\\\\d_\\\\-\\\\ ]*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','adpsample.com','Mediation','{\"hash\":\"511d76090579e92d5fcec236e80bd6d9a2246f322699a2d8a1ea40dcb7cd3c70\",\"algorithm\":\"SHA-256\"}'),('20cd67a7-de54-46f0-a20b-ad5f708a5735','apkWASMInterceptorService','v1','WASM Extension Service','This policy allows you to call an WASM extension service for a request message','[request, response]','[ChoreoConnect]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"policyName\",\n    \"displayName\": \"Policy Name\",\n    \"description\": \"Name for the WASM policy(Must be unique within the gateway).\",\n    \"validationRegex\": \"^([a-zA-Z_\\\\:][a-zA-Z\\\\d_\\\\-\\\\ ]*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"rootId\",\n    \"displayName\": \"Root ID\",\n    \"description\": \"This uniquely identifies a set of extensions within a VM that share the same RootContext and Contexts.\",\n    \"validationRegex\": \"^([a-zA-Z_\\\\:][a-zA-Z\\\\d_\\\\-\\\\ ]*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"wasmpolicyURL\",\n    \"displayName\": \"Policy URL\",\n    \"description\": \"The HTTP URL containing the Wasm code.\",\n    \"validationRegex\": \"^(([\\\\w+]+\\\\:\\\\/\\\\/)?([\\\\w\\\\d-]+\\\\.)*[\\\\w-]+([\\\\.\\\\:]\\\\w+)*([\\\\/\\\\?\\\\\\u003d\\\\\\u0026\\\\#\\\\.]?[\\\\w-]+)*\\\\/?)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"wasmpolicyImage\",\n    \"displayName\": \"Policy Image\",\n    \"description\": \"The OCI image containing the WASM code.\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"imagePullPolicy\",\n    \"displayName\": \"Image Pull Policy\",\n    \"description\": \"This is the policy to use when pulling the Wasm module by either the HTTP or Image source.\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"Enum\",\n    \"allowedValues\": [\n      \"Always\",\n      \"IfNotPresent\"\n    ],\n    \"required\": false\n  },\n  {\n    \"name\": \"wasmConfig\",\n    \"displayName\": \"Config\",\n    \"description\": \"Configuration for the WASM extension(Must be a valid JSON string).\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"failOpen\",\n    \"displayName\": \"FailOpen\",\n    \"description\": \"This is a switch used to control the behavior when a fatal error occurs during the initialization or the execution of the Wasm extension.\",\n    \"validationRegex\": \"^(true|false)$\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"hostKeys\",\n    \"displayName\": \"Host Keys\",\n    \"description\": \"Includes a comma separated list of keys for environment variables from the host envoy process that should be passed into the Wasm VM.\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Mediation','{\"hash\":\"cd074b68b8128cac2e9398507617c1f2a506e501490f65328c478c5e575214bf\",\"algorithm\":\"SHA-256\"}'),('23cc975a-b81d-47be-8019-c91ce44b3939','removeHeader','v2','Remove Header','This policy allows you to remove a header from the request','[request, response, fault]','[Synapse]','[\"HTTP\",\"GRAPHQL\"]',_binary '[\n  {\n    \"name\": \"headerName\",\n    \"displayName\": \"Header Name\",\n    \"description\": \"Name of the header to be removed\",\n    \"validationRegex\": \"^([a-zA-Z_][a-zA-Z\\\\d_\\\\-\\\\ ]*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','adpsample.com','Mediation','{\"hash\":\"1929039b132035d7af2012fdd95bebdc6f06336134fe3fba365e61d1b2c28706\",\"algorithm\":\"SHA-256\"}'),('25d89d1f-4930-408b-b3e4-e494ed1015bf','PIIMaskingRegex','v1.0','PII Masking with Regex','Detects and masks Personally Identifiable Information (PII) based on specified regular expression patterns. By default, PII values are masked during the request flow and restored in the response flow. If the \'redact\' attribute is set to true, PII values will be permanently replaced with \'*****\'.','[request, response]','[Synapse]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"name\",\n    \"displayName\": \"Guardrail Name\",\n    \"description\": \"The name of the guardrail policy. This will be used for tracking purposes.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"piiEntities\",\n    \"displayName\": \"PII Entities\",\n    \"description\": \"The PII entities to detect and mask using regular expressions. Each entry should include the entity name and its corresponding regex pattern.\",\n    \"type\": \"JSON\",\n    \"defaultValue\": \"[\\n  {\\n    \\\"piiEntity\\\": \\\"\\\",\\n    \\\"piiRegex\\\": \\\"\\\"\\n  }\\n]\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"jsonPath\",\n    \"displayName\": \"JSON Path\",\n    \"description\": \"Specifies the JSONPath expression to extract content from the payload for analysis. If omitted, the entire payload will be analyzed.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"redact\",\n    \"displayName\": \"Redact PII\",\n    \"description\": \"If set to true, identified PII values will be permanently replaced with \\\"*****\\\" (irreversible).\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Mediation','{\"hash\":\"fd5d71d3d5bfe1c7c4502b22c5e15e6f679bdf59adbc6642c1dbf6ee4bfbaf8f\",\"algorithm\":\"SHA-256\"}'),('261163b7-ca0e-4d6b-8a8e-e64d5e16563d','AWSBedrockGuardrail','v1.1','AWS Bedrock Guardrail','Integrate AWS Bedrock Guardrails to enhance the safety of AI APIs. AWS Bedrock Guardrails offer configurable protections designed to help developers build generative AI applications responsibly and at scale. This policy mediates both request and response content by validating it through the AWS Bedrock Guardrails service, and enforces the serviceâ€™s decision to allow, block, or mask content accordingly.','[request, response]','[Synapse]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"name\",\n    \"displayName\": \"Guardrail Name\",\n    \"description\": \"The name of the guardrail policy. This will be used for tracking purposes.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"region\",\n    \"displayName\": \"Guardrail Region\",\n    \"description\": \"The deployed region of the guardrail resource.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"guardrailId\",\n    \"displayName\": \"Guardrail ID\",\n    \"description\": \"The ID of the guardrail resource.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"guardrailVersion\",\n    \"displayName\": \"Guardrail Version\",\n    \"description\": \"The version of the guardrail resource.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"jsonPath\",\n    \"displayName\": \"JSON Path\",\n    \"description\": \"Specify the JSONPath expression that identifies the location where prompt decoration should be applied.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"redactPII\",\n    \"displayName\": \"Redact PII\",\n    \"description\": \"When enabled, detected PIIs are redacted and will not be restored to its original form. This should be enabled when the policy is attached to the response flow to prevent exposing AI-generated content with sensitive data to the client. When disabled and applied to the request flow, detected PII is temporarily masked and automatically restored in the corresponding response.\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"passthroughOnError\",\n    \"displayName\": \"Passthrough on Error\",\n    \"description\": \"If enabled, the request or response is passed through without validation when the AWS Bedrock Guardrails service is unavailable. Otherwise, a guardrail validation error is triggered.\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"showAssessment\",\n    \"displayName\": \"Show Guardrail Assessment\",\n    \"description\": \"When enabled, the error response will include detailed information about the reason for the guardrail intervention.\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Mediation','{\"hash\":\"264069e3a1afd942e79f0727f93d152c29210147ed3a210385c9b486962822b1\",\"algorithm\":\"SHA-256\"}'),('29825f9a-77aa-4608-bf21-e4094ce3cba7','preserveAcceptHeader','v1','Preserve Accept Header','This policy allows you to preserve the Accept header','[request]','[Synapse]','[\"HTTP\"]',_binary '[]','adpsample.com','Mediation','{\"hash\":\"96b1e9d142493fdcee5897d31eabf2e7e8c4e4f0e4a07e9624cb492d23c39173\",\"algorithm\":\"SHA-256\"}'),('2ab36620-3596-4e99-aecd-87f0c87ddaf3','setToHeaderWS','v1','Set To Header for Websocket','This policy allows the user to set the To header for a websocket API','[request]','[Synapse]','[\"WS\"]',_binary '[\n  {\n    \"name\": \"value\",\n    \"displayName\": \"To Header Value\",\n    \"description\": \"This is the value of the To header\",\n    \"validationRegex\": \"(.*?)\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"94209df2ccf2c1b71561abadf2d2ed4af3dfbda4361781f55853c42fdd770544\",\"algorithm\":\"SHA-256\"}'),('2bfe0544-9105-4cdb-a578-3447bb418907','azureOAuth2','v1','Set Azure OAuth','This policy allows the user to configure OAuth2 for an Azure API','[request]','[Azure]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"openIdURL\",\n    \"displayName\": \"Open ID configuration endpoint URL\",\n    \"description\": \"Open ID configuration endpoint URL from where Open ID configuration metadata can be obtained.\",\n    \"validationRegex\": \"(.*?)\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Security','{\"hash\":\"834011178145ff6c160934a3b3aeb52fce018907c483e2867a91e41f2d0f90a7\",\"algorithm\":\"SHA-256\"}'),('2cab6e3a-4754-4c7e-aa00-2b21b0f0b649','preserveAcceptHeader','v1','Preserve Accept Header','This policy allows you to preserve the Accept header','[request]','[Synapse]','[\"HTTP\"]',_binary '[]','carbon.super','Mediation','{\"hash\":\"96b1e9d142493fdcee5897d31eabf2e7e8c4e4f0e4a07e9624cb492d23c39173\",\"algorithm\":\"SHA-256\"}'),('39547d0c-8806-4f9d-b675-7885055f789c','jwtClaimBasedAccessValidator','v1','JWT claim based access validator','This policy validates configured claim name and value in this policy with the claim name and value sent in the JWT access token to grant access to the API resource.','[request]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"accessVerificationClaim\",\n    \"displayName\": \"Access verification claim name\",\n    \"description\": \"This should be the name the custom claim which is expected in the JWT access token.\",\n    \"validationRegex\": \"^[a-zA-Z_]+$\",\n    \"type\": \"String\",\n    \"defaultValue\": \"aut\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"accessVerificationClaimValue\",\n    \"displayName\": \"Access verification claim value\",\n    \"description\": \"This should be the value of a custom claim which is expected in the JWT access token.\",\n    \"type\": \"String\",\n    \"defaultValue\": \"APPLICATION\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"accessVerificationClaimValueRegex\",\n    \"displayName\": \"Access verification claim value regex\",\n    \"description\": \"If a regex is provided, the claim values will be matched using this regex. Otherwise they will be checked for equality.\",\n    \"type\": \"String\",\n    \"defaultValue\": \"\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"shouldAllowValidation\",\n    \"displayName\": \"Allow flow when claims are not matching\",\n    \"description\": \"Tick this to allow the flow when the claims are not matching. Keeping this un-ticked will allow the flow only when the claims are matched.\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','adpsample.com','Mediation','{\"hash\":\"84836b8dd67f7450bc1b723af305e0be0ab20adb1dc43e525c23077a25c1221c\",\"algorithm\":\"SHA-256\"}'),('395547e1-7b9f-4c2c-bb07-d9f1fab0a775','setToHeaderWS','v1','Set To Header for Websocket','This policy allows the user to set the To header for a websocket API','[request]','[Synapse]','[\"WS\"]',_binary '[\n  {\n    \"name\": \"value\",\n    \"displayName\": \"To Header Value\",\n    \"description\": \"This is the value of the To header\",\n    \"validationRegex\": \"(.*?)\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','adpsample.com','Mediation','{\"hash\":\"94209df2ccf2c1b71561abadf2d2ed4af3dfbda4361781f55853c42fdd770544\",\"algorithm\":\"SHA-256\"}'),('3dbe421f-4f4a-4e9c-bc27-bb6b5def8adb','debugJsonFault','v1','Debug JSON Fault','This policy allows you to debug the fault payload in JSON format','[fault]','[Synapse]','[\"HTTP\"]',_binary '[]','carbon.super','Mediation','{\"hash\":\"2639cf4334bdec6a3f3693f980af06dc92cbe96611817b8c7b927ba45c44b93a\",\"algorithm\":\"SHA-256\"}'),('4495cb20-0e1e-4178-b807-f460430ec679','setToHeader','v2','Set To Header','This policy allows the user to set the To header','[request]','[Synapse]','[\"HTTP\",\"GRAPHQL\"]',_binary '[\n  {\n    \"name\": \"value\",\n    \"displayName\": \"To Header Value\",\n    \"description\": \"This is the value of the To header\",\n    \"validationRegex\": \"(.*?)\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','adpsample.com','Mediation','{\"hash\":\"d5aa23421dda1d35cd68e4afb21e6c567129655bfb12013023bb738139d58b5f\",\"algorithm\":\"SHA-256\"}'),('462f49eb-18e9-402a-9436-b7d07ba625ab','apkRedirectRequest','v1','Redirect Request','This policy allows you to redirect a request','[request]','[ChoreoConnect]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"url\",\n    \"displayName\": \"URL\",\n    \"description\": \"URL to redirect the request to\",\n    \"validationRegex\": \"^(([\\\\w+]+\\\\:\\\\/\\\\/)?([\\\\w\\\\d-]+\\\\.)*[\\\\w-]+([\\\\.\\\\:]\\\\w+)*([\\\\/\\\\?\\\\\\u003d\\\\\\u0026\\\\#\\\\.]?[\\\\w-]+)*\\\\/?)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"statusCode\",\n    \"displayName\": \"Status Code\",\n    \"description\": \"Status code to display upon redirecting the request. Must be either 301 or 302\",\n    \"validationRegex\": \"^(301|302)$\",\n    \"type\": \"Integer\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','adpsample.com','Mediation','{\"hash\":\"fe0bdae1a06feb19ab3e1e95c375752b5946d478e837c6c7d7d5a037b9354bc3\",\"algorithm\":\"SHA-256\"}'),('4abe9cb7-e156-460d-b535-160e6ac27169','SentenceCountGuardrail','v1.0','Sentence Count Guardrail','Validates the request or response content to ensure it complies with the specified minimum and maximum sentence count limits. If a violation is detected, the guardrail intervenes and returns an error response.','[request, response]','[Synapse]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"name\",\n    \"displayName\": \"Guardrail Name\",\n    \"description\": \"The name of the guardrail policy. This will be used for tracking purposes.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"min\",\n    \"displayName\": \"Minimum Sentence Count\",\n    \"description\": \"The minimum number of sentences the content must contain.\",\n    \"validationRegex\": \"^[1-9][0-9]*$\",\n    \"type\": \"Integer\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"max\",\n    \"displayName\": \"Maximum Sentence Count\",\n    \"description\": \"The maximum number of sentences the content must contain.\",\n    \"validationRegex\": \"^[1-9][0-9]*$\",\n    \"type\": \"Integer\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"jsonPath\",\n    \"displayName\": \"JSON Path\",\n    \"description\": \"The JSONPath expression used to extract content from the payload. If not specified, the entire payload will be used for validation.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"invert\",\n    \"displayName\": \"Invert the Guardrail Decision\",\n    \"description\": \"If enabled, inverts the guardrail blocking decision, causing the guardrail to intervene and return an error response when the content is within the specified limits.\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"showAssessment\",\n    \"displayName\": \"Show Guardrail Assessment\",\n    \"description\": \"When enabled, the error response will include detailed information about the reason for the guardrail intervention.\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Mediation','{\"hash\":\"1cfccfbeb570435f905ada80507df86eaaf321764ff6a8a970d1203d6da69e4c\",\"algorithm\":\"SHA-256\"}'),('4c4b296d-6e09-4655-8ea4-89815883a829','xmlToJson','v1','XML to JSON','This policy allows the user to change the payload from XML to JSON','[request, response]','[Synapse]','[\"HTTP\"]',_binary '[]','carbon.super','Mediation','{\"hash\":\"4923490e8163348f02dc97705585edc1a39aaa27703e735b47344e6450143fdb\",\"algorithm\":\"SHA-256\"}'),('4c8433bf-6802-41e6-b18f-b19d7f0bf88e','jsonToXML','v1','JSON to XML','This policy allows you to change the payload from JSON to XML','[request, response]','[Synapse]','[\"HTTP\"]',_binary '[]','adpsample.com','Mediation','{\"hash\":\"6ec82501ab2619c720663025ab8144837637204428ab31c07e4586bd2407535d\",\"algorithm\":\"SHA-256\"}'),('51e75f7e-4e87-45d3-849f-9113409ea3e4','modelWeightedRoundRobin','v1','Model Weighted Round Robin','This policy allows you to route traffic to different models within the same AI/LLM vendor in a weighted round robin fashion','[request]','[Synapse, ChoreoConnect]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"weightedRoundRobinConfigs\",\n    \"displayName\": \"Weighted Round Robin Configurations\",\n    \"description\": \"Configurations for the weighted round robin policy\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"68b2494da07bfa9aae284ea9161407d4ca2a8af953a8c01a63f09bdb10f819c2\",\"algorithm\":\"SHA-256\"}'),('5871ead5-2556-4470-9a9d-b8b11b6c5aa3','xmlValidator','v1','XML Validator','This policy validates the request body of the XML message','[request]','[Synapse]','[\"HTTP\"]',_binary '[]','carbon.super','Mediation','{\"hash\":\"b11f3751b6c505398b2640f8c191603f05b859ecabe596cc2de09048f0768644\",\"algorithm\":\"SHA-256\"}'),('5b1435e6-00c9-4e42-8bf4-4f5b98eb5ff9','removeHeader','v1','Remove Header','This policy allows you to remove a header from the request','[request, response, fault]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"headerName\",\n    \"displayName\": \"Header Name\",\n    \"description\": \"Name of the header to be removed\",\n    \"validationRegex\": \"^([a-zA-Z_][a-zA-Z\\\\d_\\\\-\\\\ ]*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"cbe3258c382c12ec98b500acea95c4d7126963d0eff6cd8eadfa482544206bd6\",\"algorithm\":\"SHA-256\"}'),('5b159378-7ff8-4b5d-a4b8-76ce34f0f290','apkLuaInterceptorService','v1','Lua Extension Service','This policy allows you to call an Lua extension service for a request message','[request, response]','[ChoreoConnect]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"policyName\",\n    \"displayName\": \"Policy Name\",\n    \"description\": \"Name for the Lua policy(Must be unique within the gateway)\",\n    \"validationRegex\": \"^([a-zA-Z_\\\\:][a-zA-Z\\\\d_\\\\-\\\\ ]*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"sourceCode\",\n    \"displayName\": \"Source Code\",\n    \"description\": \"The source code as an inline string.\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"sourceCodeRef\",\n    \"displayName\": \"Source Code Reference\",\n    \"description\": \"This is the source code specified as a local object reference\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"mountInConfigMap\",\n    \"displayName\": \"Mount In ConfigMap\",\n    \"description\": \"Specifies that when both source code and a reference are provided, a ConfigMap is created with the reference name for reuse across the system.\",\n    \"validationRegex\": \"^(true|false)$\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Mediation','{\"hash\":\"829fbb68c2276aa2b4f8523fe4d06dbcfe10b53ccdc7a3b35b4b76831215d758\",\"algorithm\":\"SHA-256\"}'),('5e741622-8383-470c-a7c8-c0fb28cbe0ca','addHeader','v3','Add Header','This policy allows you to add a new header to the request','[request, response, fault]','[Synapse]','[\"HTTP\",\"GRAPHQL\"]',_binary '[\n  {\n    \"name\": \"headerName\",\n    \"displayName\": \"Header Name\",\n    \"description\": \"Name of the header to be added\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"headerValue\",\n    \"displayName\": \"Header Value\",\n    \"description\": \"Value of the header\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','adpsample.com','Mediation','{\"hash\":\"9452b2d88f2562ab8a5acd38d3cffb06166a3f0aa6749d2de143f773c070df5d\",\"algorithm\":\"SHA-256\"}'),('5faeb8b6-36a4-4df7-919f-cead259a60e8','AzureContentSafetyContentModeration','v1.0','Azure Content Safety Content Moderation','Integrate Azure Content Safety\'s Content Moderation Service to filter out harmful content in request messages sent to AI APIs and in AI generated content within AI API responses. The policy defines four severity levels across content safety categories hate, sexual, self-harm, and violence. If the severity level identified by the content moderation service exceeds the configured policy thresholds, the guardrail intervenes and returns an error response.','[request, response]','[Synapse]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"name\",\n    \"displayName\": \"Guardrail Name\",\n    \"description\": \"The name of the guardrail policy. This will be used for tracking purposes.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"hateCategory\",\n    \"displayName\": \"Hate\",\n    \"description\": \"The severity level for the hate category.\",\n    \"validationRegex\": \"^[0-7]$\",\n    \"type\": \"Integer\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"sexualCategory\",\n    \"displayName\": \"Sexual\",\n    \"description\": \"The severity level for the sexual category.\",\n    \"validationRegex\": \"^[0-7]$\",\n    \"type\": \"Integer\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"selfHarmCategory\",\n    \"displayName\": \"Self Harm\",\n    \"description\": \"The severity level for the self harm category.\",\n    \"validationRegex\": \"^[0-7]$\",\n    \"type\": \"Integer\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"violenceCategory\",\n    \"displayName\": \"Violence\",\n    \"description\": \"The severity level for the violence category.\",\n    \"validationRegex\": \"^[0-7]$\",\n    \"type\": \"Integer\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"jsonPath\",\n    \"displayName\": \"JSON Path\",\n    \"description\": \"Specify the JSONPath expression that identifies the content location for validation.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"passthroughOnError\",\n    \"displayName\": \"Passthrough on Error\",\n    \"description\": \"If enabled, the request or response is passed through without validation when the Azure Content Safety service is unavailable. Otherwise, a guardrail validation error is triggered.\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"showAssessment\",\n    \"displayName\": \"Show Guardrail Assessment\",\n    \"description\": \"When enabled, the error response will include detailed information about the reason for the guardrail intervention.\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Mediation','{\"hash\":\"2029a4439fd485ce4e449675a4dea3fd260c3afed282c9e9735f2e2e57231354\",\"algorithm\":\"SHA-256\"}'),('6039f769-a8e0-41b8-a91d-003dcbb6a5d8','backEndJWT','v1','Backend JWT','This policy allows you to enable backend jwt','[request]','[ChoreoConnect]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"encoding\",\n    \"displayName\": \"Encoding\",\n    \"description\": \"Encoding of the JWT token\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"Enum\",\n    \"allowedValues\": [\n      \"Base64\",\n      \"Base64Url\"\n    ],\n    \"required\": true\n  },\n  {\n    \"name\": \"header\",\n    \"displayName\": \"Header Name\",\n    \"description\": \"Header of the JWT token\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"defaultValue\": \"X-JWT-Assertion\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"signingAlgorithm\",\n    \"displayName\": \"Signing Algorithm\",\n    \"description\": \"Signing algorithm of the JWT token\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"Enum\",\n    \"allowedValues\": [\n      \"SHA256withRSA\",\n      \"NONE\"\n    ],\n    \"required\": true\n  },\n  {\n    \"name\": \"tokenTTL\",\n    \"displayName\": \"Token TTL\",\n    \"description\": \"TokenTTL time to live for the backend JWT token in seconds\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"3600\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','adpsample.com','Mediation','{\"hash\":\"5ff890b9a397f0370acc2b0586a43c5b17e2ddf569a9fdcfbf7a210bfb3ab8db\",\"algorithm\":\"SHA-256\"}'),('66a1b8f3-6b75-4772-8806-3b66b5013217','azureSetHeader','v1','Set Header','This policy assigns a value to an existing HTTP response and/or request header or adds a new response and/or request header.','[request, response, fault]','[Azure]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"headerName\",\n    \"displayName\": \"Header Name\",\n    \"description\": \"Name of the header to be added\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"headerValue\",\n    \"displayName\": \"Header Value\",\n    \"description\": \"Value of the header. Will be ignored if exists-action is delete.\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"existsAction\",\n    \"displayName\": \"Exists Action\",\n    \"description\": \"Action to take if the header exists\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"Enum\",\n    \"allowedValues\": [\n      \"override\",\n      \"skip\",\n      \"append\",\n      \"delete\"\n    ],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"e3adbfaf7b751690a91de12e06cef8c92bf29c518d339d882d29931c382bc185\",\"algorithm\":\"SHA-256\"}'),('692479f3-b247-43cc-9647-e1d0d5b4632b','addHeader','v2','Add Header','This policy allows you to add a new header to the request','[request, response, fault]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"headerName\",\n    \"displayName\": \"Header Name\",\n    \"description\": \"Name of the header to be added\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"headerValue\",\n    \"displayName\": \"Header Value\",\n    \"description\": \"Value of the header\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"8abbb330cca71c4339036753456ef620aeaad5bdd043ca8c4c01fc7790c50720\",\"algorithm\":\"SHA-256\"}'),('69f6228f-fc5e-42d1-918f-b22e62b909ca','debugRequestFlow','v2','Debug Request Flow','This policy allows you to log the special properties of the request message for debugging purposes','[request]','[Synapse]','[\"HTTP\",\"GRAPHQL\"]',_binary '[]','adpsample.com','Mediation','{\"hash\":\"3d69098044a4464e31aa63d860530bd75255df8ef71cf815657b09f971598b6a\",\"algorithm\":\"SHA-256\"}'),('6a85ce73-4390-4775-a7b4-12edb8da5b82','apkMirrorRequest','v1','Mirror Request','This policy allows you to mirror a request to various URLs','[request]','[ChoreoConnect]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"url\",\n    \"displayName\": \"URL\",\n    \"description\": \"URL to mirror the request to\",\n    \"validationRegex\": \"^(([\\\\w+]+\\\\:\\\\/\\\\/)?([\\\\w\\\\d-]+\\\\.)*[\\\\w-]+([\\\\.\\\\:]\\\\w+)*([\\\\/\\\\?\\\\\\u003d\\\\\\u0026\\\\#\\\\.]?[\\\\w-]+)*\\\\/?)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"469a82ce7d0c7abda0edd4c94591c9bf32c9884336bcf0d7fee37364947f0359\",\"algorithm\":\"SHA-256\"}'),('6bc589d4-64ac-4408-bb01-9b26f34e0235','jsonToXML','v1','JSON to XML','This policy allows you to change the payload from JSON to XML','[request, response]','[Synapse]','[\"HTTP\"]',_binary '[]','carbon.super','Mediation','{\"hash\":\"6ec82501ab2619c720663025ab8144837637204428ab31c07e4586bd2407535d\",\"algorithm\":\"SHA-256\"}'),('6e5a416b-2edd-4ffb-832b-481b26f54e5e','modelRoundRobin','v1','Model Round Robin','This policy allows you to route traffic to different models within the same AI/LLM vendor in a round robin fashion','[request]','[Synapse, ChoreoConnect]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"roundRobinConfigs\",\n    \"displayName\": \"Round Robin Configurations\",\n    \"description\": \"Configurations for the round robin policy\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','adpsample.com','Mediation','{\"hash\":\"af22b33e582bd743c766e8d80c74eb982a3cd749e94458069aa4c5feb97a8c84\",\"algorithm\":\"SHA-256\"}'),('7549647f-a1f4-4ff9-a65a-f0f91551d28b','changeHTTPMethod','v1','Change HTTP Method','This policy allows you to change the HTTP Method','[request]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"httpMethod\",\n    \"displayName\": \"HTTP Method\",\n    \"description\": \"Method of the HTTP request\",\n    \"validationRegex\": \"^(GET|PUT|POST|PATCH|DELETE|HEAD|OPTIONS)$\",\n    \"type\": \"Enum\",\n    \"allowedValues\": [\n      \"GET\",\n      \"PUT\",\n      \"POST\",\n      \"PATCH\",\n      \"DELETE\",\n      \"HEAD\",\n      \"OPTIONS\"\n    ],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"e53ef9fd7ff8a3bd9a7708c24354a08bdcece4ce531b306a837cae3a7a0e55ee\",\"algorithm\":\"SHA-256\"}'),('7950c970-1827-426a-a9bc-7b4b813ae009','RegexGuardrail','v1.0','Regex Guardrail','Validates the request or response content against a regular expression pattern to ensure it contains a match. If no match is found, the guardrail intervenes and returns an error response.','[request, response]','[Synapse]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"name\",\n    \"displayName\": \"Guardrail Name\",\n    \"description\": \"The name of the guardrail policy. This will be used for tracking purposes.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"regex\",\n    \"displayName\": \"Regex Pattern\",\n    \"description\": \"The regular expression used to validate the content.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"jsonPath\",\n    \"displayName\": \"JSON Path\",\n    \"description\": \"The JSONPath expression used to extract content from the payload. If not specified, the entire payload will be used for validation.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"invert\",\n    \"displayName\": \"Invert the Guardrail Decision\",\n    \"description\": \"If enabled, inverts the guardrail blocking decision, causing the guardrail to intervene and return an error response when a match is found in the content.\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"showAssessment\",\n    \"displayName\": \"Show Guardrail Assessment\",\n    \"description\": \"When enabled, the error response will include detailed information about the reason for the guardrail intervention.\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Mediation','{\"hash\":\"9b5114ad7d287b9479d0ccfae83555bf67ae49713f6c4d02eade259319fee972\",\"algorithm\":\"SHA-256\"}'),('7a6be18f-9b31-48d8-8698-f536c6aa2609','debugResponseFlow','v2','Debug Response Flow','This policy allows you to log the special properties of the response message for debugging purposes','[response]','[Synapse]','[\"HTTP\",\"GRAPHQL\"]',_binary '[]','adpsample.com','Mediation','{\"hash\":\"e8e473cc0761f1d485f5e62deb22661fe26cd2fda334f25bb53a05ca00be31be\",\"algorithm\":\"SHA-256\"}'),('7a8d7fd3-8239-456c-aa17-bc50542215cb','xmlValidator','v1','XML Validator','This policy validates the request body of the XML message','[request]','[Synapse]','[\"HTTP\"]',_binary '[]','adpsample.com','Mediation','{\"hash\":\"b11f3751b6c505398b2640f8c191603f05b859ecabe596cc2de09048f0768644\",\"algorithm\":\"SHA-256\"}'),('7de6b70d-5660-4f5a-bde0-c3018743e935','addLogMessage','v2','Log Policy','This policy allows you to log the important details of the request','[request, response, fault]','[Synapse]','[\"HTTP\",\"GRAPHQL\",\"WS\"]',_binary '[]','carbon.super','Mediation','{\"hash\":\"56642c1a0dd6ce8acb2495ddae75a4dd30fabb237ac8d0609c9e7402b5854192\",\"algorithm\":\"SHA-256\"}'),('7fcd321b-b3d0-48bf-9db1-e05379f56aff','jwtClaimBasedAccessValidator','v1','JWT claim based access validator','This policy validates configured claim name and value in this policy with the claim name and value sent in the JWT access token to grant access to the API resource.','[request]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"accessVerificationClaim\",\n    \"displayName\": \"Access verification claim name\",\n    \"description\": \"This should be the name the custom claim which is expected in the JWT access token.\",\n    \"validationRegex\": \"^[a-zA-Z_]+$\",\n    \"type\": \"String\",\n    \"defaultValue\": \"aut\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"accessVerificationClaimValue\",\n    \"displayName\": \"Access verification claim value\",\n    \"description\": \"This should be the value of a custom claim which is expected in the JWT access token.\",\n    \"type\": \"String\",\n    \"defaultValue\": \"APPLICATION\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"accessVerificationClaimValueRegex\",\n    \"displayName\": \"Access verification claim value regex\",\n    \"description\": \"If a regex is provided, the claim values will be matched using this regex. Otherwise they will be checked for equality.\",\n    \"type\": \"String\",\n    \"defaultValue\": \"\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"shouldAllowValidation\",\n    \"displayName\": \"Allow flow when claims are not matching\",\n    \"description\": \"Tick this to allow the flow when the claims are not matching. Keeping this un-ticked will allow the flow only when the claims are matched.\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Mediation','{\"hash\":\"84836b8dd67f7450bc1b723af305e0be0ab20adb1dc43e525c23077a25c1221c\",\"algorithm\":\"SHA-256\"}'),('841e8d34-906d-4c8a-bf34-9758577542ef','rewriteResourcePath','v3','Rewrite Resource Path','This policy allows you to rewrite the resource path of a request','[request]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"newResourcePath\",\n    \"displayName\": \"New Resource Path\",\n    \"description\": \"Name of the new resource path\",\n    \"validationRegex\": \"^/?([a-zA-Z0-9!@#\\\\$%\\\\^\\\\\\u0026*\\\\)\\\\(+\\u003d._\\\\-~:,\\\\?{}/]*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"includeQueryParams\",\n    \"displayName\": \"Include Query Parameters\",\n    \"description\": \"Select whether to include exiting query params to the new resource path\",\n    \"validationRegex\": \"^(true|false)$\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"true\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Mediation','{\"hash\":\"c2fb113511ce95688f49f285bc16397e51f13c07fd03b91c89d08cd13eac8e02\",\"algorithm\":\"SHA-256\"}'),('87504691-b1f2-4b59-87e7-f5abfc1ed95c','SemanticCache','v1.0','Semantic Cache','Caches API responses based on semantic similarity, reducing redundant processing and improving performance.','[request, response]','[Synapse]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"name\",\n    \"displayName\": \"Semantic Cache Policy Name\",\n    \"description\": \"The name of the semantic cache policy. Used for tracking and referencing this policy instance.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"threshold\",\n    \"displayName\": \"Threshold\",\n    \"description\": \"The maximum distance threshold value for the semantic cache.\",\n    \"type\": \"String\",\n    \"defaultValue\": \"0.32\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"jsonPath\",\n    \"displayName\": \"JSON Path\",\n    \"description\": \"The JSONPath expression used to extract content from the payload. If not specified, the entire payload will be used for validation.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Mediation','{\"hash\":\"4c25dc5eb3bdce4d94e3f5aa6715913b643cc5bbd906bd16b71f5e70912658e1\",\"algorithm\":\"SHA-256\"}'),('87a24a48-aff8-4ba9-b53d-2a533e1402cb','debugRequestFlow','v1','Debug Request Flow','This policy allows you to log the special properties of the request message for debugging purposes','[request]','[Synapse]','[\"HTTP\"]',_binary '[]','carbon.super','Mediation','{\"hash\":\"44b17e088b7553a4926f161799ed92d4d58f578fd753905c5c0bc3a855c3c6f5\",\"algorithm\":\"SHA-256\"}'),('89d68e05-fa50-4034-a5c1-7c2eadfc22bd','apkCallInterceptorService','v1','Call Interceptor Service','This policy allows you to call an interceptor service for a request message','[request, response]','[ChoreoConnect]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"interceptorServiceURL\",\n    \"displayName\": \"Service URL\",\n    \"description\": \"Interceptor Service URL\",\n    \"validationRegex\": \"^(([\\\\w+]+\\\\:\\\\/\\\\/)?([\\\\w\\\\d-]+\\\\.)*[\\\\w-]+([\\\\.\\\\:]\\\\w+)*([\\\\/\\\\?\\\\\\u003d\\\\\\u0026\\\\#\\\\.]?[\\\\w-]+)*\\\\/?)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"includes\",\n    \"displayName\": \"Includes to Payload\",\n    \"description\": \"Includes a comma separated list of items (for example: request_header, request_body, response_header, response_body) to the request payload of interceptor service\",\n    \"validationRegex\": \"^(([a-zA-Z\\\\d_][a-zA-Z\\\\d_\\\\-]*)(,[a-zA-Z\\\\d_][a-zA-Z\\\\d_\\\\-]*)*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','adpsample.com','Mediation','{\"hash\":\"e2e9d62c53549dac11d621181b6ef1f33dc468a966f527237c670489e60d4b6d\",\"algorithm\":\"SHA-256\"}'),('8a9f8ba5-1ef1-4dac-8be9-34086c6b7bc5','debugResponseFlow','v2','Debug Response Flow','This policy allows you to log the special properties of the response message for debugging purposes','[response]','[Synapse]','[\"HTTP\",\"GRAPHQL\"]',_binary '[]','carbon.super','Mediation','{\"hash\":\"e8e473cc0761f1d485f5e62deb22661fe26cd2fda334f25bb53a05ca00be31be\",\"algorithm\":\"SHA-256\"}'),('8d13d134-f084-4097-965a-610c22153dba','WordCountGuardrail','v1.1','Word Count Guardrail','Validates the request or response content to ensure it complies with the specified minimum and maximum word count limits. If a violation is detected, the guardrail intervenes and returns an error response.','[request, response]','[Synapse]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"name\",\n    \"displayName\": \"Guardrail Name\",\n    \"description\": \"The name of the guardrail policy. This will be used for tracking purposes.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"min\",\n    \"displayName\": \"Minimum Word Count\",\n    \"description\": \"The minimum number of words the content must contain.\",\n    \"validationRegex\": \"^[1-9][0-9]*$\",\n    \"type\": \"Integer\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"max\",\n    \"displayName\": \"Maximum Word Count\",\n    \"description\": \"The maximum number of words the content must contain.\",\n    \"validationRegex\": \"^[1-9][0-9]*$\",\n    \"type\": \"Integer\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"jsonPath\",\n    \"displayName\": \"JSON Path\",\n    \"description\": \"The JSONPath expression used to extract content from the payload. If not specified, the entire payload will be used for validation.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"invert\",\n    \"displayName\": \"Invert the Guardrail Decision\",\n    \"description\": \"If enabled, inverts the guardrail blocking decision, causing the guardrail to intervene and return an error response when the content is within the specified limits.\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"showAssessment\",\n    \"displayName\": \"Show Guardrail Assessment\",\n    \"description\": \"When enabled, the error response will include detailed information about the reason for the guardrail intervention.\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Mediation','{\"hash\":\"707485db524a7efb35ed8f919203bc220e79fb95668a4c6b7876d8bedb0aeb46\",\"algorithm\":\"SHA-256\"}'),('8e076d4a-46bd-4a50-854b-10d27537149e','revokeOneTimeToken','v1','Revoke One Time Token','This policy is used to revoke one time tokens. Attach the policy to the required resource and add the \'scope\' defined in the policy to the JWT token to identify the token as a one time token ','[request]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"scope\",\n    \"displayName\": \"Scope\",\n    \"description\": \"The designated scope name for the JWT token in order to identify the token as a One Time Token\",\n    \"validationRegex\": \"^([a-zA-Z_][a-zA-Z\\\\d_\\\\-\\\\ ]*)$\",\n    \"type\": \"String\",\n    \"defaultValue\": \"OTT\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','adpsample.com','Mediation','{\"hash\":\"734cad7194684db41ff22d9a052cf10e5810b18b42ed128cb48c1ceb65c02766\",\"algorithm\":\"SHA-256\"}'),('8e56c29b-6170-4910-809f-1048caa29ded','PromptTemplate','v1.0','Prompt Template','Dynamically modifies the prompt by applying custom templates using a configured strategy.','[request]','[Synapse]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"name\",\n    \"displayName\": \"Template Name\",\n    \"description\": \"The name of the prompt template policy. Used for tracking and referencing this policy instance.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"promptTemplateConfig\",\n    \"displayName\": \"Prompt Template Configuration\",\n    \"description\": \"The configuration that defines one or more prompt templates to be used during request mediation. Each template includes a unique name and a corresponding formatted prompt.\",\n    \"type\": \"JSON\",\n    \"defaultValue\": \"[\\n  {\\n    \\\"name\\\": \\\"\\\",\\n    \\\"prompt\\\": \\\"\\\"\\n  }\\n]\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"233d4d1b8bb0dc0f8734ebe6111391c6ce019a08a6c82725045f3a29870ea0ac\",\"algorithm\":\"SHA-256\"}'),('90870587-6612-42ee-b273-80ddf3ba36c1','apkRemoveHeader','v1','Remove Header','This policy allows you to remove a header from the request','[request, response]','[ChoreoConnect]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"headerName\",\n    \"displayName\": \"Header Name\",\n    \"description\": \"Name of the header to be removed\",\n    \"validationRegex\": \"^([a-zA-Z_\\\\:][a-zA-Z\\\\d_\\\\-\\\\ ]*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"511d76090579e92d5fcec236e80bd6d9a2246f322699a2d8a1ea40dcb7cd3c70\",\"algorithm\":\"SHA-256\"}'),('9136f30c-3cd8-44cc-ae2b-66ee64d5d5df','debugResponseFlow','v1','Debug Response Flow','This policy allows you to log the special properties of the response message for debugging purposes','[response]','[Synapse]','[\"HTTP\"]',_binary '[]','carbon.super','Mediation','{\"hash\":\"d4a986fe8ee1551135f0618743a460de9118fc6876414707ed524aac7f0012aa\",\"algorithm\":\"SHA-256\"}'),('9170009f-d806-4632-8131-8bf7a73f5172','awsOAuth2','v1','Set AWS OAuth','This policy allows the user to configure OAuth2 for an AWS API','[request]','[AWS]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"lambdaARN\",\n    \"displayName\": \"Lambda ARN\",\n    \"description\": \"Lambda ARN for function validating OAuth2 tokens\",\n    \"validationRegex\": \"(.*?)\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"invokeRoleArn\",\n    \"displayName\": \"AWS Lambda Invoke Role ARN\",\n    \"description\": \"Role to execute Authorizer Lambda\",\n    \"validationRegex\": \"(.*?)\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Security','{\"hash\":\"a2957f37d3125f32183504ac70144547f34c081fa4d61a08561f58131fe3db81\",\"algorithm\":\"SHA-256\"}'),('988bc3a0-afe2-4737-bef4-ecc1bbacafa6','apkAddHeader','v1','Add Header','This policy allows you to add a new header to the request','[request, response]','[ChoreoConnect]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"headerName\",\n    \"displayName\": \"Header Name\",\n    \"description\": \"Name of the header to be added\",\n    \"validationRegex\": \"^([a-zA-Z_\\\\:][a-zA-Z\\\\d_\\\\-\\\\ ]*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"headerValue\",\n    \"displayName\": \"Header Value\",\n    \"description\": \"Value of the header\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"d08ea6eb6cf3f8bd85c5df6125c065470da1eec23bb5cda81923e0af2ad36fb1\",\"algorithm\":\"SHA-256\"}'),('9933e91c-f5e4-4658-a62a-f5fac511acfc','xmlToJson','v1','XML to JSON','This policy allows the user to change the payload from XML to JSON','[request, response]','[Synapse]','[\"HTTP\"]',_binary '[]','adpsample.com','Mediation','{\"hash\":\"4923490e8163348f02dc97705585edc1a39aaa27703e735b47344e6450143fdb\",\"algorithm\":\"SHA-256\"}'),('9b8d1b83-3338-4e90-9534-e528836b71c4','apkMirrorRequest','v1','Mirror Request','This policy allows you to mirror a request to various URLs','[request]','[ChoreoConnect]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"url\",\n    \"displayName\": \"URL\",\n    \"description\": \"URL to mirror the request to\",\n    \"validationRegex\": \"^(([\\\\w+]+\\\\:\\\\/\\\\/)?([\\\\w\\\\d-]+\\\\.)*[\\\\w-]+([\\\\.\\\\:]\\\\w+)*([\\\\/\\\\?\\\\\\u003d\\\\\\u0026\\\\#\\\\.]?[\\\\w-]+)*\\\\/?)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','adpsample.com','Mediation','{\"hash\":\"469a82ce7d0c7abda0edd4c94591c9bf32c9884336bcf0d7fee37364947f0359\",\"algorithm\":\"SHA-256\"}'),('9c6fbf53-571d-4cc1-9313-f04d9186b5e5','PromptDecorator','v1.0','Prompt Decorator','Dynamically modifies the prompt by applying custom decorations using a configured strategy.','[request]','[Synapse]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"name\",\n    \"displayName\": \"Decorator Name\",\n    \"description\": \"The name of the prompt decorator policy. Used for tracking and referencing this policy instance.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"promptDecoratorConfig\",\n    \"displayName\": \"Prompt Decorator Configuration\",\n    \"description\": \"The configuration for decorating the prompt. Can decorate completions or chat/completions definitions.\",\n    \"type\": \"JSON\",\n    \"defaultValue\": \"{\\n  \\\"decoration\\\": [\\n    {\\n      \\\"role\\\": \\\"\\\",\\n      \\\"content\\\": \\\"\\\"\\n    }\\n  ]\\n}\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"jsonPath\",\n    \"displayName\": \"JSON Path\",\n    \"description\": \"The JSONPath expression to extract the portion of the prompt that should be modified.\",\n    \"type\": \"String\",\n    \"defaultValue\": \"$.messages\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"append\",\n    \"displayName\": \"Append Decorated Content\",\n    \"description\": \"If true, the decorated content will be appended to the prompt. Otherwise, it will be prepended.\",\n    \"type\": \"Boolean\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Mediation','{\"hash\":\"45396d3f6b6efd233152eba66d731e171b4e76770af71d53ebb96e1bd1234ea3\",\"algorithm\":\"SHA-256\"}'),('9dbbe3bb-644a-424b-8532-68eb00184174','modelWeightedRoundRobin','v1','Model Weighted Round Robin','This policy allows you to route traffic to different models within the same AI/LLM vendor in a weighted round robin fashion','[request]','[Synapse, ChoreoConnect]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"weightedRoundRobinConfigs\",\n    \"displayName\": \"Weighted Round Robin Configurations\",\n    \"description\": \"Configurations for the weighted round robin policy\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','adpsample.com','Mediation','{\"hash\":\"68b2494da07bfa9aae284ea9161407d4ca2a8af953a8c01a63f09bdb10f819c2\",\"algorithm\":\"SHA-256\"}'),('aa99e732-b89a-48de-b689-698887577599','jsonValidator','v1','JSON Validator','This policy validates the request body of the JSON message','[request]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"maxPropertyCount\",\n    \"displayName\": \"Max Property Count\",\n    \"description\": \"Maximum number of properties allowed in the json payload\",\n    \"validationRegex\": \"^\\\\d{1,3}$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"100\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"maxStringLength\",\n    \"displayName\": \"Max String Length\",\n    \"description\": \"Maximum length of a string in the json payload\",\n    \"validationRegex\": \"^\\\\d{1,3}$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"100\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"maxArrayElementCount\",\n    \"displayName\": \"Max Array Element Count\",\n    \"description\": \"Maximum number of array elements allowed in the json payload\",\n    \"validationRegex\": \"^\\\\d{1,3}$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"100\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"maxKeyLength\",\n    \"displayName\": \"Max Key Length\",\n    \"description\": \"Maximum length of a key allowed in the json payload\",\n    \"validationRegex\": \"^\\\\d{1,3}$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"100\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"maxJsonDepth\",\n    \"displayName\": \"Max Json Depth\",\n    \"description\": \"Maximum depth of the json payload\",\n    \"validationRegex\": \"^\\\\d{1,3}$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"100\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"requestMessageBufferSize\",\n    \"displayName\": \"Request message buffer size\",\n    \"description\": \"Request message buffer size\",\n    \"validationRegex\": \"^\\\\d{1,4}$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"1024\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"jsonSchemaValidator\",\n    \"displayName\": \"Json schema validator\",\n    \"description\": \"Json schema validator implementation class\",\n    \"validationRegex\": \"^([a-zA-Z_$][a-zA-Z\\\\d_$.]*)$\",\n    \"type\": \"String\",\n    \"defaultValue\": \"org.wso2.carbon.apimgt.gateway.mediators.JsonSchemaValidator\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Mediation','{\"hash\":\"8d6cf8a5e12fd729d9095d013f72ae6a7f4729177d769bcd46c9366095bde6f5\",\"algorithm\":\"SHA-256\"}'),('abfe7003-a886-4508-a987-de7b77ba3a81','addLogMessage','v1','Log Policy','This policy allows you to log the important details of the request','[request, response, fault]','[Synapse]','[\"HTTP\"]',_binary '[]','carbon.super','Mediation','{\"hash\":\"9534df9a2723d2a605e322815426d15756c1021ea0f75c594397c4f480fe566d\",\"algorithm\":\"SHA-256\"}'),('add80ac6-6e2b-4052-b760-2101c7679c8a','apkCallInterceptorService','v1','Call Interceptor Service','This policy allows you to call an interceptor service for a request message','[request, response]','[ChoreoConnect]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"interceptorServiceURL\",\n    \"displayName\": \"Service URL\",\n    \"description\": \"Interceptor Service URL\",\n    \"validationRegex\": \"^(([\\\\w+]+\\\\:\\\\/\\\\/)?([\\\\w\\\\d-]+\\\\.)*[\\\\w-]+([\\\\.\\\\:]\\\\w+)*([\\\\/\\\\?\\\\\\u003d\\\\\\u0026\\\\#\\\\.]?[\\\\w-]+)*\\\\/?)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"includes\",\n    \"displayName\": \"Includes to Payload\",\n    \"description\": \"Includes a comma separated list of items (for example: request_header, request_body, response_header, response_body) to the request payload of interceptor service\",\n    \"validationRegex\": \"^(([a-zA-Z\\\\d_][a-zA-Z\\\\d_\\\\-]*)(,[a-zA-Z\\\\d_][a-zA-Z\\\\d_\\\\-]*)*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"e2e9d62c53549dac11d621181b6ef1f33dc468a966f527237c670489e60d4b6d\",\"algorithm\":\"SHA-256\"}'),('af698c25-c113-47cd-a5ec-870453ef318f','applyAcceptHeader','v1','Apply Accept Header','This policy allows you to apply the Accept header','[request]','[Synapse]','[\"HTTP\"]',_binary '[]','carbon.super','Mediation','{\"hash\":\"c9b77d52cef54f83231e8d5fdc7ad91de2844932319445ef1e7287b8c3f5b3a7\",\"algorithm\":\"SHA-256\"}'),('b3a87c9e-993f-4305-ab7a-f296562b0156','addLogMessage','v2','Log Policy','This policy allows you to log the important details of the request','[request, response, fault]','[Synapse]','[\"HTTP\",\"GRAPHQL\",\"WS\"]',_binary '[]','adpsample.com','Mediation','{\"hash\":\"56642c1a0dd6ce8acb2495ddae75a4dd30fabb237ac8d0609c9e7402b5854192\",\"algorithm\":\"SHA-256\"}'),('b7ff2a2d-5150-4919-ad32-554a48a170e5','SemanticPromptGuardrail','v1.0','Semantic Prompt Guardrail','Validate the request content by checking its semantic similarity against a list of defined allowed and denied prompts.','[request, response]','[Synapse]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"name\",\n    \"displayName\": \"Guardrail Name\",\n    \"description\": \"The name of the guardrail policy. This will be used for tracking purposes.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"rules\",\n    \"displayName\": \"Semantic Rules\",\n    \"description\": \"Define the allowed and denied prompts.\",\n    \"type\": \"JSON\",\n    \"defaultValue\": \"{\\n  \\\"allowPrompts\\\": [],\\n  \\\"denyPrompts\\\": []\\n}\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"threshold\",\n    \"displayName\": \"Similarity Threshold\",\n    \"description\": \"The similarity threshold that must be met for rule enforcement.\",\n    \"validationRegex\": \"^(100|[1-9]?[0-9])$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"90\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"jsonPath\",\n    \"displayName\": \"JSON Path\",\n    \"description\": \"The JSONPath expression used to extract content from the payload. If not specified, the entire payload will be used for validation.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"showAssessment\",\n    \"displayName\": \"Show Guardrail Assessment\",\n    \"description\": \"When enabled, the error response will include detailed information about the reason for the guardrail intervention.\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Mediation','{\"hash\":\"6fedb956a1591b5c9e23538c45ec80075b7715f5637b5cfcb5a65d7da17db01b\",\"algorithm\":\"SHA-256\"}'),('b940710e-f988-4664-806d-cdda281eced1','URLGuardrail','v1.0','URL Guardrail','Extract and Validate URLs included in the request or response content by either performing a DNS lookup or a connection establishment. If a violation is detected, the guardrail intervenes and returns an error response.','[request, response]','[Synapse]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"name\",\n    \"displayName\": \"Guardrail Name\",\n    \"description\": \"The name of the guardrail policy. This will be used for tracking purposes.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"jsonPath\",\n    \"displayName\": \"JSON Path\",\n    \"description\": \"The JSONPath expression used to extract content from the payload. If not specified, the entire payload will be used for validation.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"onlyDNS\",\n    \"displayName\": \"Perform DNS Lookup\",\n    \"description\": \"If enabled, a DNS lookup will be performed to validate the extracted URLs. If disabled, a connection attempt will be made instead.\\n\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"timeout\",\n    \"displayName\": \"Connection Timeout\",\n    \"description\": \"The connection timeout for DNS lookups or connection attempts, in milliseconds. If not specified, a default timeout will be used.\",\n    \"validationRegex\": \"^[1-9][0-9]*$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"3000\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"showAssessment\",\n    \"displayName\": \"Show Guardrail Assessment\",\n    \"description\": \"When enabled, the error response will include detailed information about the reason for the guardrail intervention.\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Mediation','{\"hash\":\"5180d38148022bde646b0d83b5118d9cf822621395cdbf624ecf2c23865cba03\",\"algorithm\":\"SHA-256\"}'),('bcef6d85-4921-49fb-9487-f14599c0dad0','apkRedirectRequest','v1','Redirect Request','This policy allows you to redirect a request','[request]','[ChoreoConnect]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"url\",\n    \"displayName\": \"URL\",\n    \"description\": \"URL to redirect the request to\",\n    \"validationRegex\": \"^(([\\\\w+]+\\\\:\\\\/\\\\/)?([\\\\w\\\\d-]+\\\\.)*[\\\\w-]+([\\\\.\\\\:]\\\\w+)*([\\\\/\\\\?\\\\\\u003d\\\\\\u0026\\\\#\\\\.]?[\\\\w-]+)*\\\\/?)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"statusCode\",\n    \"displayName\": \"Status Code\",\n    \"description\": \"Status code to display upon redirecting the request. Must be either 301 or 302\",\n    \"validationRegex\": \"^(301|302)$\",\n    \"type\": \"Integer\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"fe0bdae1a06feb19ab3e1e95c375752b5946d478e837c6c7d7d5a037b9354bc3\",\"algorithm\":\"SHA-256\"}'),('c2134073-b44a-43ab-8791-5452cbb52383','setToHeader','v1','Set To Header','This policy allows the user to set the To header','[request]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"value\",\n    \"displayName\": \"To Header Value\",\n    \"description\": \"This is the value of the To header\",\n    \"validationRegex\": \"(.*?)\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"7c539f33acde699a8c30ffa100dda2ff80e0e651348ed5a846895dc583894c78\",\"algorithm\":\"SHA-256\"}'),('c658fbd4-5d60-4b79-8074-66e33fe2bbde','JSONSchemaGuardrail','v1.0','JSON Schema Guardrail','Enforces that the request or response adheres to a defined JSON schema. If a violation is detected, the guardrail intervenes and returns an error response.','[request, response]','[Synapse]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"name\",\n    \"displayName\": \"Guardrail Name\",\n    \"description\": \"The name of the guardrail policy. This will be used for tracking purposes.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"schema\",\n    \"displayName\": \"JSON Schema\",\n    \"description\": \"The JSON Schema used to enforce the structure of the content.\",\n    \"type\": \"JSON\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"jsonPath\",\n    \"displayName\": \"JSON Path\",\n    \"description\": \"The JSONPath expression used to extract content from the payload. If not specified, the entire payload will be used for validation.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"invert\",\n    \"displayName\": \"Invert the Decision\",\n    \"description\": \"If enabled, inverts the guardrail blocking decision, causing the guardrail to intervene and return an error response when the content matches the defined schema.\",\n    \"type\": \"Boolean\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"showAssessment\",\n    \"displayName\": \"Show Guardrail Assessment\",\n    \"description\": \"When enabled, the error response will include detailed information about the reason for the guardrail intervention.\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Mediation','{\"hash\":\"9147ba288ad101c86c9d12a8c0bb24070f51da985e29b607f3a72f101410aa8a\",\"algorithm\":\"SHA-256\"}'),('c681b6e2-6a78-46da-93de-e8aa2a2c5be6','addQueryParam','v1','Add Query Param','This policy allows you to add a query parameter to the request','[request]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"paramKey\",\n    \"displayName\": \"Parameter Key\",\n    \"description\": \"Query parameter\\u0027s key in URL encoded format\",\n    \"validationRegex\": \"^([a-zA-Z_\\\\%][a-zA-Z\\\\d_\\\\-\\\\ \\\\%]*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"paramValue\",\n    \"displayName\": \"Parameter Value\",\n    \"description\": \"Query parameter\\u0027s value in URL encoded format\",\n    \"validationRegex\": \"^([a-zA-Z\\\\d_\\\\%][a-zA-Z\\\\d_\\\\-\\\\ \\\\%]*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','adpsample.com','Mediation','{\"hash\":\"2eb85cb0db3378122229d2bafc118f0c1db26bf8b387b170922dfe1656e64df7\",\"algorithm\":\"SHA-256\"}'),('c7be0e15-7684-459a-9a12-799e02636fb1','addHeader','v3','Add Header','This policy allows you to add a new header to the request','[request, response, fault]','[Synapse]','[\"HTTP\",\"GRAPHQL\"]',_binary '[\n  {\n    \"name\": \"headerName\",\n    \"displayName\": \"Header Name\",\n    \"description\": \"Name of the header to be added\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"headerValue\",\n    \"displayName\": \"Header Value\",\n    \"description\": \"Value of the header\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"9452b2d88f2562ab8a5acd38d3cffb06166a3f0aa6749d2de143f773c070df5d\",\"algorithm\":\"SHA-256\"}'),('cccd1b61-0e1f-4095-9e2f-e412c768fee7','changeHTTPMethod','v1','Change HTTP Method','This policy allows you to change the HTTP Method','[request]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"httpMethod\",\n    \"displayName\": \"HTTP Method\",\n    \"description\": \"Method of the HTTP request\",\n    \"validationRegex\": \"^(GET|PUT|POST|PATCH|DELETE|HEAD|OPTIONS)$\",\n    \"type\": \"Enum\",\n    \"allowedValues\": [\n      \"GET\",\n      \"PUT\",\n      \"POST\",\n      \"PATCH\",\n      \"DELETE\",\n      \"HEAD\",\n      \"OPTIONS\"\n    ],\n    \"required\": true\n  }\n]','adpsample.com','Mediation','{\"hash\":\"e53ef9fd7ff8a3bd9a7708c24354a08bdcece4ce531b306a837cae3a7a0e55ee\",\"algorithm\":\"SHA-256\"}'),('d4041075-bc55-490c-b207-a68396c23d16','opaPolicy','v1','Validate Request with OPA','This policy allows you to validate requests based on the response from OPA policy engine. The Open Policy Agent is an open source, general-purpose policy engine that unifies policy enforcement across different technologies and systems. Before applying the policy, please make sure that the OPA policy engine is configured properly. Once a gateway receives a request, gateway will extract a predefined set of meta-data from the request and query OPA via HTTP/HTTPS. OPA Policy engine will evaluate the request meta-data against the configured policy and return it\'s validation response.Based on the response, gateway will allow or block the request.','[request]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"serverUrl\",\n    \"displayName\": \"OPA server URL\",\n    \"description\": \"OPA server\\u0027s URL. Sample URL: https://opa-server-host:8181/v1/data. This can be an HTTP or HTTPS endpoint. If you are using a HTTPS endpoint, make sure the relevant certificates are added to the trust-store.\",\n    \"validationRegex\": \"([\\\\w+]+\\\\://)?([\\\\w\\\\d-]+\\\\.)*[\\\\w-]+[\\\\.\\\\:]?\\\\w+([/\\\\?\\\\\\u003d\\\\\\u0026\\\\#\\\\.]?[\\\\w-]+)*/?\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"accessKey\",\n    \"displayName\": \"Access Key\",\n    \"description\": \"Access key for the validation request. This is required only if the the token authentication mode is enabled at OPA server. This token will be sent along the OPA validation request as the Authorization header.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"policy\",\n    \"displayName\": \"Policy\",\n    \"description\": \"Policy to be validated\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"rule\",\n    \"displayName\": \"Rule\",\n    \"description\": \"Rule to validate the policy\",\n    \"type\": \"String\",\n    \"defaultValue\": \"allow\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"sendAccessToken\",\n    \"displayName\": \"Send access token\",\n    \"description\": \"Select whether to send access token to the OPA payload.\",\n    \"validationRegex\": \"^(true|false)$\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"additionalProperties\",\n    \"displayName\": \"Additional properties\",\n    \"description\": \"Additional message context (request context) properties to be included in the OPA input. Add these properties in a comma separated list. Provided properties will be added to the OPA input payload after retrieving the values from the message context.\",\n    \"validationRegex\": \"^(([a-zA-Z\\\\d_][a-zA-Z\\\\d_\\\\-]*)(,[a-zA-Z\\\\d_][a-zA-Z\\\\d_\\\\-]*)*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"maxOpenConnections\",\n    \"displayName\": \"Max open connections\",\n    \"description\": \"Maximum number of open HTTP connections between the OPA server and gateway.\",\n    \"validationRegex\": \"^\\\\d{1,3}$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"500\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"connectionTimeout\",\n    \"displayName\": \"Connection timeout\",\n    \"description\": \"Connection timeout in seconds for the connection between the OPA server and gateway.\",\n    \"validationRegex\": \"^\\\\d{1,3}$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"30\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','adpsample.com','Security','{\"hash\":\"05df2e600847049bcd8210451da79f6dd8c64933067f97399fad81eb75e0e726\",\"algorithm\":\"SHA-256\"}'),('d63faebd-cdc4-47be-a519-ef15080a1cee','removeHeader','v2','Remove Header','This policy allows you to remove a header from the request','[request, response, fault]','[Synapse]','[\"HTTP\",\"GRAPHQL\"]',_binary '[\n  {\n    \"name\": \"headerName\",\n    \"displayName\": \"Header Name\",\n    \"description\": \"Name of the header to be removed\",\n    \"validationRegex\": \"^([a-zA-Z_][a-zA-Z\\\\d_\\\\-\\\\ ]*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"1929039b132035d7af2012fdd95bebdc6f06336134fe3fba365e61d1b2c28706\",\"algorithm\":\"SHA-256\"}'),('e241dec9-7c5b-48cd-b2e7-f16831baa7b5','addQueryParam','v1','Add Query Param','This policy allows you to add a query parameter to the request','[request]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"paramKey\",\n    \"displayName\": \"Parameter Key\",\n    \"description\": \"Query parameter\\u0027s key in URL encoded format\",\n    \"validationRegex\": \"^([a-zA-Z_\\\\%][a-zA-Z\\\\d_\\\\-\\\\ \\\\%]*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"paramValue\",\n    \"displayName\": \"Parameter Value\",\n    \"description\": \"Query parameter\\u0027s value in URL encoded format\",\n    \"validationRegex\": \"^([a-zA-Z\\\\d_\\\\%][a-zA-Z\\\\d_\\\\-\\\\ \\\\%]*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"2eb85cb0db3378122229d2bafc118f0c1db26bf8b387b170922dfe1656e64df7\",\"algorithm\":\"SHA-256\"}'),('e25c6552-fa2c-484c-b2b8-9bbda135f982','modelFailover','v1','Model Failover','This policy enables traffic rerouting to one or more fallback models if the target model fails, ensuring continued availability','[request]','[Synapse]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"failoverConfigs\",\n    \"displayName\": \"Failover Configurations\",\n    \"description\": \"Configurations for the failover policy\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','adpsample.com','Mediation','{\"hash\":\"9725680415a528c7dfe8b632ab7850b78f926abc7c79bb7ba466ba85a7868a60\",\"algorithm\":\"SHA-256\"}'),('e425a7dd-3647-4d6c-9ada-38a1d705f082','awsOAuth2','v1','Set AWS OAuth','This policy allows the user to configure OAuth2 for an AWS API','[request]','[AWS]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"lambdaARN\",\n    \"displayName\": \"Lambda ARN\",\n    \"description\": \"Lambda ARN for function validating OAuth2 tokens\",\n    \"validationRegex\": \"(.*?)\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"invokeRoleArn\",\n    \"displayName\": \"AWS Lambda Invoke Role ARN\",\n    \"description\": \"Role to execute Authorizer Lambda\",\n    \"validationRegex\": \"(.*?)\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','adpsample.com','Security','{\"hash\":\"a2957f37d3125f32183504ac70144547f34c081fa4d61a08561f58131fe3db81\",\"algorithm\":\"SHA-256\"}'),('e70c9ff9-e2e4-446d-a90e-5c4dbf42b1f1','rewriteResourcePath','v3','Rewrite Resource Path','This policy allows you to rewrite the resource path of a request','[request]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"newResourcePath\",\n    \"displayName\": \"New Resource Path\",\n    \"description\": \"Name of the new resource path\",\n    \"validationRegex\": \"^/?([a-zA-Z0-9!@#\\\\$%\\\\^\\\\\\u0026*\\\\)\\\\(+\\u003d._\\\\-~:,\\\\?{}/]*)$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"includeQueryParams\",\n    \"displayName\": \"Include Query Parameters\",\n    \"description\": \"Select whether to include exiting query params to the new resource path\",\n    \"validationRegex\": \"^(true|false)$\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"true\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','adpsample.com','Mediation','{\"hash\":\"c2fb113511ce95688f49f285bc16397e51f13c07fd03b91c89d08cd13eac8e02\",\"algorithm\":\"SHA-256\"}'),('e72183ce-b187-4bdc-914b-6be4231c14fa','debugJsonFault','v1','Debug JSON Fault','This policy allows you to debug the fault payload in JSON format','[fault]','[Synapse]','[\"HTTP\"]',_binary '[]','adpsample.com','Mediation','{\"hash\":\"2639cf4334bdec6a3f3693f980af06dc92cbe96611817b8c7b927ba45c44b93a\",\"algorithm\":\"SHA-256\"}'),('e7f45fff-8477-42e6-a214-34d1cb087d61','modelRoundRobin','v1','Model Round Robin','This policy allows you to route traffic to different models within the same AI/LLM vendor in a round robin fashion','[request]','[Synapse, ChoreoConnect]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"roundRobinConfigs\",\n    \"displayName\": \"Round Robin Configurations\",\n    \"description\": \"Configurations for the round robin policy\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"af22b33e582bd743c766e8d80c74eb982a3cd749e94458069aa4c5feb97a8c84\",\"algorithm\":\"SHA-256\"}'),('e884100c-cc5e-4808-8791-49a2fa605c58','debugRequestFlow','v2','Debug Request Flow','This policy allows you to log the special properties of the request message for debugging purposes','[request]','[Synapse]','[\"HTTP\",\"GRAPHQL\"]',_binary '[]','carbon.super','Mediation','{\"hash\":\"3d69098044a4464e31aa63d860530bd75255df8ef71cf815657b09f971598b6a\",\"algorithm\":\"SHA-256\"}'),('ed864a8f-91b5-4ac2-9811-12c025ed2760','disableChunking','v1','Disable Chunking','This policy disables chunking of the payload','[request, response]','[Synapse]','[\"HTTP\"]',_binary '[]','adpsample.com','Mediation','{\"hash\":\"2de4471fb6f8485bc6bb72bbb1bee1c4bca9704e085c1ba20a41fbe510f99437\",\"algorithm\":\"SHA-256\"}'),('efae6974-0a5e-4e66-ba1d-dba1c68bf7df','jsonValidator','v1','JSON Validator','This policy validates the request body of the JSON message','[request]','[Synapse]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"maxPropertyCount\",\n    \"displayName\": \"Max Property Count\",\n    \"description\": \"Maximum number of properties allowed in the json payload\",\n    \"validationRegex\": \"^\\\\d{1,3}$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"100\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"maxStringLength\",\n    \"displayName\": \"Max String Length\",\n    \"description\": \"Maximum length of a string in the json payload\",\n    \"validationRegex\": \"^\\\\d{1,3}$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"100\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"maxArrayElementCount\",\n    \"displayName\": \"Max Array Element Count\",\n    \"description\": \"Maximum number of array elements allowed in the json payload\",\n    \"validationRegex\": \"^\\\\d{1,3}$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"100\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"maxKeyLength\",\n    \"displayName\": \"Max Key Length\",\n    \"description\": \"Maximum length of a key allowed in the json payload\",\n    \"validationRegex\": \"^\\\\d{1,3}$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"100\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"maxJsonDepth\",\n    \"displayName\": \"Max Json Depth\",\n    \"description\": \"Maximum depth of the json payload\",\n    \"validationRegex\": \"^\\\\d{1,3}$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"100\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"requestMessageBufferSize\",\n    \"displayName\": \"Request message buffer size\",\n    \"description\": \"Request message buffer size\",\n    \"validationRegex\": \"^\\\\d{1,4}$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"1024\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"jsonSchemaValidator\",\n    \"displayName\": \"Json schema validator\",\n    \"description\": \"Json schema validator implementation class\",\n    \"validationRegex\": \"^([a-zA-Z_$][a-zA-Z\\\\d_$.]*)$\",\n    \"type\": \"String\",\n    \"defaultValue\": \"org.wso2.carbon.apimgt.gateway.mediators.JsonSchemaValidator\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','adpsample.com','Mediation','{\"hash\":\"8d6cf8a5e12fd729d9095d013f72ae6a7f4729177d769bcd46c9366095bde6f5\",\"algorithm\":\"SHA-256\"}'),('f109f9cf-704e-41de-a099-417ec7de69dc','ContentLengthGuardrail','v1.0','Content Length Guardrail','Validates the request or response content to ensure it complies with the specified minimum and maximum content length limits. If a violation is detected, the guardrail intervenes and returns an error response.','[request, response]','[Synapse]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"name\",\n    \"displayName\": \"Guardrail Name\",\n    \"description\": \"The name of the guardrail policy. This will be used for tracking purposes.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"min\",\n    \"displayName\": \"Minimum Content Length\",\n    \"description\": \"The minimum number of bytes the content must contain.\",\n    \"validationRegex\": \"^[1-9][0-9]*$\",\n    \"type\": \"Integer\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"max\",\n    \"displayName\": \"Maximum Content Length\",\n    \"description\": \"The maximum number of bytes the content must contain.\",\n    \"validationRegex\": \"^[1-9][0-9]*$\",\n    \"type\": \"Integer\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"jsonPath\",\n    \"displayName\": \"JSON Path\",\n    \"description\": \"The JSONPath expression used to extract content from the payload. If not specified, the entire payload will be used for validation.\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"invert\",\n    \"displayName\": \"Invert the Guardrail Decision\",\n    \"description\": \"If enabled, inverts the guardrail blocking decision, causing the guardrail to intervene and return an error response when the content is within the specified limits.\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  },\n  {\n    \"name\": \"showAssessment\",\n    \"displayName\": \"Show Guardrail Assessment\",\n    \"description\": \"When enabled, the error response will include detailed information about the reason for the guardrail intervention.\",\n    \"type\": \"Boolean\",\n    \"defaultValue\": \"false\",\n    \"allowedValues\": [],\n    \"required\": false\n  }\n]','carbon.super','Mediation','{\"hash\":\"095fe1a80c4af195327e99c9f4d5e809d4f79ea85516e29d9b6901d3b10700de\",\"algorithm\":\"SHA-256\"}'),('f4048e7a-ce23-4920-848e-8f04629873e7','modelFailover','v1','Model Failover','This policy enables traffic rerouting to one or more fallback models if the target model fails, ensuring continued availability','[request]','[Synapse]','[{\"subType\":\"AIAPI\",\"apiType\":\"HTTP\"}]',_binary '[\n  {\n    \"name\": \"failoverConfigs\",\n    \"displayName\": \"Failover Configurations\",\n    \"description\": \"Configurations for the failover policy\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"9725680415a528c7dfe8b632ab7850b78f926abc7c79bb7ba466ba85a7868a60\",\"algorithm\":\"SHA-256\"}'),('f62fc897-5291-408b-98da-f23525e9caa0','backEndJWT','v1','Backend JWT','This policy allows you to enable backend jwt','[request]','[ChoreoConnect]','[\"HTTP\"]',_binary '[\n  {\n    \"name\": \"encoding\",\n    \"displayName\": \"Encoding\",\n    \"description\": \"Encoding of the JWT token\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"Enum\",\n    \"allowedValues\": [\n      \"Base64\",\n      \"Base64Url\"\n    ],\n    \"required\": true\n  },\n  {\n    \"name\": \"header\",\n    \"displayName\": \"Header Name\",\n    \"description\": \"Header of the JWT token\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"String\",\n    \"defaultValue\": \"X-JWT-Assertion\",\n    \"allowedValues\": [],\n    \"required\": true\n  },\n  {\n    \"name\": \"signingAlgorithm\",\n    \"displayName\": \"Signing Algorithm\",\n    \"description\": \"Signing algorithm of the JWT token\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"Enum\",\n    \"allowedValues\": [\n      \"SHA256withRSA\",\n      \"NONE\"\n    ],\n    \"required\": true\n  },\n  {\n    \"name\": \"tokenTTL\",\n    \"displayName\": \"Token TTL\",\n    \"description\": \"TokenTTL time to live for the backend JWT token in seconds\",\n    \"validationRegex\": \"^.+$\",\n    \"type\": \"Integer\",\n    \"defaultValue\": \"3600\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"5ff890b9a397f0370acc2b0586a43c5b17e2ddf569a9fdcfbf7a210bfb3ab8db\",\"algorithm\":\"SHA-256\"}'),('ff63534a-9481-48f5-927d-7ac61c12d37c','setToHeader','v2','Set To Header','This policy allows the user to set the To header','[request]','[Synapse]','[\"HTTP\",\"GRAPHQL\"]',_binary '[\n  {\n    \"name\": \"value\",\n    \"displayName\": \"To Header Value\",\n    \"description\": \"This is the value of the To header\",\n    \"validationRegex\": \"(.*?)\",\n    \"type\": \"String\",\n    \"allowedValues\": [],\n    \"required\": true\n  }\n]','carbon.super','Mediation','{\"hash\":\"d5aa23421dda1d35cd68e4afb21e6c567129655bfb12013023bb738139d58b5f\",\"algorithm\":\"SHA-256\"}');
