INSERT INTO `GOV_RULESET` VALUES ('4007b90b-7cf1-4d85-984a-3c97bba8e819','WSO2 REST API Design Guidelines','A set of guidelines focused on enforcing uniformity in API style, including naming conventions, formatting, and documentation to ensure clarity and maintainability across all APIs.','REST_API','SPECTRAL','API_DEFINITION','https://apim.docs.wso2.com/en/4.5.0/reference/governance/wso2-rest-api-design-guidelines/','WSO2','adpsample.com',NULL,'2025-12-30 20:34:10',NULL,NULL),('50d2bca0-6f5c-4f68-a808-228f51fcde7d','WSO2 API Management Guidelines','A guide detailing best practices for creating robust, scalable, and secure APIs, ensuring alignment with industry standards for optimal design.','REST_API','SPECTRAL','API_METADATA','https://apim.docs.wso2.com/en/4.5.0/reference/governance/wso2-api-management-guidelines/','WSO2','carbon.super',NULL,'2025-12-30 20:33:48',NULL,NULL),('86c2c300-e2b7-4f7a-8331-18dbd632cb41','OWASP Top 10','A set of rules enforcing OWASP security guidelines to prevent common vulnerabilities and ensure secure coding practices.','REST_API','SPECTRAL','API_DEFINITION','https://apim.docs.wso2.com/en/4.5.0/reference/governance/owasp-top-10/','WSO2','adpsample.com',NULL,'2025-12-30 20:34:10',NULL,NULL),('9692e2a3-bd17-493a-a3c7-02614a42e9a9','WSO2 API Management Guidelines','A guide detailing best practices for creating robust, scalable, and secure APIs, ensuring alignment with industry standards for optimal design.','REST_API','SPECTRAL','API_METADATA','https://apim.docs.wso2.com/en/4.5.0/reference/governance/wso2-api-management-guidelines/','WSO2','adpsample.com',NULL,'2025-12-30 20:34:10',NULL,NULL),('d53ed719-89c9-4241-9f85-a460465cafa9','WSO2 REST API Design Guidelines','A set of guidelines focused on enforcing uniformity in API style, including naming conventions, formatting, and documentation to ensure clarity and maintainability across all APIs.','REST_API','SPECTRAL','API_DEFINITION','https://apim.docs.wso2.com/en/4.5.0/reference/governance/wso2-rest-api-design-guidelines/','WSO2','carbon.super',NULL,'2025-12-30 20:33:48',NULL,NULL),('f401081a-360f-44e6-89d9-d65d905fc365','OWASP Top 10','A set of rules enforcing OWASP security guidelines to prevent common vulnerabilities and ensure secure coding practices.','REST_API','SPECTRAL','API_DEFINITION','https://apim.docs.wso2.com/en/4.5.0/reference/governance/owasp-top-10/','WSO2','carbon.super',NULL,'2025-12-30 20:33:48',NULL,NULL);
