INSERT INTO `GOV_RULESET_CONTENT` VALUES ('4007b90b-7cf1-4d85-984a-3c97bba8e819',_binary '---\naliases:\n  API_Document:\n    description: \"The complete API specification document. This can be used to target\\\n      \\ any part of the OpenAPI document using **field**.\\n\\n*Use this if you don\'t\\\n      \\ find specific targets that cater to your usecase.* \"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$\"\n  Operation_Object:\n    description: \"The complete operation object. Use it in combo with field object.\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"#Path_Item[\'get\']\"\n      - \"#Path_Item[\'put\']\"\n      - \"#Path_Item[\'post\']\"\n      - \"#Path_Item[\'delete\']\"\n      - \"#Path_Item[\'options\']\"\n      - \"#Path_Item[\'head\']\"\n      - \"#Path_Item[\'patch\']\"\n      - \"#Path_Item[\'trace\']\"\n  Operation_Responses:\n    description: \"Responses for all operations including get, put, post, delete, options,\\\n      \\ head, patch, trace.\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"#Operation_Object.responses\"\n  Path_Item:\n    description: \"\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$.paths[*]\"\n  API_Contact:\n    description: \"The top level description in an API document\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$.info.contact\"\n  API_License:\n    description: \"The top level description in an API document\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$.info.license\"\n  All_Markdown:\n    description: \"All markdown descriptions across the document.\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$..description\"\n      - \"$..title\"\n  API_Tags:\n    description: \"Tags on an API object\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"#Operation_Object.tags\"\n  Response_All_Object:\n    description: \"All responses (object) in an API\"\n    targets:\n    - formats:\n      - \"oas2\"\n      given:\n      - \"$.responses\"\n      - \"#Operation_Responses\"\n      - \"$..responses\"\n    - formats:\n      - \"oas3\"\n      given:\n      - \"$.components.responses\"\n      - \"#Operation_Responses\"\n      - \"$..responses\"\n  Request_Parameter_All:\n    description: \"All request parameters\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$..parameters[*]\"\n  Path_Object:\n    description: \"Path object. Usually used to target the Path key e.g. `/users/{userId}`\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$.paths\"\n  API_Document_RecursiveSearch:\n    description: \"The complete API specification document. This can be used to target\\\n      \\ any part of the OpenAPI document using **field**.\\n\\n*Use this if you don\'t\\\n      \\ find specific targets that cater to your usecase.* \"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$..*\"\n  All_Example:\n    description: \"All examples across the API document\"\n    targets:\n    - formats:\n      - \"oas2\"\n      given:\n      - \"$..examples[*]\"\n    - formats:\n      - \"oas3\"\n      given:\n      - \"$.components.examples[*]\"\n      - \"$.paths[*][*]..content[*].examples[*]\"\n      - \"$.paths[*][*]..parameters[*].examples[*]\"\n      - \"$.components.parameters[*].examples[*]\"\n      - \"$.paths[*][*]..headers[*].examples[*]\"\n      - \"$.components.headers[*].examples[*]\"\n  API_Tags_Item:\n    description: \"Tags on an API object\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$.tags[*]\"\n  All_Array_Item:\n    description: \"\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      - \"oas3_0\"\n      given:\n      - \"$..[?(@ && @.type==\'array\')]\"\n  Request_Parameter_Path:\n    description: \"All request path parameters\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$..parameters[?(@ && @.in==\\\"path\\\")]\"\nrules:\n  contact-url:\n    given:\n    - \"#API_Contact\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"url\"\n    description: \"The `contact` object should have a valid organization URL.\\n\\n**Valid\\\n      \\ Example**\\n\\n```json\\n{\\n  \\\"contact\\\": {\\n     ... ,\\n     \\\"url\\\": \\\"https://acme.com\\\"\\\n      ,\\n     ...\\n  },\\n```\"\n    message: \"Contact object should have \\\"url\\\".\"\n  contact-email:\n    given:\n    - \"#API_Contact\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"email\"\n    description: \"The `contact` object should have a valid email.\\n\\n**Valid Example**\\n\\\n      \\n```json\\n{\\n  \\\"contact\\\": {\\n     ... ,\\n     \\\"email\\\": \\\"support.contact@acme.com\\\"\\\n      \\n  },\\n```\"\n    message: \"Contact object should have \\\"email\\\"\"\n  info-contact:\n    given:\n    - \"#API_Document\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"info.contact\"\n    description: \"The `info` object should include a `contact` object.\\n\\n**Valid\\\n      \\ Example**\\n\\n```json\\n{\\n  \\\"info\\\": {\\n    ... ,\\n    \\\"contact\\\": {\\n  \\\n      \\    \\\"name\\\": \\\"ACME Corporation\\\",\\n      \\\"url\\\": \\\"https://acme.com\\\",\\n\\\n      \\      \\\"email\\\": \\\"support.contact@acme.com\\\"\\n    }\\n  }\\n}\\n```\"\n    message: \"Info object should have \\\"contact\\\" object.\"\n  info-description:\n    given:\n    - \"#API_Document\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"info.description\"\n    description: \"The `info` object should have a `description` object.\\n\\n**Valid\\\n      \\ Example**\\n\\n```json\\n{\\n  \\\"info\\\": {\\n     ... ,\\n     \\\"description\\\":\\\n      \\ \\\"This describes my API.\\\"\\n  }\\n}\\n```\"\n    message: \"Info object should have \\\"description\\\" object.\"\n  info-license:\n    given:\n    - \"#API_Document\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"info.license\"\n    description: \"The `info` object should have a `license` object.\\n\\n**Valid Example**\\n\\\n      \\n```json\\n{\\n  \\\"info\\\": {\\n    ... ,\\n    \\\"license\\\": {\\n      \\\"name\\\":\\\n      \\ \\\"Attribution-ShareAlike 4.0 International (CC BY-SA 4.0)\\\",\\n      \\\"url\\\"\\\n      : \\\"https://creativecommons.org/licenses/by-sa/4.0/\\\"\\n    }\\n  }\\n}\\n```\"\n    message: \"Info object should have \\\"license\\\" object.\"\n  license-url:\n    given:\n    - \"#API_License\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"url\"\n    description: \"The `license` object should include a valid url.\\n\\n**Valid Example**\\n\\\n      \\n```json\\n{\\n  \\\"license\\\": {\\n    \\\"name\\\": \\\"Attribution-ShareAlike 4.0 International\\\n      \\ (CC BY-SA 4.0)\\\",\\n    \\\"url\\\": \\\"https://creativecommons.org/licenses/by-sa/4.0/\\\"\\\n      \\n  }\\n}\\n```\"\n    message: \"License object should include \\\"url\\\".\"\n  no-eval-in-markdown:\n    given:\n    - \"#All_Markdown\"\n    severity: \"warn\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"eval\\\\(\"\n    description: \"Markdown descriptions should not contain [`eval()` functions](https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/eval),\\n\\\n      which pose a security risk.\\n\\n**Invalid Example**\\n\\n```json\\n{\\n  \\\"info\\\"\\\n      : {\\n    ... ,\\n    \\\"description\\\": \\\"API for users. eval()\\\"\\n  }\\n}\\n```\"\n    message: \"Markdown descriptions must not have \\\"eval(\\\".\"\n  no-script-tags-in-markdown:\n    given:\n    - \"#All_Markdown\"\n    severity: \"warn\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"<script\"\n    description: \"Markdown descriptions should not contain `script` tags, which pose\\\n      \\ a security risk.\\n\\n**Invalid Example**\\n\\n```json\\n{\\n  \\\"info\\\": {\\n   \\\n      \\ ... ,\\n    \\\"description\\\": \\\"API for users. <script>alert(\\\\\\\"You are Hacked\\\\\\\n      \\\");</script>\\\"\\n  }\\n}\\n```\"\n    message: \"Markdown descriptions must not have \\\"<script>\\\" tags.\"\n  openapi-tags-alphabetical:\n    given:\n    - \"#API_Document\"\n    severity: \"warn\"\n    then:\n      function: \"alphabetical\"\n      functionOptions:\n        keyedBy: \"name\"\n      field: \"tags\"\n    description: \"Global tags specified at the root OpenAPI Document level should\\\n      \\ be in alphabetical order based on the `name` property.\\n\\n**Invalid Example**\\n\\\n      \\n```json\\n{\\n  \\\"tags\\\":[\\n    {\\n      \\\"name\\\":\\\"Z Global Tag\\\"\\n    },\\n\\\n      \\    {\\n      \\\"name\\\":\\\"A Global Tag\\\"\\n    }\\n  ]\\n}\\n```\\n\\n**Valid Example**\\n\\\n      \\n```json\\n{\\n  \\\"tags\\\":[\\n    {\\n      \\\"name\\\":\\\"A Global Tag\\\"\\n    },\\n\\\n      \\    {\\n      \\\"name\\\":\\\"Z Global Tag\\\"\\n    }\\n  ]\\n}\\n```\"\n    message: \"OpenAPI object should have alphabetical \\\"tags\\\".\"\n  openapi-tags:\n    given:\n    - \"#API_Document\"\n    severity: \"warn\"\n    then:\n      function: \"schema\"\n      functionOptions:\n        schema:\n          type: \"array\"\n          minItems: 1\n      field: \"tags\"\n    description: \"At least one global tag should be specified at the root OpenAPI\\\n      \\ Document level.\\n\\n**Valid Example**\\n\\n```json\\n{\\n  \\\"tags\\\":[\\n    {\\n\\\n      \\      \\\"name\\\":\\\"Global Tag #1\\\"\\n    },\\n    {\\n      \\\"name\\\":\\\"Global Tag\\\n      \\ #2\\\"\\n    }\\n  ]\\n}\\n```\"\n    message: \"OpenAPI object should have non-empty \\\"tags\\\" array.\"\n  operation-description:\n    given:\n    - \"#Operation_Object\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"description\"\n    description: \"Each operation should have a description.\\n\\n**Valid Example**\\n\\\n      \\n```json\\n{\\n  \\\"get\\\": {\\n    \\\"description\\\": \\\"Get a list of users.\\\"\\n\\\n      \\  }\\n}\\n```\"\n    message: \"Operation \\\"description\\\" should be present and non-empty string.\"\n  operation-operationId:\n    given:\n    - \"#Operation_Object\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"operationId\"\n    description: \"All operations should have an `operationId`.\\n\\n**Valid Example**\\n\\\n      \\n```json\\n{\\n  \\\"get\\\": {\\n    \\\"summary\\\": \\\"Get users\\\",\\n    \\\"operationId\\\"\\\n      : \\\"get-users\\\"\\n  }\\n}\\n```\"\n    message: \"Operation should have \\\"operationId\\\".\"\n  operation-operationId-valid-in-url:\n    given:\n    - \"#Operation_Object\"\n    severity: \"error\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        match: \"^[A-Za-z0-9-._~:/?#\\\\[\\\\]@!\\\\$&\'()*+,;=]*$\"\n      field: \"operationId\"\n    description: \"Operation IDs must not contain characters that are invalid for URLs.\\n\\\n      \\n**Invalid Example**\\n\\nThe `operationId` in this example includes a pipe and\\\n      \\ space, which are invalid for URLs.\\n\\n```json\\n{\\n  \\\"/users\\\": {\\n    \\\"\\\n      get\\\": {\\n      \\\"operationId\\\": \\\"invalid|operationID\\\"\\n    }\\n  }\\n}\\n```\\n\\\n      \\n**Valid Example**\\n\\nThis `operationId` is valid for URLs.\\n\\n```json\\n{\\n\\\n      \\  \\\"/users\\\": {\\n    \\\"get\\\": {\\n      \\\"operationId\\\": \\\"this-must-be-unique\\\"\\\n      \\n    }\\n  }\\n}\\n```\"\n    message: \"OperationId should not have characters that are invalid when used in\\\n      \\ URL.\"\n  operation-tags:\n    given:\n    - \"#Operation_Object\"\n    severity: \"warn\"\n    then:\n    - function: \"length\"\n      functionOptions:\n        max: 999\n        min: 1\n      field: \"tags\"\n    - function: \"truthy\"\n      field: \"tags\"\n    description: \"At least one tag should be defined for each operation.\\n\\n**Valid\\\n      \\ Example**\\n\\n```json\\n{\\n  \\\"get\\\": {\\n    \\\"tags\\\": [\\\"Users\\\"]\\n  }\\n}\\n\\\n      ```\"\n    message: \"Operation should have non-empty \\\"tags\\\" array.\"\n  path-declarations-must-exist:\n    given:\n    - \"#Path_Object\"\n    severity: \"error\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"\\\\{\\\\}\"\n      field: \"@key\"\n    description: \"Path parameter declarations must not be empty.\\n\\n**Invalid Example**\\n\\\n      \\n`/users/{}`\\n\\n**Valid Example**\\n\\n`/users/{userId}`\"\n    message: \"Path parameter declarations must not be empty, e.g., \\\"/given/{}\\\" is\\\n      \\ invalid.\"\n  paths-no-trailing-slash:\n    given:\n    - \"#Path_Object\"\n    severity: \"error\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \".+\\\\/$\"\n      field: \"@key\"\n    description: \"Paths must not end with a trailing slash.\\n\\n`/users` and `/users/`\\\n      \\ are separate paths. It\'s considered bad practice for them to differ based\\\n      \\ only on a trailing slash. It\'s usually preferred to not have a trailing slash.\\n\\\n      \\n**Invalid Example**\\n\\nThe `users` path ends with a slash.\\n\\n```json\\n{\\n\\\n      \\  \\\"/users/\\\": {\\n    \\\"post\\\": {}\\n  }\\n}\\n```\\n\\n**Valid Example**\\n\\n```json\\n\\\n      {\\n  \\\"/user\\\": {\\n    \\\"post\\\": {}\\n  }\\n}\\n```\"\n  contact-name:\n    given:\n    - \"#API_Contact\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"name\"\n    description: \"The `contact` object should have an organization name.\\n\\n**Valid\\\n      \\ Example**\\n\\n```json\\n{\\n  \\\"contact\\\": {\\n    \\\"name\\\": \\\"ACME Corporation\\\"\\\n      \\n  }\\n}\\n```\"\n    message: \"Contact object should have \\\"name\\\".\"\n  path-not-include-query:\n    given:\n    - \"#Path_Object\"\n    severity: \"warn\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"\\\\?\"\n      field: \"@key\"\n    description: \"Paths should not include `query` string items. Instead, add them\\\n      \\ as parameters with `in: query`.\\n\\n**Invalid Example**\\n\\n```json\\n{\\n  \\\"\\\n      /users/{?id}\\\": {\\n  }\\n}\\n```\\n\\n**Valid Example**\\n\\n```json\\n{\\n  \\\"parameters\\\"\\\n      : [\\n    {\\n      \\\"schema\\\": {\\n        \\\"type\\\": \\\"string\\\"\\n      },\\n  \\\n      \\    \\\"name\\\": \\\"id\\\",\\n      \\\"in\\\": \\\"path\\\",\\n      \\\"required\\\": true,\\n\\\n      \\      \\\"description\\\": \\\"User\'s ID\\\"\\n    }\\n  ]\\n}\\n```\"\n    message: \"Path should not include query string.\"\n  tag-description:\n    given:\n    - \"#API_Tags_Item\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"description\"\n    description: \"Tags defined at the global level should have a description.\\n\\n\\\n      **Valid Example**\\n\\n```json\\n{\\n  \\\"tags\\\": [\\n    {\\n      \\\"name\\\": \\\"Users\\\"\\\n      ,\\n      \\\"description\\\": \\\"End-user information\\\"\\n    }\\n  ]\\n}\\n```\"\n    message: \"Tag object should have \\\"description\\\".\"\n  parameter-description:\n    given:\n    - \"#Request_Parameter_All\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"description\"\n    description: \"All `parameter` objects should have a description.\\n\\n**Valid Example**\\n\\\n      \\n```json\\n{\\n  \\\"parameters\\\": [\\n    {\\n      \\\"schema\\\": {\\n        \\\"type\\\"\\\n      : \\\"integer\\\"\\n      },\\n      ... ,\\n      ... ,\\n      \\\"description\\\": \\\"\\\n      The number of days to include in the response.\\\"\\n    }\\n  ]\\n}\\n```\\n\"\n    message: \"Parameter objects must have \\\"description\\\".\"\n  oas3-examples-value-or-externalValue:\n    given:\n    - \"#All_Example\"\n    severity: \"warn\"\n    then:\n      function: \"xor\"\n      functionOptions:\n        properties:\n        - \"externalValue\"\n        - \"value\"\n    description: \"The `examples` object should include a `value` or `externalValue`\\\n      \\ field, but cannot include both.\\n\\n**Invalid Example**\\n\\nThis example includes\\\n      \\ both a `value` field and an `externalValue` field.\\n\\n```json\\n{\\n  \\\"examples\\\"\\\n      : {\\n    \\\"example-1\\\": {\\n      \\\"value\\\": {\\n        \\\"id\\\": \\\"string\\\",\\n\\\n      \\        \\\"name\\\": \\\"string\\\"\\n      },\\n      \\\"externalValue\\\": {\\n      \\\n      \\  \\\"id\\\": \\\"string\\\",\\n        \\\"name\\\": \\\"string\\\"\\n      }\\n    }\\n  }\\n\\\n      }\\n```\\n\\n**Valid Example**\\n\\nThis example includes only a `value` field.\\n\\\n      \\n```json\\n{\\n  \\\"examples\\\": {\\n    \\\"example-1\\\": {\\n      \\\"value\\\": {\\n\\\n      \\        \\\"id\\\": \\\"string\\\",\\n        \\\"name\\\": \\\"string\\\"\\n      }\\n    }\\n\\\n      \\  }\\n}\\n```\\n\"\n    message: \"Examples must have either \\\"value\\\" or \\\"externalValue\\\" field.\"\n    formats:\n    - \"oas3\"\n  array-items:\n    given:\n    - \"#All_Array_Item\"\n    severity: \"error\"\n    then:\n      function: \"truthy\"\n      field: \"items\"\n    description: \"Schemas with `type: array`, require a sibling `items` field.\\n\\n\\\n      **Recommended:** Yes\\n\\n**Good Example**\\n\\n```yaml\\nTheGoodModel:\\n  type:\\\n      \\ object\\n  properties:\\n    favoriteColorSets:\\n      type: array\\n      items:\\n\\\n      \\        type: array\\n        items: {}\\n```\\n\\n**Bad Example**\\n\\n```yaml\\n\\\n      TheBadModel:\\n  type: object\\n  properties:\\n    favoriteColorSets:\\n      type:\\\n      \\ array\\n      items:\\n        type: array\\n```\"\n    message: \"Schemas with \\\"type: array\\\", require a sibling \\\"items\\\" field\"\n  path-parameters-on-path-only:\n    given:\n    - \"$.paths[*][*].parameters[?(@.in == \'path\')]\"\n    severity: \"warn\"\n    then:\n      function: \"falsy\"\n    description: \"Path parameters should be defined on the path level instead of the\\\n      \\ operation level.\\n\\n**Invalid Example**\\n\\nThe `user_id` path parameter on\\\n      \\ line 8 should not be included with the `patch` operation.\\n\\n```json\\n{\\n\\\n      \\  \\\"patch\\\": {\\n    \\\"parameters\\\": [\\n      {\\n        \\\"schema\\\": {\\n   \\\n      \\       \\\"type\\\": \\\"integer\\\"\\n        },\\n        \\\"name\\\": \\\"user_id\\\",\\n\\\n      \\        \\\"in\\\": \\\"path\\\"\\n      }\\n    ]\\n  }\\n}\\n```\\n\\n**Valid Example**\\n\\\n      \\nThe `user-id` path parameter is correctly located at the path level.\\n\\n```json\\n\\\n      {\\n  \\\"paths\\\": {\\n    \\\"/users/{userId}\\\": {\\n      \\\"parameters\\\": [\\n   \\\n      \\     {\\n          \\\"schema\\\": {\\n            \\\"type\\\": \\\"integer\\\"\\n      \\\n      \\    },\\n          \\\"name\\\": \\\"user_id\\\",\\n          \\\"in\\\": \\\"path\\\"\\n    \\\n      \\    }\\n      ]\\n    }\\n  }\\n}\\n```\"\n    message: \"Path parameters should be defined on the path level.\"\n  paths-no-query-params:\n    given:\n    - \"$.paths\"\n    severity: \"warn\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"\\\\?\"\n      field: \"@key\"\n    description: \"Paths should not have query parameters in them. They should be defined\\\n      \\ separately in the OpenAPI.\\n\\n**Invalid Example**\\n\\n```json\\n{\\n  \\\"/users/{?id}\\\"\\\n      : {\\n```\\n\\n**Valid Example**\\n\\n```json\\n{\\n  \\\"parameters\\\": [\\n    {\\n  \\\n      \\    \\\"schema\\\": {\\n        \\\"type\\\": \\\"string\\\"\\n      },\\n      \\\"name\\\":\\\n      \\ \\\"id\\\",\\n      \\\"in\\\": \\\"path\\\",\\n      \\\"required\\\": true,\\n      \\\"description\\\"\\\n      : \\\"User\'s ID\\\"\\n    }\\n  ]\\n}\\n```\"\n    message: \"Paths should not have query parameters in them. They should be defined\\\n      \\ separately in the OpenAPI.\"\n  path-casing:\n    given:\n    - \"$.paths\"\n    severity: \"error\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        match: \"^\\\\/([a-z0-9]+(-[a-z0-9]+)*)?(\\\\/[a-z0-9]+(-[a-z0-9]+)*|\\\\/\\\\{.+\\\\\\\n          })*$\"\n      field: \"@key\"\n    description: \"Paths must be `kebab-case`, with hyphens separating words.\\n\\n**Invalid\\\n      \\ Example**\\n\\n`userInfo` must be separated with a hyphen.\\n\\n```json\\n{\\n \\\n      \\   \\\"/userInfo\\\": {\\n        \\\"post: }\\n       ....\\n}\\n```\\n\\n**Valid Example**\\n\\\n      \\n```json\\n{\\n    \\\"/user-info\\\": {\\n       \\\"post: }\\n       ....\\n}\\n```\"\n    message: \"Paths must be kebab-case\"\n  resource-names-plural:\n    given:\n    - \"$.paths\"\n    severity: \"warn\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        match: \"^((\\\\/v\\\\d+)*((\\\\/[\\\\w+-]*s)(\\\\/\\\\{.*\\\\})*)*)$\"\n      field: \"@key\"\n    description: \"Resource names should generally be plural.\\n\\n**Invalid Example**\\n\\\n      \\n```json\\n{\\n    \\\"paths\\\": {\\n      \\\"/user\\\":\\n    }\\n  }\\n```\\n\\n**Valid\\\n      \\ Example**\\n\\n```json\\n{\\n    \\\"paths\\\": {\\n      \\\"/users\\\":\\n    }\\n}\\n```\"\n    message: \"Resource names should generally be plural\"\n  paths-no-http-verbs:\n    given:\n    - \"$.paths\"\n    severity: \"error\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"\\\\b(GET|PUT|POST|DELETE|LIST|CREATE|REMOVE|get|put|post|delete|list|create|remove|Get|Put|Post|Delete|List|Create|Remove)\\\\\\\n          b\"\n      field: \"@key\"\n    description: \"Verbs such as `get`, `delete`, and `put` must not be included in\\\n      \\ paths because this information is conveyed by the HTTP method.\\n\\n**Invalid\\\n      \\ Example**\\n\\nThe path contains the verb `get`.\\n\\n```json\\n{\\n    \\\"/getUsers\\\"\\\n      : {\\n       \\\"post: }\\n       ....\\n}\\n```\\n\\n**Valid Example**\\n\\n```json\\n\\\n      {\\n    \\\"/user\\\": {\\n       \\\"post: }\\n       ....\\n}\\n```\"\n    message: \"Paths must not have HTTP verbs in them\"\n  paths-avoid-special-characters:\n    given:\n    - \"$.paths\"\n    severity: \"warn\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"^(.*)([\\\\$&+,;=?@%]+)(.*)$\"\n        match: \"\"\n      field: \"@key\"\n    description: \"Paths should not contain special characters, such as `$` `&` `+`\\\n      \\ `,` `;` `=` `?` and `@%`.\\n\\n**Invalid Example**\\n\\nThe path contains an ampersand.\\n\\\n      \\n```json\\n{\\n    \\\"/user&info\\\": {\\n       \\\"post: }\\n       ....\\n}\\n```\\n\\\n      \\n**Valid Example**\\n\\n```json\\n{\\n    \\\"/user\\\": {\\n       \\\"post: }\\n    \\\n      \\   ....\\n}\\n```\"\n    message: \"Avoid using special characters in paths\"\n','YAML','wso2_rest_api_design_guidelines.yaml'),('50d2bca0-6f5c-4f68-a808-228f51fcde7d',_binary '---\nrules:\n  api-name-required:\n    description: \"API name is required.\"\n    message: \"API name is required.\"\n    severity: \"error\"\n    given: \"$.data\"\n    then:\n      field: \"name\"\n      function: \"truthy\"\n  api-name-no-special-characters:\n    description: \"API name should not contain whitespaces or special characters except\\\n      \\ for hyphens, underscores and periods.\"\n    message: \"API name contains spaces or special characters. Use only letters, numbers,\\\n      \\ hyphens, underscores and periods.\"\n    severity: \"error\"\n    given: \"$.data.name\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        match: \"^[a-zA-Z0-9-_\\\\.]+$\"\n  api-name-length:\n    description: \"API name should be between 1 and 50 characters.\"\n    message: \"API name must be between 1 and 50 characters.\"\n    severity: \"error\"\n    given: \"$.data.name\"\n    then:\n      function: \"length\"\n      functionOptions:\n        min: 1\n        max: 50\n  api-name-cannot-contain-version:\n    description: \"API name should not contain a semantic version substring (e.g.,\\\n      \\ x.y.z). This helps keep the version separate from the API name.\\n**Correct\\\n      \\ Example**: ```json {\\n  \\\"data\\\": {\\n    \\\"name\\\": \\\"CustomerProfileAPI\\\"\\n\\\n      \\  }\\n} ```\\n**Incorrect Example**: ```json {\\n  \\\"data\\\": {\\n    \\\"name\\\":\\\n      \\ \\\"CustomerProfileAPI-1.2.3\\\"\\n  }\\n} ```\\n\"\n    message: \"API name should not contain the version.\"\n    severity: \"warn\"\n    given: \"$.data.name\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"[0-9]+\\\\.[0-9]+\\\\.[0-9]+\"\n  api-context-required:\n    description: \"Checks that the API context field is present and starts with a slash.\"\n    message: \"API \'context\' must be present and begin with \'/\'.\"\n    severity: \"error\"\n    given: \"$.data\"\n    then:\n      field: \"context\"\n      function: \"truthy\"\n  api-context-no-special-characters:\n    description: \"API context should not contain whitespaces or special characters\\\n      \\ except for hyphens, underscores, periods and forward slashes.\"\n    message: \"API context contains spaces or special characters. Use only letters,\\\n      \\ numbers, hyphens, underscores, periods and forwards slashes.\"\n    severity: \"error\"\n    given: \"$.data.context\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        match: \"^/[\\\\{\\\\}/a-zA-Z0-9-_\\\\\\\\.]+$\"\n  api-context-length:\n    description: \"API context should be between 1 and 200 characters.\"\n    message: \"API context must be between 1 and 200 characters.\"\n    severity: \"error\"\n    given: \"$.data.context\"\n    then:\n      function: \"length\"\n      functionOptions:\n        min: 1\n        max: 200\n  api-context-cannot-end-with-slash:\n    description: \"API context should not end with a slash. For example, `/myapi/`\\\n      \\ is disallowed.\\n**Correct Example**: ```json {\\n  \\\"data\\\": {\\n    \\\"context\\\"\\\n      : \\\"/myapi\\\"\\n  }\\n} ```\\n**Incorrect Example**: ```json {\\n  \\\"data\\\": {\\n\\\n      \\    \\\"context\\\": \\\"/myapi/\\\"\\n  }\\n} ```\\n\"\n    message: \"API context should not end with a slash.\"\n    severity: \"error\"\n    given: \"$.data.context\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"/$\"\n  api-context-cannot-contain-version:\n    description: \"API context should not contain the version (e.g., x.y.z) embedded.\\\n      \\ Instead, the version is specified separately in the \'version\' field.\\n**Correct\\\n      \\ Example**: ```json {\\n  \\\"data\\\": {\\n    \\\"context\\\": \\\"/customer\\\"\\n  }\\n\\\n      } ```\\n**Incorrect Example**: ```json {\\n  \\\"data\\\": {\\n    \\\"context\\\": \\\"\\\n      /customer/1.2.3\\\"\\n  }\\n} ```\\n\"\n    message: \"API context should not contain the version.\"\n    severity: \"warn\"\n    given: \"$.data.context\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"[0-9]+\\\\.[0-9]+\\\\.[0-9]+\"\n  api-version-required:\n    description: \"Verifies the API version is specified and not empty.\"\n    message: \"API \'version\' is missing or empty.\"\n    severity: \"error\"\n    given: \"$.data\"\n    then:\n      field: \"version\"\n      function: \"truthy\"\n  api-no-unlimited-business-plan:\n    description: \"API should not have an unlimited business plan.\"\n    message: \"API should not have an unlimited business plan.\"\n    severity: \"warn\"\n    given: \"$.data.policies.*\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"Unlimited\"\n  api-no-insecure-transports:\n    description: \"API should not have insecure transports.\"\n    message: \"API should not have insecure transports.\"\n    severity: \"warn\"\n    given: \"$.data.transport.*\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"http$\"\n  api-tags:\n    description: \"API should have tags.\"\n    message: \"API should have tags.\"\n    severity: \"warn\"\n    given: \"$.data\"\n    then:\n      field: \"tags\"\n      function: \"truthy\"\n  api-tags-count:\n    description: \"API should have at least one tag.\"\n    message: \"API should have at least one tag.\"\n    severity: \"warn\"\n    given: \"$.data.tags\"\n    then:\n      function: \"length\"\n      functionOptions:\n        min: 1\n  api-business-owner-email:\n    description: \"Checks that the business ownerâ€™s email is set\"\n    message: \"Business owner email is missing or empty.\"\n    severity: \"warn\"\n    given: \"$.data.businessInformation\"\n    then:\n      field: \"businessOwnerEmail\"\n      function: \"truthy\"\n  api-business-owner-email-format:\n    description: \"Checks that the business ownerâ€™s email is valid.\"\n    message: \"Business owner email seems invalid. Please use a proper email format.\"\n    severity: \"error\"\n    given: \"$.data.businessInformation\"\n    then:\n      field: \"businessOwnerEmail\"\n      function: \"pattern\"\n      functionOptions:\n        match: \"^[^@\\\\s]+@[^@\\\\s]+\\\\.[^@\\\\s]+$\"\n  api-business-owner:\n    description: \"Checks that the business owner is set\"\n    message: \"Business owner is missing or empty.\"\n    severity: \"warn\"\n    given: \"$.data.businessInformation\"\n    then:\n      field: \"businessOwner\"\n      function: \"truthy\"\n  api-technical-owner:\n    description: \"Checks that the technical owner is set\"\n    message: \"Technical owner is missing or empty.\"\n    severity: \"warn\"\n    given: \"$.data.businessInformation\"\n    then:\n      field: \"technicalOwner\"\n      function: \"truthy\"\n  api-technical-owner-email:\n    description: \"Checks that the technical ownerâ€™s email is set\"\n    message: \"Technical owner email is missing or empty.\"\n    severity: \"warn\"\n    given: \"$.data.businessInformation\"\n    then:\n      field: \"technicalOwnerEmail\"\n      function: \"truthy\"\n  api-technical-owner-email-format:\n    description: \"Checks that the technical ownerâ€™s email is valid.\"\n    message: \"Technical owner email seems invalid. Please use a proper email format.\"\n    severity: \"error\"\n    given: \"$.data.businessInformation\"\n    then:\n      field: \"technicalOwnerEmail\"\n      function: \"pattern\"\n      functionOptions:\n        match: \"^[^@\\\\s]+@[^@\\\\s]+\\\\.[^@\\\\s]+$\"\n  api-endpointConfig-production-required:\n    description: \"Confirms that a production endpoint is provided.\"\n    message: \"Production endpoint is missing or has an empty URL.\"\n    severity: \"error\"\n    given: \"$.data.endpointConfig\"\n    then:\n      field: \"production_endpoints\"\n      function: \"truthy\"\n  api-endpointConfig-sandbox-suggestion:\n    description: \"Suggests providing a sandbox endpoint for testing if not already\\\n      \\ present.\"\n    message: \"Consider providing a sandbox endpoint for testing.\"\n    severity: \"info\"\n    given: \"$.data.endpointConfig\"\n    then:\n      field: \"sandbox_endpoints\"\n      function: \"truthy\"\n  api-no-unlimited-throttling-policy:\n    description: \"API should not have an unlimited throttling policy.\"\n    message: \"API should not have an unlimited throttling policy.\"\n    severity: \"warn\"\n    given: \"$.data.apiThrottlingPolicy\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"^Unlimited$\"\n  api-resources-security-required:\n    description: \"Checks that security is enabled for all resources.\"\n    message: \"Security is not enabled for all resources.\"\n    severity: \"error\"\n    given: \"$.data.operations.*\"\n    then:\n      field: \"authType\"\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"None\"\n','YAML','wso2_api_management_guidelines.yaml'),('86c2c300-e2b7-4f7a-8331-18dbd632cb41',_binary '---\nrules:\n  owasp:api2:2023-no-http-basic:\n    given:\n    - \"$.components.securitySchemes[*]\"\n    severity: \"error\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"basic\"\n      field: \"scheme\"\n    description: \"Basic authentication credentials transported over network are more\\\n      \\ susceptible to interception than other forms of authentication, and as they\\\n      \\ are not encrypted it means passwords and tokens are more easily leaked.\"\n    message: \"Security scheme uses HTTP Basic. Use a more secure authentication method,\\\n      \\ like OAuth 2, or OpenID.\"\n    resolved: true\n    formats:\n    - \"oas2\"\n    - \"oas3\"\n  owasp:api2:2023-jwt-best-practices:\n    given:\n    - \"$.components.securitySchemes[?(@ && @.type==\\\"oauth2\\\")]\"\n    - \"$.components.securitySchemes[?(@ && (@.bearerFormat==\\\"jwt\\\" || @.bearerFormat==\\\"\\\n      JWT\\\"))]\"\n    severity: \"error\"\n    then:\n    - function: \"truthy\"\n      field: \"description\"\n    - function: \"pattern\"\n      functionOptions:\n        match: \".*RFC8725.*\"\n      field: \"description\"\n    description: \"JSON Web Tokens RFC7519 is a compact, URL-safe, means of representing\\\n      \\ claims to be transferred between two parties. JWT can be enclosed in encrypted\\\n      \\ or signed tokens like JWS and JWE.\\n\\nThe [JOSE IANA registry](https://www.iana.org/assignments/jose/jose.xhtml)\\\n      \\ provides algorithms information.\\n\\nRFC8725 describes common pitfalls in the\\\n      \\ JWx specifications and in\\ntheir implementations, such as:\\n- the ability\\\n      \\ to ignore algorithms, eg. `{\\\"alg\\\": \\\"none\\\"}`;\\n- using insecure algorithms\\\n      \\ like `RSASSA-PKCS1-v1_5` eg. `{\\\"alg\\\": \\\"RS256\\\"}`.\\nAn API using JWT should\\\n      \\ explicit in the `description`\\nthat the implementation conforms to RFC8725.\\n\\\n      ```\\ncomponents:\\n  securitySchemes:\\n    JWTBearer:\\n      type: http\\n   \\\n      \\   scheme: bearer\\n      bearerFormat: JWT\\n      description: |-\\n       \\\n      \\ A bearer token in the format of a JWS and conformato\\n        to the specifications\\\n      \\ included in RFC8725.\\n```\"\n    message: \"Security schemes using JWTs must explicitly declare support for RFC8725\\\n      \\ in the description.\"\n    resolved: true\n    formats:\n    - \"oas2\"\n    - \"oas3\"\n  owasp:api3:2023-no-additionalProperties:\n    given:\n    - \"$..[?(@ && @.type==\\\"object\\\" && @.additionalProperties)]\"\n    severity: \"warn\"\n    then:\n      function: \"falsy\"\n      field: \"additionalProperties\"\n    description: \"By default JSON Schema allows additional properties, which can potentially\\\n      \\ lead to mass assignment issues, where unspecified fields are passed to the\\\n      \\ API without validation. Disable them with `additionalProperties: false` or\\\n      \\ add `maxProperties`.\"\n    message: \"If the additionalProperties keyword is used it must be set to false.\"\n    resolved: true\n    formats:\n    - \"oas3_0\"\n  owasp:api3:2023-constrained-additionalProperties:\n    given:\n    - \"$..[?(@ && @.type==\\\"object\\\" && @.additionalProperties &&  @.additionalProperties!=true\\\n      \\ &&  @.additionalProperties!=false )]\"\n    severity: \"warn\"\n    then:\n      function: \"defined\"\n      field: \"maxProperties\"\n    description: \"By default JSON Schema allows additional properties, which can potentially\\\n      \\ lead to mass assignment issues, where unspecified fields are passed to the\\\n      \\ API without validation. Disable them with `additionalProperties: false` or\\\n      \\ add `maxProperties`\"\n    message: \"Objects should not allow unconstrained additionalProperties.\"\n    resolved: true\n    formats:\n    - \"oas3_0\"\n  owasp:api3:2023-no-unevaluatedProperties:\n    given:\n    - \"$..[?(@ && @.type==\\\"object\\\" && @.unevaluatedProperties)]\"\n    severity: \"warn\"\n    then:\n      function: \"falsy\"\n      field: \"unevaluatedProperties\"\n    description: \"By default JSON Schema allows unevaluated properties, which can\\\n      \\ potentially lead to mass assignment issues, where unspecified fields are passed\\\n      \\ to the API without validation. Disable them with `unevaluatedProperties: false`\\\n      \\ or add `maxProperties`.\"\n    message: \"If the unevaluatedProperties keyword is used it must be set to false.\"\n    resolved: true\n    formats:\n    - \"oas3_1\"\n  owasp:api3:2023-constrained-unevaluatedProperties:\n    given:\n    - \"$..[?(@ && @.type==\\\"object\\\" && @.unevaluatedProperties &&  @.unevaluatedProperties!=true\\\n      \\ &&  @.unevaluatedProperties!=false )]\"\n    severity: \"warn\"\n    then:\n      function: \"defined\"\n      field: \"maxProperties\"\n    description: \"By default JSON Schema allows unevaluated properties, which can\\\n      \\ potentially lead to mass assignment issues, where unspecified fields are passed\\\n      \\ to the API without validation. Disable them with `unevaluatedProperties: false`\\\n      \\ or add `maxProperties`\"\n    message: \"Objects should not allow unconstrained unevaluatedProperties.\"\n    resolved: true\n    formats:\n    - \"oas3_1\"\n  owasp:api4:2023-rate-limit-retry-after:\n    given:\n    - \"$..responses[429].headers\"\n    severity: \"error\"\n    then:\n      function: \"defined\"\n      field: \"Retry-After\"\n    description: \"Define proper rate limiting to avoid attackers overloading the API.\\\n      \\ Part of that involves setting a Retry-After header so well meaning consumers\\\n      \\ are not polling and potentially exacerbating problems.\"\n    message: \"A 429 response should define a Retry-After header.\"\n    resolved: true\n    formats:\n    - \"oas3\"\n  owasp:api4:2023-rate-limit-responses-429:\n    given:\n    - \"$.paths..responses\"\n    severity: \"warn\"\n    then:\n    - function: \"truthy\"\n      field: \"429\"\n    - function: \"truthy\"\n      field: \"429.content\"\n    description: \"OWASP API Security recommends defining schemas for all responses,\\\n      \\ even errors. A HTTP 429 response signals the API client is making too many\\\n      \\ requests, and will supply information about when to retry so that the client\\\n      \\ can back off calmly without everything breaking. Defining this response is\\\n      \\ important not just for documentation, but to empower contract testing to make\\\n      \\ sure the proper JSON structure is being returned instead of leaking implementation\\\n      \\ details in backtraces. It also ensures your API/framework/gateway actually\\\n      \\ has rate limiting set up.\"\n    message: \"Operation is missing rate limiting response in {{property}}.\"\n    resolved: true\n    formats:\n    - \"oas2\"\n    - \"oas3\"\n  owasp:api8:2023-no-scheme-http:\n    given:\n    - \"$.schemes.*\"\n    severity: \"error\"\n    then:\n      function: \"schema\"\n      functionOptions:\n        schema:\n          type: \"string\"\n          enum:\n          - \"https\"\n          - \"wss\"\n    description: \"Server interactions must use the http protocol as it\'s inherently\\\n      \\ insecure and can lead to PII and other sensitive information being leaked\\\n      \\ through traffic sniffing or man-in-the-middle attacks. Use the https or wss\\\n      \\ schemes instead.\\n\\nLearn more about the importance of TLS (over SSL) here:\\\n      \\ [https://cheatsheetseries.owasp.org/cheatsheets/Transport_Layer_Security_Cheat_Sheet.html](https://cheatsheetseries.owasp.org/cheatsheets/Transport_Layer_Security_Cheat_Sheet.html)\"\n    message: \"Server schemes must not use http. Use https or wss instead.\"\n    resolved: true\n    formats:\n    - \"oas2\"\n  owasp:api8:2023-no-server-http:\n    given:\n    - \"$.servers..url\"\n    severity: \"error\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"/^http:/\"\n    description: \"Server interactions must not use the http:// as it\'s inherently\\\n      \\ insecure and can lead to PII and other sensitive information being leaked\\\n      \\ through traffic sniffing or man-in-the-middle attacks. Use https:// or wss://\\\n      \\ protocols instead.\\n\\nLearn more about the importance of TLS (over SSL) here:\\\n      \\ [https://cheatsheetseries.owasp.org/cheatsheets/Transport_Layer_Security_Cheat_Sheet.html](https://cheatsheetseries.owasp.org/cheatsheets/Transport_Layer_Security_Cheat_Sheet.html)\"\n    message: \"Server URLs must not use http://. Use https:// or wss:// instead.\"\n    resolved: true\n    formats:\n    - \"oas3\"\n  owasp:api8:2023-define-error-validation:\n    given:\n    - \"$.paths..responses\"\n    severity: \"warn\"\n    then:\n      function: \"schema\"\n      functionOptions:\n        schema:\n          type: \"object\"\n          anyOf:\n          - required:\n            - \"400\"\n          - required:\n            - \"422\"\n          - required:\n            - \"4XX\"\n    description: \"Carefully define schemas for all the API responses, including either\\\n      \\ 400, 422 or 4XX responses which describe errors caused by invalid requests.\"\n    message: \"Missing error response of either 400, 422 or 4XX.\"\n    resolved: true\n    formats:\n    - \"oas2\"\n    - \"oas3\"\n  owasp:api8:2023-define-error-responses-401:\n    given:\n    - \"$.paths..responses\"\n    severity: \"warn\"\n    then:\n    - function: \"truthy\"\n      field: \"401\"\n    - function: \"truthy\"\n      field: \"401.content\"\n    description: \"OWASP API Security recommends defining schemas for all responses,\\\n      \\ even errors. The 401 describes what happens when a request is unauthorized,\\\n      \\ so its important to define this not just for documentation, but to empower\\\n      \\ contract testing to make sure the proper JSON structure is being returned\\\n      \\ instead of leaking implementation details in backtraces.\"\n    message: \"Operation is missing {{property}}.\"\n    resolved: true\n    formats:\n    - \"oas2\"\n    - \"oas3\"\n  owasp:api8:2023-define-error-responses-500:\n    given:\n    - \"$.paths..responses\"\n    severity: \"warn\"\n    then:\n    - function: \"truthy\"\n      field: \"500\"\n    - function: \"truthy\"\n      field: \"500.content\"\n    description: \"OWASP API Security recommends defining schemas for all responses,\\\n      \\ even errors. The 500 describes what happens when a request fails with an internal\\\n      \\ server error, so its important to define this not just for documentation,\\\n      \\ but to empower contract testing to make sure the proper JSON structure is\\\n      \\ being returned instead of leaking implementation details in backtraces.\"\n    message: \"Operation is missing {{property}}.\"\n    resolved: true\n    formats:\n    - \"oas2\"\n    - \"oas3\"\n  owasp:api9:2023-inventory-access:\n    given:\n    - \"$.servers.*\"\n    severity: \"error\"\n    then:\n      function: \"defined\"\n      field: \"x-internal\"\n    description: \"Servers are required to use vendor extension x-internal set to true\\\n      \\ or false to explicitly explain the audience for the API, which will be picked\\\n      \\ up by most documentation tools.\"\n    message: \"Declare intended audience of every server by defining servers{{property}}\\\n      \\ as true/false.\"\n    resolved: true\n    formats:\n    - \"oas3\"\n  owasp:api9:2023-inventory-environment:\n    given:\n    - \"$.servers.*\"\n    severity: \"error\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        match: \"/(local|sandbox|alpha|beta|test|testing|stag|staging|prod|production|next|preprod|preproduction)/i\"\n      field: \"description\"\n    description: \"Make it clear which servers are expected to run as which environment\\\n      \\ to avoid unexpected problems, exposing test data to the public, or letting\\\n      \\ bad actors bypass security measures to get to production-like environments.\"\n    message: \"Declare intended environment in server descriptions using terms like\\\n      \\ local, staging, production.\"\n    resolved: true\n    formats:\n    - \"oas3\"\n','YAML','owasp_top_10.yaml'),('9692e2a3-bd17-493a-a3c7-02614a42e9a9',_binary '---\nrules:\n  api-name-required:\n    description: \"API name is required.\"\n    message: \"API name is required.\"\n    severity: \"error\"\n    given: \"$.data\"\n    then:\n      field: \"name\"\n      function: \"truthy\"\n  api-name-no-special-characters:\n    description: \"API name should not contain whitespaces or special characters except\\\n      \\ for hyphens, underscores and periods.\"\n    message: \"API name contains spaces or special characters. Use only letters, numbers,\\\n      \\ hyphens, underscores and periods.\"\n    severity: \"error\"\n    given: \"$.data.name\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        match: \"^[a-zA-Z0-9-_\\\\.]+$\"\n  api-name-length:\n    description: \"API name should be between 1 and 50 characters.\"\n    message: \"API name must be between 1 and 50 characters.\"\n    severity: \"error\"\n    given: \"$.data.name\"\n    then:\n      function: \"length\"\n      functionOptions:\n        min: 1\n        max: 50\n  api-name-cannot-contain-version:\n    description: \"API name should not contain a semantic version substring (e.g.,\\\n      \\ x.y.z). This helps keep the version separate from the API name.\\n**Correct\\\n      \\ Example**: ```json {\\n  \\\"data\\\": {\\n    \\\"name\\\": \\\"CustomerProfileAPI\\\"\\n\\\n      \\  }\\n} ```\\n**Incorrect Example**: ```json {\\n  \\\"data\\\": {\\n    \\\"name\\\":\\\n      \\ \\\"CustomerProfileAPI-1.2.3\\\"\\n  }\\n} ```\\n\"\n    message: \"API name should not contain the version.\"\n    severity: \"warn\"\n    given: \"$.data.name\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"[0-9]+\\\\.[0-9]+\\\\.[0-9]+\"\n  api-context-required:\n    description: \"Checks that the API context field is present and starts with a slash.\"\n    message: \"API \'context\' must be present and begin with \'/\'.\"\n    severity: \"error\"\n    given: \"$.data\"\n    then:\n      field: \"context\"\n      function: \"truthy\"\n  api-context-no-special-characters:\n    description: \"API context should not contain whitespaces or special characters\\\n      \\ except for hyphens, underscores, periods and forward slashes.\"\n    message: \"API context contains spaces or special characters. Use only letters,\\\n      \\ numbers, hyphens, underscores, periods and forwards slashes.\"\n    severity: \"error\"\n    given: \"$.data.context\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        match: \"^/[\\\\{\\\\}/a-zA-Z0-9-_\\\\\\\\.]+$\"\n  api-context-length:\n    description: \"API context should be between 1 and 200 characters.\"\n    message: \"API context must be between 1 and 200 characters.\"\n    severity: \"error\"\n    given: \"$.data.context\"\n    then:\n      function: \"length\"\n      functionOptions:\n        min: 1\n        max: 200\n  api-context-cannot-end-with-slash:\n    description: \"API context should not end with a slash. For example, `/myapi/`\\\n      \\ is disallowed.\\n**Correct Example**: ```json {\\n  \\\"data\\\": {\\n    \\\"context\\\"\\\n      : \\\"/myapi\\\"\\n  }\\n} ```\\n**Incorrect Example**: ```json {\\n  \\\"data\\\": {\\n\\\n      \\    \\\"context\\\": \\\"/myapi/\\\"\\n  }\\n} ```\\n\"\n    message: \"API context should not end with a slash.\"\n    severity: \"error\"\n    given: \"$.data.context\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"/$\"\n  api-context-cannot-contain-version:\n    description: \"API context should not contain the version (e.g., x.y.z) embedded.\\\n      \\ Instead, the version is specified separately in the \'version\' field.\\n**Correct\\\n      \\ Example**: ```json {\\n  \\\"data\\\": {\\n    \\\"context\\\": \\\"/customer\\\"\\n  }\\n\\\n      } ```\\n**Incorrect Example**: ```json {\\n  \\\"data\\\": {\\n    \\\"context\\\": \\\"\\\n      /customer/1.2.3\\\"\\n  }\\n} ```\\n\"\n    message: \"API context should not contain the version.\"\n    severity: \"warn\"\n    given: \"$.data.context\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"[0-9]+\\\\.[0-9]+\\\\.[0-9]+\"\n  api-version-required:\n    description: \"Verifies the API version is specified and not empty.\"\n    message: \"API \'version\' is missing or empty.\"\n    severity: \"error\"\n    given: \"$.data\"\n    then:\n      field: \"version\"\n      function: \"truthy\"\n  api-no-unlimited-business-plan:\n    description: \"API should not have an unlimited business plan.\"\n    message: \"API should not have an unlimited business plan.\"\n    severity: \"warn\"\n    given: \"$.data.policies.*\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"Unlimited\"\n  api-no-insecure-transports:\n    description: \"API should not have insecure transports.\"\n    message: \"API should not have insecure transports.\"\n    severity: \"warn\"\n    given: \"$.data.transport.*\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"http$\"\n  api-tags:\n    description: \"API should have tags.\"\n    message: \"API should have tags.\"\n    severity: \"warn\"\n    given: \"$.data\"\n    then:\n      field: \"tags\"\n      function: \"truthy\"\n  api-tags-count:\n    description: \"API should have at least one tag.\"\n    message: \"API should have at least one tag.\"\n    severity: \"warn\"\n    given: \"$.data.tags\"\n    then:\n      function: \"length\"\n      functionOptions:\n        min: 1\n  api-business-owner-email:\n    description: \"Checks that the business ownerâ€™s email is set\"\n    message: \"Business owner email is missing or empty.\"\n    severity: \"warn\"\n    given: \"$.data.businessInformation\"\n    then:\n      field: \"businessOwnerEmail\"\n      function: \"truthy\"\n  api-business-owner-email-format:\n    description: \"Checks that the business ownerâ€™s email is valid.\"\n    message: \"Business owner email seems invalid. Please use a proper email format.\"\n    severity: \"error\"\n    given: \"$.data.businessInformation\"\n    then:\n      field: \"businessOwnerEmail\"\n      function: \"pattern\"\n      functionOptions:\n        match: \"^[^@\\\\s]+@[^@\\\\s]+\\\\.[^@\\\\s]+$\"\n  api-business-owner:\n    description: \"Checks that the business owner is set\"\n    message: \"Business owner is missing or empty.\"\n    severity: \"warn\"\n    given: \"$.data.businessInformation\"\n    then:\n      field: \"businessOwner\"\n      function: \"truthy\"\n  api-technical-owner:\n    description: \"Checks that the technical owner is set\"\n    message: \"Technical owner is missing or empty.\"\n    severity: \"warn\"\n    given: \"$.data.businessInformation\"\n    then:\n      field: \"technicalOwner\"\n      function: \"truthy\"\n  api-technical-owner-email:\n    description: \"Checks that the technical ownerâ€™s email is set\"\n    message: \"Technical owner email is missing or empty.\"\n    severity: \"warn\"\n    given: \"$.data.businessInformation\"\n    then:\n      field: \"technicalOwnerEmail\"\n      function: \"truthy\"\n  api-technical-owner-email-format:\n    description: \"Checks that the technical ownerâ€™s email is valid.\"\n    message: \"Technical owner email seems invalid. Please use a proper email format.\"\n    severity: \"error\"\n    given: \"$.data.businessInformation\"\n    then:\n      field: \"technicalOwnerEmail\"\n      function: \"pattern\"\n      functionOptions:\n        match: \"^[^@\\\\s]+@[^@\\\\s]+\\\\.[^@\\\\s]+$\"\n  api-endpointConfig-production-required:\n    description: \"Confirms that a production endpoint is provided.\"\n    message: \"Production endpoint is missing or has an empty URL.\"\n    severity: \"error\"\n    given: \"$.data.endpointConfig\"\n    then:\n      field: \"production_endpoints\"\n      function: \"truthy\"\n  api-endpointConfig-sandbox-suggestion:\n    description: \"Suggests providing a sandbox endpoint for testing if not already\\\n      \\ present.\"\n    message: \"Consider providing a sandbox endpoint for testing.\"\n    severity: \"info\"\n    given: \"$.data.endpointConfig\"\n    then:\n      field: \"sandbox_endpoints\"\n      function: \"truthy\"\n  api-no-unlimited-throttling-policy:\n    description: \"API should not have an unlimited throttling policy.\"\n    message: \"API should not have an unlimited throttling policy.\"\n    severity: \"warn\"\n    given: \"$.data.apiThrottlingPolicy\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"^Unlimited$\"\n  api-resources-security-required:\n    description: \"Checks that security is enabled for all resources.\"\n    message: \"Security is not enabled for all resources.\"\n    severity: \"error\"\n    given: \"$.data.operations.*\"\n    then:\n      field: \"authType\"\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"None\"\n','YAML','wso2_api_management_guidelines.yaml'),('d53ed719-89c9-4241-9f85-a460465cafa9',_binary '---\naliases:\n  API_Document:\n    description: \"The complete API specification document. This can be used to target\\\n      \\ any part of the OpenAPI document using **field**.\\n\\n*Use this if you don\'t\\\n      \\ find specific targets that cater to your usecase.* \"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$\"\n  Operation_Object:\n    description: \"The complete operation object. Use it in combo with field object.\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"#Path_Item[\'get\']\"\n      - \"#Path_Item[\'put\']\"\n      - \"#Path_Item[\'post\']\"\n      - \"#Path_Item[\'delete\']\"\n      - \"#Path_Item[\'options\']\"\n      - \"#Path_Item[\'head\']\"\n      - \"#Path_Item[\'patch\']\"\n      - \"#Path_Item[\'trace\']\"\n  Operation_Responses:\n    description: \"Responses for all operations including get, put, post, delete, options,\\\n      \\ head, patch, trace.\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"#Operation_Object.responses\"\n  Path_Item:\n    description: \"\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$.paths[*]\"\n  API_Contact:\n    description: \"The top level description in an API document\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$.info.contact\"\n  API_License:\n    description: \"The top level description in an API document\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$.info.license\"\n  All_Markdown:\n    description: \"All markdown descriptions across the document.\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$..description\"\n      - \"$..title\"\n  API_Tags:\n    description: \"Tags on an API object\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"#Operation_Object.tags\"\n  Response_All_Object:\n    description: \"All responses (object) in an API\"\n    targets:\n    - formats:\n      - \"oas2\"\n      given:\n      - \"$.responses\"\n      - \"#Operation_Responses\"\n      - \"$..responses\"\n    - formats:\n      - \"oas3\"\n      given:\n      - \"$.components.responses\"\n      - \"#Operation_Responses\"\n      - \"$..responses\"\n  Request_Parameter_All:\n    description: \"All request parameters\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$..parameters[*]\"\n  Path_Object:\n    description: \"Path object. Usually used to target the Path key e.g. `/users/{userId}`\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$.paths\"\n  API_Document_RecursiveSearch:\n    description: \"The complete API specification document. This can be used to target\\\n      \\ any part of the OpenAPI document using **field**.\\n\\n*Use this if you don\'t\\\n      \\ find specific targets that cater to your usecase.* \"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$..*\"\n  All_Example:\n    description: \"All examples across the API document\"\n    targets:\n    - formats:\n      - \"oas2\"\n      given:\n      - \"$..examples[*]\"\n    - formats:\n      - \"oas3\"\n      given:\n      - \"$.components.examples[*]\"\n      - \"$.paths[*][*]..content[*].examples[*]\"\n      - \"$.paths[*][*]..parameters[*].examples[*]\"\n      - \"$.components.parameters[*].examples[*]\"\n      - \"$.paths[*][*]..headers[*].examples[*]\"\n      - \"$.components.headers[*].examples[*]\"\n  API_Tags_Item:\n    description: \"Tags on an API object\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$.tags[*]\"\n  All_Array_Item:\n    description: \"\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      - \"oas3_0\"\n      given:\n      - \"$..[?(@ && @.type==\'array\')]\"\n  Request_Parameter_Path:\n    description: \"All request path parameters\"\n    targets:\n    - formats:\n      - \"oas2\"\n      - \"oas3\"\n      given:\n      - \"$..parameters[?(@ && @.in==\\\"path\\\")]\"\nrules:\n  contact-url:\n    given:\n    - \"#API_Contact\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"url\"\n    description: \"The `contact` object should have a valid organization URL.\\n\\n**Valid\\\n      \\ Example**\\n\\n```json\\n{\\n  \\\"contact\\\": {\\n     ... ,\\n     \\\"url\\\": \\\"https://acme.com\\\"\\\n      ,\\n     ...\\n  },\\n```\"\n    message: \"Contact object should have \\\"url\\\".\"\n  contact-email:\n    given:\n    - \"#API_Contact\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"email\"\n    description: \"The `contact` object should have a valid email.\\n\\n**Valid Example**\\n\\\n      \\n```json\\n{\\n  \\\"contact\\\": {\\n     ... ,\\n     \\\"email\\\": \\\"support.contact@acme.com\\\"\\\n      \\n  },\\n```\"\n    message: \"Contact object should have \\\"email\\\"\"\n  info-contact:\n    given:\n    - \"#API_Document\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"info.contact\"\n    description: \"The `info` object should include a `contact` object.\\n\\n**Valid\\\n      \\ Example**\\n\\n```json\\n{\\n  \\\"info\\\": {\\n    ... ,\\n    \\\"contact\\\": {\\n  \\\n      \\    \\\"name\\\": \\\"ACME Corporation\\\",\\n      \\\"url\\\": \\\"https://acme.com\\\",\\n\\\n      \\      \\\"email\\\": \\\"support.contact@acme.com\\\"\\n    }\\n  }\\n}\\n```\"\n    message: \"Info object should have \\\"contact\\\" object.\"\n  info-description:\n    given:\n    - \"#API_Document\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"info.description\"\n    description: \"The `info` object should have a `description` object.\\n\\n**Valid\\\n      \\ Example**\\n\\n```json\\n{\\n  \\\"info\\\": {\\n     ... ,\\n     \\\"description\\\":\\\n      \\ \\\"This describes my API.\\\"\\n  }\\n}\\n```\"\n    message: \"Info object should have \\\"description\\\" object.\"\n  info-license:\n    given:\n    - \"#API_Document\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"info.license\"\n    description: \"The `info` object should have a `license` object.\\n\\n**Valid Example**\\n\\\n      \\n```json\\n{\\n  \\\"info\\\": {\\n    ... ,\\n    \\\"license\\\": {\\n      \\\"name\\\":\\\n      \\ \\\"Attribution-ShareAlike 4.0 International (CC BY-SA 4.0)\\\",\\n      \\\"url\\\"\\\n      : \\\"https://creativecommons.org/licenses/by-sa/4.0/\\\"\\n    }\\n  }\\n}\\n```\"\n    message: \"Info object should have \\\"license\\\" object.\"\n  license-url:\n    given:\n    - \"#API_License\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"url\"\n    description: \"The `license` object should include a valid url.\\n\\n**Valid Example**\\n\\\n      \\n```json\\n{\\n  \\\"license\\\": {\\n    \\\"name\\\": \\\"Attribution-ShareAlike 4.0 International\\\n      \\ (CC BY-SA 4.0)\\\",\\n    \\\"url\\\": \\\"https://creativecommons.org/licenses/by-sa/4.0/\\\"\\\n      \\n  }\\n}\\n```\"\n    message: \"License object should include \\\"url\\\".\"\n  no-eval-in-markdown:\n    given:\n    - \"#All_Markdown\"\n    severity: \"warn\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"eval\\\\(\"\n    description: \"Markdown descriptions should not contain [`eval()` functions](https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/eval),\\n\\\n      which pose a security risk.\\n\\n**Invalid Example**\\n\\n```json\\n{\\n  \\\"info\\\"\\\n      : {\\n    ... ,\\n    \\\"description\\\": \\\"API for users. eval()\\\"\\n  }\\n}\\n```\"\n    message: \"Markdown descriptions must not have \\\"eval(\\\".\"\n  no-script-tags-in-markdown:\n    given:\n    - \"#All_Markdown\"\n    severity: \"warn\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"<script\"\n    description: \"Markdown descriptions should not contain `script` tags, which pose\\\n      \\ a security risk.\\n\\n**Invalid Example**\\n\\n```json\\n{\\n  \\\"info\\\": {\\n   \\\n      \\ ... ,\\n    \\\"description\\\": \\\"API for users. <script>alert(\\\\\\\"You are Hacked\\\\\\\n      \\\");</script>\\\"\\n  }\\n}\\n```\"\n    message: \"Markdown descriptions must not have \\\"<script>\\\" tags.\"\n  openapi-tags-alphabetical:\n    given:\n    - \"#API_Document\"\n    severity: \"warn\"\n    then:\n      function: \"alphabetical\"\n      functionOptions:\n        keyedBy: \"name\"\n      field: \"tags\"\n    description: \"Global tags specified at the root OpenAPI Document level should\\\n      \\ be in alphabetical order based on the `name` property.\\n\\n**Invalid Example**\\n\\\n      \\n```json\\n{\\n  \\\"tags\\\":[\\n    {\\n      \\\"name\\\":\\\"Z Global Tag\\\"\\n    },\\n\\\n      \\    {\\n      \\\"name\\\":\\\"A Global Tag\\\"\\n    }\\n  ]\\n}\\n```\\n\\n**Valid Example**\\n\\\n      \\n```json\\n{\\n  \\\"tags\\\":[\\n    {\\n      \\\"name\\\":\\\"A Global Tag\\\"\\n    },\\n\\\n      \\    {\\n      \\\"name\\\":\\\"Z Global Tag\\\"\\n    }\\n  ]\\n}\\n```\"\n    message: \"OpenAPI object should have alphabetical \\\"tags\\\".\"\n  openapi-tags:\n    given:\n    - \"#API_Document\"\n    severity: \"warn\"\n    then:\n      function: \"schema\"\n      functionOptions:\n        schema:\n          type: \"array\"\n          minItems: 1\n      field: \"tags\"\n    description: \"At least one global tag should be specified at the root OpenAPI\\\n      \\ Document level.\\n\\n**Valid Example**\\n\\n```json\\n{\\n  \\\"tags\\\":[\\n    {\\n\\\n      \\      \\\"name\\\":\\\"Global Tag #1\\\"\\n    },\\n    {\\n      \\\"name\\\":\\\"Global Tag\\\n      \\ #2\\\"\\n    }\\n  ]\\n}\\n```\"\n    message: \"OpenAPI object should have non-empty \\\"tags\\\" array.\"\n  operation-description:\n    given:\n    - \"#Operation_Object\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"description\"\n    description: \"Each operation should have a description.\\n\\n**Valid Example**\\n\\\n      \\n```json\\n{\\n  \\\"get\\\": {\\n    \\\"description\\\": \\\"Get a list of users.\\\"\\n\\\n      \\  }\\n}\\n```\"\n    message: \"Operation \\\"description\\\" should be present and non-empty string.\"\n  operation-operationId:\n    given:\n    - \"#Operation_Object\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"operationId\"\n    description: \"All operations should have an `operationId`.\\n\\n**Valid Example**\\n\\\n      \\n```json\\n{\\n  \\\"get\\\": {\\n    \\\"summary\\\": \\\"Get users\\\",\\n    \\\"operationId\\\"\\\n      : \\\"get-users\\\"\\n  }\\n}\\n```\"\n    message: \"Operation should have \\\"operationId\\\".\"\n  operation-operationId-valid-in-url:\n    given:\n    - \"#Operation_Object\"\n    severity: \"error\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        match: \"^[A-Za-z0-9-._~:/?#\\\\[\\\\]@!\\\\$&\'()*+,;=]*$\"\n      field: \"operationId\"\n    description: \"Operation IDs must not contain characters that are invalid for URLs.\\n\\\n      \\n**Invalid Example**\\n\\nThe `operationId` in this example includes a pipe and\\\n      \\ space, which are invalid for URLs.\\n\\n```json\\n{\\n  \\\"/users\\\": {\\n    \\\"\\\n      get\\\": {\\n      \\\"operationId\\\": \\\"invalid|operationID\\\"\\n    }\\n  }\\n}\\n```\\n\\\n      \\n**Valid Example**\\n\\nThis `operationId` is valid for URLs.\\n\\n```json\\n{\\n\\\n      \\  \\\"/users\\\": {\\n    \\\"get\\\": {\\n      \\\"operationId\\\": \\\"this-must-be-unique\\\"\\\n      \\n    }\\n  }\\n}\\n```\"\n    message: \"OperationId should not have characters that are invalid when used in\\\n      \\ URL.\"\n  operation-tags:\n    given:\n    - \"#Operation_Object\"\n    severity: \"warn\"\n    then:\n    - function: \"length\"\n      functionOptions:\n        max: 999\n        min: 1\n      field: \"tags\"\n    - function: \"truthy\"\n      field: \"tags\"\n    description: \"At least one tag should be defined for each operation.\\n\\n**Valid\\\n      \\ Example**\\n\\n```json\\n{\\n  \\\"get\\\": {\\n    \\\"tags\\\": [\\\"Users\\\"]\\n  }\\n}\\n\\\n      ```\"\n    message: \"Operation should have non-empty \\\"tags\\\" array.\"\n  path-declarations-must-exist:\n    given:\n    - \"#Path_Object\"\n    severity: \"error\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"\\\\{\\\\}\"\n      field: \"@key\"\n    description: \"Path parameter declarations must not be empty.\\n\\n**Invalid Example**\\n\\\n      \\n`/users/{}`\\n\\n**Valid Example**\\n\\n`/users/{userId}`\"\n    message: \"Path parameter declarations must not be empty, e.g., \\\"/given/{}\\\" is\\\n      \\ invalid.\"\n  paths-no-trailing-slash:\n    given:\n    - \"#Path_Object\"\n    severity: \"error\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \".+\\\\/$\"\n      field: \"@key\"\n    description: \"Paths must not end with a trailing slash.\\n\\n`/users` and `/users/`\\\n      \\ are separate paths. It\'s considered bad practice for them to differ based\\\n      \\ only on a trailing slash. It\'s usually preferred to not have a trailing slash.\\n\\\n      \\n**Invalid Example**\\n\\nThe `users` path ends with a slash.\\n\\n```json\\n{\\n\\\n      \\  \\\"/users/\\\": {\\n    \\\"post\\\": {}\\n  }\\n}\\n```\\n\\n**Valid Example**\\n\\n```json\\n\\\n      {\\n  \\\"/user\\\": {\\n    \\\"post\\\": {}\\n  }\\n}\\n```\"\n  contact-name:\n    given:\n    - \"#API_Contact\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"name\"\n    description: \"The `contact` object should have an organization name.\\n\\n**Valid\\\n      \\ Example**\\n\\n```json\\n{\\n  \\\"contact\\\": {\\n    \\\"name\\\": \\\"ACME Corporation\\\"\\\n      \\n  }\\n}\\n```\"\n    message: \"Contact object should have \\\"name\\\".\"\n  path-not-include-query:\n    given:\n    - \"#Path_Object\"\n    severity: \"warn\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"\\\\?\"\n      field: \"@key\"\n    description: \"Paths should not include `query` string items. Instead, add them\\\n      \\ as parameters with `in: query`.\\n\\n**Invalid Example**\\n\\n```json\\n{\\n  \\\"\\\n      /users/{?id}\\\": {\\n  }\\n}\\n```\\n\\n**Valid Example**\\n\\n```json\\n{\\n  \\\"parameters\\\"\\\n      : [\\n    {\\n      \\\"schema\\\": {\\n        \\\"type\\\": \\\"string\\\"\\n      },\\n  \\\n      \\    \\\"name\\\": \\\"id\\\",\\n      \\\"in\\\": \\\"path\\\",\\n      \\\"required\\\": true,\\n\\\n      \\      \\\"description\\\": \\\"User\'s ID\\\"\\n    }\\n  ]\\n}\\n```\"\n    message: \"Path should not include query string.\"\n  tag-description:\n    given:\n    - \"#API_Tags_Item\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"description\"\n    description: \"Tags defined at the global level should have a description.\\n\\n\\\n      **Valid Example**\\n\\n```json\\n{\\n  \\\"tags\\\": [\\n    {\\n      \\\"name\\\": \\\"Users\\\"\\\n      ,\\n      \\\"description\\\": \\\"End-user information\\\"\\n    }\\n  ]\\n}\\n```\"\n    message: \"Tag object should have \\\"description\\\".\"\n  parameter-description:\n    given:\n    - \"#Request_Parameter_All\"\n    severity: \"warn\"\n    then:\n      function: \"truthy\"\n      field: \"description\"\n    description: \"All `parameter` objects should have a description.\\n\\n**Valid Example**\\n\\\n      \\n```json\\n{\\n  \\\"parameters\\\": [\\n    {\\n      \\\"schema\\\": {\\n        \\\"type\\\"\\\n      : \\\"integer\\\"\\n      },\\n      ... ,\\n      ... ,\\n      \\\"description\\\": \\\"\\\n      The number of days to include in the response.\\\"\\n    }\\n  ]\\n}\\n```\\n\"\n    message: \"Parameter objects must have \\\"description\\\".\"\n  oas3-examples-value-or-externalValue:\n    given:\n    - \"#All_Example\"\n    severity: \"warn\"\n    then:\n      function: \"xor\"\n      functionOptions:\n        properties:\n        - \"externalValue\"\n        - \"value\"\n    description: \"The `examples` object should include a `value` or `externalValue`\\\n      \\ field, but cannot include both.\\n\\n**Invalid Example**\\n\\nThis example includes\\\n      \\ both a `value` field and an `externalValue` field.\\n\\n```json\\n{\\n  \\\"examples\\\"\\\n      : {\\n    \\\"example-1\\\": {\\n      \\\"value\\\": {\\n        \\\"id\\\": \\\"string\\\",\\n\\\n      \\        \\\"name\\\": \\\"string\\\"\\n      },\\n      \\\"externalValue\\\": {\\n      \\\n      \\  \\\"id\\\": \\\"string\\\",\\n        \\\"name\\\": \\\"string\\\"\\n      }\\n    }\\n  }\\n\\\n      }\\n```\\n\\n**Valid Example**\\n\\nThis example includes only a `value` field.\\n\\\n      \\n```json\\n{\\n  \\\"examples\\\": {\\n    \\\"example-1\\\": {\\n      \\\"value\\\": {\\n\\\n      \\        \\\"id\\\": \\\"string\\\",\\n        \\\"name\\\": \\\"string\\\"\\n      }\\n    }\\n\\\n      \\  }\\n}\\n```\\n\"\n    message: \"Examples must have either \\\"value\\\" or \\\"externalValue\\\" field.\"\n    formats:\n    - \"oas3\"\n  array-items:\n    given:\n    - \"#All_Array_Item\"\n    severity: \"error\"\n    then:\n      function: \"truthy\"\n      field: \"items\"\n    description: \"Schemas with `type: array`, require a sibling `items` field.\\n\\n\\\n      **Recommended:** Yes\\n\\n**Good Example**\\n\\n```yaml\\nTheGoodModel:\\n  type:\\\n      \\ object\\n  properties:\\n    favoriteColorSets:\\n      type: array\\n      items:\\n\\\n      \\        type: array\\n        items: {}\\n```\\n\\n**Bad Example**\\n\\n```yaml\\n\\\n      TheBadModel:\\n  type: object\\n  properties:\\n    favoriteColorSets:\\n      type:\\\n      \\ array\\n      items:\\n        type: array\\n```\"\n    message: \"Schemas with \\\"type: array\\\", require a sibling \\\"items\\\" field\"\n  path-parameters-on-path-only:\n    given:\n    - \"$.paths[*][*].parameters[?(@.in == \'path\')]\"\n    severity: \"warn\"\n    then:\n      function: \"falsy\"\n    description: \"Path parameters should be defined on the path level instead of the\\\n      \\ operation level.\\n\\n**Invalid Example**\\n\\nThe `user_id` path parameter on\\\n      \\ line 8 should not be included with the `patch` operation.\\n\\n```json\\n{\\n\\\n      \\  \\\"patch\\\": {\\n    \\\"parameters\\\": [\\n      {\\n        \\\"schema\\\": {\\n   \\\n      \\       \\\"type\\\": \\\"integer\\\"\\n        },\\n        \\\"name\\\": \\\"user_id\\\",\\n\\\n      \\        \\\"in\\\": \\\"path\\\"\\n      }\\n    ]\\n  }\\n}\\n```\\n\\n**Valid Example**\\n\\\n      \\nThe `user-id` path parameter is correctly located at the path level.\\n\\n```json\\n\\\n      {\\n  \\\"paths\\\": {\\n    \\\"/users/{userId}\\\": {\\n      \\\"parameters\\\": [\\n   \\\n      \\     {\\n          \\\"schema\\\": {\\n            \\\"type\\\": \\\"integer\\\"\\n      \\\n      \\    },\\n          \\\"name\\\": \\\"user_id\\\",\\n          \\\"in\\\": \\\"path\\\"\\n    \\\n      \\    }\\n      ]\\n    }\\n  }\\n}\\n```\"\n    message: \"Path parameters should be defined on the path level.\"\n  paths-no-query-params:\n    given:\n    - \"$.paths\"\n    severity: \"warn\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"\\\\?\"\n      field: \"@key\"\n    description: \"Paths should not have query parameters in them. They should be defined\\\n      \\ separately in the OpenAPI.\\n\\n**Invalid Example**\\n\\n```json\\n{\\n  \\\"/users/{?id}\\\"\\\n      : {\\n```\\n\\n**Valid Example**\\n\\n```json\\n{\\n  \\\"parameters\\\": [\\n    {\\n  \\\n      \\    \\\"schema\\\": {\\n        \\\"type\\\": \\\"string\\\"\\n      },\\n      \\\"name\\\":\\\n      \\ \\\"id\\\",\\n      \\\"in\\\": \\\"path\\\",\\n      \\\"required\\\": true,\\n      \\\"description\\\"\\\n      : \\\"User\'s ID\\\"\\n    }\\n  ]\\n}\\n```\"\n    message: \"Paths should not have query parameters in them. They should be defined\\\n      \\ separately in the OpenAPI.\"\n  path-casing:\n    given:\n    - \"$.paths\"\n    severity: \"error\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        match: \"^\\\\/([a-z0-9]+(-[a-z0-9]+)*)?(\\\\/[a-z0-9]+(-[a-z0-9]+)*|\\\\/\\\\{.+\\\\\\\n          })*$\"\n      field: \"@key\"\n    description: \"Paths must be `kebab-case`, with hyphens separating words.\\n\\n**Invalid\\\n      \\ Example**\\n\\n`userInfo` must be separated with a hyphen.\\n\\n```json\\n{\\n \\\n      \\   \\\"/userInfo\\\": {\\n        \\\"post: }\\n       ....\\n}\\n```\\n\\n**Valid Example**\\n\\\n      \\n```json\\n{\\n    \\\"/user-info\\\": {\\n       \\\"post: }\\n       ....\\n}\\n```\"\n    message: \"Paths must be kebab-case\"\n  resource-names-plural:\n    given:\n    - \"$.paths\"\n    severity: \"warn\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        match: \"^((\\\\/v\\\\d+)*((\\\\/[\\\\w+-]*s)(\\\\/\\\\{.*\\\\})*)*)$\"\n      field: \"@key\"\n    description: \"Resource names should generally be plural.\\n\\n**Invalid Example**\\n\\\n      \\n```json\\n{\\n    \\\"paths\\\": {\\n      \\\"/user\\\":\\n    }\\n  }\\n```\\n\\n**Valid\\\n      \\ Example**\\n\\n```json\\n{\\n    \\\"paths\\\": {\\n      \\\"/users\\\":\\n    }\\n}\\n```\"\n    message: \"Resource names should generally be plural\"\n  paths-no-http-verbs:\n    given:\n    - \"$.paths\"\n    severity: \"error\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"\\\\b(GET|PUT|POST|DELETE|LIST|CREATE|REMOVE|get|put|post|delete|list|create|remove|Get|Put|Post|Delete|List|Create|Remove)\\\\\\\n          b\"\n      field: \"@key\"\n    description: \"Verbs such as `get`, `delete`, and `put` must not be included in\\\n      \\ paths because this information is conveyed by the HTTP method.\\n\\n**Invalid\\\n      \\ Example**\\n\\nThe path contains the verb `get`.\\n\\n```json\\n{\\n    \\\"/getUsers\\\"\\\n      : {\\n       \\\"post: }\\n       ....\\n}\\n```\\n\\n**Valid Example**\\n\\n```json\\n\\\n      {\\n    \\\"/user\\\": {\\n       \\\"post: }\\n       ....\\n}\\n```\"\n    message: \"Paths must not have HTTP verbs in them\"\n  paths-avoid-special-characters:\n    given:\n    - \"$.paths\"\n    severity: \"warn\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"^(.*)([\\\\$&+,;=?@%]+)(.*)$\"\n        match: \"\"\n      field: \"@key\"\n    description: \"Paths should not contain special characters, such as `$` `&` `+`\\\n      \\ `,` `;` `=` `?` and `@%`.\\n\\n**Invalid Example**\\n\\nThe path contains an ampersand.\\n\\\n      \\n```json\\n{\\n    \\\"/user&info\\\": {\\n       \\\"post: }\\n       ....\\n}\\n```\\n\\\n      \\n**Valid Example**\\n\\n```json\\n{\\n    \\\"/user\\\": {\\n       \\\"post: }\\n    \\\n      \\   ....\\n}\\n```\"\n    message: \"Avoid using special characters in paths\"\n','YAML','wso2_rest_api_design_guidelines.yaml'),('f401081a-360f-44e6-89d9-d65d905fc365',_binary '---\nrules:\n  owasp:api2:2023-no-http-basic:\n    given:\n    - \"$.components.securitySchemes[*]\"\n    severity: \"error\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"basic\"\n      field: \"scheme\"\n    description: \"Basic authentication credentials transported over network are more\\\n      \\ susceptible to interception than other forms of authentication, and as they\\\n      \\ are not encrypted it means passwords and tokens are more easily leaked.\"\n    message: \"Security scheme uses HTTP Basic. Use a more secure authentication method,\\\n      \\ like OAuth 2, or OpenID.\"\n    resolved: true\n    formats:\n    - \"oas2\"\n    - \"oas3\"\n  owasp:api2:2023-jwt-best-practices:\n    given:\n    - \"$.components.securitySchemes[?(@ && @.type==\\\"oauth2\\\")]\"\n    - \"$.components.securitySchemes[?(@ && (@.bearerFormat==\\\"jwt\\\" || @.bearerFormat==\\\"\\\n      JWT\\\"))]\"\n    severity: \"error\"\n    then:\n    - function: \"truthy\"\n      field: \"description\"\n    - function: \"pattern\"\n      functionOptions:\n        match: \".*RFC8725.*\"\n      field: \"description\"\n    description: \"JSON Web Tokens RFC7519 is a compact, URL-safe, means of representing\\\n      \\ claims to be transferred between two parties. JWT can be enclosed in encrypted\\\n      \\ or signed tokens like JWS and JWE.\\n\\nThe [JOSE IANA registry](https://www.iana.org/assignments/jose/jose.xhtml)\\\n      \\ provides algorithms information.\\n\\nRFC8725 describes common pitfalls in the\\\n      \\ JWx specifications and in\\ntheir implementations, such as:\\n- the ability\\\n      \\ to ignore algorithms, eg. `{\\\"alg\\\": \\\"none\\\"}`;\\n- using insecure algorithms\\\n      \\ like `RSASSA-PKCS1-v1_5` eg. `{\\\"alg\\\": \\\"RS256\\\"}`.\\nAn API using JWT should\\\n      \\ explicit in the `description`\\nthat the implementation conforms to RFC8725.\\n\\\n      ```\\ncomponents:\\n  securitySchemes:\\n    JWTBearer:\\n      type: http\\n   \\\n      \\   scheme: bearer\\n      bearerFormat: JWT\\n      description: |-\\n       \\\n      \\ A bearer token in the format of a JWS and conformato\\n        to the specifications\\\n      \\ included in RFC8725.\\n```\"\n    message: \"Security schemes using JWTs must explicitly declare support for RFC8725\\\n      \\ in the description.\"\n    resolved: true\n    formats:\n    - \"oas2\"\n    - \"oas3\"\n  owasp:api3:2023-no-additionalProperties:\n    given:\n    - \"$..[?(@ && @.type==\\\"object\\\" && @.additionalProperties)]\"\n    severity: \"warn\"\n    then:\n      function: \"falsy\"\n      field: \"additionalProperties\"\n    description: \"By default JSON Schema allows additional properties, which can potentially\\\n      \\ lead to mass assignment issues, where unspecified fields are passed to the\\\n      \\ API without validation. Disable them with `additionalProperties: false` or\\\n      \\ add `maxProperties`.\"\n    message: \"If the additionalProperties keyword is used it must be set to false.\"\n    resolved: true\n    formats:\n    - \"oas3_0\"\n  owasp:api3:2023-constrained-additionalProperties:\n    given:\n    - \"$..[?(@ && @.type==\\\"object\\\" && @.additionalProperties &&  @.additionalProperties!=true\\\n      \\ &&  @.additionalProperties!=false )]\"\n    severity: \"warn\"\n    then:\n      function: \"defined\"\n      field: \"maxProperties\"\n    description: \"By default JSON Schema allows additional properties, which can potentially\\\n      \\ lead to mass assignment issues, where unspecified fields are passed to the\\\n      \\ API without validation. Disable them with `additionalProperties: false` or\\\n      \\ add `maxProperties`\"\n    message: \"Objects should not allow unconstrained additionalProperties.\"\n    resolved: true\n    formats:\n    - \"oas3_0\"\n  owasp:api3:2023-no-unevaluatedProperties:\n    given:\n    - \"$..[?(@ && @.type==\\\"object\\\" && @.unevaluatedProperties)]\"\n    severity: \"warn\"\n    then:\n      function: \"falsy\"\n      field: \"unevaluatedProperties\"\n    description: \"By default JSON Schema allows unevaluated properties, which can\\\n      \\ potentially lead to mass assignment issues, where unspecified fields are passed\\\n      \\ to the API without validation. Disable them with `unevaluatedProperties: false`\\\n      \\ or add `maxProperties`.\"\n    message: \"If the unevaluatedProperties keyword is used it must be set to false.\"\n    resolved: true\n    formats:\n    - \"oas3_1\"\n  owasp:api3:2023-constrained-unevaluatedProperties:\n    given:\n    - \"$..[?(@ && @.type==\\\"object\\\" && @.unevaluatedProperties &&  @.unevaluatedProperties!=true\\\n      \\ &&  @.unevaluatedProperties!=false )]\"\n    severity: \"warn\"\n    then:\n      function: \"defined\"\n      field: \"maxProperties\"\n    description: \"By default JSON Schema allows unevaluated properties, which can\\\n      \\ potentially lead to mass assignment issues, where unspecified fields are passed\\\n      \\ to the API without validation. Disable them with `unevaluatedProperties: false`\\\n      \\ or add `maxProperties`\"\n    message: \"Objects should not allow unconstrained unevaluatedProperties.\"\n    resolved: true\n    formats:\n    - \"oas3_1\"\n  owasp:api4:2023-rate-limit-retry-after:\n    given:\n    - \"$..responses[429].headers\"\n    severity: \"error\"\n    then:\n      function: \"defined\"\n      field: \"Retry-After\"\n    description: \"Define proper rate limiting to avoid attackers overloading the API.\\\n      \\ Part of that involves setting a Retry-After header so well meaning consumers\\\n      \\ are not polling and potentially exacerbating problems.\"\n    message: \"A 429 response should define a Retry-After header.\"\n    resolved: true\n    formats:\n    - \"oas3\"\n  owasp:api4:2023-rate-limit-responses-429:\n    given:\n    - \"$.paths..responses\"\n    severity: \"warn\"\n    then:\n    - function: \"truthy\"\n      field: \"429\"\n    - function: \"truthy\"\n      field: \"429.content\"\n    description: \"OWASP API Security recommends defining schemas for all responses,\\\n      \\ even errors. A HTTP 429 response signals the API client is making too many\\\n      \\ requests, and will supply information about when to retry so that the client\\\n      \\ can back off calmly without everything breaking. Defining this response is\\\n      \\ important not just for documentation, but to empower contract testing to make\\\n      \\ sure the proper JSON structure is being returned instead of leaking implementation\\\n      \\ details in backtraces. It also ensures your API/framework/gateway actually\\\n      \\ has rate limiting set up.\"\n    message: \"Operation is missing rate limiting response in {{property}}.\"\n    resolved: true\n    formats:\n    - \"oas2\"\n    - \"oas3\"\n  owasp:api8:2023-no-scheme-http:\n    given:\n    - \"$.schemes.*\"\n    severity: \"error\"\n    then:\n      function: \"schema\"\n      functionOptions:\n        schema:\n          type: \"string\"\n          enum:\n          - \"https\"\n          - \"wss\"\n    description: \"Server interactions must use the http protocol as it\'s inherently\\\n      \\ insecure and can lead to PII and other sensitive information being leaked\\\n      \\ through traffic sniffing or man-in-the-middle attacks. Use the https or wss\\\n      \\ schemes instead.\\n\\nLearn more about the importance of TLS (over SSL) here:\\\n      \\ [https://cheatsheetseries.owasp.org/cheatsheets/Transport_Layer_Security_Cheat_Sheet.html](https://cheatsheetseries.owasp.org/cheatsheets/Transport_Layer_Security_Cheat_Sheet.html)\"\n    message: \"Server schemes must not use http. Use https or wss instead.\"\n    resolved: true\n    formats:\n    - \"oas2\"\n  owasp:api8:2023-no-server-http:\n    given:\n    - \"$.servers..url\"\n    severity: \"error\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        notMatch: \"/^http:/\"\n    description: \"Server interactions must not use the http:// as it\'s inherently\\\n      \\ insecure and can lead to PII and other sensitive information being leaked\\\n      \\ through traffic sniffing or man-in-the-middle attacks. Use https:// or wss://\\\n      \\ protocols instead.\\n\\nLearn more about the importance of TLS (over SSL) here:\\\n      \\ [https://cheatsheetseries.owasp.org/cheatsheets/Transport_Layer_Security_Cheat_Sheet.html](https://cheatsheetseries.owasp.org/cheatsheets/Transport_Layer_Security_Cheat_Sheet.html)\"\n    message: \"Server URLs must not use http://. Use https:// or wss:// instead.\"\n    resolved: true\n    formats:\n    - \"oas3\"\n  owasp:api8:2023-define-error-validation:\n    given:\n    - \"$.paths..responses\"\n    severity: \"warn\"\n    then:\n      function: \"schema\"\n      functionOptions:\n        schema:\n          type: \"object\"\n          anyOf:\n          - required:\n            - \"400\"\n          - required:\n            - \"422\"\n          - required:\n            - \"4XX\"\n    description: \"Carefully define schemas for all the API responses, including either\\\n      \\ 400, 422 or 4XX responses which describe errors caused by invalid requests.\"\n    message: \"Missing error response of either 400, 422 or 4XX.\"\n    resolved: true\n    formats:\n    - \"oas2\"\n    - \"oas3\"\n  owasp:api8:2023-define-error-responses-401:\n    given:\n    - \"$.paths..responses\"\n    severity: \"warn\"\n    then:\n    - function: \"truthy\"\n      field: \"401\"\n    - function: \"truthy\"\n      field: \"401.content\"\n    description: \"OWASP API Security recommends defining schemas for all responses,\\\n      \\ even errors. The 401 describes what happens when a request is unauthorized,\\\n      \\ so its important to define this not just for documentation, but to empower\\\n      \\ contract testing to make sure the proper JSON structure is being returned\\\n      \\ instead of leaking implementation details in backtraces.\"\n    message: \"Operation is missing {{property}}.\"\n    resolved: true\n    formats:\n    - \"oas2\"\n    - \"oas3\"\n  owasp:api8:2023-define-error-responses-500:\n    given:\n    - \"$.paths..responses\"\n    severity: \"warn\"\n    then:\n    - function: \"truthy\"\n      field: \"500\"\n    - function: \"truthy\"\n      field: \"500.content\"\n    description: \"OWASP API Security recommends defining schemas for all responses,\\\n      \\ even errors. The 500 describes what happens when a request fails with an internal\\\n      \\ server error, so its important to define this not just for documentation,\\\n      \\ but to empower contract testing to make sure the proper JSON structure is\\\n      \\ being returned instead of leaking implementation details in backtraces.\"\n    message: \"Operation is missing {{property}}.\"\n    resolved: true\n    formats:\n    - \"oas2\"\n    - \"oas3\"\n  owasp:api9:2023-inventory-access:\n    given:\n    - \"$.servers.*\"\n    severity: \"error\"\n    then:\n      function: \"defined\"\n      field: \"x-internal\"\n    description: \"Servers are required to use vendor extension x-internal set to true\\\n      \\ or false to explicitly explain the audience for the API, which will be picked\\\n      \\ up by most documentation tools.\"\n    message: \"Declare intended audience of every server by defining servers{{property}}\\\n      \\ as true/false.\"\n    resolved: true\n    formats:\n    - \"oas3\"\n  owasp:api9:2023-inventory-environment:\n    given:\n    - \"$.servers.*\"\n    severity: \"error\"\n    then:\n      function: \"pattern\"\n      functionOptions:\n        match: \"/(local|sandbox|alpha|beta|test|testing|stag|staging|prod|production|next|preprod|preproduction)/i\"\n      field: \"description\"\n    description: \"Make it clear which servers are expected to run as which environment\\\n      \\ to avoid unexpected problems, exposing test data to the public, or letting\\\n      \\ bad actors bypass security measures to get to production-like environments.\"\n    message: \"Declare intended environment in server descriptions using terms like\\\n      \\ local, staging, production.\"\n    resolved: true\n    formats:\n    - \"oas3\"\n','YAML','owasp_top_10.yaml');
/*!40000 ALTER TABLE `GOV_RULESET_CONTENT` ENABLE KEYS */;
