--
-- Table structure for table `GOV_RULESET_RULE`
--

DROP TABLE IF EXISTS `GOV_RULESET_RULE`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `GOV_RULESET_RULE` (
  `RULESET_RULE_ID` varchar(36) NOT NULL,
  `RULESET_ID` varchar(36) NOT NULL,
  `RULE_NAME` varchar(256) NOT NULL,
  `RULE_DESCRIPTION` varchar(1024) DEFAULT NULL,
  `SEVERITY` varchar(32) NOT NULL,
  `RULE_CONTENT` blob NOT NULL,
  PRIMARY KEY (`RULESET_RULE_ID`),
  UNIQUE KEY `RULESET_RULE_CONSTRAINT` (`RULESET_ID`,`RULE_NAME`),
  CONSTRAINT `GOV_RULESET_RULE_ibfk_1` FOREIGN KEY (`RULESET_ID`) REFERENCES `GOV_RULESET` (`RULESET_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;
